INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq1_13', 'lesson-1', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “学校” chứa bộ thủ nào sau đây?', '["Bộ cấu tạo [留] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [同] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [晚] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [学] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)"]'::jsonb, 3, 'Chữ “学校” có Bộ cấu tạo [学] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán). Ghép từ các chữ Hán: [学] + [校].', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq1_14', 'lesson-1', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “老师” chứa bộ thủ nào sau đây?', '["Bộ cấu tạo [老] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","木 (Mộc) (Cây cối, gỗ)","Bộ cấu tạo [你] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [早] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)"]'::jsonb, 0, 'Chữ “老师” có Bộ cấu tạo [老] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán). Ghép từ các chữ Hán: [老] + [师].', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
