INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq1_16', 'lesson-1', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “学生” chứa bộ thủ nào sau đây?', '["Bộ cấu tạo [学] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [也] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [我] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","日 (Nhật) (Mặt trời, ban ngày, thời gian, ánh sáng)"]'::jsonb, 0, 'Chữ “学生” có Bộ cấu tạo [学] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán). Ghép từ các chữ Hán: [学] + [生].', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq1_17', 'lesson-1', NULL, 'expanded_quiz', 'reading', NULL, NULL, '[Mở rộng] Câu “刘老师，下午好！” có nghĩa tiếng Việt là gì?', '["học sinh tiểu học","Ba người bạn (cách dùng đúng)","một người","Em chào thầy Lưu buổi chiều ạ!"]'::jsonb, 3, '刘老师，下午好！ (Liú lǎoshī, xiàwǔ hǎo!) → Em chào thầy Lưu buổi chiều ạ!', 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
