INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq1_19', 'lesson-1', NULL, 'expanded_quiz', 'reading', NULL, NULL, '[Mở rộng] Câu “范玉兰是留学生吗？” có nghĩa tiếng Việt là gì?', '["môi trường làm việc","Anh ấy là ai?","bên trái (của) trường học","Phạm Ngọc Lan là du học sinh phải không?"]'::jsonb, 3, '范玉兰是留学生吗？ (Fàn Yùlán shì liúxuéshēng ma?) → Phạm Ngọc Lan là du học sinh phải không?', 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq1_20', 'lesson-1', NULL, 'expanded_quiz', 'reading', NULL, NULL, '[Mở rộng] Câu “阮日明也是学生吗？” có nghĩa tiếng Việt là gì?', '["Nữ sinh phía sau","Nguyễn Nhật Minh cũng là học sinh à?","Cô giáo không ở trong phòng làm việc.","ba cây bút chì"]'::jsonb, 1, '阮日明也是学生吗？ (Ruǎn Rìmíng yě shì xuésheng ma?) → Nguyễn Nhật Minh cũng là học sinh à?', 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
