INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct1_6', 'lesson-1', NULL, 'comprehensive_test', 'listening', '你们晚上好', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["范玉兰是留学生吗","你们晚上好","她是老师。","刘老师下午好"]'::jsonb, 1, 'Câu vừa đọc: “你们晚上好” (Nǐmen wǎnshang hǎo!) → Chào buổi tối các bạn!', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
