INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v2_1', 'lesson-2', '贵姓', 'guìxìng', 'quý tính', 'họ, quý tính, quý danh (cách nói lịch sử)', 'Danh từ', 'Bộ cấu tạo [贵] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [贵] + [姓].', 'Kết hợp các thành tố [贵] + [姓] để tạo thành từ mang nghĩa ''họ, quý tính, quý danh (cách nói lịch sử)''.', '这是关于“贵姓”的常用句子。', 'Zhè shì guānyú ''guìxìng'' de chángyòng jùzi.', 'Đây là câu ví dụ sử dụng từ ''贵姓'' (họ, quý tính, quý danh (cách nói lịch sử)).', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v2_2', 'lesson-2', '姓', 'xìng', 'tính', 'họ, tính', 'Danh từ / Động từ', 'Bộ cấu tạo [姓] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Chữ độc thể / hình thanh gồm Bộ cấu tạo [姓] và các nét bổ trợ.', 'Ghi nhớ chữ [姓] (họ, tính) qua hình tượng Thành phần biểu ý/biểu âm cơ bản trong chữ Hán.', 'B: 我姓林。', 'Wǒ xìng Lín.', 'Tôi họ Lâm.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v2_3', 'lesson-2', '名字', 'míngzi', 'danh tự', 'tên', 'Danh từ', 'Bộ cấu tạo [名] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [名] + [字].', 'Kết hợp các thành tố [名] + [字] để tạo thành từ mang nghĩa ''tên''.', 'A: 你叫什么名字？', 'Nǐ jiào shénme míngzi?', 'Bạn tên là gì?', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v2_4', 'lesson-2', '马克', 'Mǎkè', 'Mã khắc', 'Mark (du học sinh Mỹ)', 'Cụm từ / Tên riêng', 'Bộ cấu tạo [马] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [马] + [克].', 'Kết hợp các thành tố [马] + [克] để tạo thành từ mang nghĩa ''Mark (du học sinh Mỹ)''.', '我叫马克。她叫什么名字？', 'Wǒ jiào Mǎkè. Tā jiào shénme míngzi?', 'Tôi tên là Mark. Cô ấy tên là gì?', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v2_5', 'lesson-2', '张风', 'Zhāng Fēng', 'phong', 'Trương Phong (sinh viên người Trung Quốc đại học Thanh Hoa)', 'Cụm từ / Tên riêng', 'Bộ cấu tạo [张] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [张] + [风].', 'Kết hợp các thành tố [张] + [风] để tạo thành từ mang nghĩa ''Trương Phong (sinh viên người Trung Quốc đại học Thanh Hoa)''.', '是。我叫张风。你叫什么名字？', 'Shì. Wǒ jiào Zhāng Fēng. Nǐ jiào shénme míngzi?', 'Đúng rồi. Tôi tên là Trương Phong. Bạn tên là gì?', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
