INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v2_18', 'lesson-2', '了', 'le', 'từ Hán ngữ', 'rồi', 'Trợ từ', 'Bộ cấu tạo [了] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Chữ độc thể / hình thanh gồm Bộ cấu tạo [了] và các nét bổ trợ.', 'Ghi nhớ chữ [了] (rồi) qua hình tượng Thành phần biểu ý/biểu âm cơ bản trong chữ Hán.', '你昨天去学校了吗？', 'Nǐ zuótiān qù xuéxiào le ma?', 'Hôm qua cậu đã đến trường chưa?', 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g2_1', 'lesson-2', '1. Cách chào tạm biệt', 'Cấu trúc câu ngữ pháp trọng tâm', ' Có một số câu chào tạm biệt đơn giản như sau: 再见！/Zàijiàn!/: Tạm biệt! 明天见！/Míngtiān jiàn!/: Hẹn gặp lại vào ngày mai! (Hoặc “Mai gặp nhé!”) 拜拜！/Bàibai!/:   Bye! (thường dùng trong giới trẻ)', NULL, '[{"hanzi":"再见！","pinyin":"Zàijiàn!","meaning":"Tạm biệt!"},{"hanzi":"明天见！","pinyin":"Míngtiān jiàn!","meaning":"Hẹn gặp lại vào ngày mai! (Hoặc “Mai gặp nhé!”)"}]'::jsonb, 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g2_2', 'lesson-2', '2. Cách hỏi tên và trả lời', 'Cấu trúc câu ngữ pháp trọng tâm', ' a. Cách hỏi Khi muốn hỏi tên ai đó, có thể sử dụng các mẫu câu sau: * 您贵姓？ Cách hỏi này mang ngữ khí lịch sự, thường dùng để hỏi họ của người có địa vị cao hơn người nói, người lớn tuổi hơn, ... * 你叫什么(名字)？ Cách hỏi này mang ngữ khí tự nhiên hơn, th', NULL, '[{"hanzi":"拜拜！","pinyin":"Bàibai!","meaning":"Bye! (thường dùng trong giới trẻ)"},{"hanzi":"B: 我姓林。","pinyin":"Wǒ xìng Lín.","meaning":"Tôi họ Lâm."}]'::jsonb, 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g2_3', 'lesson-2', '3. Đại từ nghi vấn 什么', 'Cấu trúc câu ngữ pháp trọng tâm', ' - 什么 là đại từ nghi vấn, biểu thị ý nghĩa “cái gì, thứ gì, gì”. 你说什么？ Nǐ shuō shénme? Cậu nói gì? - Đại từ nghi vấn 什么 cũng có thể đứng trước danh từ, hỏi thành phần tu sức cho danh từ trung tâm, làm rõ chủng loại,... (Nội dung này sẽ được làm rõ hơ', NULL, '[{"hanzi":"A: 你叫什么名字？","pinyin":"Nǐ jiào shénme míngzi?","meaning":"Bạn tên là gì?"},{"hanzi":"B: 我叫陈英。","pinyin":"Wǒ jiào Chén Yīng.","meaning":"Tôi là Trần Anh."}]'::jsonb, 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g2_4', 'lesson-2', '4. Trạng ngữ chỉ thời gian', 'Cấu trúc câu ngữ pháp trọng tâm', ' a. Khái niệm Trạng ngữ chỉ thời gian do danh từ hoặc cụm danh từ biểu thị thời gian đảm nhiệm, biểu thị thời gian xảy ra hiện tượng, động tác,... b. Cách dùng Trạng ngữ chỉ thời gian thường đứng sát ngay trước động từ, tính từ (sau chủ ngữ) hoặc trư', NULL, '[{"hanzi":"你说什么？","pinyin":"Nǐ shuō shénme?","meaning":"Cậu nói gì?"},{"hanzi":"这是什么书？","pinyin":"Zhè shì shénme shū?","meaning":"Đây là sách gì?"}]'::jsonb, 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_2_1', 'lesson-2', 'Bài khoá #1: Hội thoại giáo trình — Chào hỏi (2)', 'Hội thoại chuẩn giáo trình Bài 2. Từ vựng chưa học được chú thích phiên âm & nghĩa trong ngoặc.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
