INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_2_1_5', 'txt_2_1', '张风', '她是白茹雪。', '她是白茹雪。', 'Tā shì Bái Rúxuě.', 'Cô ấy là Bạch Như Tuyết.', 5) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_2_1_1', 'lesson-2', 'txt_2_1', 'listening', 'listening', '你好！', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Xin chào!","Khó quá đi, tôi không biết nên làm như thế nào nữa!","Bạn tôi sắp đi Trùng Khánh du học rồi.","Nếu ngày mai mưa thì chúng tôi sẽ không đi chơi nữa."]'::jsonb, 0, 'Nội dung nghe được: 你好！ (Nǐ hǎo!) → Xin chào!', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_2_1_2', 'lesson-2', 'txt_2_1', 'listening', 'listening', '你好！你也是学生吗？', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["B: 我叫陈英 (Chén Yīng: Trần Anh)。","B: 我姓林 (Lín: Lâm)。","我姓范，叫范玉兰。","你好！你也是学生吗？"]'::jsonb, 3, 'Câu vừa đọc: 你好！你也是学生吗？ (Nǐ hǎo! Nǐ yě shì xuésheng ma?) → Xin chào! Bạn cũng là học sinh à?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_2_1_3', 'lesson-2', 'txt_2_1', 'listening', 'listening', '是。我叫张风。你叫什么名字？', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Ngày mai tôi sẽ đi Thượng Hải.","Đúng rồi. Tôi tên là Trương Phong. Bạn tên là gì?","Hôm nay anh ta bảo tôi tháng sau ra nước ngoài.","Tôi có một cậu em trai."]'::jsonb, 1, 'Nội dung nghe được: 是。我叫张风。你叫什么名字？ (Shì. Wǒ jiào Zhāng Fēng. Nǐ jiào shénme míngzi?) → Đúng rồi. Tôi tên là Trương Phong. Bạn tên là gì?', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_2_1_4', 'lesson-2', 'txt_2_1', 'listening', 'listening', '我叫马克。她叫什么名字？', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["你好！","A: 你叫什么名字？","我叫马克。她叫什么名字？","再见！"]'::jsonb, 2, 'Câu vừa đọc: 我叫马克。她叫什么名字？ (Wǒ jiào Mǎkè. Tā jiào shénme míngzi?) → Tôi tên là Mark. Cô ấy tên là gì?', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_2_2', 'lesson-2', 'Bài khoá #2: Hội thoại giáo trình — Chào hỏi (2)', 'Hội thoại chuẩn giáo trình Bài 2. Từ vựng chưa học được chú thích phiên âm & nghĩa trong ngoặc.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_2_2_1', 'txt_2_2', '马克', '我要回宿舍了。再见!', '我要回宿舍了。再见!', 'Wǒ yào huí sùshè le. Zàijiàn!', 'Tôi phải về ký túc xá rồi. Tạm biệt!', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_2_2_2', 'txt_2_2', '张风', '好，明天见！', '好，明天见！', 'Hǎo, míngtiān jiàn!', 'Được, ngày mai gặp lại nhé!', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_2_2_1', 'lesson-2', 'txt_2_2', 'listening', 'listening', '我要回宿舍了。再见!', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Hẹn gặp lại vào ngày mai! (Hoặc “Mai gặp nhé!”)","Tôi không nghe thấy anh ấy nói gì.","Tôi phải về ký túc xá rồi. Tạm biệt!","Tôi vẫn chưa nghĩ xong nên mặc váy màu đỏ hay là váy màu xanh nữa."]'::jsonb, 2, 'Nội dung nghe được: 我要回宿舍了。再见! (Wǒ yào huí sùshè le. Zàijiàn!) → Tôi phải về ký túc xá rồi. Tạm biệt!', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_2_2_2', 'lesson-2', 'txt_2_2', 'listening', 'listening', '好，明天见！', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["马克，明天早上见！","好，明天见！","你说 (shuō: nói)什么？","她叫什么名字？"]'::jsonb, 1, 'Câu vừa đọc: 好，明天见！ (Hǎo, míngtiān jiàn!) → Được, ngày mai gặp lại nhé!', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_2_2_3', 'lesson-2', 'txt_2_2', 'listening', 'listening', '再见！', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["phía trước (của) tôi","Tạm biệt!","Tôi đến không muộn lắm, vẫn còn mấy người nữa chưa đến.","Sao cậu lại đến nữa vậy?"]'::jsonb, 1, 'Nội dung nghe được: 再见！ (Zàijiàn!) → Tạm biệt!', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_2_2_4', 'lesson-2', 'txt_2_2', 'listening', 'listening', '明天见！', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["你说 (shuō: nói)什么？","你好！","明天见！","她叫什么名字？"]'::jsonb, 2, 'Câu vừa đọc: 明天见！ (Míngtiān jiàn!) → Hẹn gặp lại vào ngày mai! (Hoặc “Mai gặp nhé!”)', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_2_3', 'lesson-2', 'Bài nghe tổng hợp: Ôn tập lũy tiến (Bài 1 – Bài 2)', 'Kết hợp từ vựng & mẫu câu đã học từ Bài 1 đến Bài 1 cùng trọng tâm Bài 2 để củng cố phản xạ nghe.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
