INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq2_13', 'lesson-2', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “贵姓” chứa bộ thủ nào sau đây?', '["白 (Bạch) (Màu trắng, sáng tỏ)","木 (Mộc) (Cây cối, gỗ)","Bộ cấu tạo [上] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [贵] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)"]'::jsonb, 3, 'Chữ “贵姓” có Bộ cấu tạo [贵] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán). Ghép từ các chữ Hán: [贵] + [姓].', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq2_14', 'lesson-2', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “姓” chứa bộ thủ nào sau đây?', '["Bộ cấu tạo [姓] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [叫] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [明] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [名] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)"]'::jsonb, 0, 'Chữ “姓” có Bộ cấu tạo [姓] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán). Chữ độc thể / hình thanh gồm Bộ cấu tạo [姓] và các nét bổ trợ.', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq2_15', 'lesson-2', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “名字” chứa bộ thủ nào sau đây?', '["Bộ cấu tạo [张] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [名] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","氵 (Ba chấm thủy) (Nước, chất lỏng)","口 (Khẩu) (Miệng, ăn uống, lời nói)"]'::jsonb, 1, 'Chữ “名字” có Bộ cấu tạo [名] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán). Ghép từ các chữ Hán: [名] + [字].', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq2_16', 'lesson-2', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “马克” chứa bộ thủ nào sau đây?', '["Bộ cấu tạo [张] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [回] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [宿] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [马] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)"]'::jsonb, 3, 'Chữ “马克” có Bộ cấu tạo [马] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán). Ghép từ các chữ Hán: [马] + [克].', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq2_17', 'lesson-2', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 1] Từ đã học “您” (nín) có nghĩa là gì?', '["hiện tại, bây giờ","ngài, ông, bà... (cách gọi tôn trọng và lịch sự dành cho những người có địa vị cao...)","bạn, cậu, anh, chị... (ngôi thứ hai số ít)","buổi tối"]'::jsonb, 1, 'Ôn tập Bài 1: “您” (nín) nghĩa là: ngài, ông, bà... (cách gọi tôn trọng và lịch sự dành cho những người có địa vị cao...).', 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq2_18', 'lesson-2', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 1] Từ đã học “是” (shì) có nghĩa là gì?', '["phải","là, thì...","Trường học","hiện tại, bây giờ"]'::jsonb, 1, 'Ôn tập Bài 1: “是” (shì) nghĩa là: là, thì....', 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq2_19', 'lesson-2', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 1] Từ đã học “好” (hǎo) có nghĩa là gì?', '["rồi","tốt, khỏe, hay, ngon...","Bạch Như Tuyết (sinh viên người Trung Quốc đại học Bắc Kinh)","tên"]'::jsonb, 1, 'Ôn tập Bài 1: “好” (hǎo) nghĩa là: tốt, khỏe, hay, ngon....', 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq2_20', 'lesson-2', NULL, 'expanded_quiz', 'reading', NULL, NULL, '[Mở rộng] Câu “现在我要上课了。” có nghĩa tiếng Việt là gì?', '["cây thước kẻ của anh ấy","Tôi đợi các bạn ở cổng trường.","Nữ sinh phía sau","Bây giờ tôi phải vào lớp học rồi."]'::jsonb, 3, '现在我要上课了。 (Xiànzài wǒ yào shàngkè le.) → Bây giờ tôi phải vào lớp học rồi.', 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
