INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v3_1', 'lesson-3', '朋友', 'péngyou', 'bằng hữu', 'bạn bè', 'Danh từ', 'Bộ cấu tạo [朋] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [朋] + [友].', 'Kết hợp các thành tố [朋] + [友] để tạo thành từ mang nghĩa ''bạn bè''.', '这是我的好朋友，他叫马克。', 'Zhè shì wǒ de hǎo péngyou, tā jiào Mǎkè.', 'Đây là bạn thân của tôi, cậu ấy tên là Mark.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v3_2', 'lesson-3', '人', 'rén', 'nhân', 'người, con người', 'Danh từ', '人 (Nhân) (Con người, nhân loại)', 'Chữ độc thể / hình thanh gồm 人 (Nhân) và các nét bổ trợ.', 'Ghi nhớ chữ [人] (người, con người) qua hình tượng Con người, nhân loại.', '你是哪国人？', 'Nǐ shì nǎ guó rén?', 'Bạn là người nước nào?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
