INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v3_4', 'lesson-3', '国家', 'guójiā', 'quốc gia', 'quốc gia, đất nước', 'Danh từ', 'Bộ cấu tạo [国] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [国] + [家].', 'Kết hợp các thành tố [国] + [家] để tạo thành từ mang nghĩa ''quốc gia, đất nước''.', '不是。我是美国人。你来自哪个国家？', 'Bú shì. Wǒ shì Měiguó rén. Nǐ láizì nǎ gè guójiā?', 'Không phải. Tôi là người Mỹ. Bạn đến từ nước nào?', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
