INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v3_18', 'lesson-3', '个', 'gè', 'từ Hán ngữ', 'cái, chiếc,...', 'Lượng từ', 'Bộ cấu tạo [个] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Chữ độc thể / hình thanh gồm Bộ cấu tạo [个] và các nét bổ trợ.', 'Ghi nhớ chữ [个] (cái, chiếc,...) qua hình tượng Thành phần biểu ý/biểu âm cơ bản trong chữ Hán.', '她是哪个学校的学生？', 'Tā shì nǎ gè xuéxiào de xuésheng?', 'Cô ấy là học sinh trường nào?', 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v3_19', 'lesson-3', '的', 'de', 'từ Hán ngữ', 'của (trợ từ)', 'Trợ từ', 'Bộ cấu tạo [的] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Chữ độc thể / hình thanh gồm Bộ cấu tạo [的] và các nét bổ trợ.', 'Ghi nhớ chữ [的] (của (trợ từ)) qua hình tượng Thành phần biểu ý/biểu âm cơ bản trong chữ Hán.', '他是我的老师。', 'Tā shì wǒ de lǎoshī.', 'Thầy ấy là thầy giáo của tớ.', 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g3_1', 'lesson-3', '1. Trợ từ kết cấu 的', 'Chủ sở hữu  +的 + được sở hữu.', ' Đây là trợ từ kết cấu biểu thị mối quan hệ sở hữu, được sử dụng theo cấu trúc: Trong đó chủ sở hữu thường là danh từ hoặc đại từ còn được sở hữu thường là danh từ. 他是我的老师。 Tā shì wǒ de lǎoshī. Thầy ấy là thầy giáo của tớ. 这是我的书。 Zhè shì wǒ de shū. Đ', NULL, '[{"hanzi":"他是我的老师。","pinyin":"Tā shì wǒ de lǎoshī.","meaning":"Thầy ấy là thầy giáo của tớ."},{"hanzi":"这是我的书。","pinyin":"Zhè shì wǒ de shū.","meaning":"Đây là sách của tôi."}]'::jsonb, 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g3_2', 'lesson-3', '2. 疑问代词 “哪”、“谁” – Đại từ nghi vấn 哪, 谁', 'Cấu trúc câu ngữ pháp trọng tâm', ' a. Đại từ nghi vấn 哪 Phía sau có thể thêm danh từ hoặc số lượng từ, hỏi xác định phạm vi hoặc xác định sự vật (đâu) trong 1 loạt sự vật cùng loại (nào).', NULL, '[{"hanzi":"你是哪国人？","pinyin":"Nǐ shì nǎ guó rén?","meaning":"Bạn là người nước nào?"},{"hanzi":"她是哪个学校的学生？","pinyin":"Tā shì nǎ gè xuéxiào de xuésheng?","meaning":"Cô ấy là học sinh trường nào?"}]'::jsonb, 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g3_3', 'lesson-3', '1. 哪 + lượng từ / số lượng từ + Danh từ', 'Cấu trúc câu ngữ pháp trọng tâm', 'Quy tắc ngữ pháp quan trọng trong Kết bạn.', NULL, '[{"hanzi":"谁啊？","pinyin":"Shéi a?","meaning":"Ai đấy?"},{"hanzi":"他是谁？","pinyin":"Tā shì shéi?","meaning":"Anh ấy là ai?"}]'::jsonb, 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g3_4', 'lesson-3', '2. 哪 + Danh từ lượng từ', 'Cấu trúc câu ngữ pháp trọng tâm', ' 你是哪国人？ Nǐ shì nǎ guó rén? Bạn là người nước nào? 她是哪个学校的学生？ Tā shì nǎ gè xuéxiào de xuésheng? Cô ấy là học sinh trường nào? 你哪天去上课? ( 天 là một danh lượng từ) Nǐ nǎ tiān qù shàngkè? Ngày nào mày đi học? b. Đại từ nghi vấn 谁 - Đây là đại từ nghi vấn c', NULL, '[{"hanzi":"这本书是我的书。","pinyin":"Zhè běn shū shì wǒ de shū.","meaning":"Quyển sách này là sách của tớ."},{"hanzi":"那个人是王老师。","pinyin":"Nà gè rén shì Wáng lǎoshī.","meaning":"Người đó là thầy Vương."}]'::jsonb, 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_3_1', 'lesson-3', 'Bài khoá #1: Hội thoại giáo trình — Kết bạn', 'Hội thoại chuẩn giáo trình Bài 3. Từ vựng chưa học được chú thích phiên âm & nghĩa trong ngoặc.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_3_1_1', 'txt_3_1', '安妮', '日明同学！你好！', '日明同学！你好！', 'Rìmíng tóngxué! Nǐ hǎo!', 'Chào bạn Nhật Minh!', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_3_1_2', 'txt_3_1', '阮日明', '安妮同学！你好！这是谁啊？', '安妮同学！你好！这是谁啊 (a: dùng cuối câu)？', 'Ānnī tóngxué nǐ hǎo! Zhè shì shéi a?', 'Chào bạn Annie! Đây là ai vậy?', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_3_1_3', 'txt_3_1', '安妮', '这是我的好朋友，他叫马克。', '这是我的好朋友，他叫马克。', 'Zhè shì wǒ de hǎo péngyou, tā jiào Mǎkè.', 'Đây là bạn thân của tôi, cậu ấy tên là Mark.', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_3_1_4', 'txt_3_1', '阮日明', '马克同学你好！你也是加拿大人吗？', '马克同学你好！你也是加拿大人吗？', 'Mǎkè tóngxué nǐ hǎo! Nǐ yě shì Jiānádà rén ma?', 'Chào bạn Mark! Bạn cũng là người Canada à?', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_3_1_5', 'txt_3_1', '马克', '不是。我是美国人。你来自哪个国家？', '不 (bù: không)是。我是美国人。你来自哪个国家？', 'Bú shì. Wǒ shì Měiguó rén. Nǐ láizì nǎ gè guójiā?', 'Không phải. Tôi là người Mỹ. Bạn đến từ nước nào?', 5) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_3_1_6', 'txt_3_1', '阮日明', '我来自越南。', '我来自越南。', 'Wǒ láizì Yuènán.', 'Tôi đến từ Việt Nam.', 6) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_3_1_7', 'txt_3_1', '马克', '很高兴认识你！', '很高兴认识你！', 'Hěn gāoxìng rènshi nǐ!', 'Rất vui được làm quen với bạn!', 7) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_3_1_8', 'txt_3_1', '阮日明', '我也很高兴认识你。', '我也很高兴认识你。', 'Wǒ yě hěn gāoxìng rènshi nǐ.', 'Tôi cũng rất vui được làm quen với bạn.', 8) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_3_1_1', 'lesson-3', 'txt_3_1', 'listening', 'listening', '日明同学！你好！', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Không phải ngoài trời đang mưa à? Cậu dùng ô của tớ đi! (Khẳng định","Tôi đang đọc sách.","Chào bạn Nhật Minh!","Bây giờ cậu cảm thấy thế nào?"]'::jsonb, 2, 'Nội dung nghe được: 日明同学！你好！ (Rìmíng tóngxué! Nǐ hǎo!) → Chào bạn Nhật Minh!', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_3_1_2', 'lesson-3', 'txt_3_1', 'listening', 'listening', '安妮同学！你好！这是谁啊？', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["你认识阮日明吗？","张风不 (bù: không)是美国人，他是中国 (Zhōngguó: Trung Quốc)人。","安妮同学！你好！这是谁啊 (a: dùng cuối câu)？","日明同学！你好！"]'::jsonb, 2, 'Câu vừa đọc: 安妮同学！你好！这是谁啊？ (Ānnī tóngxué nǐ hǎo! Zhè shì shéi a?) → Chào bạn Annie! Đây là ai vậy?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_3_1_3', 'lesson-3', 'txt_3_1', 'listening', 'listening', '这是我的好朋友，他叫马克。', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Anh ta thật sự nói như thế.","Đây là bạn thân của tôi, cậu ấy tên là Mark.","Tàu hỏa sắp chạy ngay bây giờ.","Bệnh của mẹ khỏi lâu rồi, con đừng lo lắng."]'::jsonb, 1, 'Nội dung nghe được: 这是我的好朋友，他叫马克。 (Zhè shì wǒ de hǎo péngyou, tā jiào Mǎkè.) → Đây là bạn thân của tôi, cậu ấy tên là Mark.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_3_1_4', 'lesson-3', 'txt_3_1', 'listening', 'listening', '马克同学你好！你也是加拿大人吗？', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["张风不 (bù: không)是美国人，他是中国 (Zhōngguó: Trung Quốc)人。","这是我的好朋友，他叫马克。","马克同学你好！你也是加拿大人吗？","认识刘老师我很高兴。"]'::jsonb, 2, 'Câu vừa đọc: 马克同学你好！你也是加拿大人吗？ (Mǎkè tóngxué nǐ hǎo! Nǐ yě shì Jiānádà rén ma?) → Chào bạn Mark! Bạn cũng là người Canada à?', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_3_2', 'lesson-3', 'Bài nghe tổng hợp: Ôn tập lũy tiến (Bài 1 – Bài 3)', 'Kết hợp từ vựng & mẫu câu đã học từ Bài 1 đến Bài 2 cùng trọng tâm Bài 3 để củng cố phản xạ nghe.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
