INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_3_2_1', 'lesson-3', 'txt_3_2', 'listening', 'listening', '明天见！', NULL, '[Ôn tập Bài 2] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Cô ấy đã ăn 3 cái sủi cảo.","Hẹn gặp lại vào ngày mai! (Hoặc “Mai gặp nhé!”)","Ba người bạn (cách dùng đúng)","Cậu là Nhật Minh phải không?"]'::jsonb, 1, 'Nội dung nghe được: 明天见！ (Míngtiān jiàn!) → Hẹn gặp lại vào ngày mai! (Hoặc “Mai gặp nhé!”)', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_3_2_2', 'lesson-3', 'txt_3_2', 'listening', 'listening', '他是我的老师。', NULL, '[Bài 3] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["马克同学你好！你也是加拿大人吗？","他是我的老师。","这是我的好朋友，他叫马克。","这本 (běn: cuốn, vở)书 (shū: sách)是我的书。"]'::jsonb, 1, 'Câu vừa đọc: 他是我的老师。 (Tā shì wǒ de lǎoshī.) → Thầy ấy là thầy giáo của tớ.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_3_2_3', 'lesson-3', 'txt_3_2', 'listening', 'listening', '中午好！', NULL, '[Ôn tập Bài 1] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Chào buổi trưa!","Hai người","Chúng ta cùng qua bên đó xem đi!","đất nước (quốc gia) của chúng tôi"]'::jsonb, 0, 'Nội dung nghe được: 中午好！ (Zhōngwǔ hǎo) → Chào buổi trưa!', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_3_2_4', 'lesson-3', 'txt_3_2', 'listening', 'listening', '她是哪个学校的学生？', NULL, '[Bài 3] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["谁啊 (a: dùng cuối câu)？","她是哪个学校的学生？","安妮是我的好朋友。","这本 (běn: cuốn, vở)书 (shū: sách)是我的书。"]'::jsonb, 1, 'Câu vừa đọc: 她是哪个学校的学生？ (Tā shì nǎ gè xuéxiào de xuésheng?) → Cô ấy là học sinh trường nào?', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_3_2_5', 'lesson-3', 'txt_3_2', 'listening', 'listening', 'A: 你叫什么名字？', NULL, '[Ôn tập Bài 2] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Bạn tên là gì?","bút bi của cô ấy","Tôi dọn đồ xong sẽ đi.","Đây là sách gì?"]'::jsonb, 0, 'Nội dung nghe được: A: 你叫什么名字？ (Nǐ jiào shénme míngzi?) → Bạn tên là gì?', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_3_3', 'lesson-3', 'Bài khoá mở rộng: Bạn bè quốc tế trong lớp (Mở rộng)', 'Hội thoại tình huống mới xây dựng dựa trên từ vựng và ngữ pháp Bài 3 (không trùng lặp nguyên văn giáo trình).', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_3_3_1', 'txt_3_3', 'Annie', '日明，这位是我的朋友，他叫马克。', '日明，这位 (wèi: vị)是我的朋友，他叫马克。', 'Rìmíng, zhè wèi shì wǒ de péngyou, tā jiào Mǎkè.', 'Nhật Minh, vị này là bạn tôi, cậu ấy tên là Mark.', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_3_3_2', 'txt_3_3', 'Minh', '很高兴认识你！你来自加拿大吗？', '很高兴认识你！你来自加拿大吗？', 'Hěn gāoxìng rènshi nǐ! Nǐ láizì Jiānádà ma?', 'Rất vui được làm quen với bạn! Bạn đến từ Canada à?', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_3_3_3', 'txt_3_3', 'Mark', '不是，我来自美国。安妮是加拿大人。', '不 (bù: không)是，我来自美国。安妮是加拿大人。', 'Bú shì, wǒ láizì Měiguó. Ānnī shì Jiānádà rén.', 'Không phải, tôi đến từ Mỹ. Annie là người Canada.', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_3_3_4', 'txt_3_3', 'Minh', '我来自越南，现在生活在这里。', '我来自越南，现在生活在 (zài: ở)这里 (lǐ: trong)。', 'Wǒ láizì Yuènán, xiànzài shēnghuó zài zhèlǐ.', 'Tôi đến từ Việt Nam, hiện đang sống ở đây.', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_3_3_1', 'lesson-3', 'txt_3_3', 'listening', 'listening', '日明，这位是我的朋友，他叫马克。 很高兴认识你！你来自加拿大吗？ 不是，我来自美国。安妮是加拿大人。 我来自越南，现在生活在这里。', NULL, '[Nghe hiểu tình huống mới] Theo đoạn hội thoại, quốc tịch của Mark và Annie lần lượt là gì?', '["Cả hai đều là người Canada","Mark là người Mỹ, Annie là người Canada","Mark người Canada, Annie người Trung Quốc","Mark người Việt Nam, Annie người Mỹ"]'::jsonb, 1, 'Mark nói ''我来自美国'' (Mỹ) và ''安妮是加拿大人'' (Canada).', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_3_3_2', 'lesson-3', 'txt_3_3', 'listening', 'listening', '日明，这位是我的朋友，他叫马克。', NULL, '[Mở rộng] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Nhật Minh, vị này là bạn tôi, cậu ấy tên là Mark.","Mẹ gõ nhẹ vào đầu tôi.","Anh ta lại đến rồi!","Vận động viên bị thương rồi nên đành phải bỏ thi đấu."]'::jsonb, 0, 'Nội dung nghe được: 日明，这位是我的朋友，他叫马克。 (Rìmíng, zhè wèi shì wǒ de péngyou, tā jiào Mǎkè.) → Nhật Minh, vị này là bạn tôi, cậu ấy tên là Mark.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_3_3_3', 'lesson-3', 'txt_3_3', 'listening', 'listening', '很高兴认识你！你来自加拿大吗？', NULL, '[Mở rộng] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["很高兴认识你！你来自加拿大吗？","谁啊 (a: dùng cuối câu)？","张风不 (bù: không)是美国人，他是中国 (Zhōngguó: Trung Quốc)人。","她是哪个学校的学生？"]'::jsonb, 0, 'Câu vừa đọc: 很高兴认识你！你来自加拿大吗？ (Hěn gāoxìng rènshi nǐ! Nǐ láizì Jiānádà ma?) → Rất vui được làm quen với bạn! Bạn đến từ Canada à?', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_3_3_4', 'lesson-3', 'txt_3_3', 'listening', 'listening', '不是，我来自美国。安妮是加拿大人。', NULL, '[Mở rộng] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Cậu ấy không đi nên tôi đành phải đi.","Sao bố vẫn chưa tan làm, con sắp đói chết rồi!","Không phải, tôi đến từ Mỹ. Annie là người Canada.","Tôi muốn học bơi."]'::jsonb, 2, 'Nội dung nghe được: 不是，我来自美国。安妮是加拿大人。 (Bú shì, wǒ láizì Měiguó. Ānnī shì Jiānádà rén.) → Không phải, tôi đến từ Mỹ. Annie là người Canada.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
