INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq3_13', 'lesson-3', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “朋友” chứa bộ thủ nào sau đây?', '["Bộ cấu tạo [朋] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [谁] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [哪] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [个] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)"]'::jsonb, 0, 'Chữ “朋友” có Bộ cấu tạo [朋] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán). Ghép từ các chữ Hán: [朋] + [友].', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq3_14', 'lesson-3', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “人” chứa bộ thủ nào sau đây?', '["Bộ cấu tạo [他] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","人 (Nhân) (Con người, nhân loại)","Bộ cấu tạo [朋] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","木 (Mộc) (Cây cối, gỗ)"]'::jsonb, 1, 'Chữ “人” có 人 (Nhân) (Con người, nhân loại). Chữ độc thể / hình thanh gồm 人 (Nhân) và các nét bổ trợ.', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq3_15', 'lesson-3', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “安妮” chứa bộ thủ nào sau đây?', '["Bộ cấu tạo [安] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [认] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [的] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [个] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)"]'::jsonb, 0, 'Chữ “安妮” có Bộ cấu tạo [安] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán). Ghép từ các chữ Hán: [安] + [妮].', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq3_16', 'lesson-3', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “国家” chứa bộ thủ nào sau đây?', '["Bộ cấu tạo [美] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [国] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [谁] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [哪] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)"]'::jsonb, 1, 'Chữ “国家” có Bộ cấu tạo [国] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán). Ghép từ các chữ Hán: [国] + [家].', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq3_17', 'lesson-3', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 1] Từ đã học “刘” (Liú) có nghĩa là gì?', '["ngài, ông, bà... (cách gọi tôn trọng và lịch sự dành cho những người có địa vị cao...)","Lưu (họ người)","Giáo viên, thầy cô giáo","ký túc xá"]'::jsonb, 1, 'Ôn tập Bài 1: “刘” (Liú) nghĩa là: Lưu (họ người).', 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq3_18', 'lesson-3', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 2] Từ đã học “回” (huí) có nghĩa là gì?', '["rồi","quốc gia, đất nước","ai","về, trở về, trở lại"]'::jsonb, 3, 'Ôn tập Bài 2: “回” (huí) nghĩa là: về, trở về, trở lại.', 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq3_19', 'lesson-3', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 2] Từ đã học “再见” (zàijiàn) có nghĩa là gì?', '["ngài, ông, bà... (cách gọi tôn trọng và lịch sự dành cho những người có địa vị cao...)","tạm biệt, hẹn gặp lại","họ, quý tính, quý danh (cách nói lịch sử)","hiện tại, bây giờ"]'::jsonb, 1, 'Ôn tập Bài 2: “再见” (zàijiàn) nghĩa là: tạm biệt, hẹn gặp lại.', 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq3_20', 'lesson-3', NULL, 'expanded_quiz', 'reading', NULL, NULL, '[Mở rộng] Câu “安妮是我的好朋友。” có nghĩa tiếng Việt là gì?', '["Annie là bạn thân của tôi.","Câu phía dưới","đất nước (quốc gia) của chúng tôi","Phía dưới bàn"]'::jsonb, 0, '安妮是我的好朋友。 (Ānnī shì wǒ de hǎo péngyou.) → Annie là bạn thân của tôi.', 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
