INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v4_1', 'lesson-4', '食堂', 'shítáng', 'thực đường', 'nhà ăn', 'Danh từ', '食 (Thực) (Đồ ăn, ẩm thực)', 'Ghép từ các chữ Hán: [食] + [堂].', 'Kết hợp các thành tố [食] + [堂] để tạo thành từ mang nghĩa ''nhà ăn''.', '食堂在教学楼旁边。', 'Shítáng zài jiàoxué lóu pángbiān.', 'Nhà ăn ở cạnh giảng đường.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
