INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v4_14', 'lesson-4', '知道', 'zhīdào', 'đạo', 'biết', 'Động từ', 'Bộ cấu tạo [知] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [知] + [道].', 'Kết hợp các thành tố [知] + [道] để tạo thành từ mang nghĩa ''biết''.', '好的，我去食堂吃饭。啊，你知道图书馆在哪里吗？', 'Hǎo de, wǒ qù shítáng chīfàn. A, nǐ zhīdào túshūguǎn zài nǎli ma?', 'Vâng, tôi đến nhà ăn ăn cơm. À, bạn có biết thư viện ở đâu không?', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
