INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq4_13', 'lesson-4', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “食堂” chứa bộ thủ nào sau đây?', '["Bộ cấu tạo [附] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [不] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [饭] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","食 (Thực) (Đồ ăn, ẩm thực)"]'::jsonb, 3, 'Chữ “食堂” có 食 (Thực) (Đồ ăn, ẩm thực). Ghép từ các chữ Hán: [食] + [堂].', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq4_14', 'lesson-4', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “图书馆” chứa bộ thủ nào sau đây?', '["Bộ cấu tạo [吃] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [图] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [右] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [前] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)"]'::jsonb, 1, 'Chữ “图书馆” có Bộ cấu tạo [图] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán). Ghép từ các chữ Hán: [图] + [书] + [馆].', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq4_15', 'lesson-4', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “楼” chứa bộ thủ nào sau đây?', '["Bộ cấu tạo [不] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [哪] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [知] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [楼] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)"]'::jsonb, 3, 'Chữ “楼” có Bộ cấu tạo [楼] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán). Chữ độc thể / hình thanh gồm Bộ cấu tạo [楼] và các nét bổ trợ.', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq4_16', 'lesson-4', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “教学楼” chứa bộ thủ nào sau đây?', '["Bộ cấu tạo [谢] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [教] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [前] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [知] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)"]'::jsonb, 1, 'Chữ “教学楼” có Bộ cấu tạo [教] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán). Ghép từ các chữ Hán: [教] + [学] + [楼].', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq4_17', 'lesson-4', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 1] Từ đã học “学生” (xuésheng) có nghĩa là gì?', '["quen biết, biết","học sinh","buổi tối","bạn bè"]'::jsonb, 1, 'Ôn tập Bài 1: “学生” (xuésheng) nghĩa là: học sinh.', 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq4_18', 'lesson-4', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 3] Từ đã học “哪” (nǎ) có nghĩa là gì?', '["bạn, cậu, anh, chị... (ngôi thứ hai số ít)","buổi sáng","bạn học","nào, đâu"]'::jsonb, 3, 'Ôn tập Bài 3: “哪” (nǎ) nghĩa là: nào, đâu.', 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq4_19', 'lesson-4', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 2] Từ đã học “马克” (Mǎkè) có nghĩa là gì?', '["sách","Mark (du học sinh Mỹ)","người, con người","tôi, tớ, mình... (ngôi thứ nhất số ít)"]'::jsonb, 1, 'Ôn tập Bài 2: “马克” (Mǎkè) nghĩa là: Mark (du học sinh Mỹ).', 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq4_20', 'lesson-4', NULL, 'expanded_quiz', 'reading', NULL, NULL, '[Mở rộng] Câu “学校的图书馆在哪儿？” có nghĩa tiếng Việt là gì?', '["Cô ấy là học sinh trường nào?","Tôi rất thích cô ấy.","Thư viện của trường ở đâu vậy?","Chào buổi sáng!"]'::jsonb, 2, '学校的图书馆在哪儿？ (Xuéxiào de túshūguǎn zài nǎr?) → Thư viện của trường ở đâu vậy?', 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
