INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq4_22', 'lesson-4', NULL, 'expanded_quiz', 'reading', NULL, NULL, 'Câu “食堂左边” có nghĩa tiếng Việt là gì?', '["Phía bên trái nhà ăn","người Trung Quốc","Tạm biệt!","Em trai tôi chơi trong vườn hoa."]'::jsonb, 0, '食堂左边 (shítáng zuǒbian) → Phía bên trái nhà ăn', 22) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct4_1', 'lesson-4', NULL, 'comprehensive_test', 'listening', '学校的图书馆在哪儿', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Đây là sách gì?","Tôi cũng là học sinh.","Bạn tên là gì?","Thư viện của trường ở đâu vậy?"]'::jsonb, 3, 'Nội dung nghe được: “学校的图书馆在哪儿” (Xuéxiào de túshūguǎn zài nǎr?) → Thư viện của trường ở đâu vậy?', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct4_2', 'lesson-4', NULL, 'comprehensive_test', 'listening', '是啊，谢谢你！', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["谁啊？","好，明天见！","老师好","是啊，谢谢你！"]'::jsonb, 3, 'Câu vừa đọc: “是啊，谢谢你！” (Shì a, xièxie nǐ!) → Đúng vậy, cảm ơn bạn!', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct4_3', 'lesson-4', NULL, 'comprehensive_test', 'listening', '有，食堂在教学楼的右边。', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Cô ấy là Bạch Như Tuyết.","Có, nhà ăn nằm ở bên phải tòa nhà giảng đường.","Bạn có quen biết Nguyễn Nhật Minh không?","Vâng, tôi cũng là du học sinh."]'::jsonb, 1, 'Nội dung nghe được: “有，食堂在教学楼的右边。” (Yǒu, shítáng zài jiàoxué lóu de yòubian.) → Có, nhà ăn nằm ở bên phải tòa nhà giảng đường.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct4_4', 'lesson-4', NULL, 'comprehensive_test', 'listening', '他是我的老师。', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["欢迎！范玉兰也是留学生吗？","他是我的老师。","你好！你也是学生吗？","日明，这位是我的朋友，他叫马克。"]'::jsonb, 1, 'Câu vừa đọc: “他是我的老师。” (Tā shì wǒ de lǎoshī.) → Thầy ấy là thầy giáo của tớ.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct4_5', 'lesson-4', NULL, 'comprehensive_test', 'listening', '你好。请问，学校的食堂在哪儿？', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Ai đấy?","Bạn cũng là du học sinh à?","Xin chào. Xin hỏi nhà ăn của trường ở đâu vậy?","Anh ấy là ai?"]'::jsonb, 2, 'Nội dung nghe được: “你好。请问，学校的食堂在哪儿？” (Nǐ hǎo. Qǐngwèn, xuéxiào de shítáng zài nǎr?) → Xin chào. Xin hỏi nhà ăn của trường ở đâu vậy?', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct4_6', 'lesson-4', NULL, 'comprehensive_test', 'listening', '后面的那座楼是宿舍，食堂在宿舍的左边。', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["我的左边不是教学楼。","学校的图书馆在哪儿","后面的那座楼是宿舍，食堂在宿舍的左边。","我也是学生。"]'::jsonb, 2, 'Câu vừa đọc: “后面的那座楼是宿舍，食堂在宿舍的左边。” (Hòumian de nà zuò lóu shì sùshè, shítáng zài sùshè de zuǒbian.) → Tòa nhà phía sau kia là ký túc xá, nhà ăn nằm ở bên trái ký túc xá.', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct4_7', 'lesson-4', NULL, 'comprehensive_test', 'listening', '请问，附近有食堂吗？', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Chào thầy/Chào cô","Cô giáo không ở trong phòng làm việc.","Xin hỏi quanh đây có nhà ăn không ạ?","Trước mặt bạn là thư viện thành phố."]'::jsonb, 2, 'Nội dung nghe được: “请问，附近有食堂吗？” (Qǐngwèn, fùjìn yǒu shítáng ma?) → Xin hỏi quanh đây có nhà ăn không ạ?', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
