INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct4_22', 'lesson-4', NULL, 'comprehensive_test', 'listening', '请问，附近有食堂吗？ 有，食堂在教学楼的右边。 图书馆也在教学楼前面吗？ 不是，图书馆在教学楼的左边，我们一起去吧！', NULL, 'Theo chỉ dẫn của Minh, thư viện nằm ở phía nào so với tòa giảng đường?', '["Ở bên trái tòa nhà giảng đường","Ở bên phải tòa nhà giảng đường","Ở phía sau nhà ăn","Ở ngoài trường học"]'::jsonb, 0, 'Minh nói rõ: ''图书馆在教学楼的左边'' (bên trái tòa giảng đường).', 22) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
