INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v5_1', 'lesson-5', '时间', 'shíjiān', 'thời gian', 'thời gian', 'Danh từ', 'Bộ cấu tạo [时] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [时] + [间].', 'Kết hợp các thành tố [时] + [间] để tạo thành từ mang nghĩa ''thời gian''.', '这是关于“时间”的常用句子。', 'Zhè shì guānyú ''shíjiān'' de chángyòng jùzi.', 'Đây là câu ví dụ sử dụng từ ''时间'' (thời gian).', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v5_2', 'lesson-5', '时候', 'shíhou', 'thời hậu', 'thời gian, lúc, khi', 'Danh từ', 'Bộ cấu tạo [时] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [时] + [候].', 'Kết hợp các thành tố [时] + [候] để tạo thành từ mang nghĩa ''thời gian, lúc, khi''.', '三点一刻。你什么时候去？', 'Sān diǎn yí kè. Nǐ shénme shíhou qù?', '3 giờ 15 phút. Khi nào bạn đi?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v5_3', 'lesson-5', '点', 'diǎn', 'điểm', 'giờ, châm(lửa)', 'Danh từ / Động từ', 'Bộ cấu tạo [点] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Chữ độc thể / hình thanh gồm Bộ cấu tạo [点] và các nét bổ trợ.', 'Ghi nhớ chữ [点] (giờ, châm(lửa)) qua hình tượng Thành phần biểu ý/biểu âm cơ bản trong chữ Hán.', '我明天上午八点上课。', 'Wǒ míngtiān shàngwǔ bā diǎn shàngkè.', 'Tám giờ sáng ngày mai tớ đi học.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v5_4', 'lesson-5', '点钟', 'diǎnzhōng', 'điểm chung', 'giờ đúng, giờ chẵn, tiếng (đồng hồ)', 'Danh từ', 'Bộ cấu tạo [点] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [点] + [钟].', 'Kết hợp các thành tố [点] + [钟] để tạo thành từ mang nghĩa ''giờ đúng, giờ chẵn, tiếng (đồng hồ)''.', '这是关于“点钟”的常用句子。', 'Zhè shì guānyú ''diǎnzhōng'' de chángyòng jùzi.', 'Đây là câu ví dụ sử dụng từ ''点钟'' (giờ đúng, giờ chẵn, tiếng (đồng hồ)).', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
