INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_5_1_5', 'txt_5_1', '安妮', '对。你知道图书馆在几楼吗？', '对 (duì: đúng, phải)。你知道图书馆在几楼吗？', 'Dùi. Nǐ zhīdào túshūguǎn zài jǐ lóu ma?', 'Đúng rồi. Bạn có biết thư viện ở tầng mấy không?', 5) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_5_1_6', 'txt_5_1', '白茹雪', '三楼，202 号。', '三楼，202 号 (hào: ngày)。', 'Sān lóu, èr líng èr hào.', 'Tầng 3, phòng 202.', 6) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
