INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_5_1_1', 'lesson-5', 'txt_5_1', 'listening', 'listening', '小白，现在几点了？', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Tiểu Bạch, bây giờ mấy giờ rồi?","Cậu mua mấy quả dưa hấu thế?","Một bông hoa","Phía bên trái nhà ăn"]'::jsonb, 0, 'Nội dung nghe được: 小白，现在几点了？ (Xiǎobái, xiànzài jǐ diǎn le?) → Tiểu Bạch, bây giờ mấy giờ rồi?', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_5_1_2', 'lesson-5', 'txt_5_1', 'listening', 'listening', '四点二十分了！怎么了？', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["小白，现在几点了？","昨天下午你去图书馆了吗？","三楼，202 号 (hào: ngày)。","四点二十分了！怎么了？"]'::jsonb, 3, 'Câu vừa đọc: 四点二十分了！怎么了？ (Sì diǎn èr shí fēn le! Zěnmele?) → 4 giờ 20 phút rồi! Có chuyện gì thế?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_5_1_3', 'lesson-5', 'txt_5_1', 'listening', 'listening', '图书馆几点关门？', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Bài tập hôm nay bạn làm xong chưa?","Nhà ăn ở cạnh giảng đường.","Thư viện mấy giờ đóng cửa?","dụng cụ học tập của bọn họ"]'::jsonb, 2, 'Nội dung nghe được: 图书馆几点关门？ (Túshūguǎn jǐ diǎn guānmén?) → Thư viện mấy giờ đóng cửa?', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_5_1_4', 'lesson-5', 'txt_5_1', 'listening', 'listening', '五点半！你想借书吗？', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["小白，现在几点了？","昨天下午你去图书馆了吗？","我明天上午八点上课。","五点半！你想借书吗？"]'::jsonb, 3, 'Câu vừa đọc: 五点半！你想借书吗？ (Wǔ diǎn bàn! Nǐ xiǎng jiè shū ma?) → 5 giờ rưỡi! Bạn muốn mượn sách à?', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_5_2', 'lesson-5', 'Bài khoá #2: Hội thoại giáo trình — Thời gian', 'Hội thoại chuẩn giáo trình Bài 5. Từ vựng chưa học được chú thích phiên âm & nghĩa trong ngoặc.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_5_2_1', 'txt_5_2', '张风', '马克，你明天要上课吗？', '马克，你明天要上课吗？', 'Mǎkè, nǐ míngtiān yào shàngkè ma?', 'Mark, ngày mai bạn có phải lên lớp không?', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_5_2_2', 'txt_5_2', '马克', '上午要上课，下午不上。', '上午要上课，下午不 (bù: không)上 (shàng: trên / lên)。', 'Shàngwǔ yào shàngkè, xiàwǔ bú shàng.', 'Buổi sáng phải lên lớp, buổi chiều không học.', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
