INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_5_2_4', 'txt_5_2', '马克', '三点一刻。你什么时候去？', '三点一刻。你什么时候去？', 'Sān diǎn yí kè. Nǐ shénme shíhou qù?', '3 giờ 15 phút. Khi nào bạn đi?', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_5_2_5', 'txt_5_2', '张风', '我也是。这是我的电话号码 0322110012。明天去上课的时候你给我打电话，好吗？', '我也是。这是我的电话号码 0322110012。明天去上课的时候你给我打 (dǎ: đánh, gọi, chơi)电话，好吗？', 'Wǒ yě shì. Zhè shì wǒ de diànhuà hàomǎ líng sān èr èr yāo yāo líng líng yāo èr. Míngtiān qù shàngkè de shíhou nǐ gěi wǒ dǎ diànhuà, hǎo ma?', 'Tôi cũng vậy. Đây là số điện thoại của tôi: 0322110012. Ngày mai lúc đi học bạn gọi điện cho tôi nhé, được không?', 5) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_5_2_6', 'txt_5_2', '马克', '好！', '好！', 'Hǎo!', 'Được!', 6) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
