INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_5_2_4', 'lesson-5', 'txt_5_2', 'listening', 'listening', '三点一刻。你什么时候去？', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["三点一刻。你什么时候去？","现在是上午八点一刻。","王 (Wáng: họ Vương)老师的房间 (fángjiān: căn phòng)是几号 (hào: ngày)？","五点半！你想借书吗？"]'::jsonb, 0, 'Câu vừa đọc: 三点一刻。你什么时候去？ (Sān diǎn yí kè. Nǐ shénme shíhou qù?) → 3 giờ 15 phút. Khi nào bạn đi?', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
