INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_5_3_8', 'txt_5_3', 'Bài 5', '四点二十分了！怎么了？', '四点二十分了！怎么了？', 'Sì diǎn èr shí fēn le! Zěnmele?', '4 giờ 20 phút rồi! Có chuyện gì thế?', 8) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_5_3_1', 'lesson-5', 'txt_5_3', 'listening', 'listening', '食堂左边', NULL, '[Ôn tập Bài 4] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Phía bên trái nhà ăn","từ điển tiếng Trung","sách của giáo viên","Anh ấy là ai?"]'::jsonb, 0, 'Nội dung nghe được: 食堂左边 (shítáng zuǒbian) → Phía bên trái nhà ăn', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_5_3_2', 'lesson-5', 'txt_5_3', 'listening', 'listening', '我明天上午八点上课。', NULL, '[Bài 5] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["我明天上午八点上课。","王 (Wáng: họ Vương)老师的房间 (fángjiān: căn phòng)是几号 (hào: ngày)？","你什么时候去买 (mǎi: mua)书？","昨天下午你去图书馆了吗？"]'::jsonb, 0, 'Câu vừa đọc: 我明天上午八点上课。 (Wǒ míngtiān shàngwǔ bā diǎn shàngkè.) → Tám giờ sáng ngày mai tớ đi học.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_5_3_3', 'lesson-5', 'txt_5_3', 'listening', 'listening', '明天见！', NULL, '[Ôn tập Bài 2] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Hôm qua anh ấy không đến.","Hẹn gặp lại vào ngày mai! (Hoặc “Mai gặp nhé!”)","Vương là người như thế nào, bạn giới thiệu cho tôi xíu đi.","Nếu ngày mai mưa thì chúng tôi sẽ không đi chơi nữa."]'::jsonb, 1, 'Nội dung nghe được: 明天见！ (Míngtiān jiàn!) → Hẹn gặp lại vào ngày mai! (Hoặc “Mai gặp nhé!”)', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_5_3_4', 'lesson-5', 'txt_5_3', 'listening', 'listening', '你昨天去学校了吗？', NULL, '[Bài 5] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["你昨天去学校了吗？","食堂十一点五十分开 (kāi: mở, lái)门吗？","你什么时候去买 (mǎi: mua)书？","我也是。这是我的电话号码 0322110012。明天去上课的时候你给我打 (dǎ: đánh, gọi, chơi)电话，好吗？"]'::jsonb, 0, 'Câu vừa đọc: 你昨天去学校了吗？ (Nǐ zuótiān qù xuéxiào le ma?) → Hôm qua cậu đã đến trường chưa?', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_5_3_5', 'lesson-5', 'txt_5_3', 'listening', 'listening', '老师好', NULL, '[Ôn tập Bài 1] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Chào thầy/Chào cô","Muốn đạt kết quả tốt thì phải cố gắng học tập.","Tôi muốn học bơi.","Bố tôi đẹp trai như vậy, nên đương nhiên tôi cũng đẹp trai rồi."]'::jsonb, 0, 'Nội dung nghe được: 老师好 (Lǎoshī hǎo) → Chào thầy/Chào cô', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_5_4', 'lesson-5', 'Bài khoá mở rộng: Lịch học ngày mai (Mở rộng)', 'Hội thoại tình huống mới xây dựng dựa trên từ vựng và ngữ pháp Bài 5 (không trùng lặp nguyên văn giáo trình).', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_5_4_1', 'txt_5_4', 'Mark', '张风，现在几点了？', '张风，现在几点了？', 'Zhāng Fēng, xiànzài jǐ diǎn le?', 'Trương Phong, bây giờ mấy giờ rồi?', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_5_4_2', 'txt_5_4', 'Phong', '现在八点一刻，你要去哪儿？', '现在八点一刻，你要去哪儿？', 'Xiànzài bā diǎn yí kè, nǐ yào qù nǎr?', 'Bây giờ là 8 giờ 15 phút, cậu định đi đâu thế?', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_5_4_3', 'txt_5_4', 'Mark', '上午九点半我有一节汉语课，十一点半去食堂。', '上午九点半我有 (yǒu: có)一节汉语 (Hànyǔ: tiếng Trung Quốc)课 (kè: tiết học, bài học)，十一点半去食堂。', 'Shàngwǔ jiǔ diǎn bàn wǒ yǒu yì jié Hànyǔ kè, shíyī diǎn bàn qù shítáng.', '9 giờ 30 sáng tôi có một tiết tiếng Hán, 11 giờ rưỡi đi nhà ăn.', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_5_4_4', 'txt_5_4', 'Phong', '太好了，十一点半我也在食堂等你。', '太 (tài: quá, lắm)好了，十一点半我也在食堂等 (děng: đợi)你。', 'Tài hǎo le, shíyī diǎn bàn wǒ yě zài shítáng děng nǐ.', 'Hay quá, 11 giờ rưỡi tớ cũng đợi cậu ở nhà ăn.', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_5_4_1', 'lesson-5', 'txt_5_4', 'listening', 'listening', '张风，现在几点了？ 现在八点一刻，你要去哪儿？ 上午九点半我有一节汉语课，十一点半去食堂。 太好了，十一点半我也在食堂等你。', NULL, '[Nghe hiểu tình huống mới] Hai bạn hẹn gặp nhau ở nhà ăn vào lúc mấy giờ?', '["9 giờ 30 phút","12 giờ trưa","11 giờ 30 phút (十一点半)","8 giờ 15 phút"]'::jsonb, 2, 'Phong nói ''十一点半我也在食堂等你'' (11 giờ rưỡi đợi ở nhà ăn).', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_5_4_2', 'lesson-5', 'txt_5_4', 'listening', 'listening', '张风，现在几点了？', NULL, '[Mở rộng] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Anh ta thật sự nói như thế.","Tôi học tiếng Hán được 3 năm.","Hai cái cây","Trương Phong, bây giờ mấy giờ rồi?"]'::jsonb, 3, 'Nội dung nghe được: 张风，现在几点了？ (Zhāng Fēng, xiànzài jǐ diǎn le?) → Trương Phong, bây giờ mấy giờ rồi?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_5_4_3', 'lesson-5', 'txt_5_4', 'listening', 'listening', '现在八点一刻，你要去哪儿？', NULL, '[Mở rộng] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["我下午两 (liǎng: hai (số lượng))点零五分在宿舍。","好！","我也是。这是我的电话号码 0322110012。明天去上课的时候你给我打 (dǎ: đánh, gọi, chơi)电话，好吗？","现在八点一刻，你要去哪儿？"]'::jsonb, 3, 'Câu vừa đọc: 现在八点一刻，你要去哪儿？ (Xiànzài bā diǎn yí kè, nǐ yào qù nǎr?) → Bây giờ là 8 giờ 15 phút, cậu định đi đâu thế?', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_5_4_4', 'lesson-5', 'txt_5_4', 'listening', 'listening', '上午九点半我有一节汉语课，十一点半去食堂。', NULL, '[Mở rộng] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Bố mẹ tôi đã kết hôn được 25 năm rồi!","9 giờ 30 sáng tôi có một tiết tiếng Hán, 11 giờ rưỡi đi nhà ăn.","môi trường sống","Tớ muốn đến công viên chạy bộ."]'::jsonb, 1, 'Nội dung nghe được: 上午九点半我有一节汉语课，十一点半去食堂。 (Shàngwǔ jiǔ diǎn bàn wǒ yǒu yì jié Hànyǔ kè, shíyī diǎn bàn qù shítáng.) → 9 giờ 30 sáng tôi có một tiết tiếng Hán, 11 giờ rưỡi đi nhà ăn.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
