INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq5_13', 'lesson-5', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “时间” chứa bộ thủ nào sau đây?', '["Bộ cấu tạo [想] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [时] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [一] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [昨] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)"]'::jsonb, 1, 'Chữ “时间” có Bộ cấu tạo [时] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán). Ghép từ các chữ Hán: [时] + [间].', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq5_14', 'lesson-5', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “时候” chứa bộ thủ nào sau đây?', '["Bộ cấu tạo [时] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [电] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","门 (Môn) (Cánh cửa, lối ra vào)","Bộ cấu tạo [刻] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)"]'::jsonb, 0, 'Chữ “时候” có Bộ cấu tạo [时] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán). Ghép từ các chữ Hán: [时] + [候].', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq5_15', 'lesson-5', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “点” chứa bộ thủ nào sau đây?', '["Bộ cấu tạo [五] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [一] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [电] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [点] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)"]'::jsonb, 3, 'Chữ “点” có Bộ cấu tạo [点] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán). Chữ độc thể / hình thanh gồm Bộ cấu tạo [点] và các nét bổ trợ.', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq5_16', 'lesson-5', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “点钟” chứa bộ thủ nào sau đây?', '["Bộ cấu tạo [七] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","门 (Môn) (Cánh cửa, lối ra vào)","口 (Khẩu) (Miệng, ăn uống, lời nói)","Bộ cấu tạo [点] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)"]'::jsonb, 3, 'Chữ “点钟” có Bộ cấu tạo [点] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán). Ghép từ các chữ Hán: [点] + [钟].', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq5_17', 'lesson-5', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 4] Từ đã học “附近” (fùjìn) có nghĩa là gì?', '["chín","ăn","lân cận, gần đây","buổi tối"]'::jsonb, 2, 'Ôn tập Bài 4: “附近” (fùjìn) nghĩa là: lân cận, gần đây.', 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq5_18', 'lesson-5', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 3] Từ đã học “的” (de) có nghĩa là gì?', '["một","của (trợ từ)","cảm ơn","giờ đúng, giờ chẵn, tiếng (đồng hồ)"]'::jsonb, 1, 'Ôn tập Bài 3: “的” (de) nghĩa là: của (trợ từ).', 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq5_19', 'lesson-5', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 1] Từ đã học “阮日明” (Ruǎn Rìmíng) có nghĩa là gì?', '["cho gọi điện thoại cho ai đó","năm","ngôi (trường), tòa ( nhà)","Nguyễn Nhật Minh"]'::jsonb, 3, 'Ôn tập Bài 1: “阮日明” (Ruǎn Rìmíng) nghĩa là: Nguyễn Nhật Minh.', 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq5_20', 'lesson-5', NULL, 'expanded_quiz', 'reading', NULL, NULL, '[Mở rộng] Câu “现在是上午八点一刻。” có nghĩa tiếng Việt là gì?', '["Cô ấy là giáo viên.","cây thước kẻ của anh ấy","Bây giờ là 8 giờ 15 phút sáng.","chi phí sinh hoạt"]'::jsonb, 2, '现在是上午八点一刻。 (Xiànzài shì shàngwǔ bā diǎn yí kè.) → Bây giờ là 8 giờ 15 phút sáng.', 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
