INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct5_25', 'lesson-5', NULL, 'comprehensive_test', 'listening', '张风，现在几点了？ 现在八点一刻，你要去哪儿？ 上午九点半我有一节汉语课，十一点半去食堂。 太好了，十一点半我也在食堂等你。', NULL, 'Hai bạn hẹn gặp nhau ở nhà ăn vào lúc mấy giờ?', '["9 giờ 30 phút","12 giờ trưa","11 giờ 30 phút (十一点半)","8 giờ 15 phút"]'::jsonb, 2, 'Phong nói ''十一点半我也在食堂等你'' (11 giờ rưỡi đợi ở nhà ăn).', 25) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
