INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v6_1', 'lesson-6', '书店', 'shūdiàn', 'thư điếm', 'hiệu sách', 'Danh từ', 'Bộ cấu tạo [书] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [书] + [店].', 'Kết hợp các thành tố [书] + [店] để tạo thành từ mang nghĩa ''hiệu sách''.', '张风，你知道书店在哪儿吗？', 'Zhāng Fēng, nǐ zhīdào shūdiàn zài nǎr ma?', 'Trương Phong, bạn có biết hiệu sách ở đâu không?', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v6_2', 'lesson-6', '电影院', 'diànyǐngyuàn', 'điện ảnh viện', 'rạp chiếu phim', 'Danh từ', 'Bộ cấu tạo [电] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [电] + [影] + [院].', 'Kết hợp các thành tố [电] + [影] + [院] để tạo thành từ mang nghĩa ''rạp chiếu phim''.', '书店在西边，在美术馆和电影院中间。', 'Shūdiàn zài xībian, zài měishùguǎn hé diànyǐngyuàn zhōngjiān.', 'Hiệu sách ở phía tây, nằm giữa bảo tàng mỹ thuật và rạp chiếu phim.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v6_3', 'lesson-6', '美术馆', 'měishùguǎn', 'Mỹ quán', 'bảo tàng mỹ thuật', 'Danh từ', 'Bộ cấu tạo [美] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [美] + [术] + [馆].', 'Kết hợp các thành tố [美] + [术] + [馆] để tạo thành từ mang nghĩa ''bảo tàng mỹ thuật''.', '书店在西边，在美术馆和电影院中间。', 'Shūdiàn zài xībian, zài měishùguǎn hé diànyǐngyuàn zhōngjiān.', 'Hiệu sách ở phía tây, nằm giữa bảo tàng mỹ thuật và rạp chiếu phim.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v6_4', 'lesson-6', '马路', 'mǎlù', 'Mã', 'đường lớn, đường cái', 'Danh từ', 'Bộ cấu tạo [马] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [马] + [路].', 'Kết hợp các thành tố [马] + [路] để tạo thành từ mang nghĩa ''đường lớn, đường cái''.', '你从这儿一直往东走，到十字路口往左拐，马路西边有一座白色的大楼，那就是书店。', 'Nǐ cóng zhèr yīzhí wǎng dōng zǒu, dào shízìlùkǒu wǎng zuǒ guǎi, mǎlù xībian yǒu yízuò báisè de dàlóu, nà jiùshì shūdiàn.', 'Bạn đi thẳng về phía đông từ đây, đến ngã tư thì rẽ trái, phía tây con đường có một tòa nhà lớn màu trắng, đó chính là hiệu sách.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v6_5', 'lesson-6', '十字路口', 'shízìlùkǒu', 'tự khẩu', 'ngã tư', 'Danh từ', '十 (Thập) (Số mười, hoàn chỉnh)', 'Ghép từ các chữ Hán: [十] + [字] + [路] + [口].', 'Kết hợp các thành tố [十] + [字] + [路] + [口] để tạo thành từ mang nghĩa ''ngã tư''.', '你从这儿一直往东走，到十字路口往左拐，马路西边有一座白色的大楼，那就是书店。', 'Nǐ cóng zhèr yīzhí wǎng dōng zǒu, dào shízìlùkǒu wǎng zuǒ guǎi, mǎlù xībian yǒu yízuò báisè de dàlóu, nà jiùshì shūdiàn.', 'Bạn đi thẳng về phía đông từ đây, đến ngã tư thì rẽ trái, phía tây con đường có một tòa nhà lớn màu trắng, đó chính là hiệu sách.', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v6_6', 'lesson-6', '东边', 'dōngbian', 'biên', 'hướng đông', 'Danh từ', 'Bộ cấu tạo [东] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [东] + [边].', 'Kết hợp các thành tố [东] + [边] để tạo thành từ mang nghĩa ''hướng đông''.', '这是关于“东边”的常用句子。', 'Zhè shì guānyú ''dōngbian'' de chángyòng jùzi.', 'Đây là câu ví dụ sử dụng từ ''东边'' (hướng đông).', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v6_7', 'lesson-6', '西边', 'xībian', 'tây biên', 'hướng tây', 'Danh từ', 'Bộ cấu tạo [西] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [西] + [边].', 'Kết hợp các thành tố [西] + [边] để tạo thành từ mang nghĩa ''hướng tây''.', '书店在西边，在美术馆和电影院中间。', 'Shūdiàn zài xībian, zài měishùguǎn hé diànyǐngyuàn zhōngjiān.', 'Hiệu sách ở phía tây, nằm giữa bảo tàng mỹ thuật và rạp chiếu phim.', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
