INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v6_11', 'lesson-6', '走', 'zǒu', 'từ Hán ngữ', 'đi', 'Động từ', '走 (Tẩu) (Chạy, đi lại, rời đi)', 'Chữ độc thể / hình thanh gồm 走 (Tẩu) và các nét bổ trợ.', 'Ghi nhớ chữ [走] (đi) qua hình tượng Chạy, đi lại, rời đi.', 'A: 请问，去医院怎么走呢？', 'Qǐngwèn, qù yīyuàn zěnme zǒu ne?', 'Xin hỏi, đi đến bệnh viện như thế nào vậy?', 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v6_12', 'lesson-6', '到', 'dào', 'đáo', 'đến', 'Động từ', 'Bộ cấu tạo [到] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Chữ độc thể / hình thanh gồm Bộ cấu tạo [到] và các nét bổ trợ.', 'Ghi nhớ chữ [到] (đến) qua hình tượng Thành phần biểu ý/biểu âm cơ bản trong chữ Hán.', 'B: 你一直往前走，然后右拐就看到医院在你左边。', 'Nǐ yīzhí wǎng qián zǒu, ránhòu yòu guǎi jiù kàndào yīyuàn zài nǐ zuǒbian.', 'Bạn cứ đi thẳng, sau đó rẽ phải là sẽ nhìn thấy bệnh viện ở bên trái của', 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
