INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v6_30', 'lesson-6', '呢', 'ne', 'từ Hán ngữ', 'thế, nhé, nhỉ, cơ (dùng ở cuối câu trần thuật hoặc nghi vấn)', 'Trợ từ', 'Bộ cấu tạo [呢] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Chữ độc thể / hình thanh gồm Bộ cấu tạo [呢] và các nét bổ trợ.', 'Ghi nhớ chữ [呢] (thế, nhé, nhỉ, cơ (dùng ở cuối câu trần thuật hoặc nghi vấn)) qua hình tượng Thành phần biểu ý/biểu âm cơ bản trong chữ Hán.', 'A: 请问，去医院怎么走呢？', 'Qǐngwèn, qù yīyuàn zěnme zǒu ne?', 'Xin hỏi, đi đến bệnh viện như thế nào vậy?', 30) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v6_31', 'lesson-6', '和', 'hé', 'từ Hán ngữ', 'và, với, cùng', 'Liên từ / Giới từ', 'Bộ cấu tạo [和] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Chữ độc thể / hình thanh gồm Bộ cấu tạo [和] và các nét bổ trợ.', 'Ghi nhớ chữ [和] (và, với, cùng) qua hình tượng Thành phần biểu ý/biểu âm cơ bản trong chữ Hán.', '书店在西边，在美术馆和电影院中间。', 'Shūdiàn zài xībian, zài měishùguǎn hé diànyǐngyuàn zhōngjiān.', 'Hiệu sách ở phía tây, nằm giữa bảo tàng mỹ thuật và rạp chiếu phim.', 31) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v6_32', 'lesson-6', '白色', 'báisè', 'bạch sắc', 'màu trắng', 'Danh từ', '白 (Bạch) (Màu trắng, sáng tỏ)', 'Ghép từ các chữ Hán: [白] + [色].', 'Kết hợp các thành tố [白] + [色] để tạo thành từ mang nghĩa ''màu trắng''.', '你从这儿一直往东走，到十字路口往左拐，马路西边有一座白色的大楼，那就是书店。', 'Nǐ cóng zhèr yīzhí wǎng dōng zǒu, dào shízìlùkǒu wǎng zuǒ guǎi, mǎlù xībian yǒu yízuò báisè de dàlóu, nà jiùshì shūdiàn.', 'Bạn đi thẳng về phía đông từ đây, đến ngã tư thì rẽ trái, phía tây con đường có một tòa nhà lớn màu trắng, đó chính là hiệu sách.', 32) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v6_33', 'lesson-6', '周末', 'zhōumò', 'chu mạt', 'cuối tuần', 'Danh từ', 'Bộ cấu tạo [周] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [周] + [末].', 'Kết hợp các thành tố [周] + [末] để tạo thành từ mang nghĩa ''cuối tuần''.', '是，每个周末我都到那儿买书。', 'Shì, měi gè zhōumò wǒ dōu dào nàr mǎi shū.', 'Có, cuối tuần nào tôi cũng đến đó mua sách.', 33) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v6_34', 'lesson-6', '对', 'duì', 'từ Hán ngữ', 'đúng, phải', 'Tính từ', 'Bộ cấu tạo [对] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Chữ độc thể / hình thanh gồm Bộ cấu tạo [对] và các nét bổ trợ.', 'Ghi nhớ chữ [对] (đúng, phải) qua hình tượng Thành phần biểu ý/biểu âm cơ bản trong chữ Hán.', '这是关于“对”的常用句子。', 'Zhè shì guānyú ''duì'' de chángyòng jùzi.', 'Đây là câu ví dụ sử dụng từ ''对'' (đúng, phải).', 34) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g6_1', 'lesson-6', '1. 询问动作行为的方式 - Hỏi phương thức hành động của động tác', '怎 么 + Động từ', ' - Khi muốn hỏi phương thức hoặc phương pháp hành động của động tác, muốn đối phương nói rõ làm chuyện gì đó như thế nào ta sử dụng cấu trúc: A: 请问，去医院怎么走呢？ Qǐngwèn, qù yīyuàn zěnme zǒu ne? Xin hỏi, đi đến bệnh viện như thế nào vậy? B: 你一直往前走，然后右拐就看到', NULL, '[{"hanzi":"A: 请问，去医院怎么走呢？","pinyin":"Qǐngwèn, qù yīyuàn zěnme zǒu ne?","meaning":"Xin hỏi, đi đến bệnh viện như thế nào vậy?"},{"hanzi":"B: 你一直往前走，然后右拐就看到医院在你左边。","pinyin":"Nǐ yīzhí wǎng qián zǒu, ránhòu yòu guǎi jiù kàndào yīyuàn zài nǐ zuǒbian.","meaning":"Bạn cứ đi thẳng, sau đó rẽ phải là sẽ nhìn thấy bệnh viện ở bên trái của"}]'::jsonb, 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g6_2', 'lesson-6', '2. 从...... 到......: Từ… đến…', '从 + Từ chỉ địa điểm/thời gian + 到 + Từ chỉ địa điểm/thời gian', ' a. Khái niệm Cấu trúc “从...... 到……” biểu thị ý nghĩa “từ… đến…”, từ cái gì đến cái gì. Tân ngữ phía sau “从” và “到” thường thuộc cùng một trường từ vựng, có thể là từ chỉ thời gian, địa điểm hoặc một cột mốc nào đó. b. Cấu trúc 从我家到银行有二十公里。 Cóng wǒji', NULL, '[{"hanzi":"A: 你知道这个字怎么写吗？","pinyin":"Nǐ zhīdào zhè gè zì zěnme xiě ma?","meaning":"Cậu có biết chữ này viết như thế nào không?"},{"hanzi":"B: 我不知道。","pinyin":"Wǒ bù zhīdào.","meaning":"Mình không biết."}]'::jsonb, 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g6_3', 'lesson-6', '3. 每...... 都......: Mỗi/từng… đều…', 'Cấu trúc câu ngữ pháp trọng tâm', ' ●       Khái niệm Cấu trúc “每...... 都......” biểu thị không có ngoại lệ, tất cả đối tượng thuộc trường từ vựng của đại từ hay danh từ phía sau 每  đều có tính chất, trạng thái hoặc hành động phía sau 都. 每一个学生都坐公共汽车上课。 Měi yígè xuésheng dōu zuò gōnggò', NULL, '[{"hanzi":"A: 请问，超市怎么走呢？","pinyin":"Qǐngwèn, chāoshì zěnme zǒu ne?","meaning":"Xin hỏi đến siêu thị đi thế nào vậy?"},{"hanzi":"B: 你往左拐，然后一直往前走就到。","pinyin":"Nǐ wǎng zuǒ guǎi, ránhòu yīzhí wǎng qián","meaning":"zǒu jiù dào."}]'::jsonb, 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_6_1', 'lesson-6', 'Bài khoá #1: Hội thoại giáo trình — Hỏi đường', 'Hội thoại chuẩn giáo trình Bài 6. Từ vựng chưa học được chú thích phiên âm & nghĩa trong ngoặc.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_6_1_1', 'txt_6_1', '马克', '张风，你知道书店在哪儿吗？', '张风，你知道书店在哪儿吗？', 'Zhāng Fēng, nǐ zhīdào shūdiàn zài nǎr ma?', 'Trương Phong, bạn có biết hiệu sách ở đâu không?', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_6_1_2', 'txt_6_1', '张风', '书店在西边，在美术馆和电影院中间。', '书店在西边，在美术馆和电影院中间。', 'Shūdiàn zài xībian, zài měishùguǎn hé diànyǐngyuàn zhōngjiān.', 'Hiệu sách ở phía tây, nằm giữa bảo tàng mỹ thuật và rạp chiếu phim.', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_6_1_3', 'txt_6_1', '马克', '离这儿远吗？', '离这儿远吗？', 'Lí zhèr yuǎn ma?', 'Cách đây có xa không?', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_6_1_4', 'txt_6_1', '张风', '不远，很近。从这儿到那儿有二百米。', '不 (bù: không)远，很近。从这儿到那儿有二百 (bǎi: trăm)米。', 'Bù yuǎn，hěn jìn. Cóng zhèr dào nàr yǒu èrbǎi mǐ.', 'Không xa, rất gần. Từ đây đến đó khoảng 200 mét.', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_6_1_5', 'txt_6_1', '马克', '怎么走呢？', '怎么走呢？', 'Zěnme zǒu ne?', 'Đi như thế nào vậy?', 5) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_6_1_6', 'txt_6_1', '张风', '你从这儿一直往东走，到十字路口往左拐，马路西边有一座白色的大楼，那就是书店。', '你从这儿一直往东 (dōng: phía Đông)走，到十字路口往左 (zuǒ: trái)拐，马路西边有一座白色的大 (dà: to, lớn)楼，那就是书店。', 'Nǐ cóng zhèr yīzhí wǎng dōng zǒu, dào shízìlùkǒu wǎng zuǒ guǎi, mǎlù xībian yǒu yízuò báisè de dàlóu, nà jiùshì shūdiàn.', 'Bạn đi thẳng về phía đông từ đây, đến ngã tư thì rẽ trái, phía tây con đường có một tòa nhà lớn màu trắng, đó chính là hiệu sách.', 6) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_6_1_7', 'txt_6_1', '马克', '谢谢，你常到那儿买书吗？', '谢谢，你常到那儿买书吗？', 'Xièxie, nǐ cháng dào nàr mǎi shū ma?', 'Cảm ơn, bạn có hay đến đó mua sách không?', 7) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_6_1_8', 'txt_6_1', '张风', '是，每个周末我都到那儿买书。', '是，每个周末我都到那儿买书。', 'Shì, měi gè zhōumò wǒ dōu dào nàr mǎi shū.', 'Có, cuối tuần nào tôi cũng đến đó mua sách.', 8) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_6_1_1', 'lesson-6', 'txt_6_1', 'listening', 'listening', '张风，你知道书店在哪儿吗？', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Trương Phong, bạn có biết hiệu sách ở đâu không?","Không phải ngoài trời đang mưa à? Cậu dùng ô của tớ đi! (Khẳng định","Tạm biệt!","Sao bố vẫn chưa tan làm, con sắp đói chết rồi!"]'::jsonb, 0, 'Nội dung nghe được: 张风，你知道书店在哪儿吗？ (Zhāng Fēng, nǐ zhīdào shūdiàn zài nǎr ma?) → Trương Phong, bạn có biết hiệu sách ở đâu không?', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_6_1_2', 'lesson-6', 'txt_6_1', 'listening', 'listening', '书店在西边，在美术馆和电影院中间。', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["是，每个周末我都到那儿买书。","怎么走呢？","每一个学生都坐 (zuò: ngồi)公共汽车 (gōnggòng qìchē: xe buýt)上课。","书店在西边，在美术馆和电影院中间。"]'::jsonb, 3, 'Câu vừa đọc: 书店在西边，在美术馆和电影院中间。 (Shūdiàn zài xībian, zài měishùguǎn hé diànyǐngyuàn zhōngjiān.) → Hiệu sách ở phía tây, nằm giữa bảo tàng mỹ thuật và rạp chiếu phim.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_6_1_3', 'lesson-6', 'txt_6_1', 'listening', 'listening', '离这儿远吗？', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Cách đây có xa không?","Anh ta mời tôi ngày mai tới nhà dùng cơm.","tôi của sau này, tôi của tương lai","Lớp cậu có bao nhiêu học sinh?"]'::jsonb, 0, 'Nội dung nghe được: 离这儿远吗？ (Lí zhèr yuǎn ma?) → Cách đây có xa không?', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_6_1_4', 'lesson-6', 'txt_6_1', 'listening', 'listening', '不远，很近。从这儿到那儿有二百米。', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["怎么走呢？","张风，你知道书店在哪儿吗？","A: 请问 (qǐngwèn: xin hỏi)，去医院 (yīyuàn: bệnh viện)怎么走呢？","不 (bù: không)远，很近。从这儿到那儿有二百 (bǎi: trăm)米。"]'::jsonb, 3, 'Câu vừa đọc: 不远，很近。从这儿到那儿有二百米。 (Bù yuǎn，hěn jìn. Cóng zhèr dào nàr yǒu èrbǎi mǐ.) → Không xa, rất gần. Từ đây đến đó khoảng 200 mét.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_6_2', 'lesson-6', 'Bài nghe tổng hợp: Ôn tập lũy tiến (Bài 1 – Bài 6)', 'Kết hợp từ vựng & mẫu câu đã học từ Bài 1 đến Bài 5 cùng trọng tâm Bài 6 để củng cố phản xạ nghe.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_6_2_1', 'txt_6_2', 'Ôn Bài 5', '你昨天去学校了吗？', '你昨天去学校了吗？', 'Nǐ zuótiān qù xuéxiào le ma?', 'Hôm qua cậu đã đến trường chưa?', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_6_2_2', 'txt_6_2', 'Bài 6', '张风，你知道书店在哪儿吗？', '张风，你知道书店在哪儿吗？', 'Zhāng Fēng, nǐ zhīdào shūdiàn zài nǎr ma?', 'Trương Phong, bạn có biết hiệu sách ở đâu không?', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_6_2_3', 'txt_6_2', 'Ôn Bài 3', '他是谁？', '他是谁？', 'Tā shì shéi?', 'Anh ấy là ai?', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_6_2_4', 'txt_6_2', 'Bài 6', '书店在西边，在美术馆和电影院中间。', '书店在西边，在美术馆和电影院中间。', 'Shūdiàn zài xībian, zài měishùguǎn hé diànyǐngyuàn zhōngjiān.', 'Hiệu sách ở phía tây, nằm giữa bảo tàng mỹ thuật và rạp chiếu phim.', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_6_2_5', 'txt_6_2', 'Ôn Bài 1', '你是日明吗？', '你是日明吗？', 'Nǐ shì Rìmíng ma?', 'Cậu là Nhật Minh phải không?', 5) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_6_2_6', 'txt_6_2', 'Bài 6', '离这儿远吗？', '离这儿远吗？', 'Lí zhèr yuǎn ma?', 'Cách đây có xa không?', 6) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_6_2_7', 'txt_6_2', 'Ôn Bài 4', '食堂左边', '食堂左边', 'shítáng zuǒbian', 'Phía bên trái nhà ăn', 7) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_6_2_8', 'txt_6_2', 'Bài 6', '怎么走呢？', '怎么走呢？', 'Zěnme zǒu ne?', 'Đi như thế nào vậy?', 8) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_6_2_1', 'lesson-6', 'txt_6_2', 'listening', 'listening', '你昨天去学校了吗？', NULL, '[Ôn tập Bài 5] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Năm nay cháu mấy tuổi rồi (Hỏi trẻ em dưới mười tuổi)","người Trung Quốc","Tôi đợi các bạn ở cổng trường.","Hôm qua cậu đã đến trường chưa?"]'::jsonb, 3, 'Nội dung nghe được: 你昨天去学校了吗？ (Nǐ zuótiān qù xuéxiào le ma?) → Hôm qua cậu đã đến trường chưa?', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_6_2_2', 'lesson-6', 'txt_6_2', 'listening', 'listening', '张风，你知道书店在哪儿吗？', NULL, '[Bài 6] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["B: 你一直往前 (qián: trước)走，然后 (ránhòu: đầu tiên... sau đó...)右 (yòu: phải)拐就看到医院 (yīyuàn: bệnh viện)在你左边。","张风，你知道书店在哪儿吗？","B: 我打算 (dǎsuan: dự định)坐 (zuò: ngồi)公共汽车 (gōnggòng qìchē: xe buýt)。","离这儿远吗？"]'::jsonb, 1, 'Câu vừa đọc: 张风，你知道书店在哪儿吗？ (Zhāng Fēng, nǐ zhīdào shūdiàn zài nǎr ma?) → Trương Phong, bạn có biết hiệu sách ở đâu không?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_6_2_3', 'lesson-6', 'txt_6_2', 'listening', 'listening', '他是谁？', NULL, '[Ôn tập Bài 3] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Anh ấy là ai?","Ngày mai có lẽ là ngày nắng.","Bọn họ chỉ quan tâm đến bản thân mình mà thôi.","Lúc đó, người con gái ấy khóc không ngớt."]'::jsonb, 0, 'Nội dung nghe được: 他是谁？ (Tā shì shéi?) → Anh ấy là ai?', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_6_2_4', 'lesson-6', 'txt_6_2', 'listening', 'listening', '书店在西边，在美术馆和电影院中间。', NULL, '[Bài 6] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["书店在西边，在美术馆和电影院中间。","图书馆南边是什么地方？","B: 我不 (bù: không)知道。","到前面那个十字路口往右 (yòu: phải)拐。"]'::jsonb, 0, 'Câu vừa đọc: 书店在西边，在美术馆和电影院中间。 (Shūdiàn zài xībian, zài měishùguǎn hé diànyǐngyuàn zhōngjiān.) → Hiệu sách ở phía tây, nằm giữa bảo tàng mỹ thuật và rạp chiếu phim.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_6_2_5', 'lesson-6', 'txt_6_2', 'listening', 'listening', '你是日明吗？', NULL, '[Ôn tập Bài 1] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Cậu là Nhật Minh phải không?","đất nước (quốc gia) của chúng tôi","Tối qua ngủ có ngon không?","Có khả năng ông chủ quên hôm nay có cuộc họp rồi."]'::jsonb, 0, 'Nội dung nghe được: 你是日明吗？ (Nǐ shì Rìmíng ma?) → Cậu là Nhật Minh phải không?', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_6_3', 'lesson-6', 'Bài khoá mở rộng: Chỉ đường đến hiệu sách (Mở rộng)', 'Hội thoại tình huống mới xây dựng dựa trên từ vựng và ngữ pháp Bài 6 (không trùng lặp nguyên văn giáo trình).', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_6_3_1', 'txt_6_3', 'Annie', '请问，电影院附近有书店吗？', '请问 (qǐngwèn: xin hỏi)，电影院附近有书店吗？', 'Qǐngwèn, diànyǐngyuàn fùjìn yǒu shūdiàn ma?', 'Xin hỏi quanh rạp chiếu phim có hiệu sách không?', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_6_3_2', 'txt_6_3', 'Phong', '有，书店在电影院和美术馆中间，离这儿只有三百米。', '有，书店在电影院和美术馆中间，离这儿只 (zhī: con)有三百 (bǎi: trăm)米。', 'Yǒu, shūdiàn zài diànyǐngyuàn hé měishùguǎn zhōngjiān, lí zhèr zhǐyǒu sānbǎi mǐ.', 'Có, hiệu sách nằm giữa rạp chiếu phim và bảo tàng mỹ thuật, cách đây chỉ 300 mét.', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_6_3_3', 'txt_6_3', 'Annie', '从这儿到书店怎么走？', '从这儿到书店怎么走？', 'Cóng zhèr dào shūdiàn zěnme zǒu?', 'Từ đây đến hiệu sách đi như thế nào?', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_6_3_4', 'txt_6_3', 'Phong', '你一直往北走，到十字路口往右拐就到了。', '你一直往北 (běi: phía Bắc)走，到十字路口往右 (yòu: phải)拐就到了。', 'Nǐ yīzhí wǎng běi zǒu, dào shízìlùkǒu wǎng yòu guǎi jiù dào le.', 'Bạn cứ đi thẳng về phía bắc, đến ngã tư rẽ phải là tới.', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_6_3_1', 'lesson-6', 'txt_6_3', 'listening', 'listening', '请问，电影院附近有书店吗？ 有，书店在电影院和美术馆中间，离这儿只有三百米。 从这儿到书店怎么走？ 你一直往北走，到十字路口往右拐就到了。', NULL, '[Nghe hiểu tình huống mới] Để đến được hiệu sách từ chỗ hiện tại, Annie cần đi hướng nào?', '["Đi thẳng hướng bắc rồi rẽ phải ở ngã tư","Đi hướng nam rồi rẽ trái","Quay lại cổng trường","Đi xe buýt hai tiếng"]'::jsonb, 0, 'Phong chỉ: ''一直往北走，到十字路口往右拐'' (đi thẳng hướng bắc, đến ngã tư rẽ phải).', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_6_3_2', 'lesson-6', 'txt_6_3', 'listening', 'listening', '请问，电影院附近有书店吗？', NULL, '[Mở rộng] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Con ăn nhiều rau chút, có lợi cho sức khỏe!","Chào buổi tối!","Lúc cô giáo giảng bài thì tôi đang tra từ mới.","Xin hỏi quanh rạp chiếu phim có hiệu sách không?"]'::jsonb, 3, 'Nội dung nghe được: 请问，电影院附近有书店吗？ (Qǐngwèn, diànyǐngyuàn fùjìn yǒu shūdiàn ma?) → Xin hỏi quanh rạp chiếu phim có hiệu sách không?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_6_3_3', 'lesson-6', 'txt_6_3', 'listening', 'listening', '有，书店在电影院和美术馆中间，离这儿只有三百米。', NULL, '[Mở rộng] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["A: 你知道这个字 (zì: chữ)怎么写 (xiě: viết)吗？","有，书店在电影院和美术馆中间，离这儿只 (zhī: con)有三百 (bǎi: trăm)米。","B: 你一直往前 (qián: trước)走，然后 (ránhòu: đầu tiên... sau đó...)右 (yòu: phải)拐就看到医院 (yīyuàn: bệnh viện)在你左边。","怎么走呢？"]'::jsonb, 1, 'Câu vừa đọc: 有，书店在电影院和美术馆中间，离这儿只有三百米。 (Yǒu, shūdiàn zài diànyǐngyuàn hé měishùguǎn zhōngjiān, lí zhèr zhǐyǒu sānbǎi mǐ.) → Có, hiệu sách nằm giữa rạp chiếu phim và bảo tàng mỹ thuật, cách đây chỉ 300 mét.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_6_3_4', 'lesson-6', 'txt_6_3', 'listening', 'listening', '从这儿到书店怎么走？', NULL, '[Mở rộng] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Cậu là ai thế?","Từ đây đến hiệu sách đi như thế nào?","Anh ấy đọc sách trong thư viện.","Con nên uống nước lọc nhiều hơn và uống ít nước ngọt thôi!"]'::jsonb, 1, 'Nội dung nghe được: 从这儿到书店怎么走？ (Cóng zhèr dào shūdiàn zěnme zǒu?) → Từ đây đến hiệu sách đi như thế nào?', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
