INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr6_vi_4', 'lesson-6', 'vi_to_zh', 'Cậu đi gì đến siêu thị thế?', NULL, NULL, 'A: 你怎么去超市呢？', NULL, 'nǐ zěnme qù chāoshì ne', '[]'::jsonb, 'Gợi ý Pinyin: Nǐ zěnme qù chāoshì ne? | Từ chưa học: 超市 (chāoshì: siêu thị)', 'Cậu đi gì đến siêu thị thế? → A: 你怎么去超市呢？ (Nǐ zěnme qù chāoshì ne?)', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr6_zh_1', 'lesson-6', 'zh_to_vi', '[Mở rộng] 图书馆南边是什么地方？', '图书馆南边是什么地方？', 'Túshūguǎn nánbian shì shénme dìfang?', NULL, 'Phía nam thư viện là địa điểm nào vậy?', NULL, '["Phía","nam","thư"]'::jsonb, 'Pinyin: Túshūguǎn nánbian shì shénme dìfang?', '图书馆南边是什么地方？ (Túshūguǎn nánbian shì shénme dìfang?) nghĩa là: Phía nam thư viện là địa điểm nào vậy?', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
