INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr6_zh_3', 'lesson-6', 'zh_to_vi', '每天 (tiān: ngày, trời)他都去图书馆借书。', '每天他都去图书馆借书。', 'Měitiān tā dōu qù túshūguǎn jiè shū.', NULL, 'Mỗi ngày anh ấy đều đến thư viện mượn sách.', NULL, '["Mỗi","ngày","anh"]'::jsonb, 'Pinyin: Měitiān tā dōu qù túshūguǎn jiè shū.', '每天他都去图书馆借书。 (Měitiān tā dōu qù túshūguǎn jiè shū.) nghĩa là: Mỗi ngày anh ấy đều đến thư viện mượn sách.', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
