INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq6_13', 'lesson-6', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “书店” chứa bộ thủ nào sau đây?', '["Bộ cấu tạo [就] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [书] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [马] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","木 (Mộc) (Cây cối, gỗ)"]'::jsonb, 1, 'Chữ “书店” có Bộ cấu tạo [书] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán). Ghép từ các chữ Hán: [书] + [店].', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq6_14', 'lesson-6', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “电影院” chứa bộ thủ nào sau đây?', '["Bộ cấu tạo [周] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [远] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [近] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [电] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)"]'::jsonb, 3, 'Chữ “电影院” có Bộ cấu tạo [电] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán). Ghép từ các chữ Hán: [电] + [影] + [院].', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq6_15', 'lesson-6', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “美术馆” chứa bộ thủ nào sau đây?', '["Bộ cấu tạo [东] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [和] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [到] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [美] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)"]'::jsonb, 3, 'Chữ “美术馆” có Bộ cấu tạo [美] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán). Ghép từ các chữ Hán: [美] + [术] + [馆].', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq6_16', 'lesson-6', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “马路” chứa bộ thủ nào sau đây?', '["Bộ cấu tạo [怎] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","米 (Mễ) (Hạt gạo, tinh bột)","Bộ cấu tạo [书] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [马] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)"]'::jsonb, 3, 'Chữ “马路” có Bộ cấu tạo [马] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán). Ghép từ các chữ Hán: [马] + [路].', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq6_17', 'lesson-6', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 4] Từ đã học “去” (qù) có nghĩa là gì?', '["Mark (du học sinh Mỹ)","biết","đừng khách sáo","đi"]'::jsonb, 3, 'Ôn tập Bài 4: “去” (qù) nghĩa là: đi.', 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq6_18', 'lesson-6', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 2] Từ đã học “张风” (Zhāng Fēng) có nghĩa là gì?', '["cửa, cổng","Trương Phong (sinh viên người Trung Quốc đại học Thanh Hoa)","vào học, lên lớp","nào, đâu"]'::jsonb, 1, 'Ôn tập Bài 2: “张风” (Zhāng Fēng) nghĩa là: Trương Phong (sinh viên người Trung Quốc đại học Thanh Hoa).', 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq6_19', 'lesson-6', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 1] Từ đã học “你们” (nǐmen) có nghĩa là gì?', '["có","thời gian","hai","các bạn, các anh, các chị… (ngôi thứ hai số nhiều)"]'::jsonb, 3, 'Ôn tập Bài 1: “你们” (nǐmen) nghĩa là: các bạn, các anh, các chị… (ngôi thứ hai số nhiều).', 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq6_20', 'lesson-6', NULL, 'expanded_quiz', 'reading', NULL, NULL, '[Mở rộng] Câu “电影院在美术馆的东边。” có nghĩa tiếng Việt là gì?', '["con đường này","hai quyển sách","Xin hỏi, đi đến bệnh viện như thế nào vậy?","Rạp chiếu phim nằm ở phía đông bảo tàng mỹ thuật."]'::jsonb, 3, '电影院在美术馆的东边。 (Diànyǐngyuàn zài měishùguǎn de dōngbian.) → Rạp chiếu phim nằm ở phía đông bảo tàng mỹ thuật.', 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq6_21', 'lesson-6', NULL, 'expanded_quiz', 'reading', NULL, NULL, '[Đọc hiểu mở rộng] Đọc đoạn hội thoại:
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq6_22', 'lesson-6', NULL, 'expanded_quiz', 'reading', NULL, NULL, 'Câu “B: 我不 (bù: không)知道。” có nghĩa tiếng Việt là gì?', '["Tôi là Trần Anh.","Bệnh viện ở bên phải trường học của chúng ta.","Mình không biết.","Phía nam thư viện là địa điểm nào vậy?"]'::jsonb, 2, 'B: 我不知道。 (Wǒ bù zhīdào.) → Mình không biết.', 22) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct6_1', 'lesson-6', NULL, 'comprehensive_test', 'listening', '书店在西边，在美术馆和电影院中间。', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Tôi tên là Mark. Cô ấy tên là gì?","Hiệu sách ở phía tây, nằm giữa bảo tàng mỹ thuật và rạp chiếu phim.","Nguyễn Nhật Minh cũng là học sinh à?","Các em học sinh, chào buổi sáng!"]'::jsonb, 1, 'Nội dung nghe được: “书店在西边，在美术馆和电影院中间。” (Shūdiàn zài xībian, zài měishùguǎn hé diànyǐngyuàn zhōngjiān.) → Hiệu sách ở phía tây, nằm giữa bảo tàng mỹ thuật và rạp chiếu phim.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct6_2', 'lesson-6', NULL, 'comprehensive_test', 'listening', '你昨天去学校了吗？', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["安妮同学！你好！这是谁啊？","你昨天去学校了吗？","你好，同学！请问你贵姓？","食堂左边"]'::jsonb, 1, 'Câu vừa đọc: “你昨天去学校了吗？” (Nǐ zuótiān qù xuéxiào le ma?) → Hôm qua cậu đã đến trường chưa?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct6_3', 'lesson-6', NULL, 'comprehensive_test', 'listening', '请问，超市怎么走呢？', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Bạn cứ đi thẳng, sau đó rẽ phải là sẽ nhìn thấy bệnh viện ở bên trái của","Hiệu sách ở phía tây, nằm giữa bảo tàng mỹ thuật và rạp chiếu phim.","Chiều hôm qua bạn có đi thư viện không?","Xin hỏi đến siêu thị đi thế nào vậy?"]'::jsonb, 3, 'Nội dung nghe được: “请问，超市怎么走呢？” (Qǐngwèn, chāoshì zěnme zǒu ne?) → Xin hỏi đến siêu thị đi thế nào vậy?', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct6_4', 'lesson-6', NULL, 'comprehensive_test', 'listening', '中午好同学们', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["晚上好！","学校的图书馆在哪儿","你往左拐，然后一直往前走就到。","中午好同学们"]'::jsonb, 3, 'Câu vừa đọc: “中午好同学们” (Zhōngwǔ hǎo, tóngxuémen!) → Chào buổi trưa các bạn học sinh!', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct6_5', 'lesson-6', NULL, 'comprehensive_test', 'listening', '我的朋友在食堂吃饭', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Bạn của tôi đang ăn cơm ở nhà ăn.","Từ đây đến hiệu sách đi như thế nào?","Đúng rồi. Tôi tên là Trương Phong. Bạn tên là gì?","Thầy giáo đang đợi bạn ở bên ngoài."]'::jsonb, 0, 'Nội dung nghe được: “我的朋友在食堂吃饭” (Wǒ de péngyou zài shítáng chīfàn.) → Bạn của tôi đang ăn cơm ở nhà ăn.', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct6_6', 'lesson-6', NULL, 'comprehensive_test', 'listening', '从这儿到书店怎么走？', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["她很漂亮。","从这儿到书店怎么走？","你怎么去超市呢？","从宿舍到食堂怎么走"]'::jsonb, 1, 'Câu vừa đọc: “从这儿到书店怎么走？” (Cóng zhèr dào shūdiàn zěnme zǒu?) → Từ đây đến hiệu sách đi như thế nào?', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct6_7', 'lesson-6', NULL, 'comprehensive_test', 'listening', '你知道这个字怎么写吗？', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Thầy Lưu là giáo viên của trường.","Tạm biệt!","Cậu có biết chữ này viết như thế nào không?","Nguyễn Nhật Minh cũng là học sinh à?"]'::jsonb, 2, 'Nội dung nghe được: “你知道这个字怎么写吗？” (Nǐ zhīdào zhè gè zì zěnme xiě ma?) → Cậu có biết chữ này viết như thế nào không?', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct6_8', 'lesson-6', NULL, 'comprehensive_test', 'listening', '谢谢，你常到那儿买书吗？', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["我也很高兴认识你。","我明天上午八点上课。","谢谢，你常到那儿买书吗？","这是我的书。"]'::jsonb, 2, 'Câu vừa đọc: “谢谢，你常到那儿买书吗？” (Xièxie, nǐ cháng dào nàr mǎi shū ma?) → Cảm ơn, bạn có hay đến đó mua sách không?', 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
