INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v7_3', 'lesson-7', '尺子', 'chǐzi', 'từ Hán ngữ', 'thước kẻ', 'Danh từ', '子 (Tử) (Đứa con, trẻ nhỏ, người trí thức)', 'Ghép từ các chữ Hán: [尺] + [子].', 'Kết hợp các thành tố [尺] + [子] để tạo thành từ mang nghĩa ''thước kẻ''.', '他的尺子', 'tā de chǐzi', 'cây thước kẻ của anh ấy', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v7_4', 'lesson-7', '笔记本', 'bǐjìběn', 'từ Hán ngữ', 'vở ghi, sổ ghi', 'Danh từ', 'Bộ cấu tạo [笔] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [笔] + [记] + [本].', 'Kết hợp các thành tố [笔] + [记] + [本] để tạo thành từ mang nghĩa ''vở ghi, sổ ghi''.', '我想去商店买两支圆珠笔、一把尺子和三本笔记本。你想去吗？', 'Wǒ xiǎng qù shāngdiàn mǎi liǎng zhī yuánzhūbǐ, yī bǎ chǐzi hé sān běn bǐjìběn. Nǐ xiǎng qù ma?', 'Tôi muốn đi cửa hàng mua hai cây bút bi, một cây thước kẻ và ba quyển vở ghi chép. Bạn có muốn đi không?', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
