INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v7_10', 'lesson-7', '蓝色', 'lán sè', 'lam sắc', 'màu xanh lam', 'Danh từ', 'Bộ cấu tạo [蓝] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [蓝] + [色].', 'Kết hợp các thành tố [蓝] + [色] để tạo thành từ mang nghĩa ''màu xanh lam''.', '哇，真好看啊！你买的那家商店有蓝色的书包吗？', 'Wa, zhēn hǎokàn a! Nǐ mǎi de nà jiā shāngdiàn yǒu lán sè de shūbāo ma?', 'Chà, đẹp quá đi mất! Cửa hàng bạn mua có cặp sách màu xanh dương không?', 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
