INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v7_12', 'lesson-7', '等', 'děng', 'từ Hán ngữ', 'đợi', 'Động từ', 'Bộ cấu tạo [等] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Chữ độc thể / hình thanh gồm Bộ cấu tạo [等] và các nét bổ trợ.', 'Ghi nhớ chữ [等] (đợi) qua hình tượng Thành phần biểu ý/biểu âm cơ bản trong chữ Hán.', '那今天下午四点我在学校门口等你。我们一起去，好吗？', 'Nà jīntiān xiàwǔ sìdiǎn wǒ zài xuéxiào ménkǒu děng nǐ. Wǒmen yīqǐ qù, hǎo ma?', 'Vậy chiều nay 4 giờ tôi đợi bạn ở cổng trường. Chúng ta cùng đi nhé, được không?', 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v7_13', 'lesson-7', '觉得', 'juéde', 'từ Hán ngữ', 'thấy, cảm thấy', 'Động từ', 'Bộ cấu tạo [觉] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [觉] + [得].', 'Kết hợp các thành tố [觉] + [得] để tạo thành từ mang nghĩa ''thấy, cảm thấy''.', '小白，你觉得我今天买的书包怎么样？', 'Xiǎobái, nǐ juéde wǒ jīntiān mǎi de shūbāo zěnmeyàng?', 'Tiểu Bạch, bạn thấy chiếc cặp sách hôm nay tôi mua thế nào?', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v7_14', 'lesson-7', '好看', 'hǎokàn', 'hảo khán', 'đẹp, dễ nhìn, hay, thú vị', 'Tính từ', 'Bộ cấu tạo [好] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [好] + [看].', 'Kết hợp các thành tố [好] + [看] để tạo thành từ mang nghĩa ''đẹp, dễ nhìn, hay, thú vị''.', '哇，真好看啊！你买的那家商店有蓝色的书包吗？', 'Wa, zhēn hǎokàn a! Nǐ mǎi de nà jiā shāngdiàn yǒu lán sè de shūbāo ma?', 'Chà, đẹp quá đi mất! Cửa hàng bạn mua có cặp sách màu xanh dương không?', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v7_15', 'lesson-7', '漂亮', 'piàoliang', 'từ Hán ngữ', 'đẹp, xinh đẹp', 'Tính từ', 'Bộ cấu tạo [漂] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [漂] + [亮].', 'Kết hợp các thành tố [漂] + [亮] để tạo thành từ mang nghĩa ''đẹp, xinh đẹp''.', '后面的姑娘很漂亮。', 'Hòumian de gūniang hěn piàoliang.', 'Cô gái ở phía sau rất xinh đẹp.', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v7_16', 'lesson-7', '家', 'jiā', 'gia', 'ngôi, hiệu, tiệm, quán (lượng từ của cửa hàng, công ty,...)', 'Lượng từ', 'Bộ cấu tạo [家] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Chữ độc thể / hình thanh gồm Bộ cấu tạo [家] và các nét bổ trợ.', 'Ghi nhớ chữ [家] (ngôi, hiệu, tiệm, quán (lượng từ của cửa hàng, công ty,...)) qua hình tượng Thành phần biểu ý/biểu âm cơ bản trong chữ Hán.', '我们国家', 'wǒmen guójiā', 'đất nước (quốc gia) của chúng tôi', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v7_17', 'lesson-7', '支', 'zhī', 'từ Hán ngữ', 'cái, chiếc, cây (lượng từ của cái bút,...)', 'Lượng từ', 'Bộ cấu tạo [支] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Chữ độc thể / hình thanh gồm Bộ cấu tạo [支] và các nét bổ trợ.', 'Ghi nhớ chữ [支] (cái, chiếc, cây (lượng từ của cái bút,...)) qua hình tượng Thành phần biểu ý/biểu âm cơ bản trong chữ Hán.', '三支铅笔', 'sān zhī qiānbǐ', 'ba cây bút chì', 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v7_18', 'lesson-7', '本', 'běn', 'từ Hán ngữ', 'cuốn; vở; quyển; tập (dùng cho sách vở sổ sách)', 'Lượng từ', 'Bộ cấu tạo [本] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Chữ độc thể / hình thanh gồm Bộ cấu tạo [本] và các nét bổ trợ.', 'Ghi nhớ chữ [本] (cuốn; vở; quyển; tập (dùng cho sách vở sổ sách)) qua hình tượng Thành phần biểu ý/biểu âm cơ bản trong chữ Hán.', '这本书', 'zhè běn shū', 'quyển sách này', 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v7_19', 'lesson-7', '把', 'bǎ', 'từ Hán ngữ', 'chiếc, cái ( lượng từ của cái thước kẻ)', 'Lượng từ', 'Bộ cấu tạo [把] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Chữ độc thể / hình thanh gồm Bộ cấu tạo [把] và các nét bổ trợ.', 'Ghi nhớ chữ [把] (chiếc, cái ( lượng từ của cái thước kẻ)) qua hình tượng Thành phần biểu ý/biểu âm cơ bản trong chữ Hán.', '我想去商店买两支圆珠笔、一把尺子和三本笔记本。你想去吗？', 'Wǒ xiǎng qù shāngdiàn mǎi liǎng zhī yuánzhūbǐ, yī bǎ chǐzi hé sān běn bǐjìběn. Nǐ xiǎng qù ma?', 'Tôi muốn đi cửa hàng mua hai cây bút bi, một cây thước kẻ và ba quyển vở ghi chép. Bạn có muốn đi không?', 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v7_20', 'lesson-7', '太', 'tài', 'thái', 'quá, lắm', 'Phó từ', 'Bộ cấu tạo [太] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Chữ độc thể / hình thanh gồm Bộ cấu tạo [太] và các nét bổ trợ.', 'Ghi nhớ chữ [太] (quá, lắm) qua hình tượng Thành phần biểu ý/biểu âm cơ bản trong chữ Hán.', '太漂亮了！我下午也想去买一个。', 'Tài piàoliang le! Wǒ xiàwǔ yě xiǎng qù mǎi yígè.', 'Đẹp quá! Chiều nay tôi cũng muốn đi mua một cái.', 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v7_21', 'lesson-7', '真', 'zhēn', 'từ Hán ngữ', 'thật', 'Phó từ', 'Bộ cấu tạo [真] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Chữ độc thể / hình thanh gồm Bộ cấu tạo [真] và các nét bổ trợ.', 'Ghi nhớ chữ [真] (thật) qua hình tượng Thành phần biểu ý/biểu âm cơ bản trong chữ Hán.', '哇，真好看啊！你买的那家商店有蓝色的书包吗？', 'Wa, zhēn hǎokàn a! Nǐ mǎi de nà jiā shāngdiàn yǒu lán sè de shūbāo ma?', 'Chà, đẹp quá đi mất! Cửa hàng bạn mua có cặp sách màu xanh dương không?', 21) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v7_22', 'lesson-7', '一起', 'yīqǐ', 'từ Hán ngữ', 'cùng nhau', 'Phó từ', 'Bộ cấu tạo [一] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [一] + [起].', 'Kết hợp các thành tố [一] + [起] để tạo thành từ mang nghĩa ''cùng nhau''.', '那今天下午四点我在学校门口等你。我们一起去，好吗？', 'Nà jīntiān xiàwǔ sìdiǎn wǒ zài xuéxiào ménkǒu děng nǐ. Wǒmen yīqǐ qù, hǎo ma?', 'Vậy chiều nay 4 giờ tôi đợi bạn ở cổng trường. Chúng ta cùng đi nhé, được không?', 22) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v7_23', 'lesson-7', '怎么样', 'zěnmeyàng', 'ma', 'như thế nào', 'Đại từ', 'Bộ cấu tạo [怎] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [怎] + [么] + [样].', 'Kết hợp các thành tố [怎] + [么] + [样] để tạo thành từ mang nghĩa ''như thế nào''.', '小王是个怎么样的人，你给我介绍一下儿。', 'Xiǎowáng shì gè zěnmeyàng de rén, nǐ gěi wǒ jièshào yíxiàr.', 'Vương là người như thế nào, bạn giới thiệu cho tôi xíu đi.', 23) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g7_1', 'lesson-7', '1. Các trường hợp giữa định ngữ và trung tâm ngữ không cần thêm trợ từ', 'Cấu trúc câu ngữ pháp trọng tâm', ' kết cấu “的”', NULL, '[{"hanzi":"好学生","pinyin":"hǎo xuésheng","meaning":"học sinh tốt, học sinh giỏi"},{"hanzi":"好兄弟","pinyin":"hǎo xiōngdì","meaning":"anh em tốt"}]'::jsonb, 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g7_2', 'lesson-7', '1.1 Định ngữ là tính từ đơn âm tiết thì thường không cần dùng“的”.', 'Cấu trúc câu ngữ pháp trọng tâm', ' 好人 /hǎorén/ : người tốt 坏人  /huàirén / : người xấu 好学生 /hǎo xuésheng/  : học sinh tốt, học sinh giỏi 大楼  /dàlóu /：tòa nhà lớn 好兄弟 /hǎo xiōngdì/ : anh em tốt 好姐妹  /hǎo jiěmèi/: chị em tốt 小学生  /xiǎoxuéshēng/: học sinh tiểu học 大学生 /dàxuéshēng/ : sinh', NULL, '[{"hanzi":"好姐妹","pinyin":"hǎo jiěmèi","meaning":"chị em tốt"},{"hanzi":"小学生","pinyin":"xiǎoxuéshēng","meaning":"học sinh tiểu học"}]'::jsonb, 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g7_3', 'lesson-7', '1.2.   Định ngữ là danh từ dùng để nói rõ nghề nghiệp chức vị, hoặc nói', 'Cấu trúc câu ngữ pháp trọng tâm', ' về  thuộc tính, nguyên liệu, nguồn gốc, phân biệt chủng loại của sự vật thì thường không cần dùng“的”. 汉语老师 /Hànyǔ lǎoshī /: giáo viên tiếng Trung 汉语词典 /Hànyǔ cídiǎn/: từ điển tiếng Trung 中国人 /Zhōngguó rén/: người Trung Quốc 牛仔裤   /niúzǎikù/ : quần j', NULL, '[{"hanzi":"大学生","pinyin":"dàxuéshēng","meaning":"sinh viên đại học"},{"hanzi":"汉语老师","pinyin":"Hànyǔ lǎoshī","meaning":"giáo viên tiếng Trung"}]'::jsonb, 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g7_4', 'lesson-7', '1.4.    Định ngữ là số từ, lượng từ hoặc cụm số lượng từ biểu thị quan hệ hạn', 'Cấu trúc câu ngữ pháp trọng tâm', ' chế thì thường sẽ không thêm “的” 一个故事 /yígè gùshì/ : một câu chuyện 一个人 /yígè rén/ : một người 两本书  /liǎng běn shū/ : hai quyển sách 三支铅笔 /sān zhī qiānbǐ/ : ba cây bút chì', NULL, '[{"hanzi":"汉语词典","pinyin":"Hànyǔ cídiǎn","meaning":"từ điển tiếng Trung"},{"hanzi":"中国人","pinyin":"Zhōngguó rén","meaning":"người Trung Quốc"}]'::jsonb, 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_7_1', 'lesson-7', 'Bài khoá #1: Hội thoại giáo trình — Đồ dùng học tập của tôi', 'Hội thoại chuẩn giáo trình Bài 7. Từ vựng chưa học được chú thích phiên âm & nghĩa trong ngoặc.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_7_1_1', 'txt_7_1', '安妮', '马克，今天下午你去哪儿？', '马克，今天下午你去哪儿？', 'Mǎkè, jīntiān xiàwǔ nǐ qù nǎr?', 'Mark, chiều nay bạn đi đâu?', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_7_1_2', 'txt_7_1', '马克', '我想去商店买两支圆珠笔、一把尺子和三本笔记本。你想去吗？', '我想去商店买两 (liǎng: hai (số lượng))支圆珠笔、一把尺子和三本笔记本。你想去吗？', 'Wǒ xiǎng qù shāngdiàn mǎi liǎng zhī yuánzhūbǐ, yī bǎ chǐzi hé sān běn bǐjìběn. Nǐ xiǎng qù ma?', 'Tôi muốn đi cửa hàng mua hai cây bút bi, một cây thước kẻ và ba quyển vở ghi chép. Bạn có muốn đi không?', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_7_1_3', 'txt_7_1', '安妮', '我也想去买一支铅笔和一本汉语词典。', '我也想去买一支铅笔和一本汉语词典。', 'Wǒ yě xiǎng qù mǎi yī zhī qiānbǐ hé yī běn Hànyǔ cídiǎn.', 'Tôi cũng muốn đi mua một cây bút chì và một quyển từ điển tiếng Hán.', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_7_1_4', 'txt_7_1', '马克', '那今天下午四点我在学校门口等你。我们一起去，好吗？', '那今天下午四点我在学校门口 (kǒu: khẩu, người)等你。我们一起去，好吗？', 'Nà jīntiān xiàwǔ sìdiǎn wǒ zài xuéxiào ménkǒu děng nǐ. Wǒmen yīqǐ qù, hǎo ma?', 'Vậy chiều nay 4 giờ tôi đợi bạn ở cổng trường. Chúng ta cùng đi nhé, được không?', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_7_1_5', 'txt_7_1', '安妮', '好啊！', '好啊！', 'Hǎo a!', 'Được chứ!', 5) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_7_1_1', 'lesson-7', 'txt_7_1', 'listening', 'listening', '马克，今天下午你去哪儿？', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Mark, chiều nay bạn đi đâu?","Đợi tôi năm phút ở phía trước hiệu sách nhé.","Cậu thích mùa xuân hay mùa hè?","Mẹ ơi, quần áo của con ở đâu nhỉ?"]'::jsonb, 0, 'Nội dung nghe được: 马克，今天下午你去哪儿？ (Mǎkè, jīntiān xiàwǔ nǐ qù nǎr?) → Mark, chiều nay bạn đi đâu?', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_7_1_2', 'lesson-7', 'txt_7_1', 'listening', 'listening', '我想去商店买两支圆珠笔、一把尺子和三本笔记本。你想去吗？', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["一个故事 (shì: việc, chuyện)","我想去商店买两 (liǎng: hai (số lượng))支圆珠笔、一把尺子和三本笔记本。你想去吗？","汉语老师","好兄弟 (xiōngdì: anh em)"]'::jsonb, 1, 'Câu vừa đọc: 我想去商店买两支圆珠笔、一把尺子和三本笔记本。你想去吗？ (Wǒ xiǎng qù shāngdiàn mǎi liǎng zhī yuánzhūbǐ, yī bǎ chǐzi hé sān běn bǐjìběn. Nǐ xiǎng qù ma?) → Tôi muốn đi cửa hàng mua hai cây bút bi, một cây thước kẻ và ba quyển vở ghi chép. Bạn có muốn đi không?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_7_1_3', 'lesson-7', 'txt_7_1', 'listening', 'listening', '我也想去买一支铅笔和一本汉语词典。', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Tôi không hay (không thường) liên lạc với Lý Quân.","Tôi cũng muốn đi mua một cây bút chì và một quyển từ điển tiếng Hán.","Vấn đề này tôi không biết nên chỉ đành đi hỏi mẹ.","Anh ấy nói tiếng Trung không tốt."]'::jsonb, 1, 'Nội dung nghe được: 我也想去买一支铅笔和一本汉语词典。 (Wǒ yě xiǎng qù mǎi yī zhī qiānbǐ hé yī běn Hànyǔ cídiǎn.) → Tôi cũng muốn đi mua một cây bút chì và một quyển từ điển tiếng Hán.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_7_1_4', 'lesson-7', 'txt_7_1', 'listening', 'listening', '那今天下午四点我在学校门口等你。我们一起去，好吗？', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["今天下午我买了一把新 (xīn: mới)尺子。","那今天下午四点我在学校门口 (kǒu: khẩu, người)等你。我们一起去，好吗？","那本词典","这条 (tiáo: cái, chiếc)路 (lù: đường)"]'::jsonb, 1, 'Câu vừa đọc: 那今天下午四点我在学校门口等你。我们一起去，好吗？ (Nà jīntiān xiàwǔ sìdiǎn wǒ zài xuéxiào ménkǒu děng nǐ. Wǒmen yīqǐ qù, hǎo ma?) → Vậy chiều nay 4 giờ tôi đợi bạn ở cổng trường. Chúng ta cùng đi nhé, được không?', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_7_2', 'lesson-7', 'Bài khoá #2: Hội thoại giáo trình — Đồ dùng học tập của tôi', 'Hội thoại chuẩn giáo trình Bài 7. Từ vựng chưa học được chú thích phiên âm & nghĩa trong ngoặc.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_7_2_1', 'txt_7_2', '范玉兰', '小白，你觉得我今天买的书包怎么样？', '小白，你觉得我今天买的书包怎么样？', 'Xiǎobái, nǐ juéde wǒ jīntiān mǎi de shūbāo zěnmeyàng?', 'Tiểu Bạch, bạn thấy chiếc cặp sách hôm nay tôi mua thế nào?', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_7_2_2', 'txt_7_2', '白茹雪', '哇，真好看啊！你买的那家商店有蓝色的书包吗？', '哇 (wa: oa, chà (cảm thán))，真好看啊！你买的那家商店有蓝色的书包吗？', 'Wa, zhēn hǎokàn a! Nǐ mǎi de nà jiā shāngdiàn yǒu lán sè de shūbāo ma?', 'Chà, đẹp quá đi mất! Cửa hàng bạn mua có cặp sách màu xanh dương không?', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_7_2_3', 'txt_7_2', '范玉兰', '有啊，还有黄色和白色的书包。', '有啊，还 (hái: còn, vẫn)有黄色和白色的书包。', 'Yǒu a, hái yǒu huángsè hé báisè de shūbāo.', 'Có chứ, còn có cả cặp màu vàng và màu trắng nữa.', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_7_2_4', 'txt_7_2', '白茹雪', '太漂亮了！我下午也想去买一个。', '太漂亮了！我下午也想去买一个。', 'Tài piàoliang le! Wǒ xiàwǔ yě xiǎng qù mǎi yígè.', 'Đẹp quá! Chiều nay tôi cũng muốn đi mua một cái.', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_7_2_5', 'txt_7_2', '范玉兰', '那家商店就在学校门口前面。', '那家商店就在学校门口 (kǒu: khẩu, người)前面。', 'Nà jiā shāngdiàn jiù zài xuéxiào ménkǒu qiánmian.', 'Cửa hàng đó nằm ngay phía trước cổng trường đấy.', 5) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_7_2_6', 'txt_7_2', '白茹雪', '好，谢谢你！', '好，谢谢你！', 'Hǎo, xièxie nǐ!', 'Được, cảm ơn bạn!', 6) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_7_2_1', 'lesson-7', 'txt_7_2', 'listening', 'listening', '小白，你觉得我今天买的书包怎么样？', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Tôi muốn đi siêu thị mua một chút đồ.","Một bông hoa","Tiểu Bạch, bạn thấy chiếc cặp sách hôm nay tôi mua thế nào?","Anh ấy không phải giáo viên."]'::jsonb, 2, 'Nội dung nghe được: 小白，你觉得我今天买的书包怎么样？ (Xiǎobái, nǐ juéde wǒ jīntiān mǎi de shūbāo zěnmeyàng?) → Tiểu Bạch, bạn thấy chiếc cặp sách hôm nay tôi mua thế nào?', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_7_2_2', 'lesson-7', 'txt_7_2', 'listening', 'listening', '哇，真好看啊！你买的那家商店有蓝色的书包吗？', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["那本词典","哇 (wa: oa, chà (cảm thán))，真好看啊！你买的那家商店有蓝色的书包吗？","这个书包","我想买两 (liǎng: hai (số lượng))支蓝色圆珠笔。"]'::jsonb, 1, 'Câu vừa đọc: 哇，真好看啊！你买的那家商店有蓝色的书包吗？ (Wa, zhēn hǎokàn a! Nǐ mǎi de nà jiā shāngdiàn yǒu lán sè de shūbāo ma?) → Chà, đẹp quá đi mất! Cửa hàng bạn mua có cặp sách màu xanh dương không?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_7_2_3', 'lesson-7', 'txt_7_2', 'listening', 'listening', '有啊，还有黄色和白色的书包。', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Vận động viên bị thương rồi nên đành phải bỏ thi đấu.","Sao cậu lại đến nữa vậy?","Một khuôn mặt","Có chứ, còn có cả cặp màu vàng và màu trắng nữa."]'::jsonb, 3, 'Nội dung nghe được: 有啊，还有黄色和白色的书包。 (Yǒu a, hái yǒu huángsè hé báisè de shūbāo.) → Có chứ, còn có cả cặp màu vàng và màu trắng nữa.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_7_2_4', 'lesson-7', 'txt_7_2', 'listening', 'listening', '太漂亮了！我下午也想去买一个。', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["我想买两 (liǎng: hai (số lượng))支蓝色圆珠笔。","你觉得这支铅笔好看吗？","太漂亮了！我下午也想去买一个。","在书店前面等我五分钟。"]'::jsonb, 2, 'Câu vừa đọc: 太漂亮了！我下午也想去买一个。 (Tài piàoliang le! Wǒ xiàwǔ yě xiǎng qù mǎi yígè.) → Đẹp quá! Chiều nay tôi cũng muốn đi mua một cái.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_7_3', 'lesson-7', 'Bài nghe tổng hợp: Ôn tập lũy tiến (Bài 1 – Bài 7)', 'Kết hợp từ vựng & mẫu câu đã học từ Bài 1 đến Bài 6 cùng trọng tâm Bài 7 để củng cố phản xạ nghe.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
