INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq7_13', 'lesson-7', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “书包” chứa bộ thủ nào sau đây?', '["木 (Mộc) (Cây cối, gỗ)","Bộ cấu tạo [书] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [怎] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [本] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)"]'::jsonb, 1, 'Chữ “书包” có Bộ cấu tạo [书] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán). Ghép từ các chữ Hán: [书] + [包].', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq7_14', 'lesson-7', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “圆珠笔” chứa bộ thủ nào sau đây?', '["Bộ cấu tạo [家] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [铅] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [圆] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [支] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)"]'::jsonb, 2, 'Chữ “圆珠笔” có Bộ cấu tạo [圆] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán). Ghép từ các chữ Hán: [圆] + [珠] + [笔].', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq7_15', 'lesson-7', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “尺子” chứa bộ thủ nào sau đây?', '["Bộ cấu tạo [本] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [今] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","子 (Tử) (Đứa con, trẻ nhỏ, người trí thức)","Bộ cấu tạo [词] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)"]'::jsonb, 2, 'Chữ “尺子” có 子 (Tử) (Đứa con, trẻ nhỏ, người trí thức). Ghép từ các chữ Hán: [尺] + [子].', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq7_16', 'lesson-7', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “笔记本” chứa bộ thủ nào sau đây?', '["Bộ cấu tạo [笔] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [觉] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [太] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [好] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)"]'::jsonb, 0, 'Chữ “笔记本” có Bộ cấu tạo [笔] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán). Ghép từ các chữ Hán: [笔] + [记] + [本].', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq7_17', 'lesson-7', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 4] Từ đã học “知道” (zhīdào) có nghĩa là gì?', '["vào học, lên lớp","biết","thế, nhé, nhỉ, cơ (dùng ở cuối câu trần thuật hoặc nghi vấn)","anh ấy, cậu ấy... (ngôi thứ ba số ít chỉ nam)"]'::jsonb, 1, 'Ôn tập Bài 4: “知道” (zhīdào) nghĩa là: biết.', 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
