INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq7_19', 'lesson-7', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 1] Từ đã học “学生” (xuésheng) có nghĩa là gì?', '["buổi sáng, sáng","kia, đó","học sinh","Giáo viên, thầy cô giáo"]'::jsonb, 2, 'Ôn tập Bài 1: “学生” (xuésheng) nghĩa là: học sinh.', 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq7_20', 'lesson-7', NULL, 'expanded_quiz', 'reading', NULL, NULL, '[Mở rộng] Câu “那个黄色的书包真漂亮！” có nghĩa tiếng Việt là gì?', '["Chiếc cặp sách màu vàng kia đẹp thật đấy!","Tôi là Trần Anh.","Phía bên trái nhà ăn","con đường này"]'::jsonb, 0, '那个黄色的书包真漂亮！ (Nàge huángsè de shūbāo zhēn piàoliang!) → Chiếc cặp sách màu vàng kia đẹp thật đấy!', 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
