INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq7_22', 'lesson-7', NULL, 'expanded_quiz', 'reading', NULL, NULL, 'Câu “好学生” có nghĩa tiếng Việt là gì?', '["Bọn họ tặng cho tôi rất nhiều quà.","tiếng gõ cửa","Tôi là Trần Anh.","học sinh tốt, học sinh giỏi"]'::jsonb, 3, '好学生 (hǎo xuésheng) → học sinh tốt, học sinh giỏi', 22) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct7_1', 'lesson-7', NULL, 'comprehensive_test', 'listening', '小学生', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Mark, ngày mai bạn có phải lên lớp không?","học sinh tiểu học","Sáng mai mấy giờ bạn đến phòng học?","Đẹp thật! Tôi cũng muốn mua một chiếc màu vàng."]'::jsonb, 1, 'Nội dung nghe được: “小学生” (xiǎoxuéshēng) → học sinh tiểu học', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct7_2', 'lesson-7', NULL, 'comprehensive_test', 'listening', '他的尺子', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["明天见！","他的尺子","请问，电影院附近有书店吗？","从早上八点到下午五点，他要在公司工作。"]'::jsonb, 1, 'Câu vừa đọc: “他的尺子” (tā de chǐzi) → cây thước kẻ của anh ấy', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct7_3', 'lesson-7', NULL, 'comprehensive_test', 'listening', '后面的姑娘很漂亮。', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Cô gái ở phía sau rất xinh đẹp.","Cô ấy rất xinh đẹp.","Xin chào. Xin hỏi nhà ăn của trường ở đâu vậy?","Được, cảm ơn bạn!"]'::jsonb, 0, 'Nội dung nghe được: “后面的姑娘很漂亮。” (Hòumian de gūniang hěn piàoliang.) → Cô gái ở phía sau rất xinh đẹp.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct7_4', 'lesson-7', NULL, 'comprehensive_test', 'listening', '好兄弟', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["小兰，你房间号码是多少？","好兄弟","阮日明也是学生吗","早上好！我是刘老师。你是阮日明吗？"]'::jsonb, 1, 'Câu vừa đọc: “好兄弟” (hǎo xiōngdì) → anh em tốt', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct7_5', 'lesson-7', NULL, 'comprehensive_test', 'listening', '那家商店就在学校门口前面。', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Tôi muốn mua hai quyển vở ghi, một cây bút chì và một quyển từ điển Hán ngữ.","Cửa hàng đó nằm ngay phía trước cổng trường đấy.","Chào buổi sáng! Tôi là thầy Lưu. Em là Nguyễn Nhật Minh phải không?","Chào buổi tối các bạn!"]'::jsonb, 1, 'Nội dung nghe được: “那家商店就在学校门口前面。” (Nà jiā shāngdiàn jiù zài xuéxiào ménkǒu qiánmian.) → Cửa hàng đó nằm ngay phía trước cổng trường đấy.', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct7_6', 'lesson-7', NULL, 'comprehensive_test', 'listening', '我也想去买一支铅笔和一本汉语词典。', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["你往左拐，然后一直往前走就到。","我也想去买一支铅笔和一本汉语词典。","她是老师。","上午要上课，下午不上。"]'::jsonb, 1, 'Câu vừa đọc: “我也想去买一支铅笔和一本汉语词典。” (Wǒ yě xiǎng qù mǎi yī zhī qiānbǐ hé yī běn Hànyǔ cídiǎn.) → Tôi cũng muốn đi mua một cây bút chì và một quyển từ điển tiếng Hán.', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
