INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v8_1', 'lesson-8', '水果', 'shuǐguǒ', 'thủy quả', 'hoa quả, trái cây', 'Danh từ', 'Bộ cấu tạo [水] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [水] + [果].', 'Kết hợp các thành tố [水] + [果] để tạo thành từ mang nghĩa ''hoa quả, trái cây''.', '这是关于“水果”的常用句子。', 'Zhè shì guānyú ''shuǐguǒ'' de chángyòng jùzi.', 'Đây là câu ví dụ sử dụng từ ''水果'' (hoa quả, trái cây).', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v8_2', 'lesson-8', '苹果', 'píngguǒ', 'bình quả', 'táo', 'Danh từ', 'Bộ cấu tạo [苹] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [苹] + [果].', 'Kết hợp các thành tố [苹] + [果] để tạo thành từ mang nghĩa ''táo''.', '一斤苹果多少钱？', 'Yī jīn píngguǒ duōshao qián?', 'Nửa kg (1 cân) táo bao nhiêu tiền?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v8_3', 'lesson-8', '芒果', 'mángguǒ', 'quả', 'xoài', 'Danh từ', 'Bộ cấu tạo [芒] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [芒] + [果].', 'Kết hợp các thành tố [芒] + [果] để tạo thành từ mang nghĩa ''xoài''.', '我买三斤。啊，阿姨，西瓜和芒果怎么卖？', 'Wǒ mǎi sān jīn. A, āyí, xīguā hé mángguǒ zěnme mài?', 'Cháu mua ba cân ạ. À cô ơi, dưa hấu và xoài bán thế nào ạ?', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v8_4', 'lesson-8', '西瓜', 'xīguā', 'tây qua', 'dưa hấu', 'Danh từ', 'Bộ cấu tạo [西] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [西] + [瓜].', 'Kết hợp các thành tố [西] + [瓜] để tạo thành từ mang nghĩa ''dưa hấu''.', '你买几个西瓜？', 'Nǐ mǎi jǐ gè xīguā?', 'Cậu mua mấy quả dưa hấu thế?', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v8_5', 'lesson-8', '木瓜', 'mùguā', 'qua', 'đu đủ', 'Danh từ', '木 (Mộc) (Cây cối, gỗ, thực vật)', 'Ghép từ các chữ Hán: [木] + [瓜].', 'Kết hợp các thành tố [木] + [瓜] để tạo thành từ mang nghĩa ''đu đủ''.', '不太酸, 很好吃。还有木瓜和火龙果很甜，你要买什么吗？', 'Bú tài suān, hěn hǎo chī. Hái yǒu mùguā hé huǒlóng guǒ hěn tián, nǐ yào mǎi shénme ma?', 'Không chua lắm, ngon lắm. Còn có đu đủ và thanh long rất ngọt, cháu muốn mua thêm gì không?', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v8_6', 'lesson-8', '火龙果', 'huǒlóngguǒ', 'hỏa quả', 'thanh long', 'Danh từ', '火/灬 (Hỏa) (Lửa, nhiệt độ, nấu nướng, nóng bức)', 'Ghép từ các chữ Hán: [火] + [龙] + [果].', 'Kết hợp các thành tố [火] + [龙] + [果] để tạo thành từ mang nghĩa ''thanh long''.', '不太酸, 很好吃。还有木瓜和火龙果很甜，你要买什么吗？', 'Bú tài suān, hěn hǎo chī. Hái yǒu mùguā hé huǒlóng guǒ hěn tián, nǐ yào mǎi shénme ma?', 'Không chua lắm, ngon lắm. Còn có đu đủ và thanh long rất ngọt, cháu muốn mua thêm gì không?', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
