INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v8_9', 'lesson-8', '东西', 'dōngxi', 'tây', 'đồ đạc', 'Danh từ', 'Bộ cấu tạo [东] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [东] + [西].', 'Kết hợp các thành tố [东] + [西] để tạo thành từ mang nghĩa ''đồ đạc''.', '这是关于“东西”的常用句子。', 'Zhè shì guānyú ''dōngxi'' de chángyòng jùzi.', 'Đây là câu ví dụ sử dụng từ ''东西'' (đồ đạc).', 9) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
