INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v8_14', 'lesson-8', '找', 'zhǎo', 'trảo', 'trả (tiền thừa), tìm', 'Động từ', 'Bộ cấu tạo [找] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Chữ độc thể / hình thanh gồm Bộ cấu tạo [找] và các nét bổ trợ.', 'Ghi nhớ chữ [找] (trả (tiền thừa), tìm) qua hình tượng Thành phần biểu ý/biểu âm cơ bản trong chữ Hán.', '这是 60 块，找你 7 块。谢谢！', 'Zhè shì 60 kuài, zhǎo nǐ 7 kuài. Xièxie!', 'Đây là 60 tệ, trả lại cháu 7 tệ. Cảm ơn cháu!', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
