INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_8_2_1', 'lesson-8', 'txt_8_2', 'listening', 'listening', '汉语词典', NULL, '[Ôn tập Bài 7] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["từ điển tiếng Trung","Anh ta không cho tôi đi.","Anh ấy nói tiếng Trung rất tốt.","dáng người cao"]'::jsonb, 0, 'Nội dung nghe được: 汉语词典 (Hànyǔ cídiǎn) → từ điển tiếng Trung', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_8_2_2', 'lesson-8', 'txt_8_2', 'listening', 'listening', '你买几个西瓜？', NULL, '[Bài 8] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["一头 (tóu: con (trâu, bò) / đầu)牛 (niú: con bò)","你买几个西瓜？","一件 (jiàn: cái, chiếc (áo, việc))礼物 (lǐwù: quà)","小 (xiǎo: nhỏ, bé)姑娘 (gūniang: cô gái)，你今 (jīn: hôm nay, nay)年 (nián: năm)几岁 (suì: tuổi)？"]'::jsonb, 1, 'Câu vừa đọc: 你买几个西瓜？ (Nǐ mǎi jǐ gè xīguā?) → Cậu mua mấy quả dưa hấu thế?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_8_2_3', 'lesson-8', 'txt_8_2', 'listening', 'listening', '食堂左边', NULL, '[Ôn tập Bài 4] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Phía bên trái nhà ăn","Anh đừng đi! Có được không?","Cô ấy không phải Lan Lan.","Có khả năng ông chủ quên hôm nay có cuộc họp rồi."]'::jsonb, 0, 'Nội dung nghe được: 食堂左边 (shítáng zuǒbian) → Phía bên trái nhà ăn', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_8_2_4', 'lesson-8', 'txt_8_2', 'listening', 'listening', '你家有多少人？', NULL, '[Bài 8] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["你家有多少人？","你们班 (bān: lớp học)有多少学生？","一件 (jiàn: cái, chiếc (áo, việc))礼物 (lǐwù: quà)","一件 (jiàn: cái, chiếc (áo, việc))事 (shì: việc, chuyện)"]'::jsonb, 0, 'Câu vừa đọc: 你家有多少人？ (Nǐ jiā yǒu duōshao rén?) → Nhà cậu có bao nhiêu người?', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_8_2_5', 'lesson-8', 'txt_8_2', 'listening', 'listening', '你是日明吗？', NULL, '[Ôn tập Bài 1] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Anh ấy đi du học ở Bắc Kinh.","Cậu là Nhật Minh phải không?","Cách tốt nhất đó chính là không nói gì cả và giữ im lặng!","Cậu là ai thế?"]'::jsonb, 1, 'Nội dung nghe được: 你是日明吗？ (Nǐ shì Rìmíng ma?) → Cậu là Nhật Minh phải không?', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_8_3', 'lesson-8', 'Bài khoá mở rộng: Mua trái cây ở chợ trường (Mở rộng)', 'Hội thoại tình huống mới xây dựng dựa trên từ vựng và ngữ pháp Bài 8 (không trùng lặp nguyên văn giáo trình).', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_8_3_1', 'txt_8_3', 'Lan', '阿姨，请问西瓜和火龙果怎么卖？', '阿姨，请问 (qǐngwèn: xin hỏi)西瓜和火龙果怎么卖？', 'Āyí, qǐngwèn xīguā hé huǒlóngguǒ zěnme mài?', 'Cô ơi, cho cháu hỏi dưa hấu và thanh long bán thế nào ạ?', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_8_3_2', 'txt_8_3', 'Cô bán', '西瓜十二块钱一个，火龙果八块钱一斤。', '西瓜十二块钱一个，火龙果八块钱一斤。', 'Xīguā shí''èr kuài qián yígè, huǒlóngguǒ bā kuài qián yì jīn.', 'Dưa hấu 12 tệ một quả, thanh long 8 tệ một cân.', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_8_3_3', 'txt_8_3', 'Lan', '给我一个西瓜和两斤火龙果，还要两杯草莓果汁。', '给我一个西瓜和两 (liǎng: hai (số lượng))斤火龙果，还 (hái: còn, vẫn)要两杯草莓果汁。', 'Gěi wǒ yígè xīguā hé liǎng jīn huǒlóngguǒ, hái yào liǎng bēi cǎoméi guǒzhī.', 'Lấy cho cháu một quả dưa hấu, hai cân thanh long và hai cốc nước ép dâu.', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_8_3_4', 'txt_8_3', 'Cô bán', '果汁五块钱一杯，一共三十八块钱。', '果汁五块钱一杯，一共 (yígòng: tổng cộng)三十八块钱。', 'Guǒzhī wǔ kuài qián yì bēi, yígòng sānshíbā kuài qián.', 'Nước ép 5 tệ một cốc, tổng cộng hết 38 tệ nhé.', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_8_3_1', 'lesson-8', 'txt_8_3', 'listening', 'listening', '阿姨，请问西瓜和火龙果怎么卖？ 西瓜十二块钱一个，火龙果八块钱一斤。 给我一个西瓜和两斤火龙果，还要两杯草莓果汁。 果汁五块钱一杯，一共三十八块钱。', NULL, '[Nghe hiểu tình huống mới] Lan đã mua tất cả những thứ gì?', '["Chỉ mua 2 cân xoài","2 quả đu đủ và 1 cốc nước ép","3 cân táo và 1 quả dưa hấu","1 quả dưa hấu, 2 cân thanh long và 2 cốc nước ép dâu"]'::jsonb, 3, 'Lan gọi rõ ''一个西瓜和两斤火龙果，还要两杯草莓果汁''.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_8_3_2', 'lesson-8', 'txt_8_3', 'listening', 'listening', '阿姨，请问西瓜和火龙果怎么卖？', NULL, '[Mở rộng] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Cô ơi, cho cháu hỏi dưa hấu và thanh long bán thế nào ạ?","Việc đó là thật.","Bữa sáng cậu ấy có thể ăn 10 cái bánh bao.","Mẹ gõ nhẹ vào đầu tôi."]'::jsonb, 0, 'Nội dung nghe được: 阿姨，请问西瓜和火龙果怎么卖？ (Āyí, qǐngwèn xīguā hé huǒlóngguǒ zěnme mài?) → Cô ơi, cho cháu hỏi dưa hấu và thanh long bán thế nào ạ?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_8_3_3', 'lesson-8', 'txt_8_3', 'listening', 'listening', '西瓜十二块钱一个，火龙果八块钱一斤。', NULL, '[Mở rộng] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["一斤苹果多少钱？","西瓜十二块钱一个，火龙果八块钱一斤。","今天星期几 (xīngqī jǐ: ngày thứ mấy)？","一个面包 (miànbāo: bánh mì)"]'::jsonb, 1, 'Câu vừa đọc: 西瓜十二块钱一个，火龙果八块钱一斤。 (Xīguā shí''èr kuài qián yígè, huǒlóngguǒ bā kuài qián yì jīn.) → Dưa hấu 12 tệ một quả, thanh long 8 tệ một cân.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_8_3_4', 'lesson-8', 'txt_8_3', 'listening', 'listening', '给我一个西瓜和两斤火龙果，还要两杯草莓果汁。', NULL, '[Mở rộng] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Rất nhiều người đi siêu thị mua đồ.","Tôi đợi anh ấy về rồi nói chuyện này với anh ấy.","Lấy cho cháu một quả dưa hấu, hai cân thanh long và hai cốc nước ép dâu.","Cậu yên tâm đi!"]'::jsonb, 2, 'Nội dung nghe được: 给我一个西瓜和两斤火龙果，还要两杯草莓果汁。 (Gěi wǒ yígè xīguā hé liǎng jīn huǒlóngguǒ, hái yào liǎng bēi cǎoméi guǒzhī.) → Lấy cho cháu một quả dưa hấu, hai cân thanh long và hai cốc nước ép dâu.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss8_1', 'lesson-8', '阿姨今天的苹果甜不甜', '[Mở rộng] Cô ơi, táo hôm nay có ngọt không ạ?', 'Āyí, jīntiān de píngguǒ tián bu tián?', '["阿姨","今天的","苹果","甜","不","甜"]'::jsonb, 'Từ chưa học: 不 (bù: không)', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss8_2', 'lesson-8', '我想买两斤火龙果和一斤芒果', '[Mở rộng] Cháu muốn mua hai cân thanh long và một cân xoài.', 'Wǒ xiǎng mǎi liǎng jīn huǒlóngguǒ hé yì jīn mángguǒ.', '["我想","买两斤","火龙果","和一","斤","芒果"]'::jsonb, 'Từ chưa học: 两 (liǎng: hai (số lượng))', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss8_3', 'lesson-8', '你买几个西瓜', 'Cậu mua mấy quả dưa hấu thế?', 'Nǐ mǎi jǐ gè xīguā?', '["你","买","几","个","西瓜"]'::jsonb, NULL, 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
