INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss8_5', 'lesson-8', '在书店前面等我五分钟', '[Ôn tập Bài 7] Đợi tôi năm phút ở phía trước hiệu sách nhé.', 'Zài shūdiàn qiánmian děng wǒ wǔ fēnzhōng.', '["在","书店","前面","等我","五","分钟"]'::jsonb, NULL, 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
