INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq8_13', 'lesson-8', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “水果” chứa bộ thủ nào sau đây?', '["Bộ cấu tạo [杯] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","木 (Mộc) (Cây cối, gỗ, thực vật)","Bộ cấu tạo [水] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","口 (Khẩu) (Miệng, ăn uống, lời nói)"]'::jsonb, 2, 'Chữ “水果” có Bộ cấu tạo [水] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán). Ghép từ các chữ Hán: [水] + [果].', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
