INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq8_22', 'lesson-8', NULL, 'expanded_quiz', 'reading', NULL, NULL, 'Câu “你买几个西瓜？” có nghĩa tiếng Việt là gì?', '["Một chiếc bánh mì","Chúng ta cùng qua bên đó xem đi!","Thứ ba (ngày trong tuần)","Cậu mua mấy quả dưa hấu thế?"]'::jsonb, 3, '你买几个西瓜？ (Nǐ mǎi jǐ gè xīguā?) → Cậu mua mấy quả dưa hấu thế?', 22) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct8_1', 'lesson-8', NULL, 'comprehensive_test', 'listening', '你买几个西瓜？', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["đất nước (quốc gia) của chúng tôi","Cậu mua mấy quả dưa hấu thế?","Rất vui được làm quen với bạn! Bạn đến từ Canada à?","Không có gì!"]'::jsonb, 1, 'Nội dung nghe được: “你买几个西瓜？” (Nǐ mǎi jǐ gè xīguā?) → Cậu mua mấy quả dưa hấu thế?', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct8_2', 'lesson-8', NULL, 'comprehensive_test', 'listening', '阿姨今天的苹果甜不甜', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["刘老师是学校的老师","你认识阮日明吗","后面的姑娘很漂亮。","阿姨今天的苹果甜不甜"]'::jsonb, 3, 'Câu vừa đọc: “阿姨今天的苹果甜不甜” (Āyí, jīntiān de píngguǒ tián bu tián?) → Cô ơi, táo hôm nay có ngọt không ạ?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct8_3', 'lesson-8', NULL, 'comprehensive_test', 'listening', '我的朋友在食堂吃饭', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Bạn của tôi đang ăn cơm ở nhà ăn.","9 giờ 30 sáng tôi có một tiết tiếng Hán, 11 giờ rưỡi đi nhà ăn.","Em chào thầy/cô ạ","học sinh tốt, học sinh giỏi"]'::jsonb, 0, 'Nội dung nghe được: “我的朋友在食堂吃饭” (Wǒ de péngyou zài shítáng chīfàn.) → Bạn của tôi đang ăn cơm ở nhà ăn.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct8_4', 'lesson-8', NULL, 'comprehensive_test', 'listening', '苹果很甜，一斤两块。你想买几斤？', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["刘老师是学校的老师","苹果很甜，一斤两块。你想买几斤？","医院在我们学校的右边。","昨天下午你去图书馆了吗"]'::jsonb, 1, 'Câu vừa đọc: “苹果很甜，一斤两块。你想买几斤？” (Píngguǒ hěn tián, yī jīn liǎng kuài. Nǐ xiǎng mǎi jǐ jīn?) → Táo ngọt lắm, một cân 2 tệ. Cháu muốn mua mấy cân?', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct8_5', 'lesson-8', NULL, 'comprehensive_test', 'listening', '西瓜十二块钱一个，火龙果八块钱一斤。', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Thư viện cũng ở phía trước tòa giảng đường à?","Có, nhà ăn nằm ở bên phải tòa nhà giảng đường.","Dưa hấu 12 tệ một quả, thanh long 8 tệ một cân.","Anh ấy là ai?"]'::jsonb, 2, 'Nội dung nghe được: “西瓜十二块钱一个，火龙果八块钱一斤。” (Xīguā shí''èr kuài qián yígè, huǒlóngguǒ bā kuài qián yì jīn.) → Dưa hấu 12 tệ một quả, thanh long 8 tệ một cân.', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct8_6', 'lesson-8', NULL, 'comprehensive_test', 'listening', '西瓜一个十五块。芒果一斤七块。', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["西瓜一个十五块。芒果一斤七块。","好，明天见！","阿姨，请问，一斤苹果多少钱？","是，每个周末我都到那儿买书。"]'::jsonb, 0, 'Câu vừa đọc: “西瓜一个十五块。芒果一斤七块。” (Xīguā yí gè shíwǔ kuài. Mángguǒ yī jīn qī kuài.) → Dưa hấu 15 tệ một quả. Xoài 7 tệ một cân.', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct8_7', 'lesson-8', NULL, 'comprehensive_test', 'listening', '这是 60 块，找你 7 块。谢谢！', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Cô ấy là Bạch Như Tuyết.","Đây là 60 tệ, trả lại cháu 7 tệ. Cảm ơn cháu!","Dưa hấu 12 tệ một quả, thanh long 8 tệ một cân.","chiếc cặp này"]'::jsonb, 1, 'Nội dung nghe được: “这是 60 块，找你 7 块。谢谢！” (Zhè shì 60 kuài, zhǎo nǐ 7 kuài. Xièxie!) → Đây là 60 tệ, trả lại cháu 7 tệ. Cảm ơn cháu!', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
