INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v9_1', 'lesson-9', '超市', 'chāoshì', 'siêu thị', 'siêu thị', 'Danh từ', 'Bộ cấu tạo [超] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [超] + [市].', 'Kết hợp các thành tố [超] + [市] để tạo thành từ mang nghĩa ''siêu thị''.', '我想来超市买一些东西。', 'Wǒ xiǎng lái chāoshì mǎi yīxiē dōngxi.', 'Tôi muốn đi siêu thị mua một chút đồ.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v9_2', 'lesson-9', '售货员', 'shòuhuòyuán', 'từ Hán ngữ', 'nhân viên bán hàng', 'Danh từ', 'Bộ cấu tạo [售] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [售] + [货] + [员].', 'Kết hợp các thành tố [售] + [货] + [员] để tạo thành từ mang nghĩa ''nhân viên bán hàng''.', '这是关于“售货员”的常用句子。', 'Zhè shì guānyú ''shòuhuòyuán'' de chángyòng jùzi.', 'Đây là câu ví dụ sử dụng từ ''售货员'' (nhân viên bán hàng).', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v9_3', 'lesson-9', '衣服', 'yīfu', 'y phục', 'quần áo', 'Danh từ', '衣/衤 (Y) (Áo quần, y phục)', 'Ghép từ các chữ Hán: [衣] + [服].', 'Kết hợp các thành tố [衣] + [服] để tạo thành từ mang nghĩa ''quần áo''.', '小兰！你跟我一起去超市买衣服，好吗？', 'Xiǎolán, nǐ gēn wǒ yīqǐ qù chāoshì mǎi yīfu, hǎo ma?', 'Tiểu Lan! Cậu đi siêu thị mua quần áo cùng tớ nhé, được không?', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v9_4', 'lesson-9', '裤子', 'kùzi', 'từ Hán ngữ', 'quần', 'Danh từ', '子 (Tử) (Đứa con, trẻ nhỏ, người trí thức)', 'Ghép từ các chữ Hán: [裤] + [子].', 'Kết hợp các thành tố [裤] + [子] để tạo thành từ mang nghĩa ''quần''.', '我想买一条裤子，一条裙子和一件大衣。', 'Wǒ xiǎng mǎi yī tiáo kùzi, yī tiáo qúnzi hé yī jiàn dàyī.', 'Tớ muốn mua một chiếc quần dài, một chiếc váy và một chiếc áo khoác dài.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
