INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v9_7', 'lesson-9', '颜色', 'yánsè', 'nhan sắc', 'màu sắc', 'Danh từ', 'Bộ cấu tạo [颜] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [颜] + [色].', 'Kết hợp các thành tố [颜] + [色] để tạo thành từ mang nghĩa ''màu sắc''.', '我觉得颜色不太好看，我不喜欢绿色，我最喜欢红色和黄色。', 'Wǒ juéde yánsè bú tài hǎokàn, wǒ bù xǐhuan lǜsè, wǒ zuì xǐhuan hóngsè hé huángsè.', 'Tớ thấy màu sắc không đẹp lắm, tớ không thích màu xanh lá, tớ thích nhất màu đỏ và màu vàng.', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
