INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v9_10', 'lesson-9', '粉红色', 'fěnhóngsè', 'hồng sắc', 'màu hồng phấn', 'Danh từ', 'Bộ cấu tạo [粉] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [粉] + [红] + [色].', 'Kết hợp các thành tố [粉] + [红] + [色] để tạo thành từ mang nghĩa ''màu hồng phấn''.', '很好看，我买这件黄色的大衣和这条粉红色的裙子。你觉得这件大衣贵不贵？', 'Hěn hǎokàn, wǒ mǎi zhè jiàn huángsè de dàyī hé zhè tiáo fěnhóngsè de qúnzi. Nǐ juéde zhè jiàn dàyī guì bu guì?', 'Đẹp lắm, tớ sẽ mua chiếc áo khoác màu vàng này và chiếc váy màu hồng này. Cậu thấy chiếc áo khoác này có đắt không?', 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v9_11', 'lesson-9', '试', 'shì', 'thí', 'thử', 'Động từ', 'Bộ cấu tạo [试] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Chữ độc thể / hình thanh gồm Bộ cấu tạo [试] và các nét bổ trợ.', 'Ghi nhớ chữ [试] (thử) qua hình tượng Thành phần biểu ý/biểu âm cơ bản trong chữ Hán.', '那这条红色的裤子行吗？你试试看！', 'Nà zhè tiáo hóngsè de kùzi xíng ma? Nǐ shìshi kàn!', 'Vậy chiếc quần màu đỏ này có được không? Cậu mặc thử xem!', 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v9_12', 'lesson-9', '结账', 'jié zhàng', 'từ Hán ngữ', 'thanh toán', 'Động từ', 'Bộ cấu tạo [结] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [结] + [账].', 'Kết hợp các thành tố [结] + [账] để tạo thành từ mang nghĩa ''thanh toán''.', '好的，我们去结账吧！', 'Hǎo de, wǒmen qù jiézhàng ba!', 'Được rồi, chúng ta đi thanh toán thôi!', 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v9_13', 'lesson-9', '喜欢', 'xǐ huān', 'hoan', 'thích', 'Động từ', 'Bộ cấu tạo [喜] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [喜] + [欢].', 'Kết hợp các thành tố [喜] + [欢] để tạo thành từ mang nghĩa ''thích''.', '他最喜欢打篮球。', 'Tā zuì xǐhuān dǎ lánqiú.', 'Anh ấy thích chơi bóng rổ nhất.', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v9_14', 'lesson-9', '不错', 'bùcuò', 'từ Hán ngữ', 'được, tốt, không tồi', 'Tính từ', 'Bộ cấu tạo [不] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [不] + [错].', 'Kết hợp các thành tố [不] + [错] để tạo thành từ mang nghĩa ''được, tốt, không tồi''.', '不错，很合适。我买这条吧！', 'Búcuò, hěn héshì. Wǒ mǎi zhè tiáo ba!', 'Khá ổn, rất vừa vặn. Tớ mua chiếc này nhé!', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v9_15', 'lesson-9', '合适', 'héshì', 'hợp thích', 'vừa vặn, thích hợp, vừa', 'Tính từ', 'Bộ cấu tạo [合] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [合] + [适].', 'Kết hợp các thành tố [合] + [适] để tạo thành từ mang nghĩa ''vừa vặn, thích hợp, vừa''.', '不错，很合适。我买这条吧！', 'Búcuò, hěn héshì. Wǒ mǎi zhè tiáo ba!', 'Khá ổn, rất vừa vặn. Tớ mua chiếc này nhé!', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v9_16', 'lesson-9', '贵', 'guì', 'quý', 'đắt', 'Tính từ', 'Bộ cấu tạo [贵] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Chữ độc thể / hình thanh gồm Bộ cấu tạo [贵] và các nét bổ trợ.', 'Ghi nhớ chữ [贵] (đắt) qua hình tượng Thành phần biểu ý/biểu âm cơ bản trong chữ Hán.', '很好看，我买这件黄色的大衣和这条粉红色的裙子。你觉得这件大衣贵不贵？', 'Hěn hǎokàn, wǒ mǎi zhè jiàn huángsè de dàyī hé zhè tiáo fěnhóngsè de qúnzi. Nǐ juéde zhè jiàn dàyī guì bu guì?', 'Đẹp lắm, tớ sẽ mua chiếc áo khoác màu vàng này và chiếc váy màu hồng này. Cậu thấy chiếc áo khoác này có đắt không?', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v9_17', 'lesson-9', '便宜', 'piányi', 'tiện nghi', 'rẻ', 'Tính từ', 'Bộ cấu tạo [便] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [便] + [宜].', 'Kết hợp các thành tố [便] + [宜] để tạo thành từ mang nghĩa ''rẻ''.', '我觉得不贵，很便宜!', 'Wǒ juéde bú guì, hěn piányi!', 'Tớ thấy không đắt đâu, rất rẻ!', 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v9_18', 'lesson-9', '新', 'xīn', 'tân', 'mới', 'Tính từ', 'Bộ cấu tạo [新] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Chữ độc thể / hình thanh gồm Bộ cấu tạo [新] và các nét bổ trợ.', 'Ghi nhớ chữ [新] (mới) qua hình tượng Thành phần biểu ý/biểu âm cơ bản trong chữ Hán.', '这是关于“新”的常用句子。', 'Zhè shì guānyú ''xīn'' de chángyòng jùzi.', 'Đây là câu ví dụ sử dụng từ ''新'' (mới).', 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
