INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v9_21', 'lesson-9', '最', 'zuì', 'từ Hán ngữ', 'nhất', 'Phó từ', 'Bộ cấu tạo [最] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Chữ độc thể / hình thanh gồm Bộ cấu tạo [最] và các nét bổ trợ.', 'Ghi nhớ chữ [最] (nhất) qua hình tượng Thành phần biểu ý/biểu âm cơ bản trong chữ Hán.', '他最喜欢打篮球。', 'Tā zuì xǐhuān dǎ lánqiú.', 'Anh ấy thích chơi bóng rổ nhất.', 21) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v9_22', 'lesson-9', '条', 'tiáo', 'từ Hán ngữ', 'cái, chiếc,..lượng từ của quần, váy', 'Lượng từ', 'Bộ cấu tạo [条] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Chữ độc thể / hình thanh gồm Bộ cấu tạo [条] và các nét bổ trợ.', 'Ghi nhớ chữ [条] (cái, chiếc,..lượng từ của quần, váy) qua hình tượng Thành phần biểu ý/biểu âm cơ bản trong chữ Hán.', '我想买一条裤子，一条裙子和一件大衣。', 'Wǒ xiǎng mǎi yī tiáo kùzi, yī tiáo qúnzi hé yī jiàn dàyī.', 'Tớ muốn mua một chiếc quần dài, một chiếc váy và một chiếc áo khoác dài.', 22) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v9_23', 'lesson-9', '一下儿', 'yíxiàr', 'hạ nhi', 'một chút, một lát', 'Lượng từ', 'Bộ cấu tạo [一] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [一] + [下] + [儿].', 'Kết hợp các thành tố [一] + [下] + [儿] để tạo thành từ mang nghĩa ''một chút, một lát''.', '你好，请给我们结一下儿账！', 'Nǐ hǎo, qǐng gěi wǒmen jié yíxiàr zhàng!', 'Chào bạn, làm ơn thanh toán giúp bọn mình nhé!', 23) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v9_24', 'lesson-9', '吧', 'ba', 'từ Hán ngữ', 'đi, nhé,…', 'Trợ từ', 'Bộ cấu tạo [吧] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Chữ độc thể / hình thanh gồm Bộ cấu tạo [吧] và các nét bổ trợ.', 'Ghi nhớ chữ [吧] (đi, nhé,…) qua hình tượng Thành phần biểu ý/biểu âm cơ bản trong chữ Hán.', '我们一起去那边吧！', 'Wǒmen yīqǐ qù nàbian ba!', 'Chúng ta cùng qua bên đó xem đi!', 24) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v9_25', 'lesson-9', '那么', 'nàme', 'na ma', 'thế thì, vậy thì, trong trường hợp ấy', 'Liên từ', 'Bộ cấu tạo [那] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [那] + [么].', 'Kết hợp các thành tố [那] + [么] để tạo thành từ mang nghĩa ''thế thì, vậy thì, trong trường hợp ấy''.', '这是关于“那么”的常用句子。', 'Zhè shì guānyú ''nàme'' de chángyòng jùzi.', 'Đây là câu ví dụ sử dụng từ ''那么'' (thế thì, vậy thì, trong trường hợp ấy).', 25) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g9_1', 'lesson-9', '1. A 跟/和 B 一起 + Động từ + Tân ngữ', 'Cấu trúc câu ngữ pháp trọng tâm', ' Đây là cấu trúc biểu thị ý nghĩa A và B cùng nhau thực hiện hành vi, động tác gì đó. 明天我跟小林一起去旅游。 Míngtiān wǒ gēn Xiǎo Lín yīqǐ qù lǚyóu. Ngày mai tôi sẽ đi du lịch với Lâm. 我不会跟他一起回家。 Wǒ bú huì gēn tā yīqǐ huí jiā. Tôi sẽ không về nhà cùng với anh ', NULL, '[{"hanzi":"明天我跟小林一起去旅游。","pinyin":"Míngtiān wǒ gēn Xiǎo Lín yīqǐ qù lǚyóu.","meaning":"Ngày mai tôi sẽ đi du lịch với Lâm."},{"hanzi":"我不会跟他一起回家。","pinyin":"Wǒ bú huì gēn tā yīqǐ huí jiā.","meaning":"Tôi sẽ không về nhà cùng với anh ta đâu."}]'::jsonb, 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g9_2', 'lesson-9', '2. 连动词 – Câu liên động', '去/来 + Địa điểm + Động từ', ' Câu mà có thành phần vị ngữ do hai động từ, cụm động từ trở lên tạo thành và có chung chủ ngữ gọi là câu liên động. Câu liên động biểu thị mục đích và phương thức của hành vi động tác: - Biểu đạt mục đích của hành động: Trong đó, động từ thứ nhất th', NULL, '[{"hanzi":"你可以跟我一起去买帽子吗？","pinyin":"Nǐ kěyǐ gēn wǒ yīqǐ qù mǎi màozi ma?","meaning":"Bạn có thể đi mua mũ cùng với tôi không?"},{"hanzi":"他去北京留学。","pinyin":"Tā qù Běijīng liúxué.","meaning":"Anh ấy đi du học ở Bắc Kinh."}]'::jsonb, 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g9_3', 'lesson-9', '3. 最', '最 + Động từ tâm lý, cảm xúc /Tính từ', ' 最 là phó từ chỉ mức độ được dùng trong so sánh nhất, biểu thị chủ thể của 最 có tính chất hay trạng thái nào đó vượt qua tất cả người hoặc sự vật cùng loại, đạt đến đỉnh cao nhất trong phạm vi so sánh. 最 có thể đứng trước tính từ, động từ tâm lý... 他', NULL, '[{"hanzi":"我想来超市买一些东西。","pinyin":"Wǒ xiǎng lái chāoshì mǎi yīxiē dōngxi.","meaning":"Tôi muốn đi siêu thị mua một chút đồ."},{"hanzi":"她去银行取钱了。","pinyin":"Tā qù yínháng qǔqián le.","meaning":"Chị ấy đi ngân hàng rút tiền rồi."}]'::jsonb, 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g9_4', 'lesson-9', '4. Dạng câu hỏi chính phản của động từ, tính từ', 'Cấu trúc câu ngữ pháp trọng tâm', ' A 不 A? Đây là dạng câu hỏi chính phản, ý nghĩa tương đương với “A 吗？”, trong đó A làm động từ hoặc một tính từ. 那家商店的东西贵不贵？                  = 那家商店的东西贵吗？ Nà jiā shāngdiàn de dōngxi guì bu guì? = Nà jiā shāngdiàn de dōngxi guì ma? Đồ của cửa hàng đó ', NULL, '[{"hanzi":"小林去英国旅游过一次。","pinyin":"Xiǎolín qù Yīngguó lǚyóuguo yícì.","meaning":"Lâm từng đi Anh du lịch một lần."},{"hanzi":"我用法语跟小芳谈话。","pinyin":"Wǒ yòng Fǎyǔ gēn Xiǎofāng tánhuà.","meaning":"Tôi dùng tiếng Pháp nói chuyện với Phương."}]'::jsonb, 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_9_1', 'lesson-9', 'Bài khoá #1: Hội thoại giáo trình — Mua quần áo', 'Hội thoại chuẩn giáo trình Bài 9. Từ vựng chưa học được chú thích phiên âm & nghĩa trong ngoặc.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_9_1_1', 'txt_9_1', '白茹雪', '小兰！你跟我一起去超市买衣服，好吗？', '小兰！你跟 (gēn: cùng, với)我一起去超市买衣服，好吗？', 'Xiǎolán, nǐ gēn wǒ yīqǐ qù chāoshì mǎi yīfu, hǎo ma?', 'Tiểu Lan! Cậu đi siêu thị mua quần áo cùng tớ nhé, được không?', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_9_1_2', 'txt_9_1', '范玉兰', '好啊。', '好啊。', 'Hǎo a.', 'Được chứ.', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_9_1_3', 'txt_9_1', '范玉兰', '你想买什么衣服？', '你想买什么衣服？', 'Nǐ xiǎng mǎi shénme yīfu?', 'Cậu muốn mua quần áo gì?', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_9_1_4', 'txt_9_1', '白茹雪', '我想买一条裤子，一条裙子和一件大衣。', '我想买一条裤子，一条裙子和一件 (jiàn: cái, chiếc (áo, việc))大衣。', 'Wǒ xiǎng mǎi yī tiáo kùzi, yī tiáo qúnzi hé yī jiàn dàyī.', 'Tớ muốn mua một chiếc quần dài, một chiếc váy và một chiếc áo khoác dài.', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_9_1_5', 'txt_9_1', '范玉兰', '你觉得这条裤子好不好看？', '你觉得这条裤子好不 (bù: không)好看？', 'Nǐ juéde zhè tiáo kùzi hǎo bu hǎokàn?', 'Cậu thấy chiếc quần này có đẹp không?', 5) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_9_1_6', 'txt_9_1', '白茹雪', '我觉得颜色不太好看，我不喜欢绿色，我最喜欢红色和黄色。', '我觉得颜色不 (bù: không)太好看，我不喜欢绿色，我最喜欢红色和黄色。', 'Wǒ juéde yánsè bú tài hǎokàn, wǒ bù xǐhuan lǜsè, wǒ zuì xǐhuan hóngsè hé huángsè.', 'Tớ thấy màu sắc không đẹp lắm, tớ không thích màu xanh lá, tớ thích nhất màu đỏ và màu vàng.', 6) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_9_1_7', 'txt_9_1', '范玉兰', '那这条红色的裤子行吗？你试试看！', '那这条红色的裤子行 (xíng: được)吗？你试试看！', 'Nà zhè tiáo hóngsè de kùzi xíng ma? Nǐ shìshi kàn!', 'Vậy chiếc quần màu đỏ này có được không? Cậu mặc thử xem!', 7) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_9_1_8', 'txt_9_1', '白茹雪', '不错，很合适。我买这条吧！', '不错，很合适。我买这条吧！', 'Búcuò, hěn héshì. Wǒ mǎi zhè tiáo ba!', 'Khá ổn, rất vừa vặn. Tớ mua chiếc này nhé!', 8) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_9_1_9', 'txt_9_1', '范玉兰', '你看，那边是大衣和裙子，好漂亮啊！', '你看，那边 (biān: bên, phía)是大衣和裙子，好漂亮啊！', 'Nǐ kàn, nàbian shì dàyī hé qúnzi, hǎo piàoliang a!', 'Cậu nhìn kìa, bên kia là áo khoác và váy, đẹp quá đi!', 9) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_9_1_10', 'txt_9_1', '白茹雪', '很好看，我买这件黄色的大衣和这条粉红色的裙子。你觉得这件大衣贵不贵？', '很好看，我买这件 (jiàn: cái, chiếc (áo, việc))黄色的大衣和这条粉红色的裙子。你觉得这件大衣贵不 (bù: không)贵？', 'Hěn hǎokàn, wǒ mǎi zhè jiàn huángsè de dàyī hé zhè tiáo fěnhóngsè de qúnzi. Nǐ juéde zhè jiàn dàyī guì bu guì?', 'Đẹp lắm, tớ sẽ mua chiếc áo khoác màu vàng này và chiếc váy màu hồng này. Cậu thấy chiếc áo khoác này có đắt không?', 10) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_9_1_11', 'txt_9_1', '范玉兰', '我觉得不贵，很便宜!', '我觉得不 (bù: không)贵，很便宜!', 'Wǒ juéde bú guì, hěn piányi!', 'Tớ thấy không đắt đâu, rất rẻ!', 11) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_9_1_12', 'txt_9_1', '白茹雪', '好的，我们去结账吧！', '好的，我们去结账吧！', 'Hǎo de, wǒmen qù jiézhàng ba!', 'Được rồi, chúng ta đi thanh toán thôi!', 12) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_9_1_13', 'txt_9_1', '白茹雪', '你好，请给我们结一下儿账！', '你好，请给我们结一下儿账！', 'Nǐ hǎo, qǐng gěi wǒmen jié yíxiàr zhàng!', 'Chào bạn, làm ơn thanh toán giúp bọn mình nhé!', 13) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_9_1_14', 'txt_9_1', '售货员', '好的，一共 150 块。', '好的，一共 150 块。', 'Hǎo de, yígòng 150 kuài.', 'Vâng, tổng cộng 150 tệ ạ.', 14) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_9_1_15', 'txt_9_1', '白茹雪', '给你，谢谢!', '给你，谢谢!', 'Gěi nǐ, xièxie!', 'Gửi bạn tiền, cảm ơn nhé!', 15) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_9_1_16', 'txt_9_1', '售货员', '谢谢你们！', '谢谢你们！', 'Xièxie nǐmen!', 'Cảm ơn hai bạn!', 16) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_9_1_1', 'lesson-9', 'txt_9_1', 'listening', 'listening', '小兰！你跟我一起去超市买衣服，好吗？', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Bye! (thường dùng trong giới trẻ)","Cậu ấy ngủ suốt chín tiếng đồng hồ.","Tiểu Lan! Cậu đi siêu thị mua quần áo cùng tớ nhé, được không?","Năm nay bác tôi 56 tuổi, bác cậu thì sao?"]'::jsonb, 2, 'Nội dung nghe được: 小兰！你跟我一起去超市买衣服，好吗？ (Xiǎolán, nǐ gēn wǒ yīqǐ qù chāoshì mǎi yīfu, hǎo ma?) → Tiểu Lan! Cậu đi siêu thị mua quần áo cùng tớ nhé, được không?', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_9_1_2', 'lesson-9', 'txt_9_1', 'listening', 'listening', '好啊。', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["小兰！你跟 (gēn: cùng, với)我一起去超市买衣服，好吗？","我不 (bù: không)会 (huì: Phó, đtnn biết)跟 (gēn: cùng, với)他一起回家。","他是班里 (bān li: trong lớp)最高 (gāo: cao)的同学。","好啊。"]'::jsonb, 3, 'Câu vừa đọc: 好啊。 (Hǎo a.) → Được chứ.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_9_1_3', 'lesson-9', 'txt_9_1', 'listening', 'listening', '你想买什么衣服？', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Được rồi, tôi đồng ý, cậu đừng nói lại nữa!","Cậu muốn mua quần áo gì?","Bạn đã chuẩn bị đầy đủ đồ đạc để đi du lịch chưa?","Năm nay cháu mấy tuổi rồi?"]'::jsonb, 1, 'Nội dung nghe được: 你想买什么衣服？ (Nǐ xiǎng mǎi shénme yīfu?) → Cậu muốn mua quần áo gì?', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_9_1_4', 'lesson-9', 'txt_9_1', 'listening', 'listening', '我想买一条裤子，一条裙子和一件大衣。', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["我想来 (lái: đến)超市买一些 (yīxiē: một ít, một vài)东西。","我想买一条裤子，一条裙子和一件 (jiàn: cái, chiếc (áo, việc))大衣。","他是班里 (bān li: trong lớp)最高 (gāo: cao)的同学。","她去银行 (xíng: được)取 (qǔ: lấy)钱了。"]'::jsonb, 1, 'Câu vừa đọc: 我想买一条裤子，一条裙子和一件大衣。 (Wǒ xiǎng mǎi yī tiáo kùzi, yī tiáo qúnzi hé yī jiàn dàyī.) → Tớ muốn mua một chiếc quần dài, một chiếc váy và một chiếc áo khoác dài.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_9_2', 'lesson-9', 'Bài nghe tổng hợp: Ôn tập lũy tiến (Bài 1 – Bài 9)', 'Kết hợp từ vựng & mẫu câu đã học từ Bài 1 đến Bài 8 cùng trọng tâm Bài 9 để củng cố phản xạ nghe.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
