INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct9_22', 'lesson-9', NULL, 'comprehensive_test', 'listening', '你好，你想买什么衣服？ 我想试一下那件白色的大衣和这条黑色的裤子。 大衣很合适，颜色也不错，但是裤子有点儿大。 那你试试这条小一点儿的吧。', NULL, 'Sau khi mặc thử, Lan nhận xét chiếc quần thế nào?', '["Quá chật không mặc vừa","Hơi rộng một chút (有点儿大)","Màu sắc không đẹp","Vừa vặn hoàn hảo"]'::jsonb, 1, 'Lan nói rõ ''大衣很合适... 但是裤子有点儿大'' (quần hơi rộng).', 22) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
