INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq10_13', 'lesson-10', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “网上” chứa bộ thủ nào sau đây?', '["Bộ cấu tạo [能] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [网] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [眼] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [或] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)"]'::jsonb, 1, 'Chữ “网上” có Bộ cấu tạo [网] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán). Ghép từ các chữ Hán: [网] + [上].', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq10_14', 'lesson-10', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “电脑” chứa bộ thủ nào sau đây?', '["Bộ cấu tạo [电] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [质] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","方 (Phương) (Vuông vức, phương hướng)","Bộ cấu tạo [但] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)"]'::jsonb, 0, 'Chữ “电脑” có Bộ cấu tạo [电] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán). Ghép từ các chữ Hán: [电] + [脑].', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq10_15', 'lesson-10', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “手机” chứa bộ thủ nào sau đây?', '["Bộ cấu tạo [手] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [比] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","小 (Tiểu) (Nhỏ bé, ít ỏi)","Bộ cấu tạo [购] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)"]'::jsonb, 0, 'Chữ “手机” có Bộ cấu tạo [手] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán). Ghép từ các chữ Hán: [手] + [机].', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq10_16', 'lesson-10', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “手表” chứa bộ thủ nào sau đây?', '["Bộ cấu tạo [手] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [网] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [告] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [这] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)"]'::jsonb, 0, 'Chữ “手表” có Bộ cấu tạo [手] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán). Ghép từ các chữ Hán: [手] + [表].', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq10_17', 'lesson-10', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 1] Từ đã học “晚上” (wǎnshàng) có nghĩa là gì?', '["cùng nhau","nói cho","buổi tối","Giáo viên, thầy cô giáo"]'::jsonb, 2, 'Ôn tập Bài 1: “晚上” (wǎnshàng) nghĩa là: buổi tối.', 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq10_18', 'lesson-10', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 2] Từ đã học “她” (tā) có nghĩa là gì?', '["cô ấy, bà ấy, chị ấy,... (ngôi thứ ba số ít chỉ nữ)","Sao thế, như thế nào","chất lượng","cân (= 0,5kg ở Việt Nam)"]'::jsonb, 0, 'Ôn tập Bài 2: “她” (tā) nghĩa là: cô ấy, bà ấy, chị ấy,... (ngôi thứ ba số ít chỉ nữ).', 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq10_19', 'lesson-10', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 1] Từ đã học “学校” (xuéxiào) có nghĩa là gì?', '["anh ấy, cậu ấy... (ngôi thứ ba số ít chỉ nam)","đi","Trường học","đồng hồ"]'::jsonb, 2, 'Ôn tập Bài 1: “学校” (xuéxiào) nghĩa là: Trường học.', 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq10_20', 'lesson-10', NULL, 'expanded_quiz', 'reading', NULL, NULL, '[Mở rộng] Câu “网上买的手表质量怎么样？” có nghĩa tiếng Việt là gì?', '["Chất lượng đồng hồ mua trên mạng thế nào?","Quyển sách này là sách của tôi.","Một con bò","Một việc/chuyện"]'::jsonb, 0, '网上买的手表质量怎么样？ (Wǎngshàng mǎi de shǒubiǎo zhìliàng zěnmeyàng?) → Chất lượng đồng hồ mua trên mạng thế nào?', 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
