INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct10_22', 'lesson-10', NULL, 'comprehensive_test', 'listening', '你这副新眼镜是在超市买的吗？ 不是，我是在网上买的，不用出门也很方便。 网上的价格便宜吗？质量好不好？ 价格比商店便宜，但是买的时候要小心看质量。', NULL, 'Theo lời Minh, khi mua hàng trên mạng cần chú ý điều gì?', '["Chỉ cần chọn món đắt nhất","Không được mua kính mắt trên mạng","Phải đến tận siêu thị thanh toán","Phải cẩn thận xem xét chất lượng sản phẩm"]'::jsonb, 3, 'Minh khuyên: ''买的时候要小心看质量'' (cẩn thận xem chất lượng).', 22) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
