INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v11_1', 'lesson-11', '家', 'jiā', 'gia', 'nhà', 'Danh từ', 'Bộ cấu tạo [家] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Chữ độc thể / hình thanh gồm Bộ cấu tạo [家] và các nét bổ trợ.', 'Ghi nhớ chữ [家] (nhà) qua hình tượng Thành phần biểu ý/biểu âm cơ bản trong chữ Hán.', '学校左边有一家银行。', 'Xuéxiào zuǒbian yǒu yījiā yínháng.', 'Phía bên trái trường học có một ngân hàng.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v11_2', 'lesson-11', '全家', 'quánjiā', 'gia', 'cả nhà', 'Danh từ', 'Bộ cấu tạo [全] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [全] + [家].', 'Kết hợp các thành tố [全] + [家] để tạo thành từ mang nghĩa ''cả nhà''.', '她今年 22 岁。你想看我们全家的照片吗?', 'Tā jīnnián 22 suì. Nǐ xiǎng kàn wǒmen quánjiā de zhàopiàn ma?', 'Chị ấy năm nay 22 tuổi. Bạn có muốn xem ảnh cả nhà tôi không?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
