INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v11_4', 'lesson-11', '爷爷', 'yéye', 'từ Hán ngữ', 'ông nội', 'Danh từ', 'Bộ cấu tạo [爷] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [爷] + [爷].', 'Kết hợp các thành tố [爷] + [爷] để tạo thành từ mang nghĩa ''ông nội''.', '我家有六口人：我爷爷、奶奶、爸爸、妈妈、哥哥和我。你家呢？', 'Wǒjiā yǒu liù kǒu rén: Wǒ yéye, nǎinai, bàba, māma, gēge hé wǒ. Nǐ jiā ne?', 'Nhà tôi có 6 người: ông nội, bà nội, bố, mẹ, anh trai và tôi. Còn nhà bạn thì sao?', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
