INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v11_8', 'lesson-11', '姐姐', 'jiějie', 'tỷ tỷ', 'chị gái', 'Danh từ', 'Bộ cấu tạo [姐] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [姐] + [姐].', 'Kết hợp các thành tố [姐] + [姐] để tạo thành từ mang nghĩa ''chị gái''.', '我家有五口人：爸爸、妈妈、姐姐、弟弟和我。', 'Wǒjiā yǒu wǔ kǒu rén: Bàba, māma, jiějie, dìdi hé wǒ.', 'Nhà tôi có 5 người: bố, mẹ, chị gái, em trai và tôi.', 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
