INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v11_10', 'lesson-11', '弟弟', 'dìdi', 'đệ đệ', 'em trai', 'Danh từ', 'Bộ cấu tạo [弟] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [弟] + [弟].', 'Kết hợp các thành tố [弟] + [弟] để tạo thành từ mang nghĩa ''em trai''.', '我有一个弟弟。', 'Wǒ yǒu yígè dìdi.', 'Tôi có một cậu em trai.', 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v11_11', 'lesson-11', '自己', 'zìjǐ', 'từ Hán ngữ', 'tự mình, bản thân, một mình', 'Đại từ', 'Bộ cấu tạo [自] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [自] + [己].', 'Kết hợp các thành tố [自] + [己] để tạo thành từ mang nghĩa ''tự mình, bản thân, một mình''.', '他们只关心自己。', 'Tāmen zhǐ guānxīn zìjǐ.', 'Bọn họ chỉ quan tâm đến bản thân mình mà thôi.', 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v11_12', 'lesson-11', '岁', 'suì', 'từ Hán ngữ', 'tuổi', 'Danh từ', 'Bộ cấu tạo [岁] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Chữ độc thể / hình thanh gồm Bộ cấu tạo [岁] và các nét bổ trợ.', 'Ghi nhớ chữ [岁] (tuổi) qua hình tượng Thành phần biểu ý/biểu âm cơ bản trong chữ Hán.', '她今年 22 岁。你想看我们全家的照片吗?', 'Tā jīnnián 22 suì. Nǐ xiǎng kàn wǒmen quánjiā de zhàopiàn ma?', 'Chị ấy năm nay 22 tuổi. Bạn có muốn xem ảnh cả nhà tôi không?', 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v11_13', 'lesson-11', '年', 'nián', 'niên', 'năm', 'Danh từ', 'Bộ cấu tạo [年] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Chữ độc thể / hình thanh gồm Bộ cấu tạo [年] và các nét bổ trợ.', 'Ghi nhớ chữ [年] (năm) qua hình tượng Thành phần biểu ý/biểu âm cơ bản trong chữ Hán.', '你姐姐今年多大了？', 'Nǐ jiějie jīnnián duōdà le?', 'Chị gái bạn năm nay bao nhiêu tuổi rồi?', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v11_14', 'lesson-11', '狗', 'gǒu', 'từ Hán ngữ', 'con chó', 'Danh từ', 'Bộ cấu tạo [狗] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Chữ độc thể / hình thanh gồm Bộ cấu tạo [狗] và các nét bổ trợ.', 'Ghi nhớ chữ [狗] (con chó) qua hình tượng Thành phần biểu ý/biểu âm cơ bản trong chữ Hán.', '这里还有一条狗和一只猫。你们家是不是很爱它们？', 'Zhèli hái yǒu yītiáo gǒu hé yī zhī māo. Nǐmen jiā shì bu shì hěn ài tāmen?', 'Ở đây còn có một con chó và một con mèo nữa. Nhà bạn chắc yêu quý chúng lắm nhỉ?', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
