INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v11_16', 'lesson-11', '部分', 'bùfen', 'phân', 'bộ phận', 'Danh từ', 'Bộ cấu tạo [部] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [部] + [分].', 'Kết hợp các thành tố [部] + [分] để tạo thành từ mang nghĩa ''bộ phận''.', '是的，它们也是我家的一部分，对我来说，它们也是我的朋友。', 'Shì de, tāmen yěshì wǒjiā de yíbùfen, duì wǒ lái shuō, tāmen yěshì wǒ de péngyou.', 'Đúng rồi, chúng cũng là một phần của gia đình tôi; đối với tôi, chúng còn là những người bạn nữa.', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v11_17', 'lesson-11', '爱', 'ài', 'ái', 'yêu', 'Động từ', 'Bộ cấu tạo [爱] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Chữ độc thể / hình thanh gồm Bộ cấu tạo [爱] và các nét bổ trợ.', 'Ghi nhớ chữ [爱] (yêu) qua hình tượng Thành phần biểu ý/biểu âm cơ bản trong chữ Hán.', '这样也很可爱嘛！你姐姐好漂亮啊！', 'Zhèyàng yě hěn kě''ài ma! Nǐ jiějie hǎo piàoliang a!', 'Thế này cũng rất đáng yêu mà! Chị gái bạn xinh quá đi!', 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v11_18', 'lesson-11', '关心', 'guānxīn', 'từ Hán ngữ', 'quan tâm, chú ý', 'Động từ', '心/忄 (Tâm) (Trái tim, tình cảm, suy nghĩ, tâm lý)', 'Ghép từ các chữ Hán: [关] + [心].', 'Kết hợp các thành tố [关] + [心] để tạo thành từ mang nghĩa ''quan tâm, chú ý''.', '他们只关心自己。', 'Tāmen zhǐ guānxīn zìjǐ.', 'Bọn họ chỉ quan tâm đến bản thân mình mà thôi.', 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v11_19', 'lesson-11', '高', 'gāo', 'cao', 'cao', 'Tính từ', 'Bộ cấu tạo [高] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Chữ độc thể / hình thanh gồm Bộ cấu tạo [高] và các nét bổ trợ.', 'Ghi nhớ chữ [高] (cao) qua hình tượng Thành phần biểu ý/biểu âm cơ bản trong chữ Hán.', '你们家的人都那么高吗？', 'Nǐmen jiā de rén dōu nàme gāo ma?', 'Mọi người trong nhà bạn đều cao thế sao?', 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v11_20', 'lesson-11', '矮', 'ǎi', 'từ Hán ngữ', 'thấp', 'Tính từ', 'Bộ cấu tạo [矮] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Chữ độc thể / hình thanh gồm Bộ cấu tạo [矮] và các nét bổ trợ.', 'Ghi nhớ chữ [矮] (thấp) qua hình tượng Thành phần biểu ý/biểu âm cơ bản trong chữ Hán.', '是的，只有我这么矮。', 'Shì de, zhǐyǒu wǒ zhème ǎi.', 'Đúng vậy, chỉ có mình tôi lùn thế này thôi.', 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v11_21', 'lesson-11', '可爱', 'kě''ài', 'ái', 'đáng yêu', 'Tính từ', 'Bộ cấu tạo [可] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [可] + [爱].', 'Kết hợp các thành tố [可] + [爱] để tạo thành từ mang nghĩa ''đáng yêu''.', '这样也很可爱嘛！你姐姐好漂亮啊！', 'Zhèyàng yě hěn kě''ài ma! Nǐ jiějie hǎo piàoliang a!', 'Thế này cũng rất đáng yêu mà! Chị gái bạn xinh quá đi!', 21) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v11_22', 'lesson-11', '像', 'xiàng', 'từ Hán ngữ', 'giống', 'Động từ', 'Bộ cấu tạo [像] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Chữ độc thể / hình thanh gồm Bộ cấu tạo [像] và các nét bổ trợ.', 'Ghi nhớ chữ [像] (giống) qua hình tượng Thành phần biểu ý/biểu âm cơ bản trong chữ Hán.', '这是关于“像”的常用句子。', 'Zhè shì guānyú ''xiàng'' de chángyòng jùzi.', 'Đây là câu ví dụ sử dụng từ ''像'' (giống).', 22) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v11_23', 'lesson-11', '口', 'kǒu', 'khẩu', 'khẩu, người', 'Lượng từ', '口 (Khẩu) (Miệng, ăn uống, lời nói, âm thanh phát ra)', 'Chữ độc thể / hình thanh gồm 口 (Khẩu) và các nét bổ trợ.', 'Ghi nhớ chữ [口] (khẩu, người) qua hình tượng Miệng, ăn uống, lời nói, âm thanh phát ra.', '安妮，你家有几口人？', 'Ānnī, nǐ jiā yǒu jǐ kǒu rén?', 'Annie, nhà bạn có mấy người?', 23) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v11_24', 'lesson-11', '只', 'zhī', 'từ Hán ngữ', 'con (lượng từ)', 'Lượng từ', 'Bộ cấu tạo [只] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Chữ độc thể / hình thanh gồm Bộ cấu tạo [只] và các nét bổ trợ.', 'Ghi nhớ chữ [只] (con (lượng từ)) qua hình tượng Thành phần biểu ý/biểu âm cơ bản trong chữ Hán.', '这里只有我们两个人？', 'Zhèli zhǐ yǒu wǒmen liǎng gèrén?', 'Ở đây chỉ có hai người chúng ta?', 24) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
