INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v11_26', 'lesson-11', '它', 'tā', 'từ Hán ngữ', 'nó (ngôi thứ ba số ít, chỉ vật)', 'Đại từ', 'Bộ cấu tạo [它] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Chữ độc thể / hình thanh gồm Bộ cấu tạo [它] và các nét bổ trợ.', 'Ghi nhớ chữ [它] (nó (ngôi thứ ba số ít, chỉ vật)) qua hình tượng Thành phần biểu ý/biểu âm cơ bản trong chữ Hán.', '这里还有一条狗和一只猫。你们家是不是很爱它们？', 'Zhèli hái yǒu yītiáo gǒu hé yī zhī māo. Nǐmen jiā shì bu shì hěn ài tāmen?', 'Ở đây còn có một con chó và một con mèo nữa. Nhà bạn chắc yêu quý chúng lắm nhỉ?', 26) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v11_27', 'lesson-11', '它们', 'tāmen', 'môn', 'chúng nó (ngôi thứ ba số nhiều, chỉ vật)', 'Đại từ', 'Bộ cấu tạo [它] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [它] + [们].', 'Kết hợp các thành tố [它] + [们] để tạo thành từ mang nghĩa ''chúng nó (ngôi thứ ba số nhiều, chỉ vật)''.', '这里还有一条狗和一只猫。你们家是不是很爱它们？', 'Zhèli hái yǒu yītiáo gǒu hé yī zhī māo. Nǐmen jiā shì bu shì hěn ài tāmen?', 'Ở đây còn có một con chó và một con mèo nữa. Nhà bạn chắc yêu quý chúng lắm nhỉ?', 27) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v11_28', 'lesson-11', '多大', 'duōdà', 'đa đại', 'bao nhiêu tuổi, to/lớn chừng nào...(để hỏi)', 'Cụm từ / Tên riêng', '大 (Đại) (To lớn, vĩ đại)', 'Ghép từ các chữ Hán: [多] + [大].', 'Kết hợp các thành tố [多] + [大] để tạo thành từ mang nghĩa ''bao nhiêu tuổi, to/lớn chừng nào...(để hỏi)''.', '你姐姐今年多大了？', 'Nǐ jiějie jīnnián duōdà le?', 'Chị gái bạn năm nay bao nhiêu tuổi rồi?', 28) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v11_29', 'lesson-11', '那么', 'nàme', 'na ma', 'như thế, như thế kia thì, vậy thì, trong trường hợp ấy', 'Đại từ / Liên từ', 'Bộ cấu tạo [那] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [那] + [么].', 'Kết hợp các thành tố [那] + [么] để tạo thành từ mang nghĩa ''như thế, như thế kia thì, vậy thì, trong trường hợp ấy''.', '为什么你昨天那么晚才回来？', 'Wèishénme nǐ zuótiān nàme wǎn cái huílai?', 'Vì sao tối qua muộn như thế anh mới về?', 29) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v11_30', 'lesson-11', '这么', 'zhème', 'giá ma', 'như thế, như thế này', 'Đại từ', 'Bộ cấu tạo [这] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [这] + [么].', 'Kết hợp các thành tố [这] + [么] để tạo thành từ mang nghĩa ''như thế, như thế này''.', '他真的这么说。', 'Tā zhēn de zhème shuō.', 'Anh ta thật sự nói như thế.', 30) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v11_31', 'lesson-11', '当然', 'dāngrán', 'từ Hán ngữ', 'đương nhiên, dĩ nhiên', 'Tính từ / Phó từ', 'Bộ cấu tạo [当] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [当] + [然].', 'Kết hợp các thành tố [当] + [然] để tạo thành từ mang nghĩa ''đương nhiên, dĩ nhiên''.', '当然了。', 'Dāngrán le.', 'Tất nhiên rồi.', 31) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v11_32', 'lesson-11', '对我来说', 'duì wǒ lái shuō', 'ngã lai thuyết', 'đối với tôi mà nói,...', 'Cụm từ / Tên riêng', 'Bộ cấu tạo [对] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [对] + [我] + [来] + [说].', 'Kết hợp các thành tố [对] + [我] + [来] + [说] để tạo thành từ mang nghĩa ''đối với tôi mà nói,...''.', '是的，它们也是我家的一部分，对我来说，它们也是我的朋友。', 'Shì de, tāmen yěshì wǒjiā de yíbùfen, duì wǒ lái shuō, tāmen yěshì wǒ de péngyou.', 'Đúng rồi, chúng cũng là một phần của gia đình tôi; đối với tôi, chúng còn là những người bạn nữa.', 32) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g11_1', 'lesson-11', '1. “有” 句子 – Câu chữ 有', '●    Hình thức khẳng định: Chủ ngữ + 有 + Danh từ', ' ❖      有 được dùng để biểu thị sự sở hữu – có ●      Hình thức phủ định: Chủ ngữ + 没有+ Danh từ ●       Hình thức nghi vấn:  Chủ ngữ + 有 + Danh từ + 吗？ Chủ ngữ + 有没有+ Danh từ？ 我有一个弟弟。 Wǒ yǒu yígè dìdi. Tôi có một cậu em trai. 我没有弟弟。 Wǒ méiyǒu dìdi. T', NULL, '[{"hanzi":"我有一个弟弟。","pinyin":"Wǒ yǒu yígè dìdi.","meaning":"Tôi có một cậu em trai."},{"hanzi":"我没有弟弟。","pinyin":"Wǒ méiyǒu dìdi.","meaning":"Tôi không có em trai."}]'::jsonb, 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g11_2', 'lesson-11', '2. 只 +  Động từ  :   chỉ...', '只 + Động từ mang nghĩa là chỉ làm gì đó', ' 这里只有我们两个人？ Zhèli zhǐ yǒu wǒmen liǎng gèrén? Ở đây chỉ có hai người chúng ta? 他们只关心自己。 Tāmen zhǐ guānxīn zìjǐ. Bọn họ chỉ quan tâm đến bản thân mình mà thôi. 他不相信命运，只相信自己。 Tā bù xiāngxìn mìngyùn, zhǐ xiāngxìn zìjǐ. Anh ấy không tin vào vận mệnh, chỉ ', NULL, '[{"hanzi":"教室里有三个人。","pinyin":"Jiàoshì li yǒu sān gèrén.","meaning":"Trong phòng học có 3 người."},{"hanzi":"学校左边有一家银行。","pinyin":"Xuéxiào zuǒbian yǒu yījiā yínháng.","meaning":"Phía bên trái trường học có một ngân hàng."}]'::jsonb, 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g11_3', 'lesson-11', '3. 呢', 'Cấu trúc câu ngữ pháp trọng tâm', ' a) Trong 1 số tình huống nhất định, 呢 có thể dùng để thay thế cho đại từ nghi vấn 我的书呢？          =               我的书在哪儿呢？  (Sách của tôi đâu?) Wǒ de shū ne?        =               Wǒ de shū zài nǎr ne? 然后呢？           =               然后怎么样呢？        (', NULL, '[{"hanzi":"这里只有我们两个人？","pinyin":"Zhèli zhǐ yǒu wǒmen liǎng gèrén?","meaning":"Ở đây chỉ có hai người chúng ta?"},{"hanzi":"他们只关心自己。","pinyin":"Tāmen zhǐ guānxīn zìjǐ.","meaning":"Bọn họ chỉ quan tâm đến bản thân mình mà thôi."}]'::jsonb, 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g11_4', 'lesson-11', '4. 这么/那么 – như thế này, như vậy, như thế kia, như thế', 'Cấu trúc câu ngữ pháp trọng tâm', ' Là các đại từ chỉ thị, chỉ tính chất, trạng thái, phương thức, trình độ... thường dùng trước tính từ, động từ. 他真的这么说。 Tā zhēn de zhème shuō. Anh ta thật sự nói như thế. 你怎么这么早就起床了？ Nǐ zěnme zhème zǎo jiù qǐchuáng le? Sao sớm như thế này con đã dậy ', NULL, '[{"hanzi":"他不相信命运，只相信自己。","pinyin":"Tā bù xiāngxìn mìngyùn, zhǐ xiāngxìn zìjǐ.","meaning":"Anh ấy không tin vào vận mệnh, chỉ tin vào bản thân mình."},{"hanzi":"你是谁呢？","pinyin":"Nǐ shì shéi ne?","meaning":"Cậu là ai thế?"}]'::jsonb, 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_11_1', 'lesson-11', 'Bài khoá #1: Hội thoại giáo trình — Thành viên trong gia đình', 'Hội thoại chuẩn giáo trình Bài 11. Từ vựng chưa học được chú thích phiên âm & nghĩa trong ngoặc.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_11_1_1', 'txt_11_1', '范玉兰', '安妮，你家有几口人？', '安妮，你家有几口人？', 'Ānnī, nǐ jiā yǒu jǐ kǒu rén?', 'Annie, nhà bạn có mấy người?', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_11_1_2', 'txt_11_1', '安妮', '我家有六口人：我爷爷、奶奶、爸爸、妈妈、哥哥和我。你家呢？', '我家有六口人：我爷爷、奶奶、爸爸、妈妈、哥哥和我。你家呢？', 'Wǒjiā yǒu liù kǒu rén: Wǒ yéye, nǎinai, bàba, māma, gēge hé wǒ. Nǐ jiā ne?', 'Nhà tôi có 6 người: ông nội, bà nội, bố, mẹ, anh trai và tôi. Còn nhà bạn thì sao?', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_11_1_3', 'txt_11_1', '范玉兰', '我家有五口人：爸爸、妈妈、姐姐、弟弟和我。', '我家有五口人：爸爸、妈妈、姐姐、弟弟和我。', 'Wǒjiā yǒu wǔ kǒu rén: Bàba, māma, jiějie, dìdi hé wǒ.', 'Nhà tôi có 5 người: bố, mẹ, chị gái, em trai và tôi.', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_11_1_4', 'txt_11_1', '安妮', '你姐姐今年多大了？', '你姐姐今 (jīn: hôm nay, nay)年多大了？', 'Nǐ jiějie jīnnián duōdà le?', 'Chị gái bạn năm nay bao nhiêu tuổi rồi?', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_11_1_5', 'txt_11_1', '范玉兰', '她今年 22 岁。你想看我们全家的照片吗?', '她今 (jīn: hôm nay, nay)年 22 岁。你想看我们全家的照片吗?', 'Tā jīnnián 22 suì. Nǐ xiǎng kàn wǒmen quánjiā de zhàopiàn ma?', 'Chị ấy năm nay 22 tuổi. Bạn có muốn xem ảnh cả nhà tôi không?', 5) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_11_1_6', 'txt_11_1', '安妮', '当然了。', '当然了。', 'Dāngrán le.', 'Tất nhiên rồi.', 6) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_11_1_7', 'txt_11_1', '范玉兰', '等我一下儿，这是我家的照片，给你看。', '等我一下儿，这是我家的照片，给你看。', 'Děng wǒ yíxiàr, zhè shì wǒjiā de zhàopiàn, gěi nǐ kàn.', 'Chờ tôi một lát, đây là ảnh gia đình tôi, cho bạn xem này.', 7) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_11_1_8', 'txt_11_1', '安妮', '你们家的人都那么高吗？', '你们家的人都那么高吗？', 'Nǐmen jiā de rén dōu nàme gāo ma?', 'Mọi người trong nhà bạn đều cao thế sao?', 8) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_11_1_9', 'txt_11_1', '范玉兰', '是的，只有我这么矮。', '是的，只有我这么矮。', 'Shì de, zhǐyǒu wǒ zhème ǎi.', 'Đúng vậy, chỉ có mình tôi lùn thế này thôi.', 9) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_11_1_10', 'txt_11_1', '安妮', '这样也很可爱嘛！你姐姐好漂亮啊！', '这样也很可爱嘛 (ma: mà (ngữ khí))！你姐姐好漂亮啊！', 'Zhèyàng yě hěn kě''ài ma! Nǐ jiějie hǎo piàoliang a!', 'Thế này cũng rất đáng yêu mà! Chị gái bạn xinh quá đi!', 10) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_11_1_11', 'txt_11_1', '范玉兰', '对啊！很多人喜欢她。', '对啊！很多人喜欢她。', 'Duì a! Hěnduō rén xǐhuan tā.', 'Đúng vậy! Nhiều người thích chị ấy lắm.', 11) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_11_1_12', 'txt_11_1', '安妮', '这里还有一条狗和一只猫。你们家是不是很爱它们？', '这里 (lǐ: trong)还有一条狗和一只猫。你们家是不 (bù: không)是很爱它们？', 'Zhèli hái yǒu yītiáo gǒu hé yī zhī māo. Nǐmen jiā shì bu shì hěn ài tāmen?', 'Ở đây còn có một con chó và một con mèo nữa. Nhà bạn chắc yêu quý chúng lắm nhỉ?', 12) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_11_1_13', 'txt_11_1', '范玉兰', '是的，它们也是我家的一部分，对我来说，它们也是我的朋友。', '是的，它们也是我家的一部分，对我来说，它们也是我的朋友。', 'Shì de, tāmen yěshì wǒjiā de yíbùfen, duì wǒ lái shuō, tāmen yěshì wǒ de péngyou.', 'Đúng rồi, chúng cũng là một phần của gia đình tôi; đối với tôi, chúng còn là những người bạn nữa.', 13) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_11_1_1', 'lesson-11', 'txt_11_1', 'listening', 'listening', '安妮，你家有几口人？', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Một cái ghế","một câu chuyện","Annie, nhà bạn có mấy người?","quyển sách rất hay"]'::jsonb, 2, 'Nội dung nghe được: 安妮，你家有几口人？ (Ānnī, nǐ jiā yǒu jǐ kǒu rén?) → Annie, nhà bạn có mấy người?', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_11_1_2', 'lesson-11', 'txt_11_1', 'listening', 'listening', '我家有六口人：我爷爷、奶奶、爸爸、妈妈、哥哥和我。你家呢？', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["我姐姐比弟弟大 (dà: to, lớn)五岁。","你说 (shuō: nói)什么呢？","奶奶和爷爷每天 (tiān: ngày, trời)都很高兴。","我家有六口人：我爷爷、奶奶、爸爸、妈妈、哥哥和我。你家呢？"]'::jsonb, 3, 'Câu vừa đọc: 我家有六口人：我爷爷、奶奶、爸爸、妈妈、哥哥和我。你家呢？ (Wǒjiā yǒu liù kǒu rén: Wǒ yéye, nǎinai, bàba, māma, gēge hé wǒ. Nǐ jiā ne?) → Nhà tôi có 6 người: ông nội, bà nội, bố, mẹ, anh trai và tôi. Còn nhà bạn thì sao?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_11_1_3', 'lesson-11', 'txt_11_1', 'listening', 'listening', '我家有五口人：爸爸、妈妈、姐姐、弟弟和我。', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Ở đây còn có một con chó và một con mèo nữa. Nhà bạn chắc yêu quý chúng lắm nhỉ?","Bà ngoại cậu năm nay bao nhiêu rồi?","Nhà tôi có 5 người: bố, mẹ, chị gái, em trai và tôi.","Tớ muốn đến công viên chạy bộ."]'::jsonb, 2, 'Nội dung nghe được: 我家有五口人：爸爸、妈妈、姐姐、弟弟和我。 (Wǒjiā yǒu wǔ kǒu rén: Bàba, māma, jiějie, dìdi hé wǒ.) → Nhà tôi có 5 người: bố, mẹ, chị gái, em trai và tôi.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_11_1_4', 'lesson-11', 'txt_11_1', 'listening', 'listening', '你姐姐今年多大了？', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["我有一个弟弟。","奶奶和爷爷每天 (tiān: ngày, trời)都很高兴。","你姐姐今 (jīn: hôm nay, nay)年多大了？","你说 (shuō: nói)什么呢？"]'::jsonb, 2, 'Câu vừa đọc: 你姐姐今年多大了？ (Nǐ jiějie jīnnián duōdà le?) → Chị gái bạn năm nay bao nhiêu tuổi rồi?', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_11_2', 'lesson-11', 'Bài nghe tổng hợp: Ôn tập lũy tiến (Bài 1 – Bài 11)', 'Kết hợp từ vựng & mẫu câu đã học từ Bài 1 đến Bài 10 cùng trọng tâm Bài 11 để củng cố phản xạ nghe.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_11_2_1', 'txt_11_2', 'Ôn Bài 10', '这本书是我的。', '这本书是我的。', 'Zhè běn shū shì wǒ de.', 'Quyển sách này là sách của tôi.', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_11_2_2', 'txt_11_2', 'Bài 11', '我有一个弟弟。', '我有一个弟弟。', 'Wǒ yǒu yígè dìdi.', 'Tôi có một cậu em trai.', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_11_2_3', 'txt_11_2', 'Ôn Bài 5', '我明天上午八点上课。', '我明天上午八点上课。', 'Wǒ míngtiān shàngwǔ bā diǎn shàngkè.', 'Tám giờ sáng ngày mai tớ đi học.', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_11_2_4', 'txt_11_2', 'Bài 11', '他们只关心自己。', '他们只关心自己。', 'Tāmen zhǐ guānxīn zìjǐ.', 'Bọn họ chỉ quan tâm đến bản thân mình mà thôi.', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_11_2_5', 'txt_11_2', 'Ôn Bài 1', '她是老师。', '她是老师。', 'Tā shì lǎoshī.', 'Cô ấy là giáo viên.', 5) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_11_2_6', 'txt_11_2', 'Bài 11', '你是谁呢？', '你是谁呢？', 'Nǐ shì shéi ne?', 'Cậu là ai thế?', 6) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_11_2_7', 'txt_11_2', 'Ôn Bài 3', '她很漂亮。', '她很漂亮。', 'Tā hěn piàoliang.', 'Cô ấy rất xinh đẹp.', 7) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_11_2_8', 'txt_11_2', 'Bài 11', '他在吃饭呢。', '他在吃饭呢。', 'Tā zài chīfàn ne.', 'Anh ấy đang ăn cơm kìa.', 8) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_11_2_1', 'lesson-11', 'txt_11_2', 'listening', 'listening', '这本书是我的。', NULL, '[Ôn tập Bài 10] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Nhà tôi có 5 người: bố, mẹ, chị gái, em trai và tôi.","Một phần quà","Thầy ấy là thầy giáo của tớ.","Quyển sách này là sách của tôi."]'::jsonb, 3, 'Nội dung nghe được: 这本书是我的。 (Zhè běn shū shì wǒ de.) → Quyển sách này là sách của tôi.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_11_2_2', 'lesson-11', 'txt_11_2', 'listening', 'listening', '我有一个弟弟。', NULL, '[Bài 11] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["奶奶和爷爷每天 (tiān: ngày, trời)都很高兴。","这里 (lǐ: trong)只有我们两 (liǎng: hai (số lượng))个人？","这张 (zhāng: tờ, tấm, chiếc)全家的照片真好看！","我有一个弟弟。"]'::jsonb, 3, 'Câu vừa đọc: 我有一个弟弟。 (Wǒ yǒu yígè dìdi.) → Tôi có một cậu em trai.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_11_2_3', 'lesson-11', 'txt_11_2', 'listening', 'listening', '我明天上午八点上课。', NULL, '[Ôn tập Bài 5] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Tớ biết bơi, còn biết trượt băng.","Tám giờ sáng ngày mai tớ đi học.","Thầy ấy là thầy giáo của tớ.","Đã bảy giờ rồi, chắc anh ấy đã tan làm về nhà rồi."]'::jsonb, 1, 'Nội dung nghe được: 我明天上午八点上课。 (Wǒ míngtiān shàngwǔ bā diǎn shàngkè.) → Tám giờ sáng ngày mai tớ đi học.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_11_2_4', 'lesson-11', 'txt_11_2', 'listening', 'listening', '他们只关心自己。', NULL, '[Bài 11] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["他正在 (zhèngzài: đang, động tác đang diễn ra)听音乐 (tīng yīnyuè: nghe nhạc)呢。","他们只关心自己。","你是谁呢？","他真的这么说 (shuō: nói)。"]'::jsonb, 1, 'Câu vừa đọc: 他们只关心自己。 (Tāmen zhǐ guānxīn zìjǐ.) → Bọn họ chỉ quan tâm đến bản thân mình mà thôi.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_11_2_5', 'lesson-11', 'txt_11_2', 'listening', 'listening', '她是老师。', NULL, '[Ôn tập Bài 1] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Tôi dậy rất sớm.","Kỳ học này tôi kiểm tra một lần rồi.","Tôi đứng ở giữa Lâm và Phương.","Cô ấy là giáo viên."]'::jsonb, 3, 'Nội dung nghe được: 她是老师。 (Tā shì lǎoshī.) → Cô ấy là giáo viên.', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_11_3', 'lesson-11', 'Bài khoá mở rộng: Giới thiệu ảnh gia đình (Mở rộng)', 'Hội thoại tình huống mới xây dựng dựa trên từ vựng và ngữ pháp Bài 11 (không trùng lặp nguyên văn giáo trình).', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_11_3_1', 'txt_11_3', 'Annie', '日明，这是你全家的照片吗？你们家有几口人？', '日明，这是你全家的照片吗？你们家有几口人？', 'Rìmíng, zhè shì nǐ quánjiā de zhàopiàn ma? Nǐmen jiā yǒu jǐ kǒu rén?', 'Nhật Minh, đây là ảnh cả gia đình bạn à? Nhà bạn có mấy người?', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_11_3_2', 'txt_11_3', 'Minh', '我家有五口人：爷爷、爸爸、妈妈、姐姐和我。', '我家有五口人：爷爷、爸爸、妈妈、姐姐和我。', 'Wǒ jiā yǒu wǔ kǒu rén: yéye, bàba, māma, jiějie hé wǒ.', 'Nhà tôi có năm người: ông nội, bố, mẹ, chị gái và tôi.', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_11_3_3', 'txt_11_3', 'Annie', '你姐姐今年多大？她工作了吗？', '你姐姐今 (jīn: hôm nay, nay)年多大？她工作 (gōngzuò: nghề nghiệp, công việc)了吗？', 'Nǐ jiějie jīnnián duōdà? Tā gōngzuò le ma?', 'Chị gái bạn năm nay bao nhiêu tuổi? Chị ấy đi làm chưa?', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_11_3_4', 'txt_11_3', 'Minh', '她二十五岁了，在一家医院工作，很喜欢小猫。', '她二十五岁了，在一家医院 (yīyuàn: bệnh viện)工作 (gōngzuò: nghề nghiệp, công việc)，很喜欢小 (xiǎo: nhỏ, bé)猫。', 'Tā èrshíwǔ suì le, zài yì jiā yīyuàn gōngzuò, hěn xǐhuan xiǎo māo.', 'Chị ấy 25 tuổi rồi, làm việc ở một bệnh viện và rất thích mèo con.', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_11_3_1', 'lesson-11', 'txt_11_3', 'listening', 'listening', '日明，这是你全家的照片吗？你们家有几口人？ 我家有五口人：爷爷、爸爸、妈妈、姐姐和我。 你姐姐今年多大？她工作了吗？ 她二十五岁了，在一家医院工作，很喜欢小猫。', NULL, '[Nghe hiểu tình huống mới] Chị gái của Nhật Minh năm nay bao nhiêu tuổi và làm việc ở đâu?', '["18 tuổi, thích nuôi chó","25 tuổi, làm việc tại một bệnh viện","22 tuổi, còn là sinh viên","25 tuổi, làm ở hiệu sách"]'::jsonb, 1, 'Minh nói ''她二十五岁了，在一家医院工作''.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_11_3_2', 'lesson-11', 'txt_11_3', 'listening', 'listening', '日明，这是你全家的照片吗？你们家有几口人？', NULL, '[Mở rộng] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Tôi không có em trai.","Khó quá đi, tôi không biết nên làm như thế nào nữa!","Mỗi học sinh đều đi học bằng xe buýt.","Nhật Minh, đây là ảnh cả gia đình bạn à? Nhà bạn có mấy người?"]'::jsonb, 3, 'Nội dung nghe được: 日明，这是你全家的照片吗？你们家有几口人？ (Rìmíng, zhè shì nǐ quánjiā de zhàopiàn ma? Nǐmen jiā yǒu jǐ kǒu rén?) → Nhật Minh, đây là ảnh cả gia đình bạn à? Nhà bạn có mấy người?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_11_3_3', 'lesson-11', 'txt_11_3', 'listening', 'listening', '我家有五口人：爷爷、爸爸、妈妈、姐姐和我。', NULL, '[Mở rộng] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["我家有五口人：爷爷、爸爸、妈妈、姐姐和我。","你姐姐今 (jīn: hôm nay, nay)年多大了？","奶奶和爷爷每天 (tiān: ngày, trời)都很高兴。","学校左边有一家银行 (xíng: được)。"]'::jsonb, 0, 'Câu vừa đọc: 我家有五口人：爷爷、爸爸、妈妈、姐姐和我。 (Wǒ jiā yǒu wǔ kǒu rén: yéye, bàba, māma, jiějie hé wǒ.) → Nhà tôi có năm người: ông nội, bố, mẹ, chị gái và tôi.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_11_3_4', 'lesson-11', 'txt_11_3', 'listening', 'listening', '你姐姐今年多大？她工作了吗？', NULL, '[Mở rộng] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Chị gái bạn năm nay bao nhiêu tuổi? Chị ấy đi làm chưa?","Hai mươi lăm cái","Cậu ấy là người cao nhất trong lớp.","Mai tớ thi rồi, không thể đi cùng cậu được."]'::jsonb, 0, 'Nội dung nghe được: 你姐姐今年多大？她工作了吗？ (Nǐ jiějie jīnnián duōdà? Tā gōngzuò le ma?) → Chị gái bạn năm nay bao nhiêu tuổi? Chị ấy đi làm chưa?', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss11_1', 'lesson-11', '我家有四口人爸爸妈妈哥哥和我', '[Mở rộng] Nhà tôi có bốn người: bố, mẹ, anh trai và tôi.', 'Wǒ jiā yǒu sì kǒu rén: bàba, māma, gēge hé wǒ.', '["我家有四","口人","爸爸","妈妈","哥哥","和我"]'::jsonb, NULL, 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss11_2', 'lesson-11', '奶奶和爷爷每天都很高兴', '[Mở rộng] Bà nội và ông nội ngày nào cũng rất vui vẻ.', 'Nǎinai hé yéye měitiān dōu hěn gāoxìng.', '["奶奶","和","爷爷","每天","都很","高兴"]'::jsonb, 'Từ chưa học: 天 (tiān: ngày, trời)', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
