INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss11_5', 'lesson-11', '昨天下午你去图书馆了吗', '[Ôn tập Bài 5] Chiều hôm qua bạn có đi thư viện không?', 'Zuótiān xiàwǔ nǐ qù túshūguǎn le ma?', '["昨天","下午","你","去","图书馆","了吗"]'::jsonb, NULL, 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
