INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr11_vi_4', 'lesson-11', 'vi_to_zh', 'Bọn họ chỉ quan tâm đến bản thân mình mà thôi.', NULL, NULL, '他们只关心自己。', NULL, 'tāmen zhǐ guānxīn zìjǐ', '[]'::jsonb, 'Gợi ý Pinyin: Tāmen zhǐ guānxīn zìjǐ.', 'Bọn họ chỉ quan tâm đến bản thân mình mà thôi. → 他们只关心自己。 (Tāmen zhǐ guānxīn zìjǐ.)', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr11_zh_1', 'lesson-11', 'zh_to_vi', '[Mở rộng] 这张 (zhāng: tờ, tấm, chiếc)全家的照片真好看！', '这张全家的照片真好看！', 'Zhè zhāng quánjiā de zhàopiàn zhēn hǎokàn!', NULL, 'Bức ảnh cả gia đình này đẹp thật đấy!', NULL, '["Bức","ảnh","cả"]'::jsonb, 'Pinyin: Zhè zhāng quánjiā de zhàopiàn zhēn hǎokàn!', '这张全家的照片真好看！ (Zhè zhāng quánjiā de zhàopiàn zhēn hǎokàn!) nghĩa là: Bức ảnh cả gia đình này đẹp thật đấy!', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr11_zh_2', 'lesson-11', 'zh_to_vi', '[Mở rộng] 我姐姐比弟弟大 (dà: to, lớn)五岁。', '我姐姐比弟弟大五岁。', 'Wǒ jiějie bǐ dìdi dà wǔ suì.', NULL, 'Chị gái tôi lớn hơn em trai 5 tuổi.', NULL, '["Chị","gái","tôi"]'::jsonb, 'Pinyin: Wǒ jiějie bǐ dìdi dà wǔ suì.', '我姐姐比弟弟大五岁。 (Wǒ jiějie bǐ dìdi dà wǔ suì.) nghĩa là: Chị gái tôi lớn hơn em trai 5 tuổi.', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
