INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq11_6', 'lesson-11', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Từ Hán tự “爸爸” có nghĩa tiếng Việt là gì?', '["như thế, như thế kia thì, vậy thì, trong trường hợp ấy","thấp","con (lượng từ)","bố"]'::jsonb, 3, '“爸爸” (bàba) là Danh từ, nghĩa là: bố.', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
