INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v12_15', 'lesson-12', '听音乐', 'tīng yīnyuè', 'thính lạc', 'nghe nhạc', 'Động từ', 'Bộ cấu tạo [听] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [听] + [音] + [乐].', 'Kết hợp các thành tố [听] + [音] + [乐] để tạo thành từ mang nghĩa ''nghe nhạc''.', '打游戏、听音乐、聊天儿、喝 水、吃东西。到十点半我们才回宿舍。现在回想起来，昨天真快乐，真热闹。', 'Dǎ yóuxì, tīng yīnyuè, liáotiānr, hē shuǐ, chī dōngxi. Dào shí diǎn bàn wǒmen cái huí sùshè. Xiànzài huíxiǎng qǐlai, zuótiān zhēn kuàilè, zhēn rènao.', 'Chơi game, nghe nhạc, trò chuyện, uống nước, ăn uống. Đến 10 giờ rưỡi bọn tớ mới về ký túc xá. Giờ nhớ lại, hôm qua thật vui và náo nhiệt.', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v12_16', 'lesson-12', '打游戏', 'dǎ yóuxì', 'du', 'chơi game, chơi trò chơi', 'Động từ', 'Bộ cấu tạo [打] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [打] + [游] + [戏].', 'Kết hợp các thành tố [打] + [游] + [戏] để tạo thành từ mang nghĩa ''chơi game, chơi trò chơi''.', '打游戏、听音乐、聊天儿、喝 水、吃东西。到十点半我们才回宿舍。现在回想起来，昨天真快乐，真热闹。', 'Dǎ yóuxì, tīng yīnyuè, liáotiānr, hē shuǐ, chī dōngxi. Dào shí diǎn bàn wǒmen cái huí sùshè. Xiànzài huíxiǎng qǐlai, zuótiān zhēn kuàilè, zhēn rènao.', 'Chơi game, nghe nhạc, trò chuyện, uống nước, ăn uống. Đến 10 giờ rưỡi bọn tớ mới về ký túc xá. Giờ nhớ lại, hôm qua thật vui và náo nhiệt.', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
