INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr12_zh_1', 'lesson-12', 'zh_to_vi', '[Mở rộng] 下次我们再 (zài: lại)一起聊天儿吧！', '下次我们再一起聊天儿吧！', 'Xiàcì wǒmen zài yīqǐ liáotiānr ba!', NULL, 'Lần sau chúng ta lại cùng nhau trò chuyện nhé!', NULL, '["Lần","sau","chúng"]'::jsonb, 'Pinyin: Xiàcì wǒmen zài yīqǐ liáotiānr ba!', '下次我们再一起聊天儿吧！ (Xiàcì wǒmen zài yīqǐ liáotiānr ba!) nghĩa là: Lần sau chúng ta lại cùng nhau trò chuyện nhé!', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
