INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq12_13', 'lesson-12', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “客人” chứa bộ thủ nào sau đây?', '["Bộ cấu tạo [接] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","口 (Khẩu) (Miệng, ăn uống, lời nói)","木 (Mộc) (Cây cối, gỗ)","人 (Nhân) (Con người, nhân loại)"]'::jsonb, 3, 'Chữ “客人” có 人 (Nhân) (Con người, nhân loại). Ghép từ các chữ Hán: [客] + [人].', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq12_14', 'lesson-12', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “水” chứa bộ thủ nào sau đây?', '["Bộ cấu tạo [打] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [茶] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [水] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [决] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)"]'::jsonb, 2, 'Chữ “水” có Bộ cấu tạo [水] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán). Chữ độc thể / hình thanh gồm Bộ cấu tạo [水] và các nét bổ trợ.', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq12_15', 'lesson-12', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “茶” chứa bộ thủ nào sau đây?', '["Bộ cấu tạo [茶] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [准] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [听] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [玩] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)"]'::jsonb, 0, 'Chữ “茶” có Bộ cấu tạo [茶] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán). Chữ độc thể / hình thanh gồm Bộ cấu tạo [茶] và các nét bổ trợ.', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq12_16', 'lesson-12', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “咖啡” chứa bộ thủ nào sau đây?', '["口 (Khẩu) (Miệng, ăn uống, lời nói)","Bộ cấu tạo [下] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [欢] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [咖] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)"]'::jsonb, 3, 'Chữ “咖啡” có Bộ cấu tạo [咖] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán). Ghép từ các chữ Hán: [咖] + [啡].', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq12_17', 'lesson-12', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 10] Từ đã học “购物” (gòuwù) có nghĩa là gì?', '["mua hàng, mua đồ","em trai","Bạch Như Tuyết (sinh viên người Trung Quốc đại học Bắc Kinh)","đọc, xem, nhìn, thăm,..."]'::jsonb, 0, 'Ôn tập Bài 10: “购物” (gòuwù) nghĩa là: mua hàng, mua đồ.', 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq12_18', 'lesson-12', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 6] Từ đã học “中间” (zhōngjiān) có nghĩa là gì?', '["sách","xoài","phía trước","ở giữa, chính giữa"]'::jsonb, 3, 'Ôn tập Bài 6: “中间” (zhōngjiān) nghĩa là: ở giữa, chính giữa.', 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq12_19', 'lesson-12', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 6] Từ đã học “到” (dào) có nghĩa là gì?', '["đến","hôm nay","chết, mất","màu vàng"]'::jsonb, 0, 'Ôn tập Bài 6: “到” (dào) nghĩa là: đến.', 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq12_20', 'lesson-12', NULL, 'expanded_quiz', 'reading', NULL, NULL, '[Mở rộng] Câu “请喝一杯热 (rè: nóng)茶或者咖啡吧。” có nghĩa tiếng Việt là gì?', '["Bệnh của mẹ khỏi lâu rồi, con đừng lo lắng.","Chúng tôi đang thảo luận về vấn đề này.","Chúng tôi đang bàn bạc thảo luận.","Mời uống một tách trà nóng hoặc cà phê nhé."]'::jsonb, 3, '请喝一杯热茶或者咖啡吧。 (Qǐng hē yì bēi rè chá huòzhě kāfēi ba.) → Mời uống một tách trà nóng hoặc cà phê nhé.', 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq12_21', 'lesson-12', NULL, 'expanded_quiz', 'reading', NULL, NULL, '[Đọc hiểu mở rộng] Đọc đoạn hội thoại:
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq12_22', 'lesson-12', NULL, 'expanded_quiz', 'reading', NULL, NULL, 'Câu “他这个人真好！” có nghĩa tiếng Việt là gì?', '["Con người anh ta thật là tốt!","Anh ấy đang nghe nhạc.","Sao giờ cậu mới đến vậy, mọi người đều ăn cả rồi.","Tôi không biết người này là nam hay là nữ nữa."]'::jsonb, 0, '他这个人真好！ (Tā zhège rén zhēn hǎo!) → Con người anh ta thật là tốt!', 22) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct12_1', 'lesson-12', NULL, 'comprehensive_test', 'listening', '我也有点儿不好意思，但是张风和他家人都很欢迎我们。阿姨给我们准备了很多好吃的，有茶、咖啡、牛肉、鱼、水果等等。', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Được rồi, chúng ta đi thanh toán thôi!","Em chào thầy Lưu buổi chiều ạ!","Đúng rồi. Bạn có biết thư viện ở tầng mấy không?","Tớ cũng hơi ngại một chút, nhưng Trương Phong và gia đình cậu ấy rất hoan nghênh bọn tớ. Cô ấy chuẩn bị cho bọn tớ rất nhiều đồ ngon, nào là trà, cà phê, thịt bò, cá, hoa quả, v.v."]'::jsonb, 3, 'Nội dung nghe được: “我也有点儿不好意思，但是张风和他家人都很欢迎我们。阿姨给我们准备了很多好吃的，有茶、咖啡、牛肉、鱼、水果等等。” (Wǒ yě yǒudiǎnr bù hǎoyìsi, dànshì Zhāng Fēng hé tā jiārén dōu hěn huānyíng wǒmen. Āyí gěi wǒmen zhǔnbèi le hěnduō hǎo chī de, yǒu chá, kāfēi, niúròu, yú, shuǐguǒ děng děng.) → Tớ cũng hơi ngại một chút, nhưng Trương Phong và gia đình cậu ấy rất hoan nghênh bọn tớ. Cô ấy chuẩn bị cho bọn tớ rất nhiều đồ ngon, nào là trà, cà phê, thịt bò, cá, hoa quả, v.v.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct12_2', 'lesson-12', NULL, 'comprehensive_test', 'listening', '是的。张风给我们介绍了他的妈妈和弟弟，他爸爸不在家。阿姨很漂亮、很年轻，他弟弟也很可爱。他们都很热情地接待了我们。', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["他这个人真好！","太好了，十一点半我也在食堂等你。","早上好！我是刘老师。你是阮日明吗？","是的。张风给我们介绍了他的妈妈和弟弟，他爸爸不在家。阿姨很漂亮、很年轻，他弟弟也很可爱。他们都很热情地接待了我们。"]'::jsonb, 3, 'Câu vừa đọc: “是的。张风给我们介绍了他的妈妈和弟弟，他爸爸不在家。阿姨很漂亮、很年轻，他弟弟也很可爱。他们都很热情地接待了我们。” (Shì de. Zhāng Fēng gěi wǒmen jièshào le tā de māma hé dìdi, tā bàba bú zàijiā. Āyí hěn piàoliang, hěn niánqīng, tā dìdi yě hěn kě''ài. Tāmen dōu hěn rèqíng de jiēdài le wǒmen.) → Đúng rồi. Trương Phong giới thiệu mẹ và em trai cậu ấy cho bọn tớ, bố cậu ấy không có ở nhà. Cô ấy rất xinh đẹp và trẻ trung, em trai cậu ấy cũng rất đáng yêu. Mọi người đều tiếp đón bọn tớ rất nhiệt tình.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct12_3', 'lesson-12', NULL, 'comprehensive_test', 'listening', '那件事是真的。', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Việc đó là thật.","Trong phòng học có 3 người.","Bây giờ là 8 giờ 15 phút sáng.","Vương là người như thế nào, bạn giới thiệu cho tôi xíu đi."]'::jsonb, 0, 'Nội dung nghe được: “那件事是真的。” (Nà jiàn shì shì zhēn de.) → Việc đó là thật.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct12_4', 'lesson-12', NULL, 'comprehensive_test', 'listening', '你问上午还是下午？上午六点我去图书馆学习，下午跟 山本同学、马克同学到张风家。', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["图书馆几点关门？","你问上午还是下午？上午六点我去图书馆学习，下午跟 山本同学、马克同学到张风家。","你姐姐今年多大？她工作了吗？","你们到他家聚会还是有什么事？"]'::jsonb, 1, 'Câu vừa đọc: “你问上午还是下午？上午六点我去图书馆学习，下午跟 山本同学、马克同学到张风家。” (Nǐ wèn shàngwǔ háishi xiàwǔ? Shàngwǔ liù diǎn wǒ qù túshūguǎn xuéxí, xiàwǔ gēn Shānběn tóngxué, Mǎkè tóngxué dào Zhāng Fēng jiā.) → Cậu hỏi buổi sáng hay buổi chiều? 6 giờ sáng tớ đi thư viện học, buổi chiều cùng bạn Yamamoto và bạn Mark đến nhà Trương Phong.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct12_5', 'lesson-12', NULL, 'comprehensive_test', 'listening', '这个会议，你去还是小明去？', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Cô ơi, táo hôm nay có ngọt không ạ?","Chờ tôi một lát, đây là ảnh gia đình tôi, cho bạn xem này.","Cái váy này là của em à?","Hội nghị này, cậu đi hay Minh đi?"]'::jsonb, 3, 'Nội dung nghe được: “这个会议，你去还是小明去？” (Zhège huìyì, nǐ qù háishi Xiǎomíng qù?) → Hội nghị này, cậu đi hay Minh đi?', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct12_6', 'lesson-12', NULL, 'comprehensive_test', 'listening', '中村是中国人还是日本人？', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["中村是中国人还是日本人？","我想来超市买一些东西。","质量呢？","你说什么？"]'::jsonb, 0, 'Câu vừa đọc: “中村是中国人还是日本人？” (Zhōngcūn shì Zhōngguó rén háishi Rìběn rén?) → Nakamura là người Trung Quốc hay người Nhật Bản?', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct12_7', 'lesson-12', NULL, 'comprehensive_test', 'listening', '马路北边有一个大书店', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Bạn cứ đi thẳng về phía bắc, đến ngã tư rẽ phải là tới.","Nhà tôi có 6 người: ông nội, bà nội, bố, mẹ, anh trai và tôi. Còn nhà bạn thì sao?","Phía bắc con đường có một hiệu sách lớn.","Chào bạn Mark! Bạn cũng là người Canada à?"]'::jsonb, 2, 'Nội dung nghe được: “马路北边有一个大书店” (Mǎlù běibian yǒu yígè dà shūdiàn.) → Phía bắc con đường có một hiệu sách lớn.', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct12_8', 'lesson-12', NULL, 'comprehensive_test', 'listening', '谢谢你和阿姨这么热情地接待我们。', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["汉语老师","谢谢你和阿姨这么热情地接待我们。","为什么你昨天那么晚才回来？","欢迎大家来我家做客！快请坐！"]'::jsonb, 1, 'Câu vừa đọc: “谢谢你和阿姨这么热情地接待我们。” (Xièxie nǐ hé āyí zhème rèqíng de jiēdài wǒmen.) → Cảm ơn cậu và cô đã tiếp đón bọn mình nhiệt tình thế này.', 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
