INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct12_25', 'lesson-12', NULL, 'comprehensive_test', 'listening', '欢迎大家来我家做客！快请坐！ 谢谢你和阿姨这么热情地接待我们。 你们想喝茶还是咖啡？这里还有水果和牛肉。 我要一杯热茶吧。吃饱了我们一起听音乐、聊天儿！', NULL, 'Lan chọn đồ uống gì khi đến nhà Trương Phong làm khách?', '["Một ly cà phê đá","Một ly sữa tươi","Một cốc nước ép táo","Một tách trà nóng (热茶)"]'::jsonb, 3, 'Lan trả lời ''我要一杯热茶吧'' (một tách trà nóng).', 25) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
