INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v13_21', 'lesson-13', '一些', 'yīxiē', 'từ Hán ngữ', 'một ít, một vài', 'Số từ', 'Bộ cấu tạo [一] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [一] + [些].', 'Kết hợp các thành tố [一] + [些] để tạo thành từ mang nghĩa ''một ít, một vài''.', '这是关于“一些”的常用句子。', 'Zhè shì guānyú ''yīxiē'' de chángyòng jùzi.', 'Đây là câu ví dụ sử dụng từ ''一些'' (một ít, một vài).', 21) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v13_22', 'lesson-13', '双', 'shuāng', 'từ Hán ngữ', 'đôi (đũa, dép,...)', 'Lượng từ', 'Bộ cấu tạo [双] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Chữ độc thể / hình thanh gồm Bộ cấu tạo [双] và các nét bổ trợ.', 'Ghi nhớ chữ [双] (đôi (đũa, dép,...)) qua hình tượng Thành phần biểu ý/biểu âm cơ bản trong chữ Hán.', '我打算送给她一顶帽子和一双鞋。你觉得这顶红色的帽子怎么样？', 'Wǒ dǎsuan sòng gěi tā yī dǐng màozi hé yīshuāng xié. Nǐ juéde zhè dǐng hóngsè de màozi zěnmeyàng?', 'Tớ định tặng em ấy một chiếc mũ và một đôi giày. Cậu thấy chiếc mũ màu đỏ này thế nào?', 22) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v13_23', 'lesson-13', '感动', 'gǎndòng', 'cảm', 'cảm động', 'Động từ', 'Bộ cấu tạo [感] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [感] + [动].', 'Kết hợp các thành tố [感] + [动] để tạo thành từ mang nghĩa ''cảm động''.', '这是关于“感动”的常用句子。', 'Zhè shì guānyú ''gǎndòng'' de chángyòng jùzi.', 'Đây là câu ví dụ sử dụng từ ''感动'' (cảm động).', 23) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v13_24', 'lesson-13', '又', 'yòu', 'từ Hán ngữ', 'lại, hành động lặp lại đang hoặc đã xảy ra', 'Phó từ', '又 (Hựu) (Bàn tay phải, lặp lại, lại nữa)', 'Chữ độc thể / hình thanh gồm 又 (Hựu) và các nét bổ trợ.', 'Ghi nhớ chữ [又] (lại, hành động lặp lại đang hoặc đã xảy ra) qua hình tượng Bàn tay phải, lặp lại, lại nữa.', '马克，你又在干什么呢？', 'Mǎkè, nǐ yòu zài gàn shénme ne?', 'Mark, cậu lại đang làm gì nữa vậy?', 24) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v13_25', 'lesson-13', '正在', 'zhèngzài', 'tại', 'đang , động tác đang diễn ra', 'Phó từ', 'Bộ cấu tạo [正] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [正] + [在].', 'Kết hợp các thành tố [正] + [在] để tạo thành từ mang nghĩa ''đang , động tác đang diễn ra''.', '我正在洗澡呢。', 'Wǒ zhèngzài xǐzǎo ne.', 'Tôi đang tắm.', 25) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v13_26', 'lesson-13', '再', 'zài', 'từ Hán ngữ', 'lại, hành động lặp lại trong tương lai, hoặc sau một khoảng thời gian rồi mới làm gì', 'Phó từ', 'Bộ cấu tạo [再] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Chữ độc thể / hình thanh gồm Bộ cấu tạo [再] và các nét bổ trợ.', 'Ghi nhớ chữ [再] (lại, hành động lặp lại trong tương lai, hoặc sau một khoảng thời gian rồi mới làm gì) qua hình tượng Thành phần biểu ý/biểu âm cơ bản trong chữ Hán.', '我明天再来你家玩儿吧！', 'Wǒ míngtiān zài lái nǐ jiā wánr ba!', 'Ngày mai tớ sẽ đến nhà cậu chơi tiếp nhé!', 26) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v13_27', 'lesson-13', '差点儿', 'chàdiǎnr', 'sai điểm nhi', 'suýt nữa, suýt chút nữa', 'Phó từ', 'Bộ cấu tạo [差] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [差] + [点] + [儿].', 'Kết hợp các thành tố [差] + [点] + [儿] để tạo thành từ mang nghĩa ''suýt nữa, suýt chút nữa''.', '我差点儿忘了，星期六也是我的一个朋友的生日。那你买你的吧，我现在去书店给他买一本汉语书，明天再跟你说吧！', 'Wǒ chàdiǎnr wàng le, xīngqīliù yěshì wǒ de yígè péngyou de shēngrì. Nà nǐ mǎi nǐ de ba, wǒ xiànzài qù shūdiàn gěi tā mǎi yī běn Hànyǔ shū, míngtiān zài gēn nǐ shuō ba!', 'Suýt nữa tớ quên mất, thứ Bảy cũng là sinh nhật một người bạn của tớ. Vậy cậu cứ mua đồ của cậu đi, giờ tớ ra hiệu sách mua tặng cậu ấy một quyển sách tiếng Hán, mai nói chuyện với cậu sau nhé!', 27) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v13_28', 'lesson-13', '星期几', 'xīngqī jǐ', 'tinh kỳ kỷ', 'ngày thứ mấy', 'Cụm từ / Tên riêng', 'Bộ cấu tạo [星] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [星] + [期] + [几].', 'Kết hợp các thành tố [星] + [期] + [几] để tạo thành từ mang nghĩa ''ngày thứ mấy''.', 'A: 今天星期几啊？', 'Jīntiān xīngqī jǐ a?', 'Hôm nay là thứ mấy thế?', 28) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g13_1', 'lesson-13', '1. 正在/在 + 动词：正在/在 + Động từ', '正在/在 + Động từ biểu thị động tác đang tồn tại hoặc đang tiến hành, sau', ' động từ có thể thêm trợ từ 着 (biểu thị sự tiến hành) hoặc cuối câu thường đi với trợ từ ngữ khí 呢 (biểu thị sự tiếp tục), cả hai trợ từ này có thể xuất hiện đơn độc hoặc đồng thời cùng xuất hiện, mang nghĩa “đang...”. Có thể dùng cả phó từ 正 với ý n', NULL, '[{"hanzi":"我正在洗澡呢。","pinyin":"Wǒ zhèngzài xǐzǎo ne.","meaning":"Tôi đang tắm."},{"hanzi":"我在看书呢。","pinyin":"Wǒ zài kànshū ne.","meaning":"Tôi đang đọc sách."}]'::jsonb, 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g13_2', 'lesson-13', '2. 星期几', '- Câu hỏi: Danh từ chỉ thời gian (今天/昨天/明天...... ) + 星期几？', ' 星期几 là cách thức hỏi về thứ trong tuần, biểu thị ý nghĩa thứ mấy (trong tuần). Cách nói thứ ngày trong tiếng Trung có chút khác biệt cho với tiếng Việt. 星期一 xīngqī yī Thứ hai 星期二 xīngqī''èr Thứ ba 星期三 xīngqīsān Thứ tư 星期四 xīngqīsì Thứ năm 星期五 xīngqīw', NULL, '[{"hanzi":"我回家时，爸爸正看着电视。","pinyin":"Wǒ huí jiā shí, bàba zhèng kànzhe diànshì.","meaning":"Lúc tôi về nhà, bố đang xem ti vi."},{"hanzi":"妈妈做饭时，我正洗澡呢。","pinyin":"Māma zuò fàn shí, wǒ zhèng xǐzǎo ne.","meaning":"Lúc mẹ nấu cơm thì tôi đang tắm."}]'::jsonb, 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g13_3', 'lesson-13', '3. 又/再', '又 + Động từ', ' a. 又: Lại (làm gì đó) 又 là phó từ biểu thị sự lặp lại của sự việc đã xảy ra hoặc sự việc đang diễn ra tại thời điểm nói. 今天又下雨了！ Jīntiān yòu xià yǔ le! Hôm nay lại mưa nữa rồi! 他又来了！ Tā yòu lái le! Anh ta lại đến rồi! b. 再: Tiếp, lại, hãy - 再 biểu t', NULL, '[{"hanzi":"我给朋友打电话时，爸爸在看着我呢。","pinyin":"Wǒ gěi péngyou dǎ diànhuà shí, bàba zài kàn zhe wǒ ne.","meaning":"Lúc tôi gọi điện thoại cho bạn thì bố đang nhìn tôi."},{"hanzi":"老师讲课时，我正在查生词。","pinyin":"Lǎoshī jiǎngkè shí, wǒ zhèngzài chá shēngcí.","meaning":"Lúc cô giáo giảng bài thì tôi đang tra từ mới."}]'::jsonb, 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_13_1', 'lesson-13', 'Bài khoá #1: Hội thoại giáo trình — Sinh nhật', 'Hội thoại chuẩn giáo trình Bài 13. Từ vựng chưa học được chú thích phiên âm & nghĩa trong ngoặc.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_13_1_1', 'txt_13_1', '安妮', '马克，你在干什么呢？', '马克，你在干什么呢？', 'Mǎkè, nǐ zài gàn shénme ne?', 'Mark, cậu đang làm gì thế?', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_13_1_2', 'txt_13_1', '马克', '我正在选生日礼物。', '我正在选生日礼物。', 'Wǒ zhèngzài xuǎn shēngrì lǐwù.', 'Tớ đang chọn quà sinh nhật.', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_13_1_3', 'txt_13_1', '安妮', '是谁的生日礼物？', '是谁的生日礼物？', 'Shì shéi de shēngrì lǐwù?', 'Quà sinh nhật của ai vậy?', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_13_1_4', 'txt_13_1', '马克', '我妹妹的。', '我妹妹的。', 'Wǒ mèimei de.', 'Của em gái tớ.', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_13_1_5', 'txt_13_1', '安妮', '你打算送给她什么礼物？', '你打算送给 (sònggěi: tặng cho)她什么礼物？', 'Nǐ dǎsuan sòng gěi tā shénme lǐwù?', 'Cậu định tặng em ấy món quà gì?', 5) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_13_1_6', 'txt_13_1', '马克', '我打算送给她一顶帽子和一双鞋。你觉得这顶红色的帽子怎么样？', '我打算送给 (sònggěi: tặng cho)她一顶帽子和一双鞋。你觉得这顶红色的帽子怎么样？', 'Wǒ dǎsuan sòng gěi tā yī dǐng màozi hé yīshuāng xié. Nǐ juéde zhè dǐng hóngsè de màozi zěnmeyàng?', 'Tớ định tặng em ấy một chiếc mũ và một đôi giày. Cậu thấy chiếc mũ màu đỏ này thế nào?', 6) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_13_1_7', 'txt_13_1', '安妮', '哇，太好看了！我觉得你妹妹一定很喜欢！对了，你妹妹的生日是几月几号？', '哇 (wa: oa, chà (cảm thán))，太好看了！我觉得你妹妹一定 (yīdìng: nhất định)很喜欢！对了，你妹妹的生日是几月几号？', 'Wa, tài hǎokàn le! Wǒ juéde nǐ mèimei yídìng hěn xǐhuan! Duì le, nǐ mèimei de shēngrì shì jǐ yuè jǐ hào?', 'Chà, đẹp quá đi! Tớ nghĩ em gái cậu nhất định sẽ rất thích! À, sinh nhật em gái cậu là ngày mấy tháng mấy?', 7) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_13_1_8', 'txt_13_1', '马克', '十二月二十四号。', '十二月二十四号。', 'Shí''èr yuè èrshísì hào.', 'Ngày 24 tháng 12.', 8) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_13_1_9', 'txt_13_1', '安妮', '是星期几？', '是星期几？', 'Shì xīngqī jǐ?', 'Là thứ mấy?', 9) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_13_1_10', 'txt_13_1', '马克', '是星期六，怎么了？', '是星期六，怎么了？', 'Shì xīngqīliù, zěnme le?', 'Là thứ Bảy, có chuyện gì thế?', 10) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_13_1_11', 'txt_13_1', '安妮', '我差点儿忘了，星期六也是我的一个朋友的生日。那你买你的吧，我现在去书店给他买一本汉语书，明天再跟你说吧！', '我差点儿忘 (wàng: quên)了，星期六也是我的一个朋友的生日。那你买你的吧，我现在去书店给他买一本汉语书，明天再跟 (gēn: cùng, với)你说吧！', 'Wǒ chàdiǎnr wàng le, xīngqīliù yěshì wǒ de yígè péngyou de shēngrì. Nà nǐ mǎi nǐ de ba, wǒ xiànzài qù shūdiàn gěi tā mǎi yī běn Hànyǔ shū, míngtiān zài gēn nǐ shuō ba!', 'Suýt nữa tớ quên mất, thứ Bảy cũng là sinh nhật một người bạn của tớ. Vậy cậu cứ mua đồ của cậu đi, giờ tớ ra hiệu sách mua tặng cậu ấy một quyển sách tiếng Hán, mai nói chuyện với cậu sau nhé!', 11) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_13_1_12', 'txt_13_1', '马克', '好，再见！', '好，再见！', 'Hǎo, zàijiàn!', 'Được, tạm biệt!', 12) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_13_1_13', 'txt_13_1', '安妮', '再见！', '再见！', 'Zàijiàn!', 'Tạm biệt!', 13) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_13_1_1', 'lesson-13', 'txt_13_1', 'listening', 'listening', '马克，你在干什么呢？', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Mark, cậu đang làm gì thế?","Bạn cứ đi thẳng, sau đó rẽ phải là sẽ nhìn thấy bệnh viện ở bên trái của","môi trường sống","Hôm nay là thứ tư."]'::jsonb, 0, 'Nội dung nghe được: 马克，你在干什么呢？ (Mǎkè, nǐ zài gàn shénme ne?) → Mark, cậu đang làm gì thế?', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_13_1_2', 'lesson-13', 'txt_13_1', 'listening', 'listening', '我正在选生日礼物。', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["他一直在等你。","我给朋友打 (dǎ: đánh, gọi, chơi)电话时 (shí: lúc, khi)，爸爸在看着 (zhe: đang (trạng thái))我呢。","今天又下雨 (xià yǔ: mưa)了！","我正在选生日礼物。"]'::jsonb, 3, 'Câu vừa đọc: 我正在选生日礼物。 (Wǒ zhèngzài xuǎn shēngrì lǐwù.) → Tớ đang chọn quà sinh nhật.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_13_1_3', 'lesson-13', 'txt_13_1', 'listening', 'listening', '是谁的生日礼物？', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Quà sinh nhật của ai vậy?","Không gặp không về!","Lớp cậu có bao nhiêu học sinh?","Thầy giáo đang đợi bạn ở bên ngoài."]'::jsonb, 0, 'Nội dung nghe được: 是谁的生日礼物？ (Shì shéi de shēngrì lǐwù?) → Quà sinh nhật của ai vậy?', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_13_1_4', 'lesson-13', 'txt_13_1', 'listening', 'listening', '我妹妹的。', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["老师讲 (jiǎng: kể, giảng)课 (kè: tiết học, bài học)时 (shí: lúc, khi)，我正在查生词 (shēngcí: từ mới)。","祝你生日快乐，天 (tiān: ngày, trời)天开心 (kāixīn: vui vẻ, hạnh phúc)！","下 (xià: dưới / xuống)星期六是我妹妹的生日。","我妹妹的。"]'::jsonb, 3, 'Câu vừa đọc: 我妹妹的。 (Wǒ mèimei de.) → Của em gái tớ.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_13_2', 'lesson-13', 'Bài nghe tổng hợp: Ôn tập lũy tiến (Bài 1 – Bài 13)', 'Kết hợp từ vựng & mẫu câu đã học từ Bài 1 đến Bài 12 cùng trọng tâm Bài 13 để củng cố phản xạ nghe.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_13_2_1', 'txt_13_2', 'Ôn Bài 12', '他这个人真好！', '他这个人真好！', 'Tā zhège rén zhēn hǎo!', 'Con người anh ta thật là tốt!', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_13_2_2', 'txt_13_2', 'Bài 13', '我在看书呢。', '我在看书呢。', 'Wǒ zài kànshū ne.', 'Tôi đang đọc sách.', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_13_2_3', 'txt_13_2', 'Ôn Bài 6', 'A: 你怎么去超市呢？', 'A: 你怎么去超市呢？', 'Nǐ zěnme qù chāoshì ne?', 'Cậu đi gì đến siêu thị thế?', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_13_2_4', 'txt_13_2', 'Bài 13', '他一直在等你。', '他一直在等你。', 'Tā yīzhí zài děng nǐ.', 'Anh ấy vẫn cứ chờ đợi cậu.', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_13_2_5', 'txt_13_2', 'Ôn Bài 1', '老师您好！', '老师您好！', 'Lǎoshī nín hǎo', 'Em chào thầy/cô ạ', 5) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_13_2_6', 'txt_13_2', 'Bài 13', '马克，你又在干什么呢？', '马克，你又在干什么呢？', 'Mǎkè, nǐ yòu zài gàn shénme ne?', 'Mark, cậu lại đang làm gì nữa vậy?', 6) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_13_2_7', 'txt_13_2', 'Ôn Bài 3', '我很喜欢她。', '我很喜欢她。', 'Wǒ hěn xǐhuān tā.', 'Tôi rất thích cô ấy.', 7) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_13_2_8', 'txt_13_2', 'Bài 13', 'A: 今天星期几啊？', 'A: 今天星期几啊？', 'Jīntiān xīngqī jǐ a?', 'Hôm nay là thứ mấy thế?', 8) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_13_2_1', 'lesson-13', 'txt_13_2', 'listening', 'listening', '他这个人真好！', NULL, '[Ôn tập Bài 12] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Được rồi, tôi đồng ý, cậu đừng nói lại nữa!","Cậu nên ngủ sớm dậy sớm.","Con người anh ta thật là tốt!","Kỳ học này tôi kiểm tra một lần rồi."]'::jsonb, 2, 'Nội dung nghe được: 他这个人真好！ (Tā zhège rén zhēn hǎo!) → Con người anh ta thật là tốt!', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_13_2_2', 'lesson-13', 'txt_13_2', 'listening', 'listening', '我在看书呢。', NULL, '[Bài 13] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["我在看书呢。","我们在/正在讨论 (tǎolùn: thảo luận)。","这双新鞋穿 (chuān: mặc)起来 (qǐlái: lên (bổ ngữ))非常 (fēicháng: cực kì)舒服 (shūfu: thoải mái, dễ chịu)。","我回家时 (shí: lúc, khi)，爸爸正 (zhèng: đang)看着 (zhe: đang (trạng thái))电视 (diànshì: tivi)。"]'::jsonb, 0, 'Câu vừa đọc: 我在看书呢。 (Wǒ zài kànshū ne.) → Tôi đang đọc sách.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_13_2_3', 'lesson-13', 'txt_13_2', 'listening', 'listening', 'A: 你怎么去超市呢？', NULL, '[Ôn tập Bài 6] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Cậu đi gì đến siêu thị thế?","Cậu ấy ngủ suốt chín tiếng đồng hồ.","Anh thấy em mặc có đẹp không?","tóc dài (mang sự dễ thương)"]'::jsonb, 0, 'Nội dung nghe được: A: 你怎么去超市呢？ (Nǐ zěnme qù chāoshì ne?) → Cậu đi gì đến siêu thị thế?', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_13_2_4', 'lesson-13', 'txt_13_2', 'listening', 'listening', '他一直在等你。', NULL, '[Bài 13] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["星期三下午我们没有 (méiyǒu: không có)汉语课 (kè: tiết học, bài học)。","他一直在等你。","他又来 (lái: đến)了！","妈妈做 (zuò: làm)饭时 (shí: lúc, khi)，我正 (zhèng: đang)洗澡 (xǐzǎo: tắm rửa)呢。"]'::jsonb, 1, 'Câu vừa đọc: 他一直在等你。 (Tā yīzhí zài děng nǐ.) → Anh ấy vẫn cứ chờ đợi cậu.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_13_2_5', 'lesson-13', 'txt_13_2', 'listening', 'listening', '老师您好！', NULL, '[Ôn tập Bài 1] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Tớ đang chọn quà sinh nhật.","Em chào thầy/cô ạ","Cậu nói gì?","Cô ấy đẹp quá."]'::jsonb, 1, 'Nội dung nghe được: 老师您好！ (Lǎoshī nín hǎo) → Em chào thầy/cô ạ', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_13_3', 'lesson-13', 'Bài khoá mở rộng: Chuẩn bị quà sinh nhật cho bạn thân (Mở rộng)', 'Hội thoại tình huống mới xây dựng dựa trên từ vựng và ngữ pháp Bài 13 (không trùng lặp nguyên văn giáo trình).', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_13_3_1', 'txt_13_3', 'Mark', '安妮，这星期五是你的生日，对吗？', '安妮，这星期五是你的生日，对吗？', 'Ānnī, zhè xīngqīwǔ shì nǐ de shēngrì, duì ma?', 'Annie, thứ Sáu tuần này là sinh nhật cậu đúng không?', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_13_3_2', 'txt_13_3', 'Annie', '对呀！我打算星期五晚上在宿舍附近请大家吃饭。', '对呀！我打算星期五晚上在宿舍附近请大家 (dàjiā: mọi người)吃饭。', 'Duì ya! Wǒ dǎsuan xīngqīwǔ wǎnshang zài sùshè fùjìn qǐng dàjiā chīfàn.', 'Đúng rồi! Tớ định tối thứ Sáu mời mọi người ăn cơm gần ký túc xá.', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_13_3_3', 'txt_13_3', 'Mark', '太好了！我和玉兰给你准备了一双漂亮的运动鞋。', '太好了！我和玉兰给你准备了一双漂亮的运动 (yùndòng: vận động, hoạt động thể thao)鞋。', 'Tài hǎo le! Wǒ hé Yùlán gěi nǐ zhǔnbèi le yì shuāng piàoliang de yùndòngxié.', 'Tuyệt quá! Tớ và Ngọc Lan đã chuẩn bị tặng cậu một đôi giày thể thao rất đẹp.', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_13_3_4', 'txt_13_3', 'Annie', '谢谢你们，我太高兴了！', '谢谢你们，我太高兴了！', 'Xièxie nǐmen, wǒ tài gāoxìng le!', 'Cảm ơn các cậu nhiều, tớ vui quá đi mất!', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_13_3_1', 'lesson-13', 'txt_13_3', 'listening', 'listening', '安妮，这星期五是你的生日，对吗？ 对呀！我打算星期五晚上在宿舍附近请大家吃饭。 太好了！我和玉兰给你准备了一双漂亮的运动鞋。 谢谢你们，我太高兴了！', NULL, '[Nghe hiểu tình huống mới] Mark và Ngọc Lan tặng Annie món quà gì nhân ngày sinh nhật vào thứ Sáu?', '["Một chiếc mũ màu đỏ","Một quyển từ điển Hán ngữ","Một chiếc áo khoác trắng","Một đôi giày thể thao đẹp"]'::jsonb, 3, 'Mark nói ''我和玉兰给你准备了一双漂亮的运动鞋''.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_13_3_2', 'lesson-13', 'txt_13_3', 'listening', 'listening', '安妮，这星期五是你的生日，对吗？', NULL, '[Mở rộng] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Annie, thứ Sáu tuần này là sinh nhật cậu đúng không?","Nếu ngày mai có tuyết rơi thì tớ sẽ đi đắp người tuyết.","từ điển tiếng Trung","Tớ đến ngân hàng rút tiền trước rồi sau đó đi mua đồ."]'::jsonb, 0, 'Nội dung nghe được: 安妮，这星期五是你的生日，对吗？ (Ānnī, zhè xīngqīwǔ shì nǐ de shēngrì, duì ma?) → Annie, thứ Sáu tuần này là sinh nhật cậu đúng không?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_13_3_3', 'lesson-13', 'txt_13_3', 'listening', 'listening', '对呀！我打算星期五晚上在宿舍附近请大家吃饭。', NULL, '[Mở rộng] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["对呀！我打算星期五晚上在宿舍附近请大家 (dàjiā: mọi người)吃饭。","我给朋友打 (dǎ: đánh, gọi, chơi)电话时 (shí: lúc, khi)，爸爸在看着 (zhe: đang (trạng thái))我呢。","这双新鞋穿 (chuān: mặc)起来 (qǐlái: lên (bổ ngữ))非常 (fēicháng: cực kì)舒服 (shūfu: thoải mái, dễ chịu)。","请问 (qǐngwèn: xin hỏi)，今天是几月几号，星期几？"]'::jsonb, 0, 'Câu vừa đọc: 对呀！我打算星期五晚上在宿舍附近请大家吃饭。 (Duì ya! Wǒ dǎsuan xīngqīwǔ wǎnshang zài sùshè fùjìn qǐng dàjiā chīfàn.) → Đúng rồi! Tớ định tối thứ Sáu mời mọi người ăn cơm gần ký túc xá.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_13_3_4', 'lesson-13', 'txt_13_3', 'listening', 'listening', '太好了！我和玉兰给你准备了一双漂亮的运动鞋。', NULL, '[Mở rộng] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Dương vừa về nhà là đi nấu cơm.","Hôm nay là thứ tư.","Cậu là ai thế?","Tuyệt quá! Tớ và Ngọc Lan đã chuẩn bị tặng cậu một đôi giày thể thao rất đẹp."]'::jsonb, 3, 'Nội dung nghe được: 太好了！我和玉兰给你准备了一双漂亮的运动鞋。 (Tài hǎo le! Wǒ hé Yùlán gěi nǐ zhǔnbèi le yì shuāng piàoliang de yùndòngxié.) → Tuyệt quá! Tớ và Ngọc Lan đã chuẩn bị tặng cậu một đôi giày thể thao rất đẹp.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss13_1', 'lesson-13', '下星期六是我妹妹的生日', '[Mở rộng] Thứ Bảy tuần sau là sinh nhật em gái tôi.', 'Xià xīngqīliù shì wǒ mèimei de shēngrì.', '["下","星期六","是我","妹妹","的","生日"]'::jsonb, 'Từ chưa học: 下 (xià: dưới / xuống)', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss13_2', 'lesson-13', '我买了一顶白色帽子当生日礼物', '[Mở rộng] Tôi đã mua một chiếc mũ trắng làm quà sinh nhật.', 'Wǒ mǎi le yì dǐng báisè màozi dāng shēngrì lǐwù.', '["我买了","一顶","白色","帽子当","生日","礼物"]'::jsonb, 'Từ chưa học: 当 (dāng: đảm nhiệm, làm)', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss13_3', 'lesson-13', '我在看书呢', 'Tôi đang đọc sách.', 'Wǒ zài kànshū ne.', '["我","在","看","书","呢"]'::jsonb, NULL, 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
