INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr13_zh_1', 'lesson-13', 'zh_to_vi', '[Mở rộng] 请问 (qǐngwèn: xin hỏi)，今天是几月几号，星期几？', '请问，今天是几月几号，星期几？', 'Qǐngwèn, jīntiān shì jǐ yuè jǐ hào, xīngqī jǐ?', NULL, 'Xin hỏi hôm nay là ngày mấy tháng mấy, thứ mấy?', NULL, '["Xin","hỏi","hôm"]'::jsonb, 'Pinyin: Qǐngwèn, jīntiān shì jǐ yuè jǐ hào, xīngqī jǐ?', '请问，今天是几月几号，星期几？ (Qǐngwèn, jīntiān shì jǐ yuè jǐ hào, xīngqī jǐ?) nghĩa là: Xin hỏi hôm nay là ngày mấy tháng mấy, thứ mấy?', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
