INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq13_13', 'lesson-13', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “生日” chứa bộ thủ nào sau đây?', '["又 (Hựu) (Bàn tay phải, lặp lại, lại nữa)","Bộ cấu tạo [再] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","日 (Nhật) (Mặt trời, ban ngày, thời gian, ánh sáng)","Bộ cấu tạo [星] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)"]'::jsonb, 2, 'Chữ “生日” có 日 (Nhật) (Mặt trời, ban ngày, thời gian, ánh sáng). Ghép từ các chữ Hán: [生] + [日].', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
