INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq13_20', 'lesson-13', NULL, 'expanded_quiz', 'reading', NULL, NULL, '[Mở rộng] Câu “下 (xià: dưới / xuống)星期六是我妹妹的生日。” có nghĩa tiếng Việt là gì?', '["Bọn họ chỉ quan tâm đến bản thân mình mà thôi.","Bố tôi đẹp trai như vậy, nên đương nhiên tôi cũng đẹp trai rồi.","Tôi có một anh trai và một em gái.","Thứ Bảy tuần sau là sinh nhật em gái tôi."]'::jsonb, 3, '下星期六是我妹妹的生日。 (Xià xīngqīliù shì wǒ mèimei de shēngrì.) → Thứ Bảy tuần sau là sinh nhật em gái tôi.', 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq13_21', 'lesson-13', NULL, 'expanded_quiz', 'reading', NULL, NULL, '[Đọc hiểu mở rộng] Đọc đoạn hội thoại:
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq13_22', 'lesson-13', NULL, 'expanded_quiz', 'reading', NULL, NULL, 'Câu “我在看书呢。” có nghĩa tiếng Việt là gì?', '["Tôi thực sự không thích!","Tôi vẫn chưa nghĩ xong nên mặc váy màu đỏ hay là váy màu xanh nữa.","Thứ Bảy tuần sau là sinh nhật em gái tôi.","Tôi đang đọc sách."]'::jsonb, 3, '我在看书呢。 (Wǒ zài kànshū ne.) → Tôi đang đọc sách.', 22) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct13_1', 'lesson-13', NULL, 'comprehensive_test', 'listening', '今天下雨我不想出门买东西', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Cửa hàng đó nằm ngay phía trước cổng trường đấy.","Tôi cũng rất vui được làm quen với bạn.","Hôm nay trời mưa, tôi không muốn ra ngoài mua đồ.","Hẹn gặp lại vào ngày mai! (Hoặc “Mai gặp nhé!”)"]'::jsonb, 2, 'Nội dung nghe được: “今天下雨我不想出门买东西” (Jīntiān xià yǔ, wǒ bù xiǎng chūmén mǎi dōngxi.) → Hôm nay trời mưa, tôi không muốn ra ngoài mua đồ.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct13_2', 'lesson-13', NULL, 'comprehensive_test', 'listening', '再见！', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["她很漂亮。","再见！","我昨天睡得挺晚的，所以今天有点儿困！","爸爸在洗手间里吗？"]'::jsonb, 1, 'Câu vừa đọc: “再见！” (Zàijiàn!) → Tạm biệt!', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct13_3', 'lesson-13', NULL, 'comprehensive_test', 'listening', '请告诉我这副眼镜多少钱', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Vậy làm sao để mua được đồ tốt?","Làm ơn cho tôi biết cặp kính mắt này bao nhiêu tiền.","Một người","Chào buổi trưa các bạn học sinh!"]'::jsonb, 1, 'Nội dung nghe được: “请告诉我这副眼镜多少钱” (Qǐng gàosu wǒ zhè fù yǎnjìng duōshao qián.) → Làm ơn cho tôi biết cặp kính mắt này bao nhiêu tiền.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct13_4', 'lesson-13', NULL, 'comprehensive_test', 'listening', '老师您好！', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["马克，你在干什么呢？","她很漂亮。","老师您好！","好，谢谢你！"]'::jsonb, 2, 'Câu vừa đọc: “老师您好！” (Lǎoshī nín hǎo) → Em chào thầy/cô ạ', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct13_5', 'lesson-13', NULL, 'comprehensive_test', 'listening', '谢谢你们，我太高兴了！', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Tiểu Lan! Cậu đi siêu thị mua quần áo cùng tớ nhé, được không?","Đẹp lắm, tớ sẽ mua chiếc áo khoác màu vàng này và chiếc váy màu hồng này. Cậu thấy chiếc áo khoác này có đắt không?","Nhà tôi có bốn người: bố, mẹ, anh trai và tôi.","Cảm ơn các cậu nhiều, tớ vui quá đi mất!"]'::jsonb, 3, 'Nội dung nghe được: “谢谢你们，我太高兴了！” (Xièxie nǐmen, wǒ tài gāoxìng le!) → Cảm ơn các cậu nhiều, tớ vui quá đi mất!', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct13_6', 'lesson-13', NULL, 'comprehensive_test', 'listening', '我正在选生日礼物。', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["我正在选生日礼物。","你是日明吗？","弟弟在花园里玩儿。","三支铅笔"]'::jsonb, 0, 'Câu vừa đọc: “我正在选生日礼物。” (Wǒ zhèngzài xuǎn shēngrì lǐwù.) → Tớ đang chọn quà sinh nhật.', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct13_7', 'lesson-13', NULL, 'comprehensive_test', 'listening', '我给朋友打电话时，爸爸在看着我呢。', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Cô ơi, cho cháu hỏi dưa hấu và thanh long bán thế nào ạ?","Annie, nhà bạn có mấy người?","Lúc tôi gọi điện thoại cho bạn thì bố đang nhìn tôi.","Năm nay hay năm sau cậu đi du học?"]'::jsonb, 2, 'Nội dung nghe được: “我给朋友打电话时，爸爸在看着我呢。” (Wǒ gěi péngyou dǎ diànhuà shí, bàba zài kàn zhe wǒ ne.) → Lúc tôi gọi điện thoại cho bạn thì bố đang nhìn tôi.', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct13_8', 'lesson-13', NULL, 'comprehensive_test', 'listening', '安妮，这星期五是你的生日，对吗？', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["三个朋友","你认识阮日明吗","安妮，这星期五是你的生日，对吗？","小林去英国旅游过一次。"]'::jsonb, 2, 'Câu vừa đọc: “安妮，这星期五是你的生日，对吗？” (Ānnī, zhè xīngqīwǔ shì nǐ de shēngrì, duì ma?) → Annie, thứ Sáu tuần này là sinh nhật cậu đúng không?', 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
