INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct13_24', 'lesson-13', NULL, 'comprehensive_test', 'listening', '安妮，这星期五是你的生日，对吗？ 对呀！我打算星期五晚上在宿舍附近请大家吃饭。 太好了！我和玉兰给你准备了一双漂亮的运动鞋。 谢谢你们，我太高兴了！', NULL, 'Mark và Ngọc Lan tặng Annie món quà gì nhân ngày sinh nhật vào thứ Sáu?', '["Một chiếc mũ màu đỏ","Một quyển từ điển Hán ngữ","Một chiếc áo khoác trắng","Một đôi giày thể thao đẹp"]'::jsonb, 3, 'Mark nói ''我和玉兰给你准备了一双漂亮的运动鞋''.', 24) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
