INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v14_1', 'lesson-14', '家人', 'jiārén', 'gia nhân', 'người nhà', 'Danh từ', '人 (Nhân) (Con người, nhân loại)', 'Ghép từ các chữ Hán: [家] + [人].', 'Kết hợp các thành tố [家] + [人] để tạo thành từ mang nghĩa ''người nhà''.', '小兰，你家人的爱好是什么？', 'Xiǎo Lán, nǐ jiārén de àihào shì shénme?', 'Tiểu Lan, sở thích của những người trong gia đình cậu là gì?', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v14_2', 'lesson-14', '足球迷', 'zúqiúmí', 'túc cầu', 'fan cuồng bóng đá', 'Danh từ', '足/𧾷 (Túc) (Bàn chân, bước chân, đá bóng, chạy)', 'Ghép từ các chữ Hán: [足] + [球] + [迷].', 'Kết hợp các thành tố [足] + [球] + [迷] để tạo thành từ mang nghĩa ''fan cuồng bóng đá''.', '我也是。我家人都叫我足球迷。', 'Wǒ yěshì. Wǒ jiā rén dōu jiào wǒ zúqiúmí.', 'Tớ cũng vậy. Người nhà tớ đều gọi tớ là tín đồ bóng đá.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v14_3', 'lesson-14', '爱好', 'àihào', 'ái hảo', 'sở thích', 'Danh từ', 'Bộ cấu tạo [爱] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [爱] + [好].', 'Kết hợp các thành tố [爱] + [好] để tạo thành từ mang nghĩa ''sở thích''.', '小兰，你家人的爱好是什么？', 'Xiǎo Lán, nǐ jiārén de àihào shì shénme?', 'Tiểu Lan, sở thích của những người trong gia đình cậu là gì?', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v14_4', 'lesson-14', '园子', 'yuánzi', 'từ Hán ngữ', 'vườn', 'Danh từ', '子 (Tử) (Đứa con, trẻ nhỏ, người trí thức)', 'Ghép từ các chữ Hán: [园] + [子].', 'Kết hợp các thành tố [园] + [子] để tạo thành từ mang nghĩa ''vườn''.', '我爸爸很喜欢种树，我家有一个小园子，园子里全都是花和树.', 'Wǒ bàba hěn xǐhuan zhòng shù, wǒjiā yǒu yígè xiǎo yuánzi, yuánzi li quán dōu shì huā hé shù.', 'Bố tớ rất thích trồng cây, nhà tớ có một khu vườn nhỏ, trong vườn toàn là hoa và cây cối.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v14_5', 'lesson-14', '真容', 'zhēnróng', 'từ Hán ngữ', 'chân dung', 'Danh từ', 'Bộ cấu tạo [真] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [真] + [容].', 'Kết hợp các thành tố [真] + [容] để tạo thành từ mang nghĩa ''chân dung''.', '我弟弟今年 6 岁，他最喜欢画画儿。你看，这是他画的画儿，他画了爷爷的真容。', 'Wǒ dìdi jīnnián 6 suì, tā zuì xǐhuan huà huàr. Nǐ kàn，zhè shì tā huà de huàr, tā huà le yéye de zhēnróng.', 'Em trai tớ năm nay 6 tuổi, em ấy thích nhất là vẽ tranh. Cậu xem, đây là bức tranh em ấy vẽ, em ấy vẽ chân dung ông nội đấy.', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v14_6', 'lesson-14', '树', 'shù', 'từ Hán ngữ', 'cây', 'Danh từ', 'Bộ cấu tạo [树] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Chữ độc thể / hình thanh gồm Bộ cấu tạo [树] và các nét bổ trợ.', 'Ghi nhớ chữ [树] (cây) qua hình tượng Thành phần biểu ý/biểu âm cơ bản trong chữ Hán.', '我爸爸很喜欢种树，我家有一个小园子，园子里全都是花和树.', 'Wǒ bàba hěn xǐhuan zhòng shù, wǒjiā yǒu yígè xiǎo yuánzi, yuánzi li quán dōu shì huā hé shù.', 'Bố tớ rất thích trồng cây, nhà tớ có một khu vườn nhỏ, trong vườn toàn là hoa và cây cối.', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v14_7', 'lesson-14', '花', 'huā', 'từ Hán ngữ', 'hoa', 'Danh từ', 'Bộ cấu tạo [花] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Chữ độc thể / hình thanh gồm Bộ cấu tạo [花] và các nét bổ trợ.', 'Ghi nhớ chữ [花] (hoa) qua hình tượng Thành phần biểu ý/biểu âm cơ bản trong chữ Hán.', '我爸爸很喜欢种树，我家有一个小园子，园子里全都是花和树.', 'Wǒ bàba hěn xǐhuan zhòng shù, wǒjiā yǒu yígè xiǎo yuánzi, yuánzi li quán dōu shì huā hé shù.', 'Bố tớ rất thích trồng cây, nhà tớ có một khu vườn nhỏ, trong vườn toàn là hoa và cây cối.', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v14_8', 'lesson-14', '公园', 'gōngyuán', 'công', 'công viên', 'Danh từ', 'Bộ cấu tạo [公] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [公] + [园].', 'Kết hợp các thành tố [公] + [园] để tạo thành từ mang nghĩa ''công viên''.', '爷爷很喜欢散步和看报纸，他每天早上在家看报纸，下午去公园散步。你有什么爱好吗？', 'Yéye hěn xǐhuan sànbù hé kàn bàozhǐ, tā měitiān zǎoshang zài jiā kàn bàozhǐ, xiàwǔ qù gōngyuán sànbù. Nǐ yǒu shénme àihào ma?', 'Ông nội rất thích đi dạo và đọc báo, sáng nào ông cũng đọc báo ở nhà, chiều ra công viên đi dạo. Cậu có sở thích gì không?', 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v14_9', 'lesson-14', '比赛', 'bǐsài', 'từ Hán ngữ', 'trận đấu', 'Danh từ', 'Bộ cấu tạo [比] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [比] + [赛].', 'Kết hợp các thành tố [比] + [赛] để tạo thành từ mang nghĩa ''trận đấu''.', '我最喜欢踢足球，如果学校有足球比赛, 我一定参加。', 'Wǒ zuì xǐhuan tī zúqiú, rúguǒ xuéxiào yǒu zúqiú bǐsài, wǒ yídìng cānjiā.', 'Tớ thích nhất đá bóng, nếu trường có giải bóng đá, tớ nhất định sẽ tham gia.', 9) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v14_10', 'lesson-14', '画儿', 'huàr', 'họa nhi', '(bức) tranh', 'Danh từ', 'Bộ cấu tạo [画] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [画] + [儿].', 'Kết hợp các thành tố [画] + [儿] để tạo thành từ mang nghĩa ''(bức) tranh''.', '我弟弟今年 6 岁，他最喜欢画画儿。你看，这是他画的画儿，他画了爷爷的真容。', 'Wǒ dìdi jīnnián 6 suì, tā zuì xǐhuan huà huàr. Nǐ kàn，zhè shì tā huà de huàr, tā huà le yéye de zhēnróng.', 'Em trai tớ năm nay 6 tuổi, em ấy thích nhất là vẽ tranh. Cậu xem, đây là bức tranh em ấy vẽ, em ấy vẽ chân dung ông nội đấy.', 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v14_11', 'lesson-14', '报纸', 'bàozhǐ', 'từ Hán ngữ', 'báo', 'Danh từ', 'Bộ cấu tạo [报] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [报] + [纸].', 'Kết hợp các thành tố [报] + [纸] để tạo thành từ mang nghĩa ''báo''.', '爷爷很喜欢散步和看报纸，他每天早上在家看报纸，下午去公园散步。你有什么爱好吗？', 'Yéye hěn xǐhuan sànbù hé kàn bàozhǐ, tā měitiān zǎoshang zài jiā kàn bàozhǐ, xiàwǔ qù gōngyuán sànbù. Nǐ yǒu shénme àihào ma?', 'Ông nội rất thích đi dạo và đọc báo, sáng nào ông cũng đọc báo ở nhà, chiều ra công viên đi dạo. Cậu có sở thích gì không?', 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
