INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v14_13', 'lesson-14', '画', 'huà', 'họa', 'vẽ (tranh)', 'Động từ', 'Bộ cấu tạo [画] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Chữ độc thể / hình thanh gồm Bộ cấu tạo [画] và các nét bổ trợ.', 'Ghi nhớ chữ [画] (vẽ (tranh)) qua hình tượng Thành phần biểu ý/biểu âm cơ bản trong chữ Hán.', '我弟弟今年 6 岁，他最喜欢画画儿。你看，这是他画的画儿，他画了爷爷的真容。', 'Wǒ dìdi jīnnián 6 suì, tā zuì xǐhuan huà huàr. Nǐ kàn，zhè shì tā huà de huàr, tā huà le yéye de zhēnróng.', 'Em trai tớ năm nay 6 tuổi, em ấy thích nhất là vẽ tranh. Cậu xem, đây là bức tranh em ấy vẽ, em ấy vẽ chân dung ông nội đấy.', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v14_14', 'lesson-14', '唱歌', 'chàng gē', 'xướng ca', 'hát', 'Động từ', 'Bộ cấu tạo [唱] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [唱] + [歌].', 'Kết hợp các thành tố [唱] + [歌] để tạo thành từ mang nghĩa ''hát''.', '我妈妈很喜欢唱歌和看书，她买了很多书。', 'Wǒ māma hěn xǐhuan chàng gē hé kànshū, tā mǎi le hěnduō shū.', 'Mẹ tớ rất thích hát và đọc sách, bà mua rất nhiều sách.', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v14_15', 'lesson-14', '散步', 'sànbù', 'bộ', 'đi dạo', 'Động từ', 'Bộ cấu tạo [散] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [散] + [步].', 'Kết hợp các thành tố [散] + [步] để tạo thành từ mang nghĩa ''đi dạo''.', '爷爷很喜欢散步和看报纸，他每天早上在家看报纸，下午去公园散步。你有什么爱好吗？', 'Yéye hěn xǐhuan sànbù hé kàn bàozhǐ, tā měitiān zǎoshang zài jiā kàn bàozhǐ, xiàwǔ qù gōngyuán sànbù. Nǐ yǒu shénme àihào ma?', 'Ông nội rất thích đi dạo và đọc báo, sáng nào ông cũng đọc báo ở nhà, chiều ra công viên đi dạo. Cậu có sở thích gì không?', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v14_16', 'lesson-14', '讲故事', 'jiǎng gùshi', 'sự', 'kể chuyện', 'Động từ', 'Bộ cấu tạo [讲] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [讲] + [故] + [事].', 'Kết hợp các thành tố [讲] + [故] + [事] để tạo thành từ mang nghĩa ''kể chuyện''.', '我爸爸也很喜欢看书，他有空儿的时候就给我和弟弟讲故事。你弟弟喜欢什么？', 'Wǒ bàba yě hěn xǐhuan kànshū, tā yǒu kòngr de shíhou jiù gěi wǒ hé dìdi jiǎng gùshi. Nǐ dìdi xǐhuan shénme?', 'Bố tớ cũng rất thích đọc sách, lúc rảnh rỗi ông thường kể chuyện cho tớ và em trai nghe. Em trai cậu thích gì?', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v14_17', 'lesson-14', '踢足球', 'tī zúqiú', 'thích túc cầu', 'chơi bóng đá', 'Động từ', '足/𧾷 (Túc) (Bàn chân, bước chân, đá bóng, chạy)', 'Ghép từ các chữ Hán: [踢] + [足] + [球].', 'Kết hợp các thành tố [踢] + [足] + [球] để tạo thành từ mang nghĩa ''chơi bóng đá''.', '我最喜欢踢足球，如果学校有足球比赛, 我一定参加。', 'Wǒ zuì xǐhuan tī zúqiú, rúguǒ xuéxiào yǒu zúqiú bǐsài, wǒ yídìng cānjiā.', 'Tớ thích nhất đá bóng, nếu trường có giải bóng đá, tớ nhất định sẽ tham gia.', 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
