INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v14_19', 'lesson-14', '一样', 'yíyàng', 'từ Hán ngữ', 'giống nhau', 'Tính từ', 'Bộ cấu tạo [一] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [一] + [样].', 'Kết hợp các thành tố [一] + [样] để tạo thành từ mang nghĩa ''giống nhau''.', '我家有很多人，每个人的爱好都不一样。', 'Wǒ jiā yǒu hěn duō rén, měi gèrén de àihào dōu bù yíyàng.', 'Nhà tớ có rất nhiều người, sở thích của mỗi người đều khác nhau.', 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v14_20', 'lesson-14', '小', 'xiǎo', 'tiểu', 'nhỏ, bé', 'Tính từ', '小 (Tiểu) (Nhỏ bé, ít ỏi)', 'Chữ độc thể / hình thanh gồm 小 (Tiểu) và các nét bổ trợ.', 'Ghi nhớ chữ [小] (nhỏ, bé) qua hình tượng Nhỏ bé, ít ỏi.', '小兰，你家人的爱好是什么？', 'Xiǎo Lán, nǐ jiārén de àihào shì shénme?', 'Tiểu Lan, sở thích của những người trong gia đình cậu là gì?', 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v14_21', 'lesson-14', '全', 'quán', 'từ Hán ngữ', 'toàn, tất cả', 'Tính từ', 'Bộ cấu tạo [全] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Chữ độc thể / hình thanh gồm Bộ cấu tạo [全] và các nét bổ trợ.', 'Ghi nhớ chữ [全] (toàn, tất cả) qua hình tượng Thành phần biểu ý/biểu âm cơ bản trong chữ Hán.', '我爸爸很喜欢种树，我家有一个小园子，园子里全都是花和树.', 'Wǒ bàba hěn xǐhuan zhòng shù, wǒjiā yǒu yígè xiǎo yuánzi, yuánzi li quán dōu shì huā hé shù.', 'Bố tớ rất thích trồng cây, nhà tớ có một khu vườn nhỏ, trong vườn toàn là hoa và cây cối.', 21) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v14_22', 'lesson-14', '有空儿', 'yǒu kòngr', 'hữu nhi', 'rảnh', 'Động từ', 'Bộ cấu tạo [有] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [有] + [空] + [儿].', 'Kết hợp các thành tố [有] + [空] + [儿] để tạo thành từ mang nghĩa ''rảnh''.', '我爸爸也很喜欢看书，他有空儿的时候就给我和弟弟讲故事。你弟弟喜欢什么？', 'Wǒ bàba yě hěn xǐhuan kànshū, tā yǒu kòngr de shíhou jiù gěi wǒ hé dìdi jiǎng gùshi. Nǐ dìdi xǐhuan shénme?', 'Bố tớ cũng rất thích đọc sách, lúc rảnh rỗi ông thường kể chuyện cho tớ và em trai nghe. Em trai cậu thích gì?', 22) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g14_1', 'lesson-14', '1. Câu chữ 有', 'Cấu trúc câu ngữ pháp trọng tâm', ' 我有一个哥哥和一个妹妹。 Wǒ yǒu yígè gēge hé yígè mèimei. Tôi có một anh trai và một em gái. 客厅里有三个人。 Kètīng li yǒu sān gèrén. Trong phòng khách có 3 người.', NULL, '[{"hanzi":"我有一个哥哥和一个妹妹。","pinyin":"Wǒ yǒu yígè gēge hé yígè mèimei.","meaning":"Tôi có một anh trai và một em gái."},{"hanzi":"客厅里有三个人。","pinyin":"Kètīng li yǒu sān gèrén.","meaning":"Trong phòng khách có 3 người."}]'::jsonb, 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g14_2', 'lesson-14', '2. 只 + Động từ', 'Cấu trúc câu ngữ pháp trọng tâm', ' 他们只关心自己。 Tāmen zhǐ guānxīn zìjǐ. Bọn họ chỉ quan tâm đến bản thân mình mà thôi. 我叔叔只有一个儿子。 Wǒ shūshu zhǐyǒu yígè érzi. Chú tôi chỉ có một người con trai.', NULL, '[{"hanzi":"他们只关心自己。","pinyin":"Tāmen zhǐ guānxīn zìjǐ.","meaning":"Bọn họ chỉ quan tâm đến bản thân mình mà thôi."},{"hanzi":"我叔叔只有一个儿子。","pinyin":"Wǒ shūshu zhǐyǒu yígè érzi.","meaning":"Chú tôi chỉ có một người con trai."}]'::jsonb, 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g14_3', 'lesson-14', '3. 呢', 'Cấu trúc câu ngữ pháp trọng tâm', ' 我伯伯今年五十六岁，你伯伯呢？ Wǒ bóbo jīnnián wǔshíliù suì, nǐ bóbo ne? Năm nay bác tôi 56 tuổi, bác cậu thì sao? 妈妈，我的衣服在哪儿呢？ Māma, wǒ de yīfu zài nǎr ne? Mẹ ơi, quần áo của con ở đâu nhỉ?', NULL, '[{"hanzi":"我伯伯今年五十六岁，你伯伯呢？","pinyin":"Wǒ bóbo jīnnián wǔshíliù suì, nǐ bóbo ne?","meaning":"Năm nay bác tôi 56 tuổi, bác cậu thì sao?"},{"hanzi":"妈妈，我的衣服在哪儿呢？","pinyin":"Māma, wǒ de yīfu zài nǎr ne?","meaning":"Mẹ ơi, quần áo của con ở đâu nhỉ?"}]'::jsonb, 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g14_4', 'lesson-14', '4. 这么 và 那么', 'Cấu trúc câu ngữ pháp trọng tâm', ' 我爸爸那么帅，所以我当然也很帅了。 Wǒ bàba nàme shuài, suǒyǐ wǒ dāngrán yě hěn shuài le. Bố tôi đẹp trai như vậy, nên đương nhiên tôi cũng đẹp trai rồi. 女儿，你的房间怎么这么乱啊？ Nǚ''ér, nǐ de fángjiān zěnme zhème luàn a? Con gái à, sao phòng con lại bừa bộn vậy?', NULL, '[{"hanzi":"我爸爸那么帅，所以我当然也很帅了。","pinyin":"Wǒ bàba nàme shuài, suǒyǐ wǒ dāngrán yě hěn shuài le.","meaning":"Bố tôi đẹp trai như vậy, nên đương nhiên tôi cũng đẹp trai rồi."},{"hanzi":"我爷爷真不喜欢吃面条。","pinyin":"Wǒ yéye zhēn bù xǐhuan chī miàntiáo.","meaning":"Ông nội tôi thật sự không thích ăn mì."}]'::jsonb, 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_14_1', 'lesson-14', 'Bài khoá #1: Hội thoại giáo trình — Sở thích của các thành viên', 'Hội thoại chuẩn giáo trình Bài 14. Từ vựng chưa học được chú thích phiên âm & nghĩa trong ngoặc.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_14_1_1', 'txt_14_1', '马克', '小兰，你家人的爱好是什么？', '小兰，你家人的爱好是什么？', 'Xiǎo Lán, nǐ jiārén de àihào shì shénme?', 'Tiểu Lan, sở thích của những người trong gia đình cậu là gì?', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_14_1_2', 'txt_14_1', '范玉兰', '我家有很多人，每个人的爱好都不一样。', '我家有很多人，每个人的爱好都不 (bù: không)一样。', 'Wǒ jiā yǒu hěn duō rén, měi gèrén de àihào dōu bù yíyàng.', 'Nhà tớ có rất nhiều người, sở thích của mỗi người đều khác nhau.', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_14_1_3', 'txt_14_1', '马克', '你爸爸喜欢什么？', '你爸爸喜欢什么？', 'Nǐ bàba xǐhuan shénme?', 'Bố cậu thích gì?', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_14_1_4', 'txt_14_1', '范玉兰', '我爸爸很喜欢种树，我家有一个小园子，园子里全都是花和树.', '我爸爸很喜欢种树，我家有一个小园子，园子里 (lǐ: trong)全都是花和树.', 'Wǒ bàba hěn xǐhuan zhòng shù, wǒjiā yǒu yígè xiǎo yuánzi, yuánzi li quán dōu shì huā hé shù.', 'Bố tớ rất thích trồng cây, nhà tớ có một khu vườn nhỏ, trong vườn toàn là hoa và cây cối.', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_14_1_5', 'txt_14_1', '马克', '一定很漂亮！ 你妈妈呢？', '一定 (yīdìng: nhất định)很漂亮！ 你妈妈呢？', 'Yídìng hěn piàoliang! Nǐ māma ne?', 'Chắc chắn rất đẹp! Thế còn mẹ cậu?', 5) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_14_1_6', 'txt_14_1', '范玉兰', '我妈妈很喜欢唱歌和看书，她买了很多书。', '我妈妈很喜欢唱歌和看书，她买了很多书。', 'Wǒ māma hěn xǐhuan chàng gē hé kànshū, tā mǎi le hěnduō shū.', 'Mẹ tớ rất thích hát và đọc sách, bà mua rất nhiều sách.', 6) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_14_1_7', 'txt_14_1', '马克', '我爸爸也很喜欢看书，他有空儿的时候就给我和弟弟讲故事。你弟弟喜欢什么？', '我爸爸也很喜欢看书，他有空儿的时候就给我和弟弟讲故事。你弟弟喜欢什么？', 'Wǒ bàba yě hěn xǐhuan kànshū, tā yǒu kòngr de shíhou jiù gěi wǒ hé dìdi jiǎng gùshi. Nǐ dìdi xǐhuan shénme?', 'Bố tớ cũng rất thích đọc sách, lúc rảnh rỗi ông thường kể chuyện cho tớ và em trai nghe. Em trai cậu thích gì?', 7) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_14_1_8', 'txt_14_1', '范玉兰', '我弟弟今年 6 岁，他最喜欢画画儿。你看，这是他画的画儿，他画了爷爷的真容。', '我弟弟今 (jīn: hôm nay, nay)年 6 岁，他最喜欢画画儿。你看，这是他画的画儿，他画了爷爷的真容。', 'Wǒ dìdi jīnnián 6 suì, tā zuì xǐhuan huà huàr. Nǐ kàn，zhè shì tā huà de huàr, tā huà le yéye de zhēnróng.', 'Em trai tớ năm nay 6 tuổi, em ấy thích nhất là vẽ tranh. Cậu xem, đây là bức tranh em ấy vẽ, em ấy vẽ chân dung ông nội đấy.', 8) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_14_1_9', 'txt_14_1', '马克', '很好看！那你爷爷喜欢什么？', '很好看！那你爷爷喜欢什么？', 'Hěn hǎokàn! Nà nǐ yéye xǐhuan shénme?', 'Đẹp quá! Vậy ông nội cậu thích gì?', 9) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_14_1_10', 'txt_14_1', '范玉兰', '爷爷很喜欢散步和看报纸，他每天早上在家看报纸，下午去公园散步。你有什么爱好吗？', '爷爷很喜欢散步和看报纸，他每天 (tiān: ngày, trời)早上在家看报纸，下午去公园散步。你有什么爱好吗？', 'Yéye hěn xǐhuan sànbù hé kàn bàozhǐ, tā měitiān zǎoshang zài jiā kàn bàozhǐ, xiàwǔ qù gōngyuán sànbù. Nǐ yǒu shénme àihào ma?', 'Ông nội rất thích đi dạo và đọc báo, sáng nào ông cũng đọc báo ở nhà, chiều ra công viên đi dạo. Cậu có sở thích gì không?', 10) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_14_1_11', 'txt_14_1', '马克', '我最喜欢踢足球，如果学校有足球比赛, 我一定参加。', '我最喜欢踢足球，如果学校有足球 (zúqiú: bóng đá)比赛, 我一定 (yīdìng: nhất định)参加。', 'Wǒ zuì xǐhuan tī zúqiú, rúguǒ xuéxiào yǒu zúqiú bǐsài, wǒ yídìng cānjiā.', 'Tớ thích nhất đá bóng, nếu trường có giải bóng đá, tớ nhất định sẽ tham gia.', 11) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_14_1_12', 'txt_14_1', '范玉兰', '我也是。我家人都叫我足球迷。', '我也是。我家人都叫我足球迷。', 'Wǒ yěshì. Wǒ jiā rén dōu jiào wǒ zúqiúmí.', 'Tớ cũng vậy. Người nhà tớ đều gọi tớ là tín đồ bóng đá.', 12) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_14_1_1', 'lesson-14', 'txt_14_1', 'listening', 'listening', '小兰，你家人的爱好是什么？', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Tiểu Lan, sở thích của những người trong gia đình cậu là gì?","Đây là sách của tôi.","Anh ta mời tôi ngày mai tới nhà dùng cơm.","người kia, người đó"]'::jsonb, 0, 'Nội dung nghe được: 小兰，你家人的爱好是什么？ (Xiǎo Lán, nǐ jiārén de àihào shì shénme?) → Tiểu Lan, sở thích của những người trong gia đình cậu là gì?', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_14_1_2', 'lesson-14', 'txt_14_1', 'listening', 'listening', '我家有很多人，每个人的爱好都不一样。', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["我爸爸那么帅 (shuài: đẹp trai)，所以 (suǒyǐ: cho nên)我当然也很帅了。","晚 (wǎn: muộn, tối)饭以后 (yǐhòu: sau, lúc sau)我常常 (chángcháng: thường)去公园散步。","我正在吃饭。","我家有很多人，每个人的爱好都不 (bù: không)一样。"]'::jsonb, 3, 'Câu vừa đọc: 我家有很多人，每个人的爱好都不一样。 (Wǒ jiā yǒu hěn duō rén, měi gèrén de àihào dōu bù yíyàng.) → Nhà tớ có rất nhiều người, sở thích của mỗi người đều khác nhau.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_14_1_3', 'lesson-14', 'txt_14_1', 'listening', 'listening', '你爸爸喜欢什么？', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Bức tranh này vẽ đẹp thật đấy!","Cô ấy không phải Lan Lan.","Tôi làm phiên dịch ở Bộ Ngoại giao.","Bố cậu thích gì?"]'::jsonb, 3, 'Nội dung nghe được: 你爸爸喜欢什么？ (Nǐ bàba xǐhuan shénme?) → Bố cậu thích gì?', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_14_1_4', 'lesson-14', 'txt_14_1', 'listening', 'listening', '我爸爸很喜欢种树，我家有一个小园子，园子里全都是花和树.', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["奶奶在看一个节目 (jiémù: chương trình)，你们别 (bié: đừng)闹了！","他们只关心自己。","你怎么现在才 (cái: mới)来 (lái: đến)啊，大家 (dàjiā: mọi người)都吃了。","我爸爸很喜欢种树，我家有一个小园子，园子里 (lǐ: trong)全都是花和树."]'::jsonb, 3, 'Câu vừa đọc: 我爸爸很喜欢种树，我家有一个小园子，园子里全都是花和树. (Wǒ bàba hěn xǐhuan zhòng shù, wǒjiā yǒu yígè xiǎo yuánzi, yuánzi li quán dōu shì huā hé shù.) → Bố tớ rất thích trồng cây, nhà tớ có một khu vườn nhỏ, trong vườn toàn là hoa và cây cối.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_14_2', 'lesson-14', 'Bài nghe tổng hợp: Ôn tập lũy tiến (Bài 1 – Bài 14)', 'Kết hợp từ vựng & mẫu câu đã học từ Bài 1 đến Bài 13 cùng trọng tâm Bài 14 để củng cố phản xạ nghe.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_14_2_1', 'txt_14_2', 'Ôn Bài 13', '我在看书呢。', '我在看书呢。', 'Wǒ zài kànshū ne.', 'Tôi đang đọc sách.', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_14_2_2', 'txt_14_2', 'Bài 14', '我有一个哥哥和一个妹妹。', '我有一个哥哥和一个妹妹。', 'Wǒ yǒu yígè gēge hé yígè mèimei.', 'Tôi có một anh trai và một em gái.', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
