INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_14_2_4', 'txt_14_2', 'Bài 14', '他们只关心自己。', '他们只关心自己。', 'Tāmen zhǐ guānxīn zìjǐ.', 'Bọn họ chỉ quan tâm đến bản thân mình mà thôi.', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_14_2_5', 'txt_14_2', 'Ôn Bài 1', '我也是学生。', '我也是学生。', 'Wǒ yě shì xuéshēng.', 'Tôi cũng là học sinh.', 5) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_14_2_6', 'txt_14_2', 'Bài 14', '妈妈，我的衣服在哪儿呢？', '妈妈，我的衣服在哪儿呢？', 'Māma, wǒ de yīfu zài nǎr ne?', 'Mẹ ơi, quần áo của con ở đâu nhỉ?', 6) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_14_2_7', 'txt_14_2', 'Ôn Bài 2', '你说什么？', '你说什么？', 'Nǐ shuō shénme?', 'Cậu nói gì?', 7) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_14_2_8', 'txt_14_2', 'Bài 14', '我正在吃饭。', '我正在吃饭。', 'Wǒ zhèngzài chīfàn.', 'Tớ đang ăn cơm.', 8) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_14_2_1', 'lesson-14', 'txt_14_2', 'listening', 'listening', '我在看书呢。', NULL, '[Ôn tập Bài 13] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Tôi biết đá bóng.","Tôi đang đọc sách.","Mấy năm gần đây cô ấy càng ngày càng xinh đẹp.","Mẹ, thôi để con làm cho!"]'::jsonb, 1, 'Nội dung nghe được: 我在看书呢。 (Wǒ zài kànshū ne.) → Tôi đang đọc sách.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_14_2_2', 'lesson-14', 'txt_14_2', 'listening', 'listening', '我有一个哥哥和一个妹妹。', NULL, '[Bài 14] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["我叔叔 (shūshu: chú)只有一个儿子 (érzi: con trai)。","他们只关心自己。","我有一个哥哥和一个妹妹。","客厅 (kètīng: phòng khách)里 (lǐ: trong)有三个人。"]'::jsonb, 2, 'Câu vừa đọc: 我有一个哥哥和一个妹妹。 (Wǒ yǒu yígè gēge hé yígè mèimei.) → Tôi có một anh trai và một em gái.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_14_2_3', 'lesson-14', 'txt_14_2', 'listening', 'listening', '现在的我们', NULL, '[Ôn tập Bài 7] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Chạy một chuyến","kế bên (của) cô ấy","Sao giờ cậu mới đến vậy, mọi người đều ăn cả rồi.","chúng tôi của hiện tại"]'::jsonb, 3, 'Nội dung nghe được: 现在的我们 (xiànzài de wǒmen) → chúng tôi của hiện tại', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_14_2_4', 'lesson-14', 'txt_14_2', 'listening', 'listening', '他们只关心自己。', NULL, '[Bài 14] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["他们只关心自己。","你喜欢春天 (chūntiān: mùa xuân)还是夏天 (xiàtiān: mùa hè)？","你怎么又来 (lái: đến)了？","你爸爸喜欢什么？"]'::jsonb, 0, 'Câu vừa đọc: 他们只关心自己。 (Tāmen zhǐ guānxīn zìjǐ.) → Bọn họ chỉ quan tâm đến bản thân mình mà thôi.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_14_2_5', 'lesson-14', 'txt_14_2', 'listening', 'listening', '我也是学生。', NULL, '[Ôn tập Bài 1] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Một con đường","Năm nay cháu 6 tuổi ạ.","Tôi cũng là học sinh.","Hình như tớ quen người này."]'::jsonb, 2, 'Nội dung nghe được: 我也是学生。 (Wǒ yě shì xuéshēng.) → Tôi cũng là học sinh.', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_14_3', 'lesson-14', 'Bài khoá mở rộng: Câu lạc bộ sở thích gia đình (Mở rộng)', 'Hội thoại tình huống mới xây dựng dựa trên từ vựng và ngữ pháp Bài 14 (không trùng lặp nguyên văn giáo trình).', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_14_3_1', 'txt_14_3', 'Lan', '日明，你们家人的爱好都一样吗？', '日明，你们家人的爱好都一样吗？', 'Rìmíng, nǐmen jiārén de àihào dōu yíyàng ma?', 'Nhật Minh, sở thích của mọi người trong nhà cậu có giống nhau không?', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_14_3_2', 'txt_14_3', 'Minh', '不一样。爸爸喜欢看报纸和种花，妈妈喜欢听音乐唱歌。', '不 (bù: không)一样。爸爸喜欢看报纸和种花，妈妈喜欢听音乐唱歌。', 'Bù yíyàng. Bàba xǐhuan kàn bàozhǐ hé zhòng huā, māma xǐhuan tīng yīnyuè chànggē.', 'Không giống nhau. Bố thích đọc báo và trồng hoa, mẹ thích nghe nhạc và ca hát.', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_14_3_3', 'txt_14_3', 'Lan', '那你弟弟呢？他也喜欢踢足球吗？', '那你弟弟呢？他也喜欢踢足球吗？', 'Nà nǐ dìdi ne? Tā yě xǐhuan tī zúqiú ma?', 'Vậy còn em trai cậu? Em ấy cũng thích đá bóng à?', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_14_3_4', 'txt_14_3', 'Minh', '他最喜欢画画儿，我才是家里的足球迷。', '他最喜欢画画儿，我才 (cái: mới)是家里 (lǐ: trong)的足球迷。', 'Tā zuì xǐhuan huà huàr, wǒ cái shì jiālǐ de zúqiúmí.', 'Em ấy thích nhất vẽ tranh, còn tớ mới là tín đồ bóng đá của cả nhà.', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_14_3_1', 'lesson-14', 'txt_14_3', 'listening', 'listening', '日明，你们家人的爱好都一样吗？ 不一样。爸爸喜欢看报纸和种花，妈妈喜欢听音乐唱歌。 那你弟弟呢？他也喜欢踢足球吗？ 他最喜欢画画儿，我才是家里的足球迷。', NULL, '[Nghe hiểu tình huống mới] Trong gia đình Nhật Minh, ai là người thích nhất môn vẽ tranh?', '["Bản thân Nhật Minh","Em trai của Nhật Minh (弟弟)","Mẹ của Nhật Minh","Bố của Nhật Minh"]'::jsonb, 1, 'Nhật Minh nói rõ: em trai ''最喜欢画画儿'' (thích nhất vẽ tranh).', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_14_3_2', 'lesson-14', 'txt_14_3', 'listening', 'listening', '日明，你们家人的爱好都一样吗？', NULL, '[Mở rộng] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Nhật Minh, sở thích của mọi người trong nhà cậu có giống nhau không?","Anh đã uống 2 chai rồi, đừng uống nữa!","Năm nay cháu 6 tuổi ạ.","Hôm nay là thứ tư."]'::jsonb, 0, 'Nội dung nghe được: 日明，你们家人的爱好都一样吗？ (Rìmíng, nǐmen jiārén de àihào dōu yíyàng ma?) → Nhật Minh, sở thích của mọi người trong nhà cậu có giống nhau không?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_14_3_3', 'lesson-14', 'txt_14_3', 'listening', 'listening', '不一样。爸爸喜欢看报纸和种花，妈妈喜欢听音乐唱歌。', NULL, '[Mở rộng] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["不 (bù: không)一样。爸爸喜欢看报纸和种花，妈妈喜欢听音乐唱歌。","我家有很多人，每个人的爱好都不 (bù: không)一样。","你明天再来 (lái: đến)跟 (gēn: cùng, với)姥姥 (lǎolao: bà ngoại)聊天儿吧！","你怎么现在才 (cái: mới)来 (lái: đến)啊，大家 (dàjiā: mọi người)都吃了。"]'::jsonb, 0, 'Câu vừa đọc: 不一样。爸爸喜欢看报纸和种花，妈妈喜欢听音乐唱歌。 (Bù yíyàng. Bàba xǐhuan kàn bàozhǐ hé zhòng huā, māma xǐhuan tīng yīnyuè chànggē.) → Không giống nhau. Bố thích đọc báo và trồng hoa, mẹ thích nghe nhạc và ca hát.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_14_3_4', 'lesson-14', 'txt_14_3', 'listening', 'listening', '那你弟弟呢？他也喜欢踢足球吗？', NULL, '[Mở rộng] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Ngày mai chúng tôi sẽ đi leo núi.","Họ đã tốt nghiệp 2 năm rồi!","Vậy còn em trai cậu? Em ấy cũng thích đá bóng à?","Hôm nay lại mưa nữa rồi!"]'::jsonb, 2, 'Nội dung nghe được: 那你弟弟呢？他也喜欢踢足球吗？ (Nà nǐ dìdi ne? Tā yě xǐhuan tī zúqiú ma?) → Vậy còn em trai cậu? Em ấy cũng thích đá bóng à?', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
