INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss14_6', 'lesson-14', '这个木瓜很大也很便宜', '[Ôn tập Bài 8] Quả đu đủ này rất to mà giá cũng rất rẻ.', 'Zhège mùguā hěn dà, yě hěn piányi.', '["这个","木瓜","很大","也","很","便宜"]'::jsonb, 'Từ chưa học: 大 (dà: to, lớn)', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
