INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr14_zh_1', 'lesson-14', 'zh_to_vi', '[Mở rộng] 爸爸在园子里 (lǐ: trong)种了很多漂亮的花和树。', '爸爸在园子里种了很多漂亮的花和树。', 'Bàba zài yuánzi lǐ zhòng le hěnduō piàoliang de huā hé shù.', NULL, 'Bố trồng rất nhiều hoa đẹp và cây cối trong khu vườn.', NULL, '["Bố","trồng","rất"]'::jsonb, 'Pinyin: Bàba zài yuánzi lǐ zhòng le hěnduō piàoliang de huā hé shù.', '爸爸在园子里种了很多漂亮的花和树。 (Bàba zài yuánzi lǐ zhòng le hěnduō piàoliang de huā hé shù.) nghĩa là: Bố trồng rất nhiều hoa đẹp và cây cối trong khu vườn.', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr14_zh_2', 'lesson-14', 'zh_to_vi', '[Mở rộng] 哥哥是个足球迷，喜欢看足球 (zúqiú: bóng đá)比赛。', '哥哥是个足球迷，喜欢看足球比赛。', 'Gēge shì gè zúqiúmí, xǐhuan kàn zúqiú bǐsài.', NULL, 'Anh trai là một tín đồ bóng đá, rất thích xem các trận đấu bóng đá.', NULL, '["Anh","trai","là"]'::jsonb, 'Pinyin: Gēge shì gè zúqiúmí, xǐhuan kàn zúqiú bǐsài.', '哥哥是个足球迷，喜欢看足球比赛。 (Gēge shì gè zúqiúmí, xǐhuan kàn zúqiú bǐsài.) nghĩa là: Anh trai là một tín đồ bóng đá, rất thích xem các trận đấu bóng đá.', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
