INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v15_1', 'lesson-15', '北京', 'Běijīng', 'từ Hán ngữ', 'Bắc Kinh', 'Danh từ', 'Bộ cấu tạo [北] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [北] + [京].', 'Kết hợp các thành tố [北] + [京] để tạo thành từ mang nghĩa ''Bắc Kinh''.', '张风，北京有几个季节？', 'Zhāng Fēng, Běijīng yǒu jǐ gè jìjié?', 'Trương Phong, Bắc Kinh có mấy mùa?', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v15_2', 'lesson-15', '天气', 'tiānqì', 'thiên khí', 'thời tiết', 'Danh từ', 'Bộ cấu tạo [天] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [天] + [气].', 'Kết hợp các thành tố [天] + [气] để tạo thành từ mang nghĩa ''thời tiết''.', '今天天气怎么样？', 'Jīntiān tiānqì zěnmeyàng?', 'Hôm nay thời tiết như thế nào?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v15_3', 'lesson-15', '大风', 'dàfēng', 'đại phong', 'gió to, gió lớn', 'Danh từ', '大 (Đại) (To lớn, vĩ đại)', 'Ghép từ các chữ Hán: [大] + [风].', 'Kết hợp các thành tố [大] + [风] để tạo thành từ mang nghĩa ''gió to, gió lớn''.', '北京的春天很暖和，不常下雨，有时候刮大风。', 'Běijīng de chūntiān hěn nuǎnhuo, bù cháng xiàyǔ, yǒushíhou guā dàfēng.', 'Mùa xuân ở Bắc Kinh rất ấm áp, ít khi mưa, thỉnh thoảng có gió lớn.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v15_4', 'lesson-15', '雪', 'xuě', 'tuyết', 'tuyết', 'Danh từ', 'Bộ cấu tạo [雪] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Chữ độc thể / hình thanh gồm Bộ cấu tạo [雪] và các nét bổ trợ.', 'Ghi nhớ chữ [雪] (tuyết) qua hình tượng Thành phần biểu ý/biểu âm cơ bản trong chữ Hán.', '常下雪吗？', 'Cháng xiàxuě ma?', 'Có hay có tuyết rơi không?', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v15_5', 'lesson-15', '季节', 'jìjié', 'quý tiết', 'mùa', 'Danh từ', 'Bộ cấu tạo [季] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [季] + [节].', 'Kết hợp các thành tố [季] + [节] để tạo thành từ mang nghĩa ''mùa''.', '张风，北京有几个季节？', 'Zhāng Fēng, Běijīng yǒu jǐ gè jìjié?', 'Trương Phong, Bắc Kinh có mấy mùa?', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v15_6', 'lesson-15', '零下', 'língxià', 'hạ', 'dưới 0 độ', 'Cụm từ / Tên riêng', 'Bộ cấu tạo [零] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [零] + [下].', 'Kết hợp các thành tố [零] + [下] để tạo thành từ mang nghĩa ''dưới 0 độ''.', '是。北京的冬天比较冷，最冷差不多零下二十二度。', 'Shì. Běijīng de dōngtiān bǐjiào lěng, zuì lěng chàbùduō língxià èrshíèr dù.', 'Đúng vậy. Mùa đông Bắc Kinh khá lạnh, lạnh nhất khoảng âm 22 độ.', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v15_7', 'lesson-15', '春天', 'chūntiān', 'xuân thiên', 'mùa xuân', 'Danh từ', 'Bộ cấu tạo [春] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [春] + [天].', 'Kết hợp các thành tố [春] + [天] để tạo thành từ mang nghĩa ''mùa xuân''.', '北京有春天、夏天、秋天和冬天四个季节。', 'Běijīng yǒu chūntiān, xiàtiān, qiūtiān hé dōngtiān sì gè jìjié.', 'Bắc Kinh có bốn mùa: xuân, hạ, thu và đông.', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
