INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq15_11', 'lesson-15', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Phiên âm Pinyin chính xác của “不常” là gì?', '["bù cháng","jìjié","rè","dōngtiān"]'::jsonb, 0, '“不常” đọc là: bù cháng (không thường xuyên, ít khi).', 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq15_12', 'lesson-15', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Phiên âm Pinyin chính xác của “比较” là gì?', '["bǐjiào","xuě","tèbié","dù"]'::jsonb, 0, '“比较” đọc là: bǐjiào (tương đối, khá).', 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq15_13', 'lesson-15', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “北京” chứa bộ thủ nào sau đây?', '["口 (Khẩu) (Miệng, ăn uống, lời nói)","Bộ cấu tạo [北] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [春] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [天] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)"]'::jsonb, 1, 'Chữ “北京” có Bộ cấu tạo [北] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán). Ghép từ các chữ Hán: [北] + [京].', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq15_14', 'lesson-15', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “天气” chứa bộ thủ nào sau đây?', '["Bộ cấu tạo [天] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [比] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [季] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [暖] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)"]'::jsonb, 0, 'Chữ “天气” có Bộ cấu tạo [天] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán). Ghép từ các chữ Hán: [天] + [气].', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq15_15', 'lesson-15', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “大风” chứa bộ thủ nào sau đây?', '["Bộ cấu tạo [刮] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [春] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [度] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","大 (Đại) (To lớn, vĩ đại)"]'::jsonb, 3, 'Chữ “大风” có 大 (Đại) (To lớn, vĩ đại). Ghép từ các chữ Hán: [大] + [风].', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq15_16', 'lesson-15', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “雪” chứa bộ thủ nào sau đây?', '["Bộ cấu tạo [因] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [雪] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [滑] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [舒] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)"]'::jsonb, 1, 'Chữ “雪” có Bộ cấu tạo [雪] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán). Chữ độc thể / hình thanh gồm Bộ cấu tạo [雪] và các nét bổ trợ.', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq15_17', 'lesson-15', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 14] Từ đã học “一样” (yíyàng) có nghĩa là gì?', '["nói","giống nhau","tiếp đãi, tiếp đón","như thế nào"]'::jsonb, 1, 'Ôn tập Bài 14: “一样” (yíyàng) nghĩa là: giống nhau.', 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq15_18', 'lesson-15', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 6] Từ đã học “西边” (xībian) có nghĩa là gì?', '["tốt, khỏe, hay, ngon...","tuyết","của (trợ từ)","hướng tây"]'::jsonb, 3, 'Ôn tập Bài 6: “西边” (xībian) nghĩa là: hướng tây.', 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq15_19', 'lesson-15', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 6] Từ đã học “白色” (báisè) có nghĩa là gì?', '["là, thì...","buổi chiều","màu trắng","như thế, như thế này"]'::jsonb, 2, 'Ôn tập Bài 6: “白色” (báisè) nghĩa là: màu trắng.', 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq15_20', 'lesson-15', NULL, 'expanded_quiz', 'reading', NULL, NULL, '[Mở rộng] Câu “我觉得春天的天气最暖和、最舒服。” có nghĩa tiếng Việt là gì?', '["Mắt cô ấy đo đỏ.","Hôm nay thời tiết như thế nào?","Tôi so sánh đáp án với anh ấy.","Tôi thấy thời tiết mùa xuân ấm áp và dễ chịu nhất."]'::jsonb, 3, '我觉得春天的天气最暖和、最舒服。 (Wǒ juéde chūntiān de tiānqì zuì nuǎnhuo, zuì shūfu.) → Tôi thấy thời tiết mùa xuân ấm áp và dễ chịu nhất.', 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq15_21', 'lesson-15', NULL, 'expanded_quiz', 'reading', NULL, NULL, '[Đọc hiểu mở rộng] Đọc đoạn hội thoại:
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq15_22', 'lesson-15', NULL, 'expanded_quiz', 'reading', NULL, NULL, 'Câu “今天天气怎么样？” có nghĩa tiếng Việt là gì?', '["Không gặp không về!","Tôi thấy thời tiết mùa xuân ấm áp và dễ chịu nhất.","Bộ quần áo này không to cũng không nhỏ.","Hôm nay thời tiết như thế nào?"]'::jsonb, 3, '今天天气怎么样？ (Jīntiān tiānqì zěnmeyàng?) → Hôm nay thời tiết như thế nào?', 22) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct15_1', 'lesson-15', NULL, 'comprehensive_test', 'listening', '是。北京的冬天比较冷，最冷差不多零下二十二度。', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Cậu xem chiếc cặp màu xanh dương này có đẹp không?","Các thầy cô giáo","Đúng vậy. Mùa đông Bắc Kinh khá lạnh, lạnh nhất khoảng âm 22 độ.","Tất nhiên rồi."]'::jsonb, 2, 'Nội dung nghe được: “是。北京的冬天比较冷，最冷差不多零下二十二度。” (Shì. Běijīng de dōngtiān bǐjiào lěng, zuì lěng chàbùduō língxià èrshíèr dù.) → Đúng vậy. Mùa đông Bắc Kinh khá lạnh, lạnh nhất khoảng âm 22 độ.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct15_2', 'lesson-15', NULL, 'comprehensive_test', 'listening', '夏天怎么样？热么？', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["你好，同学！请问你贵姓？","你爸爸喜欢什么？","马克，你在干什么呢？","夏天怎么样？热么？"]'::jsonb, 3, 'Câu vừa đọc: “夏天怎么样？热么？” (Xiàtiān zěnmeyàng? Rè ma?) → Mùa hạ thì sao? Có nóng không?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct15_3', 'lesson-15', NULL, 'comprehensive_test', 'listening', '我比较累，想睡觉了！', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Đẹp lắm, tớ sẽ mua chiếc áo khoác màu vàng này và chiếc váy màu hồng này. Cậu thấy chiếc áo khoác này có đắt không?","Chị gái bạn năm nay bao nhiêu tuổi rồi?","Tôi khá mệt, muốn đi ngủ rồi!","Bạn của tôi đang ăn cơm ở nhà ăn."]'::jsonb, 2, 'Nội dung nghe được: “我比较累，想睡觉了！” (Wǒ bǐjiào lèi, xiǎng shuìjiào le!) → Tôi khá mệt, muốn đi ngủ rồi!', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct15_4', 'lesson-15', NULL, 'comprehensive_test', 'listening', '后天会下大雪，你们出去玩儿要多穿点儿大衣！', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["是星期几？","你看，那边是大衣和裙子，好漂亮啊！","哇！太方便了！但是网上的东西价格怎么样？","后天会下大雪，你们出去玩儿要多穿点儿大衣！"]'::jsonb, 3, 'Câu vừa đọc: “后天会下大雪，你们出去玩儿要多穿点儿大衣！” (Hòutiān huì xià dàxuě, nǐmen chūqù wánr yào duō chuān diǎnr dàyī!) → Ngày kia sẽ có tuyết rơi lớn, các cậu ra ngoài chơi nhớ mặc thêm áo khoác nhé!', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct15_5', 'lesson-15', NULL, 'comprehensive_test', 'listening', '常下雪。冬天的时候我经常跟朋友去滑冰、滑雪。特别好玩儿。', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Cậu là Nhật Minh phải không?","Thường hay có tuyết rơi. Vào mùa đông tôi hay đi trượt băng, trượt tuyết cùng bạn bè. Vui lắm.","Trương Phong, Bắc Kinh có mấy mùa?","Tôi muốn mua hai quyển vở ghi, một cây bút chì và một quyển từ điển Hán ngữ."]'::jsonb, 1, 'Nội dung nghe được: “常下雪。冬天的时候我经常跟朋友去滑冰、滑雪。特别好玩儿。” (Cháng xiàxuě. Dōngtiān de shíhou wǒ jīngcháng gēn péngyou qù huábīng, huáxuě. Tèbié hǎowánr.) → Thường hay có tuyết rơi. Vào mùa đông tôi hay đi trượt băng, trượt tuyết cùng bạn bè. Vui lắm.', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct15_6', 'lesson-15', NULL, 'comprehensive_test', 'listening', '他的考试成绩不怎么样。', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["这个不好说。你上网吧，我会告诉你怎么买。","他的考试成绩不怎么样。","北京的春天很暖和，不常下雨，有时候刮大风。","我真心真意想跟你去。"]'::jsonb, 1, 'Câu vừa đọc: “他的考试成绩不怎么样。” (Tā de kǎoshì chéngjì bù zěnmeyàng.) → Thành tích kiểm tra của anh ấy chẳng ra làm sao. (Ý nói kết quả kém)', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct15_7', 'lesson-15', NULL, 'comprehensive_test', 'listening', '我有一个哥哥和一个妹妹。', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Thời tiết mùa hè không quá nóng. Nóng nhất là vào tháng 7, tháng 7 và tháng 8 thường hay mưa.","Có chứ, cháu muốn mua nước ép gì nào?","Cậu nói gì?","Tôi có một anh trai và một em gái."]'::jsonb, 3, 'Nội dung nghe được: “我有一个哥哥和一个妹妹。” (Wǒ yǒu yígè gēge hé yígè mèimei.) → Tôi có một anh trai và một em gái.', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct15_8', 'lesson-15', NULL, 'comprehensive_test', 'listening', '晚上好！', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["晚上好！","马克，你明天要上课吗？","请喝一杯热茶或者咖啡吧","真的吗？"]'::jsonb, 0, 'Câu vừa đọc: “晚上好！” (Wǎnshang hǎo) → Chào buổi tối!', 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
