INSERT INTO lessons (id, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id) VALUES ('lesson-16', 'Bài 16: Cuối tuần - Đơn nguyên 5: Kỳ nghỉ', 'Bài 16', 'Đơn nguyên 5: Kỳ nghỉ', 'Lên kế hoạch vui chơi cuối tuần, xem phim, cà phê, dã ngoại, liên từ 因为... 所以...', '2026-11-14'::date, 16, TRUE, NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, date_added = EXCLUDED.date_added, sort_order = EXCLUDED.sort_order, is_system = TRUE, updated_at = NOW();
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v16_1', 'lesson-16', '假期', 'jiàqī', 'giả kỳ', 'kỳ nghỉ', 'Danh từ', 'Bộ cấu tạo [假] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [假] + [期].', 'Kết hợp các thành tố [假] + [期] để tạo thành từ mang nghĩa ''kỳ nghỉ''.', '这是关于“假期”的常用句子。', 'Zhè shì guānyú ''jiàqī'' de chángyòng jùzi.', 'Đây là câu ví dụ sử dụng từ ''假期'' (kỳ nghỉ).', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v16_2', 'lesson-16', '健身房', 'jiànshēnfáng', 'kiện thân', 'phòng gym', 'Danh từ', '身 (Thân) (Thân thể, vóc dáng)', 'Ghép từ các chữ Hán: [健] + [身] + [房].', 'Kết hợp các thành tố [健] + [身] + [房] để tạo thành từ mang nghĩa ''phòng gym''.', '可以去看电影，吃火锅，逛街，购物或者去健身房健身。', 'Kěyǐ qù kàn diànyǐng, chī huǒguō, guàngjiē, gòuwù huòzhě qù jiànshēnfáng jiànshēn.', 'Có thể đi xem phim, ăn lẩu, dạo phố, mua sắm hoặc đến phòng tập thể hình tập luyện.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v16_3', 'lesson-16', '新闻', 'xīnwén', 'tân', 'tin tức', 'Danh từ', 'Bộ cấu tạo [新] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [新] + [闻].', 'Kết hợp các thành tố [新] + [闻] để tạo thành từ mang nghĩa ''tin tức''.', '你很乖啊！如果没有什么做我就上网看新闻或者玩游戏。', 'Nǐ hěn guāi a! Rúguǒ méiyǒu shénme zuò wǒ jiù shàngwǎng kàn xīnwén huòzhě wán yóuxì.', 'Bạn ngoan thật đấy! Nếu không có việc gì làm thì tôi lên mạng đọc tin tức hoặc chơi game.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v16_4', 'lesson-16', '作业', 'zuòyè', 'tác nghiệp', 'bài tập', 'Danh từ', 'Bộ cấu tạo [作] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [作] + [业].', 'Kết hợp các thành tố [作] + [业] để tạo thành từ mang nghĩa ''bài tập''.', '周末的时候我在家休息休息，如果有作业我就做作业，如果妈妈要帮忙我就去帮忙。', 'Zhōumò de shíhou wǒ zài jiā xiūxi xiūxi, rúguǒ yǒu zuòyè wǒ jiù zuò zuòyè, rúguǒ māma yào bāngmáng wǒ jiù qù bāngmáng.', 'Cuối tuần tôi nghỉ ngơi ở nhà, nếu có bài tập thì làm bài tập, nếu mẹ cần giúp việc gì thì tôi giúp mẹ.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v16_5', 'lesson-16', '事', 'shì', 'sự', 'việc, chuyện', 'Danh từ', 'Bộ cấu tạo [事] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Chữ độc thể / hình thanh gồm Bộ cấu tạo [事] và các nét bổ trợ.', 'Ghi nhớ chữ [事] (việc, chuyện) qua hình tượng Thành phần biểu ý/biểu âm cơ bản trong chữ Hán.', '这是关于“事”的常用句子。', 'Zhè shì guānyú ''shì'' de chángyòng jùzi.', 'Đây là câu ví dụ sử dụng từ ''事'' (việc, chuyện).', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v16_6', 'lesson-16', '功课', 'gōngkè', 'công', 'bài học', 'Danh từ', 'Bộ cấu tạo [功] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [功] + [课].', 'Kết hợp các thành tố [功] + [课] để tạo thành từ mang nghĩa ''bài học''.', '那好，明天我在家复习功课吧，快要考试了。', 'Nà hǎo, míngtiān wǒ zài jiā fùxí gōngkè ba, kuàiyào kǎoshì le.', 'Thôi được, ngày mai tôi ở nhà ôn tập bài vở vậy, sắp thi rồi.', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v16_7', 'lesson-16', '出去', 'chūqù', 'khứ', 'ra ngoài', 'Động từ', 'Bộ cấu tạo [出] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [出] + [去].', 'Kết hợp các thành tố [出] + [去] để tạo thành từ mang nghĩa ''ra ngoài''.', '我常常跟朋友出去玩儿，我非常喜欢去公园照相。', 'Wǒ chángcháng gēn péngyou chūqù wánr, wǒ fēicháng xǐhuan qù gōngyuán zhàoxiàng.', 'Tôi thường ra ngoài chơi với bạn bè, tôi rất thích ra công viên chụp ảnh.', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v16_8', 'lesson-16', '吃火锅', 'chī huǒguō', 'ngật hỏa', 'ăn lẩu', 'Động từ', '火/灬 (Hỏa) (Lửa, nhiệt độ, nấu nướng, nóng bức)', 'Ghép từ các chữ Hán: [吃] + [火] + [锅].', 'Kết hợp các thành tố [吃] + [火] + [锅] để tạo thành từ mang nghĩa ''ăn lẩu''.', '可以去看电影，吃火锅，逛街，购物或者去健身房健身。', 'Kěyǐ qù kàn diànyǐng, chī huǒguō, guàngjiē, gòuwù huòzhě qù jiànshēnfáng jiànshēn.', 'Có thể đi xem phim, ăn lẩu, dạo phố, mua sắm hoặc đến phòng tập thể hình tập luyện.', 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v16_9', 'lesson-16', '看电影', 'kàn diànyǐng', 'khán điện ảnh', 'xem phim', 'Động từ', 'Bộ cấu tạo [看] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [看] + [电] + [影].', 'Kết hợp các thành tố [看] + [电] + [影] để tạo thành từ mang nghĩa ''xem phim''.', '可以去看电影，吃火锅，逛街，购物或者去健身房健身。', 'Kěyǐ qù kàn diànyǐng, chī huǒguō, guàngjiē, gòuwù huòzhě qù jiànshēnfáng jiànshēn.', 'Có thể đi xem phim, ăn lẩu, dạo phố, mua sắm hoặc đến phòng tập thể hình tập luyện.', 9) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v16_10', 'lesson-16', '逛街', 'guàngjiē', 'từ Hán ngữ', 'dạo phố', 'Động từ', 'Bộ cấu tạo [逛] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [逛] + [街].', 'Kết hợp các thành tố [逛] + [街] để tạo thành từ mang nghĩa ''dạo phố''.', '我想去逛逛街。', 'Wǒ xiǎng qù guàngguang jiē.', 'Tớ muốn đi dạo phố một lúc.', 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
