INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v16_12', 'lesson-16', '照相', 'zhàoxiàng', 'từ Hán ngữ', 'chụp ảnh', 'Động từ', 'Bộ cấu tạo [照] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [照] + [相].', 'Kết hợp các thành tố [照] + [相] để tạo thành từ mang nghĩa ''chụp ảnh''.', '我常常跟朋友出去玩儿，我非常喜欢去公园照相。', 'Wǒ chángcháng gēn péngyou chūqù wánr, wǒ fēicháng xǐhuan qù gōngyuán zhàoxiàng.', 'Tôi thường ra ngoài chơi với bạn bè, tôi rất thích ra công viên chụp ảnh.', 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v16_13', 'lesson-16', '休息', 'xiūxi', 'từ Hán ngữ', 'nghỉ ngơi', 'Động từ', 'Bộ cấu tạo [休] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [休] + [息].', 'Kết hợp các thành tố [休] + [息] để tạo thành từ mang nghĩa ''nghỉ ngơi''.', '休息休息', 'xiūxi xiūxi', 'Nghỉ ngơi một chút', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v16_14', 'lesson-16', '帮忙', 'bāng máng', 'từ Hán ngữ', 'giúp đỡ', 'Động từ', 'Bộ cấu tạo [帮] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [帮] + [忙].', 'Kết hợp các thành tố [帮] + [忙] để tạo thành từ mang nghĩa ''giúp đỡ''.', '周末的时候我在家休息休息，如果有作业我就做作业，如果妈妈要帮忙我就去帮忙。', 'Zhōumò de shíhou wǒ zài jiā xiūxi xiūxi, rúguǒ yǒu zuòyè wǒ jiù zuò zuòyè, rúguǒ māma yào bāngmáng wǒ jiù qù bāngmáng.', 'Cuối tuần tôi nghỉ ngơi ở nhà, nếu có bài tập thì làm bài tập, nếu mẹ cần giúp việc gì thì tôi giúp mẹ.', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v16_15', 'lesson-16', '帮助', 'bāngzhù', 'từ Hán ngữ', 'giúp đỡ', 'Động từ', 'Bộ cấu tạo [帮] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [帮] + [助].', 'Kết hợp các thành tố [帮] + [助] để tạo thành từ mang nghĩa ''giúp đỡ''.', '如果你有困难，我就帮助你。', 'Rúguǒ nǐ yǒu kùnnan, wǒ jiù bāngzhù nǐ.', 'Nếu cậu gặp khó khăn thì tớ sẽ giúp đỡ.', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v16_16', 'lesson-16', '安排', 'ānpái', 'An', 'sắp xếp, thu xếp', 'Động từ', 'Bộ cấu tạo [安] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [安] + [排].', 'Kết hợp các thành tố [安] + [排] để tạo thành từ mang nghĩa ''sắp xếp, thu xếp''.', '这是关于“安排”的常用句子。', 'Zhè shì guānyú ''ānpái'' de chángyòng jùzi.', 'Đây là câu ví dụ sử dụng từ ''安排'' (sắp xếp, thu xếp).', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v16_17', 'lesson-16', '复习', 'fùxí', 'tập', 'ôn bài', 'Động từ', 'Bộ cấu tạo [复] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [复] + [习].', 'Kết hợp các thành tố [复] + [习] để tạo thành từ mang nghĩa ''ôn bài''.', '昨天晚上我复习了复习课文。', 'Zuótiān wǎnshàng wǒ fùxí le fùxí kèwén.', 'Tối hôm qua tôi đã ôn tập qua bài khóa rồi.', 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v16_18', 'lesson-16', '考试', 'kǎoshì', 'thí', 'thi, kiểm tra', 'Động từ / Danh từ', 'Bộ cấu tạo [考] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [考] + [试].', 'Kết hợp các thành tố [考] + [试] để tạo thành từ mang nghĩa ''thi, kiểm tra''.', '那好，明天我在家复习功课吧，快要考试了。', 'Nà hǎo, míngtiān wǒ zài jiā fùxí gōngkè ba, kuàiyào kǎoshì le.', 'Thôi được, ngày mai tôi ở nhà ôn tập bài vở vậy, sắp thi rồi.', 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v16_19', 'lesson-16', '浪费', 'làngfèi', 'từ Hán ngữ', 'lãng phí', 'Động từ / Tính từ', 'Bộ cấu tạo [浪] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [浪] + [费].', 'Kết hợp các thành tố [浪] + [费] để tạo thành từ mang nghĩa ''lãng phí''.', '你的周末很无聊，你看看, 这简直太浪费时间了吧！', 'Nǐ de zhōumò hěn wúliáo, nǐ kànkan, zhè jiǎnzhí tài làngfèi shíjiān le ba!', 'Cuối tuần của bạn nhàm chán quá, bạn xem đấy, như vậy thật quá lãng phí thời gian rồi!', 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v16_20', 'lesson-16', '无聊', 'wúliáo', 'từ Hán ngữ', 'nhàm chán, vô vị', 'Tính từ', 'Bộ cấu tạo [无] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [无] + [聊].', 'Kết hợp các thành tố [无] + [聊] để tạo thành từ mang nghĩa ''nhàm chán, vô vị''.', '你的周末很无聊，你看看, 这简直太浪费时间了吧！', 'Nǐ de zhōumò hěn wúliáo, nǐ kànkan, zhè jiǎnzhí tài làngfèi shíjiān le ba!', 'Cuối tuần của bạn nhàm chán quá, bạn xem đấy, như vậy thật quá lãng phí thời gian rồi!', 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v16_21', 'lesson-16', '乖', 'guāi', 'từ Hán ngữ', 'ngoan ngoãn', 'Tính từ', 'Bộ cấu tạo [乖] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Chữ độc thể / hình thanh gồm Bộ cấu tạo [乖] và các nét bổ trợ.', 'Ghi nhớ chữ [乖] (ngoan ngoãn) qua hình tượng Thành phần biểu ý/biểu âm cơ bản trong chữ Hán.', '你很乖啊！如果没有什么做我就上网看新闻或者玩游戏。', 'Nǐ hěn guāi a! Rúguǒ méiyǒu shénme zuò wǒ jiù shàngwǎng kàn xīnwén huòzhě wán yóuxì.', 'Bạn ngoan thật đấy! Nếu không có việc gì làm thì tôi lên mạng đọc tin tức hoặc chơi game.', 21) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v16_22', 'lesson-16', '常常', 'chángcháng', 'từ Hán ngữ', 'thường', 'Phó từ', 'Bộ cấu tạo [常] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [常] + [常].', 'Kết hợp các thành tố [常] + [常] để tạo thành từ mang nghĩa ''thường''.', '很好，那你周末常常做什么？', 'Hěn hǎo, nà nǐ zhōumò chángcháng zuò shénme?', 'Hay đấy, thế cuối tuần bạn thường làm gì?', 22) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v16_23', 'lesson-16', '非常', 'fēicháng', 'từ Hán ngữ', 'cực kì', 'Phó từ', 'Bộ cấu tạo [非] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [非] + [常].', 'Kết hợp các thành tố [非] + [常] để tạo thành từ mang nghĩa ''cực kì''.', '我常常跟朋友出去玩儿，我非常喜欢去公园照相。', 'Wǒ chángcháng gēn péngyou chūqù wánr, wǒ fēicháng xǐhuan qù gōngyuán zhàoxiàng.', 'Tôi thường ra ngoài chơi với bạn bè, tôi rất thích ra công viên chụp ảnh.', 23) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v16_24', 'lesson-16', '简直', 'jiǎnzhí', 'từ Hán ngữ', 'thật là, quả là,...', 'Phó từ', 'Bộ cấu tạo [简] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [简] + [直].', 'Kết hợp các thành tố [简] + [直] để tạo thành từ mang nghĩa ''thật là, quả là,...''.', '你的周末很无聊，你看看, 这简直太浪费时间了吧！', 'Nǐ de zhōumò hěn wúliáo, nǐ kànkan, zhè jiǎnzhí tài làngfèi shíjiān le ba!', 'Cuối tuần của bạn nhàm chán quá, bạn xem đấy, như vậy thật quá lãng phí thời gian rồi!', 24) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v16_25', 'lesson-16', '快要......了', 'kuàiyào… le', 'khoái yếu', 'sắp… rồi', 'Cụm từ / Tên riêng', 'Bộ cấu tạo [快] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [快] + [要] + [了].', 'Kết hợp các thành tố [快] + [要] + [了] để tạo thành từ mang nghĩa ''sắp… rồi''.', '这是关于“快要......了”的常用句子。', 'Zhè shì guānyú ''kuàiyào… le'' de chángyòng jùzi.', 'Đây là câu ví dụ sử dụng từ ''快要......了'' (sắp… rồi).', 25) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v16_26', 'lesson-16', '如果......(的话), 就......', 'rúguǒ… (dehuà) jiù…', 'quả thoại', 'nếu… thì...', 'Cụm từ / Tên riêng', 'Bộ cấu tạo [如] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [如] + [果] + [的] + [话] + [就].', 'Kết hợp các thành tố [如] + [果] + [的] + [话] + [就] để tạo thành từ mang nghĩa ''nếu… thì...''.', '这是关于“如果......(的话), 就......”的常用句子。', 'Zhè shì guānyú ''rúguǒ… (dehuà) jiù…'' de chángyòng jùzi.', 'Đây là câu ví dụ sử dụng từ ''如果......(的话), 就......'' (nếu… thì...).', 26) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g16_1', 'lesson-16', '1. 如果…… 就……:  Nếu…thì…', '如果 + S + giả thiết + 就 + kết quả.', ' 如果……就…… là cấu trúc ngữ pháp dùng để đưa ra giả thuyết: nếu A thì B - Hai vế câu cùng chủ ngữ: 如果你好好学习，就能考上大学. /Rúguǒ nǐ hǎohào xuéxí, jiù néng kǎo shàng dàxué./ Nếu chăm chỉ học hành thì bạn sẽ có thể thi đỗ đại học. - Hai vế câu khác chủ ngữ: 如果 +', NULL, '[{"hanzi":"如果你好好学习，就能考上大学.","pinyin":"Rúguǒ nǐ hǎohào xuéxí, jiù néng kǎo shàng dàxué.","meaning":"Nếu chăm chỉ học hành thì bạn sẽ có thể thi đỗ đại học."},{"hanzi":"如果你有困难，我就帮助你。","pinyin":"Rúguǒ nǐ yǒu kùnnan, wǒ jiù bāngzhù nǐ.","meaning":"Nếu cậu gặp khó khăn thì tớ sẽ giúp đỡ."}]'::jsonb, 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g16_2', 'lesson-16', '2. 动词重叠 - Động từ lặp lại', '+ Khi hành động diễn ra ở hiện tại hay trong tương lai', ' a. Khái niệm Động từ trùng lặp được dùng khi muốn biểu thị ý nghĩa thời gian ngắn,  động tác xảy ra nhanh hoặc số lượng ít. Động từ lặp lại còn được dùng trong câu mệnh lệnh, khuyên nhủ, gợi ý, thử làm một việc gì đó, nhằm giảm ngữ khí ra lệnh, khiế', NULL, '[{"hanzi":"= 明天天气好的话，我们就去爬山。","pinyin":"Rúguǒ míngtiān tiānqì hǎo dehuà, wǒmen jiù qù páshān.","meaning":"Nếu ngày mai trời đẹp, chúng ta sẽ đi leo núi."},{"hanzi":"尝尝 = 尝一尝","pinyin":"chángchang = cháng yi cháng","meaning":"Thử qua một chút."}]'::jsonb, 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g16_3', 'lesson-16', '3. 离合动词 - Động từ li hợp (AB)', '*A + Tân ngữ + (的) B', ' a. Khái niệm Động từ li hợp là loại động từ có kết cấu đặc biệt, bản thân động từ này có kết cấu động tân, cách sử dụng cũng có điểm khác biệt so với động từ thường. b. Cách dùng - Trong câu có sử dụng động từ li hợp (AB) mà có mang tân ngữ thì tân ', NULL, '[{"hanzi":"找找 = 找一找","pinyin":"zhǎozhao = zhǎo yi zhǎo","meaning":"Tìm một chút, tìm qua."},{"hanzi":"等等 = 等一等","pinyin":"děngdeng = děng yi děng","meaning":"Đợi một chút."}]'::jsonb, 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g16_4', 'lesson-16', '1. 新年 xīnnián dt. năm mới', 'Cấu trúc câu ngữ pháp trọng tâm', 'Quy tắc ngữ pháp quan trọng trong Cuối tuần.', NULL, '[{"hanzi":"她看了看自己的长头发。","pinyin":"Tā kàn le kàn zìjǐ de cháng tóufa.","meaning":"Cô ấy ngắm qua mái tóc dài của mình."},{"hanzi":"妈妈拍了拍我的头。","pinyin":"Māma pāi le pāi wǒ de tóu.","meaning":"Mẹ gõ nhẹ vào đầu tôi."}]'::jsonb, 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_16_1', 'lesson-16', 'Bài khoá #1: Hội thoại giáo trình — Cuối tuần', 'Hội thoại chuẩn giáo trình Bài 16. Từ vựng chưa học được chú thích phiên âm & nghĩa trong ngoặc.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_16_1_1', 'txt_16_1', '范玉兰', '明天是周末，我们不上课！', '明天是周末，我们不上课！', 'Míngtiān shì zhōumò, wǒmen bú shàngkè!', 'Ngày mai là cuối tuần rồi, chúng ta không phải lên lớp!', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_16_1_2', 'txt_16_1', '白茹雪', '是啊！你觉得周末做什么比较好呢？', '是啊！你觉得周末做 (zuò: làm)什么比较好呢？', 'Shì a! Nǐ juéde zhōumò zuò shénme bǐjiào hǎo ne?', 'Đúng rồi! Bạn thấy cuối tuần làm gì thì hay nhỉ?', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_16_1_3', 'txt_16_1', '范玉兰', '可以去看电影，吃火锅，逛街，购物或者去健身房健身。', '可以去看电影，吃火锅，逛街，购物或者去健身房健身。', 'Kěyǐ qù kàn diànyǐng, chī huǒguō, guàngjiē, gòuwù huòzhě qù jiànshēnfáng jiànshēn.', 'Có thể đi xem phim, ăn lẩu, dạo phố, mua sắm hoặc đến phòng tập thể hình tập luyện.', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_16_1_4', 'txt_16_1', '白茹雪', '很好，那你周末常常做什么？', '很好，那你周末常常做 (zuò: làm)什么？', 'Hěn hǎo, nà nǐ zhōumò chángcháng zuò shénme?', 'Hay đấy, thế cuối tuần bạn thường làm gì?', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_16_1_5', 'txt_16_1', '范玉兰', '我常常跟朋友出去玩儿，我非常喜欢去公园照相。', '我常常跟 (gēn: cùng, với)朋友出去玩儿，我非常喜欢去公园照相。', 'Wǒ chángcháng gēn péngyou chūqù wánr, wǒ fēicháng xǐhuan qù gōngyuán zhàoxiàng.', 'Tôi thường ra ngoài chơi với bạn bè, tôi rất thích ra công viên chụp ảnh.', 5) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_16_1_6', 'txt_16_1', '白茹雪', '周末的时候我在家休息休息，如果有作业我就做作业，如果妈妈要帮忙我就去帮忙。', '周末的时候我在家休息休息，如果有作业我就做 (zuò: làm)作业，如果妈妈要帮忙我就去帮忙。', 'Zhōumò de shíhou wǒ zài jiā xiūxi xiūxi, rúguǒ yǒu zuòyè wǒ jiù zuò zuòyè, rúguǒ māma yào bāngmáng wǒ jiù qù bāngmáng.', 'Cuối tuần tôi nghỉ ngơi ở nhà, nếu có bài tập thì làm bài tập, nếu mẹ cần giúp việc gì thì tôi giúp mẹ.', 6) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_16_1_7', 'txt_16_1', '范玉兰', '你很乖啊！如果没有什么做我就上网看新闻或者玩游戏。', '你很乖啊！如果没有 (méiyǒu: không có)什么做 (zuò: làm)我就上网看新闻或者玩 (wán: chơi)游戏 (yóuxì: trò chơi)。', 'Nǐ hěn guāi a! Rúguǒ méiyǒu shénme zuò wǒ jiù shàngwǎng kàn xīnwén huòzhě wán yóuxì.', 'Bạn ngoan thật đấy! Nếu không có việc gì làm thì tôi lên mạng đọc tin tức hoặc chơi game.', 7) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_16_1_8', 'txt_16_1', '白茹雪', '你的周末很无聊，你看看, 这简直太浪费时间了吧！', '你的周末很无聊，你看看, 这简直太浪费时间了吧！', 'Nǐ de zhōumò hěn wúliáo, nǐ kànkan, zhè jiǎnzhí tài làngfèi shíjiān le ba!', 'Cuối tuần của bạn nhàm chán quá, bạn xem đấy, như vậy thật quá lãng phí thời gian rồi!', 8) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_16_1_9', 'txt_16_1', '范玉兰', '那好，明天我在家复习功课吧，快要考试了。', '那好，明天我在家复习功课吧，快要考试了。', 'Nà hǎo, míngtiān wǒ zài jiā fùxí gōngkè ba, kuàiyào kǎoshì le.', 'Thôi được, ngày mai tôi ở nhà ôn tập bài vở vậy, sắp thi rồi.', 9) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_16_1_1', 'lesson-16', 'txt_16_1', 'listening', 'listening', '明天是周末，我们不上课！', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Ngày mai là cuối tuần rồi, chúng ta không phải lên lớp!","Bạn cứ đi thẳng, sau đó rẽ phải là sẽ nhìn thấy bệnh viện ở bên trái của","Ở đây chỉ có hai người chúng ta?","Bố nhẹ nhàng vỗ vai tôi, lẳng lặng an ủi tôi."]'::jsonb, 0, 'Nội dung nghe được: 明天是周末，我们不上课！ (Míngtiān shì zhōumò, wǒmen bú shàngkè!) → Ngày mai là cuối tuần rồi, chúng ta không phải lên lớp!', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_16_1_2', 'lesson-16', 'txt_16_1', 'listening', 'listening', '是啊！你觉得周末做什么比较好呢？', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["了解 (liǎojiě: hiểu rõ, biết rõ)了解","是啊！你觉得周末做 (zuò: làm)什么比较好呢？","她歌唱 (gēchàng: ca hát)得 (děi: phải)很好听 (tīng: nghe)！","= 明天天气好的话 (huà: lời nói)，我们就去爬山 (páshān: leo núi)。"]'::jsonb, 1, 'Câu vừa đọc: 是啊！你觉得周末做什么比较好呢？ (Shì a! Nǐ juéde zhōumò zuò shénme bǐjiào hǎo ne?) → Đúng rồi! Bạn thấy cuối tuần làm gì thì hay nhỉ?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_16_1_3', 'lesson-16', 'txt_16_1', 'listening', 'listening', '可以去看电影，吃火锅，逛街，购物或者去健身房健身。', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Có thể đi xem phim, ăn lẩu, dạo phố, mua sắm hoặc đến phòng tập thể hình tập luyện.","Mẹ ơi, quần áo của con ở đâu nhỉ?","Anh ta là người chẳng ra gì.","Một phần quà"]'::jsonb, 0, 'Nội dung nghe được: 可以去看电影，吃火锅，逛街，购物或者去健身房健身。 (Kěyǐ qù kàn diànyǐng, chī huǒguō, guàngjiē, gòuwù huòzhě qù jiànshēnfáng jiànshēn.) → Có thể đi xem phim, ăn lẩu, dạo phố, mua sắm hoặc đến phòng tập thể hình tập luyện.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_16_1_4', 'lesson-16', 'txt_16_1', 'listening', 'listening', '很好，那你周末常常做什么？', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["我早上打扫 (dǎsǎo: dọn dẹp, quét dọn)了打扫房间 (fángjiān: căn phòng)。","找找 = 找一找","很好，那你周末常常做 (zuò: làm)什么？","小兰刚 (gāng: vừa mới)跟 (gēn: cùng, với)朋友吵架 (chǎojià: cãi nhau)。"]'::jsonb, 2, 'Câu vừa đọc: 很好，那你周末常常做什么？ (Hěn hǎo, nà nǐ zhōumò chángcháng zuò shénme?) → Hay đấy, thế cuối tuần bạn thường làm gì?', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_16_2', 'lesson-16', 'Bài nghe tổng hợp: Ôn tập lũy tiến (Bài 1 – Bài 16)', 'Kết hợp từ vựng & mẫu câu đã học từ Bài 1 đến Bài 15 cùng trọng tâm Bài 16 để củng cố phản xạ nghe.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_16_2_1', 'txt_16_2', 'Ôn Bài 15', '他是个不怎么样的人。', '他是个不怎么样的人。', 'Tā shì gè bù zěnme yàng de rén.', 'Anh ta là người chẳng ra gì.', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_16_2_2', 'txt_16_2', 'Bài 16', '找找 = 找一找', '找找 = 找一找', 'zhǎozhao = zhǎo yi zhǎo', 'Tìm một chút, tìm qua.', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
