INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_16_2_4', 'txt_16_2', 'Bài 16', '等等 = 等一等', '等等 = 等一等', 'děngdeng = děng yi děng', 'Đợi một chút.', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_16_2_5', 'txt_16_2', 'Ôn Bài 1', '你是日明吗？', '你是日明吗？', 'Nǐ shì Rìmíng ma?', 'Cậu là Nhật Minh phải không?', 5) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_16_2_6', 'txt_16_2', 'Bài 16', '休息休息', '休息休息', 'xiūxi xiūxi', 'Nghỉ ngơi một chút', 6) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_16_2_7', 'txt_16_2', 'Ôn Bài 12', '我真不喜欢！', '我真不喜欢！', 'Wǒ zhēn bù xǐhuan!', 'Tôi thực sự không thích!', 7) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_16_2_8', 'txt_16_2', 'Bài 16', '明天是周末，我们不上课！', '明天是周末，我们不上课！', 'Míngtiān shì zhōumò, wǒmen bú shàngkè!', 'Ngày mai là cuối tuần rồi, chúng ta không phải lên lớp!', 8) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_16_2_1', 'lesson-16', 'txt_16_2', 'listening', 'listening', '他是个不怎么样的人。', NULL, '[Ôn tập Bài 15] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Năm nay cháu mấy tuổi rồi (Hỏi trẻ em dưới mười tuổi)","Chào thầy/Chào cô","Một bộ quần áo","Anh ta là người chẳng ra gì."]'::jsonb, 3, 'Nội dung nghe được: 他是个不怎么样的人。 (Tā shì gè bù zěnme yàng de rén.) → Anh ta là người chẳng ra gì.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_16_2_2', 'lesson-16', 'txt_16_2', 'listening', 'listening', '找找 = 找一找', NULL, '[Bài 16] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["妈妈拍 (pāi: chụp, vỗ)了拍我的头 (tóu: con (trâu, bò) / đầu)。","你早上跟 (gēn: cùng, với)他见面 (miàn: mặt, phía)了没 (méi: chưa, không có)？","找找 = 找一找","= 明天天气好的话 (huà: lời nói)，我们就去爬山 (páshān: leo núi)。"]'::jsonb, 2, 'Câu vừa đọc: 找找 = 找一找 (zhǎozhao = zhǎo yi zhǎo) → Tìm một chút, tìm qua.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_16_2_3', 'lesson-16', 'txt_16_2', 'listening', 'listening', '一斤苹果多少钱？', NULL, '[Ôn tập Bài 8] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Nửa kg (1 cân) táo bao nhiêu tiền?","Bên trái tôi không phải là tòa giảng đường.","Hôm nay là thứ mấy?","Bạn ngoan thật đấy! Nếu không có việc gì làm thì tôi lên mạng đọc tin tức hoặc chơi game."]'::jsonb, 0, 'Nội dung nghe được: 一斤苹果多少钱？ (Yī jīn píngguǒ duōshao qián?) → Nửa kg (1 cân) táo bao nhiêu tiền?', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_16_2_4', 'lesson-16', 'txt_16_2', 'listening', 'listening', '等等 = 等一等', NULL, '[Bài 16] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["她歌唱 (gēchàng: ca hát)得 (děi: phải)很好听 (tīng: nghe)！","昨天晚上我复习了复习课文 (kèwén: bài khoá)。","等等 = 等一等","爸爸每天 (tiān: ngày, trời)看新闻，然后 (ránhòu: đầu tiên... sau đó...)再休息一会 (huì: Phó, đtnn biết)儿 (ér: con, (âm uốn lưỡi))。"]'::jsonb, 2, 'Câu vừa đọc: 等等 = 等一等 (děngdeng = děng yi děng) → Đợi một chút.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_16_2_5', 'lesson-16', 'txt_16_2', 'listening', 'listening', '你是日明吗？', NULL, '[Ôn tập Bài 1] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Cậu là Nhật Minh phải không?","Cô ấy đẹp quá.","Tôi mệt đến mức chẳng muốn động đậy gì nữa.","Cậu nói gì vậy?"]'::jsonb, 0, 'Nội dung nghe được: 你是日明吗？ (Nǐ shì Rìmíng ma?) → Cậu là Nhật Minh phải không?', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_16_3', 'lesson-16', 'Bài khoá mở rộng: Kế hoạch cuối tuần bận rộn (Mở rộng)', 'Hội thoại tình huống mới xây dựng dựa trên từ vựng và ngữ pháp Bài 16 (không trùng lặp nguyên văn giáo trình).', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_16_3_1', 'txt_16_3', 'Minh', '周末你有什么打算？去逛街看电影吗？', '周末你有什么打算？去逛街看电影吗？', 'Zhōumò nǐ yǒu shénme dǎsuan? Qù guàngjiē kàn diànyǐng ma?', 'Cuối tuần cậu có dự định gì? Đi dạo phố xem phim không?', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_16_3_2', 'txt_16_3', 'Mark', '上午我要在家做功课、复习新闻，下午去健身房。', '上午我要在家做 (zuò: làm)功课、复习新闻，下午去健身房。', 'Shàngwǔ wǒ yào zài jiā zuò gōngkè, fùxí xīnwén, xiàwǔ qù jiànshēnfáng.', 'Buổi sáng tôi phải làm bài tập ở nhà, buổi chiều đến phòng tập gym.', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_16_3_3', 'txt_16_3', 'Minh', '那晚上我们去吃火锅吧，好久没见大家了。', '那晚上我们去吃火锅吧，好久没 (méi: chưa, không có)见大家 (dàjiā: mọi người)了。', 'Nà wǎnshang wǒmen qù chī huǒguō ba, hǎojiǔ méi jiàn dàjiā le.', 'Vậy buổi tối chúng ta đi ăn lẩu nhé, lâu rồi không gặp mọi người.', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_16_3_4', 'txt_16_3', 'Mark', '太好了！吃完火锅我们还可以在公园照相休息。', '太好了！吃完 (wán: xong, hết)火锅我们还可以在公园照相休息。', 'Tài hǎo le! Chīwán huǒguō wǒmen hái kěyǐ zài gōngyuán zhàoxiàng xiūxi.', 'Hay quá! Ăn lẩu xong chúng ta còn có thể ra công viên chụp ảnh và thư giãn.', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_16_3_1', 'lesson-16', 'txt_16_3', 'listening', 'listening', '周末你有什么打算？去逛街看电影吗？ 上午我要在家做功课、复习新闻，下午去健身房。 那晚上我们去吃火锅吧，好久没见大家了。 太好了！吃完火锅我们还可以在公园照相休息。', NULL, '[Nghe hiểu tình huống mới] Buổi chiều cuối tuần, Mark dự định đi đâu?', '["Đến thư viện từ sáng đến tối","Đi siêu thị mua giày","Đến phòng tập thể hình (健身房)","Ở nhà xem tin tức cả ngày"]'::jsonb, 2, 'Mark nói ''下午去健身房'' (buổi chiều đến phòng tập gym).', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_16_3_2', 'lesson-16', 'txt_16_3', 'listening', 'listening', '周末你有什么打算？去逛街看电影吗？', NULL, '[Mở rộng] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Cuối tuần cậu có dự định gì? Đi dạo phố xem phim không?","Bye! (thường dùng trong giới trẻ)","Hình như ban nãy tôi mới trông thấy cô ấy.","Hình như cậu không thích ăn cay."]'::jsonb, 0, 'Nội dung nghe được: 周末你有什么打算？去逛街看电影吗？ (Zhōumò nǐ yǒu shénme dǎsuan? Qù guàngjiē kàn diànyǐng ma?) → Cuối tuần cậu có dự định gì? Đi dạo phố xem phim không?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_16_3_3', 'lesson-16', 'txt_16_3', 'listening', 'listening', '上午我要在家做功课、复习新闻，下午去健身房。', NULL, '[Mở rộng] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["昨天晚上我复习了复习课文 (kèwén: bài khoá)。","做完 (zuòwán: làm xong)功课以后 (yǐhòu: sau, lúc sau)我想去看电影。","上午我要在家做 (zuò: làm)功课、复习新闻，下午去健身房。","等等 = 等一等"]'::jsonb, 2, 'Câu vừa đọc: 上午我要在家做功课、复习新闻，下午去健身房。 (Shàngwǔ wǒ yào zài jiā zuò gōngkè, fùxí xīnwén, xiàwǔ qù jiànshēnfáng.) → Buổi sáng tôi phải làm bài tập ở nhà, buổi chiều đến phòng tập gym.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_16_3_4', 'lesson-16', 'txt_16_3', 'listening', 'listening', '那晚上我们去吃火锅吧，好久没见大家了。', NULL, '[Mở rộng] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Cô ấy hát rất hay!","từ điển tiếng Trung","Vậy buổi tối chúng ta đi ăn lẩu nhé, lâu rồi không gặp mọi người.","Hai mươi lăm cái"]'::jsonb, 2, 'Nội dung nghe được: 那晚上我们去吃火锅吧，好久没见大家了。 (Nà wǎnshang wǒmen qù chī huǒguō ba, hǎojiǔ méi jiàn dàjiā le.) → Vậy buổi tối chúng ta đi ăn lẩu nhé, lâu rồi không gặp mọi người.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
