INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq16_11', 'lesson-16', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Phiên âm Pinyin chính xác của “非常” là gì?', '["làngfèi","kàn diànyǐng","kuàiyào… le","fēicháng"]'::jsonb, 3, '“非常” đọc là: fēicháng (cực kì).', 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq16_12', 'lesson-16', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Phiên âm Pinyin chính xác của “常常” là gì?', '["jiàqī","bāngzhù","chángcháng","gōngkè"]'::jsonb, 2, '“常常” đọc là: chángcháng (thường).', 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq16_13', 'lesson-16', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “假期” chứa bộ thủ nào sau đây?', '["口 (Khẩu) (Miệng, ăn uống, lời nói)","Bộ cấu tạo [假] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [无] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [简] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)"]'::jsonb, 1, 'Chữ “假期” có Bộ cấu tạo [假] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán). Ghép từ các chữ Hán: [假] + [期].', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq16_14', 'lesson-16', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “健身房” chứa bộ thủ nào sau đây?', '["Bộ cấu tạo [作] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","身 (Thân) (Thân thể, vóc dáng)","Bộ cấu tạo [常] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [简] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)"]'::jsonb, 1, 'Chữ “健身房” có 身 (Thân) (Thân thể, vóc dáng). Ghép từ các chữ Hán: [健] + [身] + [房].', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq16_15', 'lesson-16', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “新闻” chứa bộ thủ nào sau đây?', '["Bộ cấu tạo [功] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [无] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [事] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [新] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)"]'::jsonb, 3, 'Chữ “新闻” có Bộ cấu tạo [新] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán). Ghép từ các chữ Hán: [新] + [闻].', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq16_16', 'lesson-16', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “作业” chứa bộ thủ nào sau đây?', '["Bộ cấu tạo [快] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [作] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [照] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [休] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)"]'::jsonb, 1, 'Chữ “作业” có Bộ cấu tạo [作] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán). Ghép từ các chữ Hán: [作] + [业].', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq16_17', 'lesson-16', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 15] Từ đã học “冷” (lěng) có nghĩa là gì?', '["tôi, tớ, mình... (ngôi thứ nhất số ít)","lạnh","thuận tiện, tiện lợi","Phạm Ngọc Lan"]'::jsonb, 1, 'Ôn tập Bài 15: “冷” (lěng) nghĩa là: lạnh.', 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq16_18', 'lesson-16', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 2] Từ đã học “马克” (Mǎkè) có nghĩa là gì?', '["Mark (du học sinh Mỹ)","cà phê","như thế, như thế này","cảm động"]'::jsonb, 0, 'Ôn tập Bài 2: “马克” (Mǎkè) nghĩa là: Mark (du học sinh Mỹ).', 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq16_19', 'lesson-16', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 9] Từ đã học “新” (xīn) có nghĩa là gì?', '["đến từ (đâu)","cùng nhau","buổi sáng, sáng","mới"]'::jsonb, 3, 'Ôn tập Bài 9: “新” (xīn) nghĩa là: mới.', 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq16_20', 'lesson-16', NULL, 'expanded_quiz', 'reading', NULL, NULL, '[Mở rộng] Câu “星期天我们去逛街、吃火锅吧！” có nghĩa tiếng Việt là gì?', '["Thử qua một chút.","Chủ nhật chúng ta đi dạo phố và ăn lẩu nhé!","Anh ta không cho tôi đi.","Anh ấy giận tôi rồi!"]'::jsonb, 1, '星期天我们去逛街、吃火锅吧！ (Xīngqītiān wǒmen qù guàngjiē, chī huǒguō ba!) → Chủ nhật chúng ta đi dạo phố và ăn lẩu nhé!', 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq16_21', 'lesson-16', NULL, 'expanded_quiz', 'reading', NULL, NULL, '[Đọc hiểu mở rộng] Đọc đoạn hội thoại:
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq16_22', 'lesson-16', NULL, 'expanded_quiz', 'reading', NULL, NULL, 'Câu “找找 = 找一找” có nghĩa tiếng Việt là gì?', '["Cảm ơn bạn thường xuyên giúp đỡ tôi trong việc học.","Bạn biết anh ấy ở đâu không?","Chủ nhật chúng ta đi dạo phố và ăn lẩu nhé!","Tìm một chút, tìm qua."]'::jsonb, 3, '找找 = 找一找 (zhǎozhao = zhǎo yi zhǎo) → Tìm một chút, tìm qua.', 22) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct16_1', 'lesson-16', NULL, 'comprehensive_test', 'listening', '我觉得春天的天气最暖和最舒服', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Tôi thấy thời tiết mùa xuân ấm áp và dễ chịu nhất.","3 giờ 15 phút. Khi nào bạn đi?","Tớ thấy màu sắc không đẹp lắm, tớ không thích màu xanh lá, tớ thích nhất màu đỏ và màu vàng.","Ai đấy?"]'::jsonb, 0, 'Nội dung nghe được: “我觉得春天的天气最暖和最舒服” (Wǒ juéde chūntiān de tiānqì zuì nuǎnhuo, zuì shūfu.) → Tôi thấy thời tiết mùa xuân ấm áp và dễ chịu nhất.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct16_2', 'lesson-16', NULL, 'comprehensive_test', 'listening', '你很乖啊！如果没有什么做我就上网看新闻或者玩游戏。', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["张风，北京有几个季节？","谁啊？","你很乖啊！如果没有什么做我就上网看新闻或者玩游戏。","不客气！"]'::jsonb, 2, 'Câu vừa đọc: “你很乖啊！如果没有什么做我就上网看新闻或者玩游戏。” (Nǐ hěn guāi a! Rúguǒ méiyǒu shénme zuò wǒ jiù shàngwǎng kàn xīnwén huòzhě wán yóuxì.) → Bạn ngoan thật đấy! Nếu không có việc gì làm thì tôi lên mạng đọc tin tức hoặc chơi game.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct16_3', 'lesson-16', NULL, 'comprehensive_test', 'listening', '如果你有困难，我就帮助你。', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Em thích học tiếng Trung hay tiếng Anh?","Em ấy thích nhất vẽ tranh, còn tớ mới là tín đồ bóng đá của cả nhà.","Cách đây có xa không?","Nếu cậu gặp khó khăn thì tớ sẽ giúp đỡ."]'::jsonb, 3, 'Nội dung nghe được: “如果你有困难，我就帮助你。” (Rúguǒ nǐ yǒu kùnnan, wǒ jiù bāngzhù nǐ.) → Nếu cậu gặp khó khăn thì tớ sẽ giúp đỡ.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct16_4', 'lesson-16', NULL, 'comprehensive_test', 'listening', '昨天晚上我复习了复习课文。', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["昨天晚上我复习了复习课文。","我不会跟他一起回家。","老师，早上好！您是刘老师吗？","好的，一共 150 块。"]'::jsonb, 0, 'Câu vừa đọc: “昨天晚上我复习了复习课文。” (Zuótiān wǎnshàng wǒ fùxí le fùxí kèwén.) → Tối hôm qua tôi đã ôn tập qua bài khóa rồi.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct16_5', 'lesson-16', NULL, 'comprehensive_test', 'listening', '是啊！你觉得周末做什么比较好呢？', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Một năm có bốn mùa, bạn thích mùa nào nhất?","Đúng rồi! Bạn thấy cuối tuần làm gì thì hay nhỉ?","Vâng, tôi cũng là du học sinh.","Chà, đẹp quá đi! Tớ nghĩ em gái cậu nhất định sẽ rất thích! À, sinh nhật em gái cậu là ngày mấy tháng mấy?"]'::jsonb, 1, 'Nội dung nghe được: “是啊！你觉得周末做什么比较好呢？” (Shì a! Nǐ juéde zhōumò zuò shénme bǐjiào hǎo ne?) → Đúng rồi! Bạn thấy cuối tuần làm gì thì hay nhỉ?', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct16_6', 'lesson-16', NULL, 'comprehensive_test', 'listening', '星期天我们去逛街吃火锅吧', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["这本书是我的。","他来自哪个国家","星期天我们去逛街吃火锅吧","你好！你也是学生吗？"]'::jsonb, 2, 'Câu vừa đọc: “星期天我们去逛街吃火锅吧” (Xīngqītiān wǒmen qù guàngjiē, chī huǒguō ba!) → Chủ nhật chúng ta đi dạo phố và ăn lẩu nhé!', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct16_7', 'lesson-16', NULL, 'comprehensive_test', 'listening', '我常常跟朋友出去玩儿，我非常喜欢去公园照相。', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Xin hỏi đến siêu thị đi thế nào vậy?","Vâng, tổng cộng 150 tệ ạ.","Sáng mai chúng ta cùng đi siêu thị nhé!","Tôi thường ra ngoài chơi với bạn bè, tôi rất thích ra công viên chụp ảnh."]'::jsonb, 3, 'Nội dung nghe được: “我常常跟朋友出去玩儿，我非常喜欢去公园照相。” (Wǒ chángcháng gēn péngyou chūqù wánr, wǒ fēicháng xǐhuan qù gōngyuán zhàoxiàng.) → Tôi thường ra ngoài chơi với bạn bè, tôi rất thích ra công viên chụp ảnh.', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct16_8', 'lesson-16', NULL, 'comprehensive_test', 'listening', '你的周末很无聊，你看看, 这简直太浪费时间了吧！', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["你的周末很无聊，你看看, 这简直太浪费时间了吧！","我家有四口人爸爸妈妈哥哥和我","给你，谢谢!","我姓张，叫张风。现在我要去上课了。"]'::jsonb, 0, 'Câu vừa đọc: “你的周末很无聊，你看看, 这简直太浪费时间了吧！” (Nǐ de zhōumò hěn wúliáo, nǐ kànkan, zhè jiǎnzhí tài làngfèi shíjiān le ba!) → Cuối tuần của bạn nhàm chán quá, bạn xem đấy, như vậy thật quá lãng phí thời gian rồi!', 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
