INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v17_1', 'lesson-17', '新年', 'xīnnián', 'tân niên', 'năm mới', 'Danh từ', 'Bộ cấu tạo [新] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [新] + [年].', 'Kết hợp các thành tố [新] + [年] để tạo thành từ mang nghĩa ''năm mới''.', '先准备好这些，然后到除夕，全家人团圆，一起吃年夜饭、放鞭炮，庆祝新年。', 'Xiān zhǔnbèi hǎo zhèxiē, ránhòu dào chúxī, quán jiārén tuányuán, yīqǐ chī niányèfàn, fàng biānpào, qìngzhù xīnnián.', 'Trước tiên chuẩn bị xong những thứ này, rồi đến đêm Giao thừa, cả nhà đoàn tụ cùng ăn bữa cơm tất niên, đốt pháo mừng năm mới.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v17_2', 'lesson-17', '春节', 'Chūnjié', 'xuân tiết', 'Tết âm lịch', 'Danh từ', 'Bộ cấu tạo [春] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [春] + [节].', 'Kết hợp các thành tố [春] + [节] để tạo thành từ mang nghĩa ''Tết âm lịch''.', '我听几个朋友说快到春节了，春节是你们的一个节日，对吗？', 'Wǒ tīng jǐ gè péngyou shuō kuài dào Chūnjié le, Chūnjié shì nǐmen de yígè jiérì, duì ma?', 'Tôi nghe mấy người bạn nói sắp đến Tết Nguyên Đán rồi, Tết là một ngày lễ của các bạn đúng không?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v17_3', 'lesson-17', '节日', 'jiérì', 'tiết nhật', 'ngày lễ', 'Danh từ', '日 (Nhật) (Mặt trời, ban ngày, thời gian, ánh sáng)', 'Ghép từ các chữ Hán: [节] + [日].', 'Kết hợp các thành tố [节] + [日] để tạo thành từ mang nghĩa ''ngày lễ''.', '我听几个朋友说快到春节了，春节是你们的一个节日，对吗？', 'Wǒ tīng jǐ gè péngyou shuō kuài dào Chūnjié le, Chūnjié shì nǐmen de yígè jiérì, duì ma?', 'Tôi nghe mấy người bạn nói sắp đến Tết Nguyên Đán rồi, Tết là một ngày lễ của các bạn đúng không?', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v17_4', 'lesson-17', '除夕', 'chúxī', 'từ Hán ngữ', 'đêm giao thừa', 'Danh từ', '夕 (Tịch) (Buổi chiều tối, đêm tối)', 'Ghép từ các chữ Hán: [除] + [夕].', 'Kết hợp các thành tố [除] + [夕] để tạo thành từ mang nghĩa ''đêm giao thừa''.', '先准备好这些，然后到除夕，全家人团圆，一起吃年夜饭、放鞭炮，庆祝新年。', 'Xiān zhǔnbèi hǎo zhèxiē, ránhòu dào chúxī, quán jiārén tuányuán, yīqǐ chī niányèfàn, fàng biānpào, qìngzhù xīnnián.', 'Trước tiên chuẩn bị xong những thứ này, rồi đến đêm Giao thừa, cả nhà đoàn tụ cùng ăn bữa cơm tất niên, đốt pháo mừng năm mới.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v17_5', 'lesson-17', '饺子', 'jiǎozi', 'từ Hán ngữ', 'sủi cảo', 'Danh từ', '子 (Tử) (Đứa con, trẻ nhỏ, người trí thức)', 'Ghép từ các chữ Hán: [饺] + [子].', 'Kết hợp các thành tố [饺] + [子] để tạo thành từ mang nghĩa ''sủi cảo''.', '要准备很多，比如打扫房子、买茶食、水果、贴春联、包饺子。', 'Yào zhǔnbèi hěnduō, bǐrú dǎsǎo fángzi, mǎi cháshi, shuǐguǒ, tiē chūnlián, bāo jiǎozi.', 'Phải chuẩn bị nhiều thứ lắm, ví dụ như dọn dẹp nhà cửa, mua bánh mứt, trái cây, dán câu đối Tết, gói sủi cảo.', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v17_6', 'lesson-17', '粽子', 'zòngzi', 'từ Hán ngữ', 'bánh chưng', 'Danh từ', '子 (Tử) (Đứa con, trẻ nhỏ, người trí thức)', 'Ghép từ các chữ Hán: [粽] + [子].', 'Kết hợp các thành tố [粽] + [子] để tạo thành từ mang nghĩa ''bánh chưng''.', '我们越南不包饺子，我们包粽子。', 'Wǒmen Yuènán bù bāo jiǎozi, wǒmen bāo zòngzi.', 'Việt Nam chúng tôi không gói sủi cảo, chúng tôi gói bánh chưng.', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v17_7', 'lesson-17', '茶食', 'cháshi', 'trà thực', 'bánh kẹo (nói chung)', 'Danh từ', '食 (Thực) (Đồ ăn, ẩm thực)', 'Ghép từ các chữ Hán: [茶] + [食].', 'Kết hợp các thành tố [茶] + [食] để tạo thành từ mang nghĩa ''bánh kẹo (nói chung)''.', '要准备很多，比如打扫房子、买茶食、水果、贴春联、包饺子。', 'Yào zhǔnbèi hěnduō, bǐrú dǎsǎo fángzi, mǎi cháshi, shuǐguǒ, tiē chūnlián, bāo jiǎozi.', 'Phải chuẩn bị nhiều thứ lắm, ví dụ như dọn dẹp nhà cửa, mua bánh mứt, trái cây, dán câu đối Tết, gói sủi cảo.', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v17_8', 'lesson-17', '年夜饭', 'niányèfàn', 'niên', 'bữa cơm tất niên', 'Danh từ', 'Bộ cấu tạo [年] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [年] + [夜] + [饭].', 'Kết hợp các thành tố [年] + [夜] + [饭] để tạo thành từ mang nghĩa ''bữa cơm tất niên''.', '先准备好这些，然后到除夕，全家人团圆，一起吃年夜饭、放鞭炮，庆祝新年。', 'Xiān zhǔnbèi hǎo zhèxiē, ránhòu dào chúxī, quán jiārén tuányuán, yīqǐ chī niányèfàn, fàng biānpào, qìngzhù xīnnián.', 'Trước tiên chuẩn bị xong những thứ này, rồi đến đêm Giao thừa, cả nhà đoàn tụ cùng ăn bữa cơm tất niên, đốt pháo mừng năm mới.', 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v17_9', 'lesson-17', '红包', 'hóngbāo', 'hồng bao', 'bao lì xì', 'Danh từ', 'Bộ cấu tạo [红] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [红] + [包].', 'Kết hợp các thành tố [红] + [包] để tạo thành từ mang nghĩa ''bao lì xì''.', '对，还有红包。我还记得我小时候去亲戚家拜年，他们给我很多红包，真开心，但是现在没有了。', 'Duì, hái yǒu hóngbāo. Wǒ hái jìde wǒ xiǎoshíhou qù qīnqi jiā bàinián, tāmen gěi wǒ hěnduō hóngbāo, zhēn kāixīn, dànshì xiànzài méiyǒu le.', 'Đúng rồi, còn có lì xì nữa. Tôi vẫn nhớ hồi nhỏ đi chúc Tết họ hàng, mọi người mừng tuổi tôi rất nhiều bao lì xì, vui lắm, nhưng bây giờ thì không còn nữa rồi.', 9) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v17_10', 'lesson-17', '春联', 'chūnlián', 'xuân', 'câu đối Tết', 'Danh từ', 'Bộ cấu tạo [春] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [春] + [联].', 'Kết hợp các thành tố [春] + [联] để tạo thành từ mang nghĩa ''câu đối Tết''.', '要准备很多，比如打扫房子、买茶食、水果、贴春联、包饺子。', 'Yào zhǔnbèi hěnduō, bǐrú dǎsǎo fángzi, mǎi cháshi, shuǐguǒ, tiē chūnlián, bāo jiǎozi.', 'Phải chuẩn bị nhiều thứ lắm, ví dụ như dọn dẹp nhà cửa, mua bánh mứt, trái cây, dán câu đối Tết, gói sủi cảo.', 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
