INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr17_zh_1', 'lesson-17', 'zh_to_vi', '[Mở rộng] 春节是中国 (Zhōngguó: Trung Quốc)最重要、最热闹的传统节日。', '春节是中国最重要、最热闹的传统节日。', 'Chūnjié shì Zhōngguó zuì zhòngyào, zuì rènao de chuántǒng jiérì.', NULL, 'Tết Nguyên Đán là ngày lễ truyền thống quan trọng và náo nhiệt nhất của Trung Quốc.', NULL, '["Tết","Nguyên","Đán"]'::jsonb, 'Pinyin: Chūnjié shì Zhōngguó zuì zhòngyào, zuì rènao de chuántǒng jiérì.', '春节是中国最重要、最热闹的传统节日。 (Chūnjié shì Zhōngguó zuì zhòngyào, zuì rènao de chuántǒng jiérì.) nghĩa là: Tết Nguyên Đán là ngày lễ truyền thống quan trọng và náo nhiệt nhất của Trung Quốc.', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
