INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct17_24', 'lesson-17', NULL, 'comprehensive_test', 'listening', '今年的除夕夜，欢迎你来我家过春节！ 谢谢！中国春节和越南春节都要大扫除、贴春联吧？ 是的，除夕晚上全家一起吃年夜饭、放鞭炮，还会包饺子。 太热闹了！我也想学怎么包饺子。', NULL, 'Điểm khác biệt trong hoạt động ngày Tết được nhắc đến là gì?', '["Chỉ ăn bánh mì vào đêm Giao thừa","Không dán câu đối ngày Tết","Ngọc Lan muốn học gói sủi cảo (包饺子) cùng gia đình Trương Phong đêm Giao thừa","Hai nước không tổ chức Tết"]'::jsonb, 2, 'Phong mời Lan sang ăn cơm tất niên, đốt pháo, gói sủi cảo và Lan nói ''我也想学怎么包饺子''.', 24) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
