INSERT INTO lessons (id, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id) VALUES ('lesson-18', 'Bài 18: Du lịch - Đơn nguyên 5: Kỳ nghỉ', 'Bài 18', 'Đơn nguyên 5: Kỳ nghỉ', 'Chuẩn bị hành lý, đặt vé máy bay, phòng khách sạn, tham quan danh lam thắng cảnh.', '2026-11-14'::date, 18, TRUE, NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, date_added = EXCLUDED.date_added, sort_order = EXCLUDED.sort_order, is_system = TRUE, updated_at = NOW();
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v18_1', 'lesson-18', '中国', 'Zhōngguó', 'trung quốc', 'Trung Quốc', 'Danh từ', 'Bộ cấu tạo [中] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [中] + [国].', 'Kết hợp các thành tố [中] + [国] để tạo thành từ mang nghĩa ''Trung Quốc''.', '对。万里长城非常雄伟壮丽，是中国人历史和文化的象征。', 'Duì. Wànlǐ Chángchéng fēicháng xióngwěi zhuànglì, shì Zhōngguó rén lìshǐ hé wénhuà de xiàngzhēng.', 'Đúng vậy. Vạn Lý Trường Thành vô cùng hùng vĩ tráng lệ, là biểu tượng lịch sử và văn hóa của người Trung Quốc.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v18_2', 'lesson-18', '象征', 'xiàngzhēng', 'từ Hán ngữ', 'tượng trưng', 'Danh từ', 'Bộ cấu tạo [象] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [象] + [征].', 'Kết hợp các thành tố [象] + [征] để tạo thành từ mang nghĩa ''tượng trưng''.', '对。万里长城非常雄伟壮丽，是中国人历史和文化的象征。', 'Duì. Wànlǐ Chángchéng fēicháng xióngwěi zhuànglì, shì Zhōngguó rén lìshǐ hé wénhuà de xiàngzhēng.', 'Đúng vậy. Vạn Lý Trường Thành vô cùng hùng vĩ tráng lệ, là biểu tượng lịch sử và văn hóa của người Trung Quốc.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v18_3', 'lesson-18', '景点', 'jǐngdiǎn', 'điểm', 'địa điểm, danh lam thắng cảnh', 'Danh từ', 'Bộ cấu tạo [景] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [景] + [点].', 'Kết hợp các thành tố [景] + [点] để tạo thành từ mang nghĩa ''địa điểm, danh lam thắng cảnh''.', '当然了。北京特别美，有很多有名的景点，比如：万里长城、颐和园、故宫和天安门。', 'Dāngrán le. Běijīng tèbié měi, yǒu hěnduō yǒumíng de jǐngdiǎn, bǐrú: Wànlǐ Chángchéng, Yíhéyuán, Gùgōng hé Tiān''ānmén.', 'Tất nhiên rồi. Bắc Kinh vô cùng đẹp, có rất nhiều danh thắng nổi tiếng như: Vạn Lý Trường Thành, Di Hòa Viên, Cố Cung và Thiên An Môn.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
