INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v18_7', 'lesson-18', '天安门', 'Tiān''ānmén', 'thiên An môn', 'Thiên An Môn', 'Cụm từ / Tên riêng', '门 (Môn) (Cánh cửa, lối ra vào)', 'Ghép từ các chữ Hán: [天] + [安] + [门].', 'Kết hợp các thành tố [天] + [安] + [门] để tạo thành từ mang nghĩa ''Thiên An Môn''.', '当然了。北京特别美，有很多有名的景点，比如：万里长城、颐和园、故宫和天安门。', 'Dāngrán le. Běijīng tèbié měi, yǒu hěnduō yǒumíng de jǐngdiǎn, bǐrú: Wànlǐ Chángchéng, Yíhéyuán, Gùgōng hé Tiān''ānmén.', 'Tất nhiên rồi. Bắc Kinh vô cùng đẹp, có rất nhiều danh thắng nổi tiếng như: Vạn Lý Trường Thành, Di Hòa Viên, Cố Cung và Thiên An Môn.', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v18_8', 'lesson-18', '菜', 'cài', 'từ Hán ngữ', 'món ăn, đồ ăn, rau', 'Danh từ', 'Bộ cấu tạo [菜] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Chữ độc thể / hình thanh gồm Bộ cấu tạo [菜] và các nét bổ trợ.', 'Ghi nhớ chữ [菜] (món ăn, đồ ăn, rau) qua hình tượng Thành phần biểu ý/biểu âm cơ bản trong chữ Hán.', '我还去爬山、拍照、购物和尝尝北京的菜。', 'Wǒ hái qù páshān, pāizhào, gòuwù hé chángchang Běijīng de cài.', 'Tôi còn đi leo núi, chụp ảnh, mua sắm và thưởng thức các món ăn Bắc Kinh.', 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v18_9', 'lesson-18', '烤鸭', 'kǎoyā', 'từ Hán ngữ', 'vịt quay', 'Danh từ', 'Bộ cấu tạo [烤] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [烤] + [鸭].', 'Kết hợp các thành tố [烤] + [鸭] để tạo thành từ mang nghĩa ''vịt quay''.', '不但很好吃而且也比较便宜，特别是北京烤鸭。', 'Búdàn hěn hǎo chī érqiě yě bǐjiào piányi, tèbié shì Běijīng kǎoyā.', 'Không những rất ngon mà giá cũng khá rẻ, đặc biệt là món vịt quay Bắc Kinh.', 9) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
