INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr18_vi_1', 'lesson-18', 'vi_to_zh', '[Mở rộng] Kỳ nghỉ hè năm sau tôi dự định đi du lịch Trung Quốc một tháng.', NULL, NULL, '明年暑假我打算去中国旅游一个月。', NULL, 'míngnián shǔjià wǒ dǎsuan qù zhōngguó lǚyóu yígè yuè', '[]'::jsonb, 'Gợi ý Pinyin: Míngnián shǔjià wǒ dǎsuan qù Zhōngguó lǚyóu yígè yuè.', 'Kỳ nghỉ hè năm sau tôi dự định đi du lịch Trung Quốc một tháng. → 明年暑假我打算去中国旅游一个月。 (Míngnián shǔjià wǒ dǎsuan qù Zhōngguó lǚyóu yígè yuè.)', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
