INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v19_1', 'lesson-19', '药', 'yào', 'dược', 'thuốc', 'Danh từ', 'Bộ cấu tạo [药] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Chữ độc thể / hình thanh gồm Bộ cấu tạo [药] và các nét bổ trợ.', 'Ghi nhớ chữ [药] (thuốc) qua hình tượng Thành phần biểu ý/biểu âm cơ bản trong chữ Hán.', '你还这样说！我现在去药店给你买药。对了， 听说感冒应该吃肉粥，这样很快就恢复了。我顺便给你买一碗粥吧！', 'Nǐ hái zhèyàng shuō! Wǒ xiànzài qù yàodiàn gěi nǐ mǎi yào. Duì le, tīngshuō gǎnmào yīnggāi chī ròu zhōu, zhèyàng hěn kuài jiù huīfù le. Wǒ shùnbiàn gěi nǐ mǎi yī wǎn zhōu ba!', 'Cậu vẫn còn nói thế được à! Giờ tớ ra hiệu thuốc mua thuốc cho cậu. À đúng rồi, nghe nói bị cảm nên ăn cháo thịt để mau hồi phục. Tớ tiện đường mua cho cậu một bát cháo nhé!', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v19_2', 'lesson-19', '肉粥', 'ròuzhōu', 'từ Hán ngữ', 'cháo thịt', 'Danh từ', 'Bộ cấu tạo [肉] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [肉] + [粥].', 'Kết hợp các thành tố [肉] + [粥] để tạo thành từ mang nghĩa ''cháo thịt''.', '你还这样说！我现在去药店给你买药。对了， 听说感冒应该吃肉粥，这样很快就恢复了。我顺便给你买一碗粥吧！', 'Nǐ hái zhèyàng shuō! Wǒ xiànzài qù yàodiàn gěi nǐ mǎi yào. Duì le, tīngshuō gǎnmào yīnggāi chī ròu zhōu, zhèyàng hěn kuài jiù huīfù le. Wǒ shùnbiàn gěi nǐ mǎi yī wǎn zhōu ba!', 'Cậu vẫn còn nói thế được à! Giờ tớ ra hiệu thuốc mua thuốc cho cậu. À đúng rồi, nghe nói bị cảm nên ăn cháo thịt để mau hồi phục. Tớ tiện đường mua cho cậu một bát cháo nhé!', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v19_3', 'lesson-19', '药店', 'yàodiàn', 'dược điếm', 'hiệu thuốc', 'Danh từ', 'Bộ cấu tạo [药] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [药] + [店].', 'Kết hợp các thành tố [药] + [店] để tạo thành từ mang nghĩa ''hiệu thuốc''.', '你还这样说！我现在去药店给你买药。对了， 听说感冒应该吃肉粥，这样很快就恢复了。我顺便给你买一碗粥吧！', 'Nǐ hái zhèyàng shuō! Wǒ xiànzài qù yàodiàn gěi nǐ mǎi yào. Duì le, tīngshuō gǎnmào yīnggāi chī ròu zhōu, zhèyàng hěn kuài jiù huīfù le. Wǒ shùnbiàn gěi nǐ mǎi yī wǎn zhōu ba!', 'Cậu vẫn còn nói thế được à! Giờ tớ ra hiệu thuốc mua thuốc cho cậu. À đúng rồi, nghe nói bị cảm nên ăn cháo thịt để mau hồi phục. Tớ tiện đường mua cho cậu một bát cháo nhé!', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v19_4', 'lesson-19', '脸色', 'liǎnsè', 'sắc', 'sắc mặt', 'Danh từ', 'Bộ cấu tạo [脸] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [脸] + [色].', 'Kết hợp các thành tố [脸] + [色] để tạo thành từ mang nghĩa ''sắc mặt''.', '小兰，你的脸色不太好，是不是生病了？', 'Xiǎo Lán, nǐ de liǎnsè bú tài hǎo, shì bu shì shēngbìng le?', 'Tiểu Lan, sắc mặt cậu không tốt lắm, có phải bị ốm rồi không?', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v19_5', 'lesson-19', '冰水', 'bīngshuǐ', 'thủy', 'nước đá', 'Danh từ', 'Bộ cấu tạo [冰] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [冰] + [水].', 'Kết hợp các thành tố [冰] + [水] để tạo thành từ mang nghĩa ''nước đá''.', '你是不是又喝冰水了？你的喉咙经常发炎,你还不戒除冰水。', 'Nǐ shì bu shì yòu hē bīngshuǐ le? Nǐ de hóulong jīngcháng fāyán, nǐ hái bù jièchú bīngshuǐ.', 'Có phải cậu lại uống nước đá rồi không? Cổ họng cậu hay bị viêm mà cậu vẫn chưa bỏ uống nước đá.', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v19_6', 'lesson-19', '生病', 'shēngbìng', 'sinh bệnh', 'bị ốm, bị bệnh, ốm', 'Động từ', 'Bộ cấu tạo [生] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [生] + [病].', 'Kết hợp các thành tố [生] + [病] để tạo thành từ mang nghĩa ''bị ốm, bị bệnh, ốm''.', '小兰，你的脸色不太好，是不是生病了？', 'Xiǎo Lán, nǐ de liǎnsè bú tài hǎo, shì bu shì shēngbìng le?', 'Tiểu Lan, sắc mặt cậu không tốt lắm, có phải bị ốm rồi không?', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v19_7', 'lesson-19', '感冒', 'gǎnmào', 'cảm mạo', 'cảm cúm', 'Động từ', 'Bộ cấu tạo [感] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [感] + [冒].', 'Kết hợp các thành tố [感] + [冒] để tạo thành từ mang nghĩa ''cảm cúm''.', '我觉得头很疼，上午还发烧和咳嗽， 好像感冒了。', 'Wǒ juéde tóu hěn téng, shàngwǔ hái fāshāo hé késou, hǎoxiàng gǎnmào le.', 'Tớ thấy rất đau đầu, buổi sáng còn bị sốt và ho, hình như cảm lạnh rồi.', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v19_8', 'lesson-19', '头疼', 'tóuténg', 'đông', 'đau đầu', 'Động từ', 'Bộ cấu tạo [头] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [头] + [疼].', 'Kết hợp các thành tố [头] + [疼] để tạo thành từ mang nghĩa ''đau đầu''.', '这是关于“头疼”的常用句子。', 'Zhè shì guānyú ''tóuténg'' de chángyòng jùzi.', 'Đây là câu ví dụ sử dụng từ ''头疼'' (đau đầu).', 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v19_9', 'lesson-19', '发烧', 'fāshāo', 'phát thiêu', 'sốt', 'Động từ', 'Bộ cấu tạo [发] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [发] + [烧].', 'Kết hợp các thành tố [发] + [烧] để tạo thành từ mang nghĩa ''sốt''.', '孩子发烧了，最好带她去看医生吧。', 'Háizi fāshāo le, zuì hǎo dài tā qù kàn yīshēng ba.', 'Con bị ốm rồi, tốt nhất là đưa con đi khám bác sĩ đi.', 9) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v19_10', 'lesson-19', '咳嗽', 'késou', 'từ Hán ngữ', 'ho', 'Động từ', 'Bộ cấu tạo [咳] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [咳] + [嗽].', 'Kết hợp các thành tố [咳] + [嗽] để tạo thành từ mang nghĩa ''ho''.', '你咳嗽了，最好别抽烟了。', 'Nǐ késou le, zuì hǎo bié chōuyān le.', 'Anh bị ho rồi, tốt nhất đừng hút thuốc nữa.', 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v19_11', 'lesson-19', '喉咙发炎', 'hóulong fāyán', 'phát', 'viêm họng', 'Động từ', 'Bộ cấu tạo [喉] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [喉] + [咙] + [发] + [炎].', 'Kết hợp các thành tố [喉] + [咙] + [发] + [炎] để tạo thành từ mang nghĩa ''viêm họng''.', '这是关于“喉咙发炎”的常用句子。', 'Zhè shì guānyú ''hóulong fāyán'' de chángyòng jùzi.', 'Đây là câu ví dụ sử dụng từ ''喉咙发炎'' (viêm họng).', 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v19_12', 'lesson-19', '累', 'lèi', 'từ Hán ngữ', 'mệt, mệt mỏi', 'Tính từ', 'Bộ cấu tạo [累] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Chữ độc thể / hình thanh gồm Bộ cấu tạo [累] và các nét bổ trợ.', 'Ghi nhớ chữ [累] (mệt, mệt mỏi) qua hình tượng Thành phần biểu ý/biểu âm cơ bản trong chữ Hán.', '这是关于“累”的常用句子。', 'Zhè shì guānyú ''lèi'' de chángyòng jùzi.', 'Đây là câu ví dụ sử dụng từ ''累'' (mệt, mệt mỏi).', 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v19_13', 'lesson-19', '戒除', 'jièchú', 'từ Hán ngữ', 'cai, bỏ, chừa', 'Động từ', 'Bộ cấu tạo [戒] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [戒] + [除].', 'Kết hợp các thành tố [戒] + [除] để tạo thành từ mang nghĩa ''cai, bỏ, chừa''.', '你是不是又喝冰水了？你的喉咙经常发炎,你还不戒除冰水。', 'Nǐ shì bu shì yòu hē bīngshuǐ le? Nǐ de hóulong jīngcháng fāyán, nǐ hái bù jièchú bīngshuǐ.', 'Có phải cậu lại uống nước đá rồi không? Cổ họng cậu hay bị viêm mà cậu vẫn chưa bỏ uống nước đá.', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v19_14', 'lesson-19', '得了', 'dé le', 'từ Hán ngữ', 'bị (cảm cúm)', 'Động từ', 'Bộ cấu tạo [得] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [得] + [了].', 'Kết hợp các thành tố [得] + [了] để tạo thành từ mang nghĩa ''bị (cảm cúm)''.', '没事儿， 只得了感冒而已， 不要紧。', 'Méishìr, zhǐ déle gǎnmào éryǐ, bú yàojǐn.', 'Không sao đâu, chỉ bị cảm nhẹ thôi mà, không đáng ngại đâu.', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v19_15', 'lesson-19', '恢复', 'huīfù', 'từ Hán ngữ', 'hồi phục', 'Động từ', 'Bộ cấu tạo [恢] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [恢] + [复].', 'Kết hợp các thành tố [恢] + [复] để tạo thành từ mang nghĩa ''hồi phục''.', '你还这样说！我现在去药店给你买药。对了， 听说感冒应该吃肉粥，这样很快就恢复了。我顺便给你买一碗粥吧！', 'Nǐ hái zhèyàng shuō! Wǒ xiànzài qù yàodiàn gěi nǐ mǎi yào. Duì le, tīngshuō gǎnmào yīnggāi chī ròu zhōu, zhèyàng hěn kuài jiù huīfù le. Wǒ shùnbiàn gěi nǐ mǎi yī wǎn zhōu ba!', 'Cậu vẫn còn nói thế được à! Giờ tớ ra hiệu thuốc mua thuốc cho cậu. À đúng rồi, nghe nói bị cảm nên ăn cháo thịt để mau hồi phục. Tớ tiện đường mua cho cậu một bát cháo nhé!', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v19_16', 'lesson-19', '辛苦', 'xīnkǔ', 'từ Hán ngữ', 'mệt, vất vả', 'Động từ / Tính từ', 'Bộ cấu tạo [辛] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [辛] + [苦].', 'Kết hợp các thành tố [辛] + [苦] để tạo thành từ mang nghĩa ''mệt, vất vả''.', '谢谢！你辛苦了！', 'Xièxie! Nǐ xīnkǔ le!', 'Cảm ơn cậu! Làm phiền cậu quá!', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v19_17', 'lesson-19', '听说', 'tīngshuō', 'thính thuyết', 'nghe nói', 'Động từ', 'Bộ cấu tạo [听] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [听] + [说].', 'Kết hợp các thành tố [听] + [说] để tạo thành từ mang nghĩa ''nghe nói''.', '你还这样说！我现在去药店给你买药。对了， 听说感冒应该吃肉粥，这样很快就恢复了。我顺便给你买一碗粥吧！', 'Nǐ hái zhèyàng shuō! Wǒ xiànzài qù yàodiàn gěi nǐ mǎi yào. Duì le, tīngshuō gǎnmào yīnggāi chī ròu zhōu, zhèyàng hěn kuài jiù huīfù le. Wǒ shùnbiàn gěi nǐ mǎi yī wǎn zhōu ba!', 'Cậu vẫn còn nói thế được à! Giờ tớ ra hiệu thuốc mua thuốc cho cậu. À đúng rồi, nghe nói bị cảm nên ăn cháo thịt để mau hồi phục. Tớ tiện đường mua cho cậu một bát cháo nhé!', 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v19_18', 'lesson-19', '好像', 'hǎoxiàng', 'hảo', 'hình như', 'Phó từ', 'Bộ cấu tạo [好] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [好] + [像].', 'Kết hợp các thành tố [好] + [像] để tạo thành từ mang nghĩa ''hình như''.', '我觉得头很疼，上午还发烧和咳嗽， 好像感冒了。', 'Wǒ juéde tóu hěn téng, shàngwǔ hái fāshāo hé késou, hǎoxiàng gǎnmào le.', 'Tớ thấy rất đau đầu, buổi sáng còn bị sốt và ho, hình như cảm lạnh rồi.', 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v19_19', 'lesson-19', '要紧', 'yàojǐn', 'yếu', 'nghiêm trọng', 'Tính từ', 'Bộ cấu tạo [要] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [要] + [紧].', 'Kết hợp các thành tố [要] + [紧] để tạo thành từ mang nghĩa ''nghiêm trọng''.', '没事儿， 只得了感冒而已， 不要紧。', 'Méishìr, zhǐ déle gǎnmào éryǐ, bú yàojǐn.', 'Không sao đâu, chỉ bị cảm nhẹ thôi mà, không đáng ngại đâu.', 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v19_20', 'lesson-19', '快', 'kuài', 'khoái', 'nhanh', 'Tính từ', 'Bộ cấu tạo [快] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Chữ độc thể / hình thanh gồm Bộ cấu tạo [快] và các nét bổ trợ.', 'Ghi nhớ chữ [快] (nhanh) qua hình tượng Thành phần biểu ý/biểu âm cơ bản trong chữ Hán.', '你还这样说！我现在去药店给你买药。对了， 听说感冒应该吃肉粥，这样很快就恢复了。我顺便给你买一碗粥吧！', 'Nǐ hái zhèyàng shuō! Wǒ xiànzài qù yàodiàn gěi nǐ mǎi yào. Duì le, tīngshuō gǎnmào yīnggāi chī ròu zhōu, zhèyàng hěn kuài jiù huīfù le. Wǒ shùnbiàn gěi nǐ mǎi yī wǎn zhōu ba!', 'Cậu vẫn còn nói thế được à! Giờ tớ ra hiệu thuốc mua thuốc cho cậu. À đúng rồi, nghe nói bị cảm nên ăn cháo thịt để mau hồi phục. Tớ tiện đường mua cho cậu một bát cháo nhé!', 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v19_21', 'lesson-19', '顺便', 'shùnbiàn', 'tiện', 'thuận tiện, tiện thể', 'Phó từ', 'Bộ cấu tạo [顺] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [顺] + [便].', 'Kết hợp các thành tố [顺] + [便] để tạo thành từ mang nghĩa ''thuận tiện, tiện thể''.', '你还这样说！我现在去药店给你买药。对了， 听说感冒应该吃肉粥，这样很快就恢复了。我顺便给你买一碗粥吧！', 'Nǐ hái zhèyàng shuō! Wǒ xiànzài qù yàodiàn gěi nǐ mǎi yào. Duì le, tīngshuō gǎnmào yīnggāi chī ròu zhōu, zhèyàng hěn kuài jiù huīfù le. Wǒ shùnbiàn gěi nǐ mǎi yī wǎn zhōu ba!', 'Cậu vẫn còn nói thế được à! Giờ tớ ra hiệu thuốc mua thuốc cho cậu. À đúng rồi, nghe nói bị cảm nên ăn cháo thịt để mau hồi phục. Tớ tiện đường mua cho cậu một bát cháo nhé!', 21) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v19_22', 'lesson-19', '而已', 'éryǐ', 'từ Hán ngữ', 'mà thôi', 'Trợ từ', 'Bộ cấu tạo [而] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [而] + [已].', 'Kết hợp các thành tố [而] + [已] để tạo thành từ mang nghĩa ''mà thôi''.', '没事儿， 只得了感冒而已， 不要紧。', 'Méishìr, zhǐ déle gǎnmào éryǐ, bú yàojǐn.', 'Không sao đâu, chỉ bị cảm nhẹ thôi mà, không đáng ngại đâu.', 22) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v19_23', 'lesson-19', '没事儿', 'méishìr', 'một sự nhi', 'không sao', 'Cụm từ / Tên riêng', 'Bộ cấu tạo [没] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [没] + [事] + [儿].', 'Kết hợp các thành tố [没] + [事] + [儿] để tạo thành từ mang nghĩa ''không sao''.', '没事儿， 只得了感冒而已， 不要紧。', 'Méishìr, zhǐ déle gǎnmào éryǐ, bú yàojǐn.', 'Không sao đâu, chỉ bị cảm nhẹ thôi mà, không đáng ngại đâu.', 23) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v19_24', 'lesson-19', '没想到', 'méixiǎngdào', 'một tưởng đáo', 'không ngờ (rằng)', 'Cụm từ / Tên riêng', 'Bộ cấu tạo [没] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [没] + [想] + [到].', 'Kết hợp các thành tố [没] + [想] + [到] để tạo thành từ mang nghĩa ''không ngờ (rằng)''.', '我只喝了一口，  没想到……', 'Wǒ zhǐ hē le yī kǒu, méixiǎngdào…', 'Tớ chỉ uống có một ngụm thôi, không ngờ…', 24) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g19_1', 'lesson-19', '1. 能: có thể', 'Cấu trúc câu ngữ pháp trọng tâm', ' Biểu thị có khả năng/năng lực làm gì đó. ●      Phủ định 不能: không thể 早餐他能吃十个包子。 Zǎocān tā néng chī shí gè bāozi. Bữa sáng cậu ấy có thể ăn 10 cái bánh bao. 我的头很疼，不能上课。 Wǒ de tóu hěn téng, bù néng shàngkè. Tớ rất đau đầu, không thể đi học được. 我明天', NULL, '[{"hanzi":"早餐他能吃十个包子。","pinyin":"Zǎocān tā néng chī shí gè bāozi.","meaning":"Bữa sáng cậu ấy có thể ăn 10 cái bánh bao."},{"hanzi":"我的头很疼，不能上课。","pinyin":"Wǒ de tóu hěn téng, bù néng shàngkè.","meaning":"Tớ rất đau đầu, không thể đi học được."}]'::jsonb, 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g19_2', 'lesson-19', '2. 最好 – tốt nhất', 'Cấu trúc câu ngữ pháp trọng tâm', ' Dùng trước động từ, biểu thị đề xuất, kiến nghị. 你咳嗽了，最好别抽烟了。 Nǐ késou le, zuì hǎo bié chōuyān le. Anh bị ho rồi, tốt nhất đừng hút thuốc nữa. 你感冒了，最好休息一天吧。 Nǐ gǎnmào le, zuì hǎo xiūxi yī tiān ba. Cậu bị cảm rồi, tốt nhất hãy nghỉ ngơi một ngày đi. ', NULL, '[{"hanzi":"我明天要考试了，不能跟你去。","pinyin":"Wǒ míngtiān yào kǎoshì le, bù néng gēn nǐ qù.","meaning":"Mai tớ thi rồi, không thể đi cùng cậu được."},{"hanzi":"你咳嗽了，最好别抽烟了。","pinyin":"Nǐ késou le, zuì hǎo bié chōuyān le.","meaning":"Anh bị ho rồi, tốt nhất đừng hút thuốc nữa."}]'::jsonb, 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g19_3', 'lesson-19', '3. Trợ từ ngữ khí 吧', 'Cấu trúc câu ngữ pháp trọng tâm', ' Trợ từ ngữ khí, dùng ở cuối câu, biểu thị phỏng đoán, suy đoán, ước lượng, không dám khẳng định. 她不来了吧。 Tā bù lái le ba. Chắc là cô đấy không đến nữa. 今天会下雨吧。 Jīntiān huì xià yǔ ba. Hôm nay chắc sẽ mưa đấy nhỉ. 第二十课：锻炼身体 Bài 20: Tập thể dục I. 词语表 –', NULL, '[{"hanzi":"孩子发烧了，最好带她去看医生吧。","pinyin":"Háizi fāshāo le, zuì hǎo dài tā qù kàn yīshēng ba.","meaning":"Con bị ốm rồi, tốt nhất là đưa con đi khám bác sĩ đi."},{"hanzi":"她不来了吧。","pinyin":"Tā bù lái le ba.","meaning":"Chắc là cô đấy không đến nữa."}]'::jsonb, 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g19_4', 'lesson-19', '1.身体 shēntǐ dt. cơ thể', 'Cấu trúc câu ngữ pháp trọng tâm', 'Quy tắc ngữ pháp quan trọng trong Bị ốm.', NULL, '[{"hanzi":"今天会下雨吧。","pinyin":"Jīntiān huì xià yǔ ba.","meaning":"Hôm nay chắc sẽ mưa đấy nhỉ."}]'::jsonb, 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_19_1', 'lesson-19', 'Bài khoá #1: Hội thoại giáo trình — Bị ốm', 'Hội thoại chuẩn giáo trình Bài 19. Từ vựng chưa học được chú thích phiên âm & nghĩa trong ngoặc.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_19_1_1', 'txt_19_1', '阮日明', '小兰，你的脸色不太好，是不是生病了？', '小兰，你的脸色不太好，是不是生病了？', 'Xiǎo Lán, nǐ de liǎnsè bú tài hǎo, shì bu shì shēngbìng le?', 'Tiểu Lan, sắc mặt cậu không tốt lắm, có phải bị ốm rồi không?', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_19_1_2', 'txt_19_1', '范玉兰', '我觉得头很疼，上午还发烧和咳嗽， 好像感冒了。', '我觉得头 (tóu: con (trâu, bò) / đầu)很疼 (téng: đau)，上午还发烧和咳嗽， 好像感冒了。', 'Wǒ juéde tóu hěn téng, shàngwǔ hái fāshāo hé késou, hǎoxiàng gǎnmào le.', 'Tớ thấy rất đau đầu, buổi sáng còn bị sốt và ho, hình như cảm lạnh rồi.', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_19_1_3', 'txt_19_1', '阮日明', '你是不是又喝冰水了？你的喉咙经常发炎,你还不戒除冰水。', '你是不是又喝冰水了？你的喉咙 (hóulong: cổ họng)经常发炎 (fāyán: bị viêm),你还不戒除冰水。', 'Nǐ shì bu shì yòu hē bīngshuǐ le? Nǐ de hóulong jīngcháng fāyán, nǐ hái bù jièchú bīngshuǐ.', 'Có phải cậu lại uống nước đá rồi không? Cổ họng cậu hay bị viêm mà cậu vẫn chưa bỏ uống nước đá.', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_19_1_4', 'txt_19_1', '范玉兰', '我只喝了一口，  没想到……', '我只喝了一口，  没想到……', 'Wǒ zhǐ hē le yī kǒu, méixiǎngdào…', 'Tớ chỉ uống có một ngụm thôi, không ngờ…', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_19_1_5', 'txt_19_1', '阮日明', '今天下午有课，你这样一定不能上课了。 最好回家休息吧！', '今天下午有课 (kè: tiết học, bài học)，你这样一定 (yīdìng: nhất định)不能上课了。 最好回家休息吧！', 'Jīntiān xiàwǔ yǒu kè, nǐ zhèyàng yídìng bùnéng shàngkè le. Zuì hǎo huí jiā xiūxi ba!', 'Chiều nay có tiết học, cậu thế này chắc chắn không đi học được rồi. Tốt nhất là về nhà nghỉ ngơi đi!', 5) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_19_1_6', 'txt_19_1', '范玉兰', '那你帮我跟刘老师说一声， 我生病不能上课了！', '那你帮 (bāng: giúp đỡ)我跟 (gēn: cùng, với)刘老师说一声 (shēng: tiếng)， 我生病不能上课了！', 'Nà nǐ bāng wǒ gēn Liú lǎoshī shuō yī shēng, wǒ shēngbìng bùnéng shàngkè le!', 'Vậy cậu nói giúp tớ với cô Lưu một tiếng là tớ bị ốm không thể lên lớp được nhé!', 6) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_19_1_7', 'txt_19_1', '阮日明', '好的！我现在有空儿，还能帮你做什么吗？', '好的！我现在有空儿，还能帮 (bāng: giúp đỡ)你做 (zuò: làm)什么吗？', 'Hǎo de! Wǒ xiànzài yǒu kòngr, hái néng bāng nǐ zuò shénme ma?', 'Được rồi! Giờ tớ đang rảnh, còn giúp được gì cho cậu nữa không?', 7) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_19_1_8', 'txt_19_1', '范玉兰', '没事儿， 只得了感冒而已， 不要紧。', '没事儿， 只得了感冒而已， 不要紧。', 'Méishìr, zhǐ déle gǎnmào éryǐ, bú yàojǐn.', 'Không sao đâu, chỉ bị cảm nhẹ thôi mà, không đáng ngại đâu.', 8) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_19_1_9', 'txt_19_1', '阮日明', '你还这样说！我现在去药店给你买药。对了， 听说感冒应该吃肉粥，这样很快就恢复了。我顺便给你买一碗粥吧！', '你还这样说！我现在去药店给你买药。对了， 听说感冒应该 (yīnggāi: nên, có vẻ như)吃肉粥，这样很快就恢复了。我顺便给你买一碗 (wǎn: cái bát)粥 (zhōu: cháo)吧！', 'Nǐ hái zhèyàng shuō! Wǒ xiànzài qù yàodiàn gěi nǐ mǎi yào. Duì le, tīngshuō gǎnmào yīnggāi chī ròu zhōu, zhèyàng hěn kuài jiù huīfù le. Wǒ shùnbiàn gěi nǐ mǎi yī wǎn zhōu ba!', 'Cậu vẫn còn nói thế được à! Giờ tớ ra hiệu thuốc mua thuốc cho cậu. À đúng rồi, nghe nói bị cảm nên ăn cháo thịt để mau hồi phục. Tớ tiện đường mua cho cậu một bát cháo nhé!', 9) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_19_1_10', 'txt_19_1', '范玉兰', '谢谢！你辛苦了！', '谢谢！你辛苦了！', 'Xièxie! Nǐ xīnkǔ le!', 'Cảm ơn cậu! Làm phiền cậu quá!', 10) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_19_1_1', 'lesson-19', 'txt_19_1', 'listening', 'listening', '小兰，你的脸色不太好，是不是生病了？', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Lúc tôi gọi điện thoại cho bạn thì bố đang nhìn tôi.","Tiểu Lan, sắc mặt cậu không tốt lắm, có phải bị ốm rồi không?","Hôm qua trời lạnh quá, hình như tôi bị cảm cúm rồi.","Anh ấy giận tôi rồi!"]'::jsonb, 1, 'Nội dung nghe được: 小兰，你的脸色不太好，是不是生病了？ (Xiǎo Lán, nǐ de liǎnsè bú tài hǎo, shì bu shì shēngbìng le?) → Tiểu Lan, sắc mặt cậu không tốt lắm, có phải bị ốm rồi không?', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_19_1_2', 'lesson-19', 'txt_19_1', 'listening', 'listening', '我觉得头很疼，上午还发烧和咳嗽， 好像感冒了。', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["我明天要考试了，不能跟 (gēn: cùng, với)你去。","多喝温水，过 (guò: từng, qua)几天 (tiān: ngày, trời)身体 (shēntǐ: cơ thể)就会恢复。","谢谢！你辛苦了！","我觉得头 (tóu: con (trâu, bò) / đầu)很疼 (téng: đau)，上午还发烧和咳嗽， 好像感冒了。"]'::jsonb, 3, 'Câu vừa đọc: 我觉得头很疼，上午还发烧和咳嗽， 好像感冒了。 (Wǒ juéde tóu hěn téng, shàngwǔ hái fāshāo hé késou, hǎoxiàng gǎnmào le.) → Tớ thấy rất đau đầu, buổi sáng còn bị sốt và ho, hình như cảm lạnh rồi.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_19_1_3', 'lesson-19', 'txt_19_1', 'listening', 'listening', '你是不是又喝冰水了？你的喉咙经常发炎,你还不戒除冰水。', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Có phải cậu lại uống nước đá rồi không? Cổ họng cậu hay bị viêm mà cậu vẫn chưa bỏ uống nước đá.","Cậu vẫn còn nói thế được à! Giờ tớ ra hiệu thuốc mua thuốc cho cậu. À đúng rồi, nghe nói bị cảm nên ăn cháo thịt để mau hồi phục. Tớ tiện đường mua cho cậu một bát cháo nhé!","Hôm nay là thứ mấy?","hai cô gái kia"]'::jsonb, 0, 'Nội dung nghe được: 你是不是又喝冰水了？你的喉咙经常发炎,你还不戒除冰水。 (Nǐ shì bu shì yòu hē bīngshuǐ le? Nǐ de hóulong jīngcháng fāyán, nǐ hái bù jièchú bīngshuǐ.) → Có phải cậu lại uống nước đá rồi không? Cổ họng cậu hay bị viêm mà cậu vẫn chưa bỏ uống nước đá.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_19_1_4', 'lesson-19', 'txt_19_1', 'listening', 'listening', '我只喝了一口，  没想到……', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["那你帮 (bāng: giúp đỡ)我跟 (gēn: cùng, với)刘老师说一声 (shēng: tiếng)， 我生病不能上课了！","你太累了，喝完 (wán: xong, hết)这碗 (wǎn: cái bát)肉粥就好好休息吧。","我的头 (tóu: con (trâu, bò) / đầu)很疼 (téng: đau)，不能上课。","我只喝了一口，  没想到……"]'::jsonb, 3, 'Câu vừa đọc: 我只喝了一口，  没想到…… (Wǒ zhǐ hē le yī kǒu, méixiǎngdào…) → Tớ chỉ uống có một ngụm thôi, không ngờ…', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_19_2', 'lesson-19', 'Bài nghe tổng hợp: Ôn tập lũy tiến (Bài 1 – Bài 19)', 'Kết hợp từ vựng & mẫu câu đã học từ Bài 1 đến Bài 18 cùng trọng tâm Bài 19 để củng cố phản xạ nghe.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_19_2_1', 'txt_19_2', 'Ôn Bài 18', '她会说汉语。', '她会说汉语。', 'Tā huì shuō Hànyǔ.', 'Cô ấy biết nói tiếng Trung.', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
