INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq19_13', 'lesson-19', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “药” chứa bộ thủ nào sau đây?', '["Bộ cấu tạo [咳] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [生] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [药] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [喉] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)"]'::jsonb, 2, 'Chữ “药” có Bộ cấu tạo [药] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán). Chữ độc thể / hình thanh gồm Bộ cấu tạo [药] và các nét bổ trợ.', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq19_14', 'lesson-19', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “肉粥” chứa bộ thủ nào sau đây?', '["Bộ cấu tạo [顺] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [恢] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [得] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [肉] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)"]'::jsonb, 3, 'Chữ “肉粥” có Bộ cấu tạo [肉] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán). Ghép từ các chữ Hán: [肉] + [粥].', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq19_15', 'lesson-19', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “药店” chứa bộ thủ nào sau đây?', '["Bộ cấu tạo [好] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [戒] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [药] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [咳] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)"]'::jsonb, 2, 'Chữ “药店” có Bộ cấu tạo [药] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán). Ghép từ các chữ Hán: [药] + [店].', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq19_16', 'lesson-19', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “脸色” chứa bộ thủ nào sau đây?', '["Bộ cấu tạo [恢] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [头] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [脸] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [累] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)"]'::jsonb, 2, 'Chữ “脸色” có Bộ cấu tạo [脸] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán). Ghép từ các chữ Hán: [脸] + [色].', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq19_17', 'lesson-19', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 16] Từ đã học “快要......了” (kuàiyào… le) có nghĩa là gì?', '["mệt, mệt mỏi","mét (m)","con (lượng từ)","sắp… rồi"]'::jsonb, 3, 'Ôn tập Bài 16: “快要......了” (kuàiyào… le) nghĩa là: sắp… rồi.', 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq19_18', 'lesson-19', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 13] Từ đã học “打算” (dǎsuan) có nghĩa là gì?', '["Phó,đtnn biết, sẽ","mũ","ngưỡng mộ, hâm mộ","dự định"]'::jsonb, 3, 'Ôn tập Bài 13: “打算” (dǎsuan) nghĩa là: dự định.', 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq19_19', 'lesson-19', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 14] Từ đã học “小” (xiǎo) có nghĩa là gì?', '["trà","nhỏ, bé","vườn","hầu hết, xấp xỉ"]'::jsonb, 1, 'Ôn tập Bài 14: “小” (xiǎo) nghĩa là: nhỏ, bé.', 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq19_20', 'lesson-19', NULL, 'expanded_quiz', 'reading', NULL, NULL, '[Mở rộng] Câu “昨天天气太冷，我好像得了感冒。” có nghĩa tiếng Việt là gì?', '["Ngày mai là lễ Quốc khánh, chúng ta có thể đi mua sắm.","Tớ muốn đến công viên chạy bộ.","Trời có thể sắp mưa.","Hôm qua trời lạnh quá, hình như tôi bị cảm cúm rồi."]'::jsonb, 3, '昨天天气太冷，我好像得了感冒。 (Zuótiān tiānqì tài lěng, wǒ hǎoxiàng dé le gǎnmào.) → Hôm qua trời lạnh quá, hình như tôi bị cảm cúm rồi.', 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq19_21', 'lesson-19', NULL, 'expanded_quiz', 'reading', NULL, NULL, '[Đọc hiểu mở rộng] Đọc đoạn hội thoại:
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq19_22', 'lesson-19', NULL, 'expanded_quiz', 'reading', NULL, NULL, 'Câu “今天会下雨吧。” có nghĩa tiếng Việt là gì?', '["Uống nhiều nước ấm vào, vài ngày nữa sức khỏe sẽ hồi phục thôi.","Mẹ ơi, sau khi làm xong bài tập về nhà con có thể xem phim không ạ?","Hôm nay chắc sẽ mưa đấy nhỉ.","Cô ấy biết tiếng Trung."]'::jsonb, 2, '今天会下雨吧。 (Jīntiān huì xià yǔ ba.) → Hôm nay chắc sẽ mưa đấy nhỉ.', 22) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct19_1', 'lesson-19', NULL, 'comprehensive_test', 'listening', '我只喝了一口， 没想到……', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Anh ta mời tôi ngày mai tới nhà dùng cơm.","Cô bé, năm nay cháu mấy tuổi rồi?","Tớ thích nhất đá bóng, nếu trường có giải bóng đá, tớ nhất định sẽ tham gia.","Tớ chỉ uống có một ngụm thôi, không ngờ…"]'::jsonb, 3, 'Nội dung nghe được: “我只喝了一口， 没想到……” (Wǒ zhǐ hē le yī kǒu, méixiǎngdào…) → Tớ chỉ uống có một ngụm thôi, không ngờ…', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct19_2', 'lesson-19', NULL, 'comprehensive_test', 'listening', '那你帮我跟刘老师说一声， 我生病不能上课了！', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["马克，你又在干什么呢？","上午我要在家做功课、复习新闻，下午去健身房。","请告诉我这副眼镜多少钱","那你帮我跟刘老师说一声， 我生病不能上课了！"]'::jsonb, 3, 'Câu vừa đọc: “那你帮我跟刘老师说一声， 我生病不能上课了！” (Nà nǐ bāng wǒ gēn Liú lǎoshī shuō yī shēng, wǒ shēngbìng bùnéng shàngkè le!) → Vậy cậu nói giúp tớ với cô Lưu một tiếng là tớ bị ốm không thể lên lớp được nhé!', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct19_3', 'lesson-19', NULL, 'comprehensive_test', 'listening', '昨天天气太冷我好像得了感冒', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Chủ nhật chúng ta đi dạo phố và ăn lẩu nhé!","Xin hỏi quanh đây có nhà ăn không ạ?","Hôm qua trời lạnh quá, hình như tôi bị cảm cúm rồi.","Đúng vậy. Vạn Lý Trường Thành vô cùng hùng vĩ tráng lệ, là biểu tượng lịch sử và văn hóa của người Trung Quốc."]'::jsonb, 2, 'Nội dung nghe được: “昨天天气太冷我好像得了感冒” (Zuótiān tiānqì tài lěng, wǒ hǎoxiàng dé le gǎnmào.) → Hôm qua trời lạnh quá, hình như tôi bị cảm cúm rồi.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct19_4', 'lesson-19', NULL, 'comprehensive_test', 'listening', '我们下午去吧！', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["马克，去年暑假你去北京旅游去了哪些景点？","好的，我们去结账吧！","小兰！你跟我一起去超市买衣服，好吗？","我们下午去吧！"]'::jsonb, 3, 'Câu vừa đọc: “我们下午去吧！” (Wǒmen xiàwǔ qù ba!) → Buổi chiều chúng ta đi nhé!', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct19_5', 'lesson-19', NULL, 'comprehensive_test', 'listening', '小兰，你脸色不太好，是不是感冒发烧了？', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Hội nghị này, cậu đi hay Minh đi?","Đi như thế nào vậy?","Tiểu Lan, sắc mặt cậu không tốt lắm, có phải bị cảm sốt rồi không?","Chúng tôi dán câu đối và đốt pháo trước nhà để mừng năm mới."]'::jsonb, 2, 'Nội dung nghe được: “小兰，你脸色不太好，是不是感冒发烧了？” (Xiǎolán, nǐ liǎnsè bú tài hǎo, shì bu shì gǎnmào fāshāo le?) → Tiểu Lan, sắc mặt cậu không tốt lắm, có phải bị cảm sốt rồi không?', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct19_6', 'lesson-19', NULL, 'comprehensive_test', 'listening', '她会说汉语。', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["马克，你明天要上课吗？","你喜欢学汉语还是英语？","食堂在教学楼旁边。","她会说汉语。"]'::jsonb, 3, 'Câu vừa đọc: “她会说汉语。” (Tā huì shuō Hànyǔ.) → Cô ấy biết nói tiếng Trung.', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct19_7', 'lesson-19', NULL, 'comprehensive_test', 'listening', '太谢谢你了，喝完粥吃药我一定会很快恢复！', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Nếu chăm chỉ học hành thì bạn sẽ có thể thi đỗ đại học.","Cảm ơn cậu nhiều lắm, ăn cháo uống thuốc xong tớ nhất định sẽ mau khỏi!","chiếc cặp này","Anh ấy đang ăn cơm kìa."]'::jsonb, 1, 'Nội dung nghe được: “太谢谢你了，喝完粥吃药我一定会很快恢复！” (Tài xièxie nǐ le, hēwán zhōu chī yào wǒ yídìng huì hěn kuài huīfù!) → Cảm ơn cậu nhiều lắm, ăn cháo uống thuốc xong tớ nhất định sẽ mau khỏi!', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
