INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_20_2_4', 'txt_20_2', 'Bài 20', '你是不是累了？多休息吧！', '你是不是累了？多休息吧！', 'Nǐ shì bu shì lèi le? Duō xiūxi ba!', 'Bạn mệt à? Nghỉ ngơi thêm chút đi!', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_20_2_5', 'txt_20_2', 'Ôn Bài 1', '老师们', '老师们', 'lǎoshīmen', 'Các thầy cô giáo', 5) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_20_2_6', 'txt_20_2', 'Bài 20', '明天我想去图书馆看书。', '明天我想去图书馆看书。', 'Míngtiān wǒ xiǎng qù túshū guǎn kànshū.', 'Ngày mai tôi muốn đi thư viện đọc sách.', 6) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_20_2_7', 'txt_20_2', 'Ôn Bài 18', '她会说汉语。', '她会说汉语。', 'Tā huì shuō Hànyǔ.', 'Cô ấy biết nói tiếng Trung.', 7) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_20_2_8', 'txt_20_2', 'Bài 20', '你好认真啊！', '你好认真啊！', 'Nǐ hǎo rènzhēn a!', 'Cậu chăm chỉ thật đấy!', 8) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_20_2_1', 'lesson-20', 'txt_20_2', 'listening', 'listening', '今天会下雨吧。', NULL, '[Ôn tập Bài 19] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Cậu nói gì vậy?","tóc dài (mang sự dễ thương)","Hôm nay chắc sẽ mưa đấy nhỉ.","Không phải hôm qua chúng ta đã gặp nhau rồi sao? (Khẳng định hôm"]'::jsonb, 2, 'Nội dung nghe được: 今天会下雨吧。 (Jīntiān huì xià yǔ ba.) → Hôm nay chắc sẽ mưa đấy nhỉ.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_20_2_2', 'lesson-20', 'txt_20_2', 'listening', 'listening', '你得多锻炼了。', NULL, '[Bài 20] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["天 (tiān: ngày, trời)可能要下雨。","坚持运动可以帮助我们预防很多疾病。","你得多锻炼了。","你每天 (tiān: ngày, trời)几点起床去学 (xué: học)武术？"]'::jsonb, 2, 'Câu vừa đọc: 你得多锻炼了。 (Nǐ děi duō duànliàn le.) → Bạn cần phải luyện tập nhiều hơn nữa.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_20_2_3', 'lesson-20', 'txt_20_2', 'listening', 'listening', '天气太舒服了！', NULL, '[Ôn tập Bài 10] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Thời tiết dễ chịu quá!","Cậu có biết chữ này viết như thế nào không?","Tháng sau anh ấy mới về nước.","Tớ biết bơi, còn biết trượt băng."]'::jsonb, 0, 'Nội dung nghe được: 天气太舒服了！ (Tiānqì tài shūfu le!) → Thời tiết dễ chịu quá!', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_20_2_4', 'lesson-20', 'txt_20_2', 'listening', 'listening', '你是不是累了？多休息吧！', NULL, '[Bài 20] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["是。我每天 (tiān: ngày, trời)早上六点都起来 (qǐlái: lên (bổ ngữ))跑步。","你是不是累了？多休息吧！","中 (zhōng: giữa / trong)学生不可以抽烟 (chōuyān: hút thuốc)。","她会中文 (Zhōngwén: tiếng Trung)。"]'::jsonb, 1, 'Câu vừa đọc: 你是不是累了？多休息吧！ (Nǐ shì bu shì lèi le? Duō xiūxi ba!) → Bạn mệt à? Nghỉ ngơi thêm chút đi!', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_20_2_5', 'lesson-20', 'txt_20_2', 'listening', 'listening', '老师们', NULL, '[Ôn tập Bài 1] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Các thầy cô giáo","Anh ấy đã về nước từ tuần trước rồi.","Hiệu sách ở bên phải rất lớn.","Cậu mua mấy quả dưa hấu thế?"]'::jsonb, 0, 'Nội dung nghe được: 老师们 (lǎoshīmen) → Các thầy cô giáo', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_20_3', 'lesson-20', 'Bài khoá mở rộng: Thói quen rèn luyện thể thao (Mở rộng)', 'Hội thoại tình huống mới xây dựng dựa trên từ vựng và ngữ pháp Bài 20 (không trùng lặp nguyên văn giáo trình).', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_20_3_1', 'txt_20_3', 'Mark', '阿明，你每天几点起床锻炼身体？', '阿明 (Āmíng: A Minh)，你每天 (tiān: ngày, trời)几点起床锻炼身体？', 'Āmíng, nǐ měitiān jǐ diǎn qǐchuáng duànliàn shēntǐ?', 'A Minh, mỗi ngày mấy giờ cậu thức dậy rèn luyện sức khỏe?', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_20_3_2', 'txt_20_3', 'A Minh', '我每天早上六点起床去公园跑步，下午去体育馆打篮球或武术。', '我每天 (tiān: ngày, trời)早上六点起床去公园跑步，下午去体育馆打 (dǎ: đánh, gọi, chơi)篮球或武术。', 'Wǒ měitiān zǎoshang liù diǎn qǐchuáng qù gōngyuán pǎobù, xiàwǔ qù tǐyùguǎn dǎ lánqiú huò wǔshù.', 'Sáng nào 6 giờ mình cũng dậy ra công viên chạy bộ, chiều đến nhà thi đấu chơi bóng rổ hoặc tập võ.', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_20_3_3', 'txt_20_3', 'Mark', '坚持运动真的有很多好处吗？', '坚持运动真的有很多好处吗？', 'Jiānchí yùndòng zhēn de yǒu hěnduō hǎochu ma?', 'Kiên trì vận động thực sự có nhiều lợi ích vậy sao?', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_20_3_4', 'txt_20_3', 'A Minh', '当然，不仅让人精神好，还能预防疾病呢！', '当然，不仅让 (ràng: bảo, khiến)人精神好，还能预防疾病呢！', 'Dāngrán, bùjǐn ràng rén jīngshen hǎo, hái néng yùfáng jíbìng ne!', 'Tất nhiên rồi, không chỉ giúp tinh thần minh mẫn mà còn phòng ngừa bệnh tật nữa đấy!', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_20_3_1', 'lesson-20', 'txt_20_3', 'listening', 'listening', '阿明，你每天几点起床锻炼身体？ 我每天早上六点起床去公园跑步，下午去体育馆打篮球或武术。 坚持运动真的有很多好处吗？ 当然，不仅让人精神好，还能预防疾病呢！', NULL, '[Nghe hiểu tình huống mới] Theo A Minh, buổi sáng cậu ấy tập môn thể thao gì và ở đâu?', '["Ngủ nướng đến trưa","Đá bóng trên sân thượng","Chạy bộ ở công viên lúc 6 giờ sáng","Chơi tennis trong ký túc xá"]'::jsonb, 2, 'A Minh trả lời ''每天早上六点起床去公园跑步''.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_20_3_2', 'lesson-20', 'txt_20_3', 'listening', 'listening', '阿明，你每天几点起床锻炼身体？', NULL, '[Mở rộng] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Một cái ghế","Tôi đợi các bạn ở cổng trường.","A Minh, mỗi ngày mấy giờ cậu thức dậy rèn luyện sức khỏe?","Tôi vừa nghe nhạc vừa đọc sách."]'::jsonb, 2, 'Nội dung nghe được: 阿明，你每天几点起床锻炼身体？ (Āmíng, nǐ měitiān jǐ diǎn qǐchuáng duànliàn shēntǐ?) → A Minh, mỗi ngày mấy giờ cậu thức dậy rèn luyện sức khỏe?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_20_3_3', 'lesson-20', 'txt_20_3', 'listening', 'listening', '我每天早上六点起床去公园跑步，下午去体育馆打篮球或武术。', NULL, '[Mở rộng] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["你得多锻炼了。","我喜欢在公园一边 (biān: bên, phía)锻炼一边享受新鲜空气。","我每天 (tiān: ngày, trời)早上六点起床去公园跑步，下午去体育馆打 (dǎ: đánh, gọi, chơi)篮球或武术。","妈妈，做完 (zuòwán: làm xong)作业以后 (yǐhòu: sau, lúc sau)，我可以看电影吗？"]'::jsonb, 2, 'Câu vừa đọc: 我每天早上六点起床去公园跑步，下午去体育馆打篮球或武术。 (Wǒ měitiān zǎoshang liù diǎn qǐchuáng qù gōngyuán pǎobù, xiàwǔ qù tǐyùguǎn dǎ lánqiú huò wǔshù.) → Sáng nào 6 giờ mình cũng dậy ra công viên chạy bộ, chiều đến nhà thi đấu chơi bóng rổ hoặc tập võ.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_20_3_4', 'lesson-20', 'txt_20_3', 'listening', 'listening', '坚持运动真的有很多好处吗？', NULL, '[Mở rộng] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Kiên trì vận động thực sự có nhiều lợi ích vậy sao?","Tôi không biết người này là nam hay là nữ nữa.","Hình như tớ quen người này.","Anh ta không cho tôi đi."]'::jsonb, 0, 'Nội dung nghe được: 坚持运动真的有很多好处吗？ (Jiānchí yùndòng zhēn de yǒu hěnduō hǎochu ma?) → Kiên trì vận động thực sự có nhiều lợi ích vậy sao?', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss20_1', 'lesson-20', '下午我去体育馆打篮球和打网球', '[Mở rộng] Buổi chiều tôi đến nhà thi đấu chơi bóng rổ và đánh tennis.', 'Xiàwǔ wǒ qù tǐyùguǎn dǎ lánqiú hé dǎ wǎngqiú.', '["下午","我去","体育馆","打篮球","和打","网球"]'::jsonb, 'Từ chưa học: 打 (dǎ: đánh, gọi, chơi)', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss20_2', 'lesson-20', '你每天几点起床去学武术', '[Mở rộng] Mỗi ngày mấy giờ bạn thức dậy đi học võ thuật?', 'Nǐ měitiān jǐ diǎn qǐchuáng qù xué wǔshù?', '["你每","天几","点","起床","去学","武术"]'::jsonb, 'Từ chưa học: 天 (tiān: ngày, trời), 学 (xué: học)', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
