INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss20_5', 'lesson-20', '谢谢你经常在学习上帮助我', '[Ôn tập Bài 16] Cảm ơn bạn thường xuyên giúp đỡ tôi trong việc học.', 'Xièxie nǐ jīngcháng zài xuéxí shàng bāngzhù wǒ.', '["谢谢你","经常在","学习","上","帮助","我"]'::jsonb, 'Từ chưa học: 上 (shàng: trên / lên), 学习 (xuéxí: học tập)', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss20_6', 'lesson-20', '我喜欢一边喝水一边听音乐', '[Ôn tập Bài 12] Tôi thích vừa uống nước vừa nghe nhạc.', 'Wǒ xǐhuan yìbiān hē shuǐ yìbiān tīng yīnyuè.', '["我","喜欢","一边","喝水","一边","听音乐"]'::jsonb, 'Từ chưa học: 边 (biān: bên, phía)', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr20_vi_1', 'lesson-20', 'vi_to_zh', '[Mở rộng] Kiên trì vận động có thể giúp chúng ta phòng ngừa nhiều bệnh tật.', NULL, NULL, '坚持运动可以帮助我们预防很多疾病。', NULL, 'jiānchí yùndòng kěyǐ bāngzhù wǒmen yùfáng hěnduō jíbìng', '[]'::jsonb, 'Gợi ý Pinyin: Jiānchí yùndòng kěyǐ bāngzhù wǒmen yùfáng hěnduō jíbìng.', 'Kiên trì vận động có thể giúp chúng ta phòng ngừa nhiều bệnh tật. → 坚持运动可以帮助我们预防很多疾病。 (Jiānchí yùndòng kěyǐ bāngzhù wǒmen yùfáng hěnduō jíbìng.)', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
