INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr20_vi_4', 'lesson-20', 'vi_to_zh', 'Bạn mệt à? Nghỉ ngơi thêm chút đi!', NULL, NULL, '你是不是累了？多休息吧！', NULL, 'nǐ shì bu shì lèi le duō xiūxi ba', '[]'::jsonb, 'Gợi ý Pinyin: Nǐ shì bu shì lèi le? Duō xiūxi ba!', 'Bạn mệt à? Nghỉ ngơi thêm chút đi! → 你是不是累了？多休息吧！ (Nǐ shì bu shì lèi le? Duō xiūxi ba!)', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr20_zh_1', 'lesson-20', 'zh_to_vi', '[Mở rộng] 我喜欢在公园一边 (biān: bên, phía)锻炼一边享受新鲜空气。', '我喜欢在公园一边锻炼一边享受新鲜空气。', 'Wǒ xǐhuan zài gōngyuán yìbiān duànliàn yìbiān xiǎngshòu xīnxiān kōngqì.', NULL, 'Tôi thích vừa tập thể dục vừa hít thở không khí trong lành ở công viên.', NULL, '["Tôi","thích","vừa"]'::jsonb, 'Pinyin: Wǒ xǐhuan zài gōngyuán yìbiān duànliàn yìbiān xiǎngshòu xīnxiān kōngqì.', '我喜欢在公园一边锻炼一边享受新鲜空气。 (Wǒ xǐhuan zài gōngyuán yìbiān duànliàn yìbiān xiǎngshòu xīnxiān kōngqì.) nghĩa là: Tôi thích vừa tập thể dục vừa hít thở không khí trong lành ở công viên.', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
