INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq20_13', 'lesson-20', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “身体” chứa bộ thủ nào sau đây?', '["Bộ cấu tạo [空] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [可] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","身 (Thân) (Thân thể, vóc dáng)","Bộ cấu tạo [坚] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)"]'::jsonb, 2, 'Chữ “身体” có 身 (Thân) (Thân thể, vóc dáng). Ghép từ các chữ Hán: [身] + [体].', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq20_14', 'lesson-20', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “疾病” chứa bộ thủ nào sau đây?', '["Bộ cấu tạo [跑] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [疾] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","身 (Thân) (Thân thể, vóc dáng)","大 (Đại) (To lớn, vĩ đại)"]'::jsonb, 1, 'Chữ “疾病” có Bộ cấu tạo [疾] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán). Ghép từ các chữ Hán: [疾] + [病].', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq20_15', 'lesson-20', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “空气” chứa bộ thủ nào sau đây?', '["大 (Đại) (To lớn, vĩ đại)","Bộ cấu tạo [空] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","木 (Mộc) (Cây cối, gỗ)","小 (Tiểu) (Nhỏ bé, ít ỏi)"]'::jsonb, 1, 'Chữ “空气” có Bộ cấu tạo [空] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán). Ghép từ các chữ Hán: [空] + [气].', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
