INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq20_17', 'lesson-20', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 19] Từ đã học “要紧” (yàojǐn) có nghĩa là gì?', '["cái (lượng từ dùng cho cái mũ)","hầu hết, xấp xỉ","nghiêm trọng","là, thì..."]'::jsonb, 2, 'Ôn tập Bài 19: “要紧” (yàojǐn) nghĩa là: nghiêm trọng.', 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
