INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq20_19', 'lesson-20', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 3] Từ đã học “美国” (Měiguó) có nghĩa là gì?', '["Mỹ","nào, đâu","bữa cơm tất niên","chủ nhật"]'::jsonb, 0, 'Ôn tập Bài 3: “美国” (Měiguó) nghĩa là: Mỹ.', 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq20_20', 'lesson-20', NULL, 'expanded_quiz', 'reading', NULL, NULL, '[Mở rộng] Câu “坚持运动可以帮助我们预防很多疾病。” có nghĩa tiếng Việt là gì?', '["Kiên trì vận động có thể giúp chúng ta phòng ngừa nhiều bệnh tật.","Trời có thể sắp mưa.","Bữa sáng cậu ấy có thể ăn 10 cái bánh bao.","Cậu có thể rót cho tớ cốc nước không?"]'::jsonb, 0, '坚持运动可以帮助我们预防很多疾病。 (Jiānchí yùndòng kěyǐ bāngzhù wǒmen yùfáng hěnduō jíbìng.) → Kiên trì vận động có thể giúp chúng ta phòng ngừa nhiều bệnh tật.', 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq20_21', 'lesson-20', NULL, 'expanded_quiz', 'reading', NULL, NULL, '[Đọc hiểu mở rộng] Đọc đoạn hội thoại:
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq20_22', 'lesson-20', NULL, 'expanded_quiz', 'reading', NULL, NULL, 'Câu “你得多锻炼了。” có nghĩa tiếng Việt là gì?', '["Mai tớ thi rồi, không thể đi cùng cậu được.","Mẹ ơi, sau khi làm xong bài tập về nhà con có thể xem phim không ạ?","Bữa sáng cậu ấy có thể ăn 10 cái bánh bao.","Bạn cần phải luyện tập nhiều hơn nữa."]'::jsonb, 3, '你得多锻炼了。 (Nǐ děi duō duànliàn le.) → Bạn cần phải luyện tập nhiều hơn nữa.', 22) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct20_1', 'lesson-20', NULL, 'comprehensive_test', 'listening', '她会说汉语。', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Cô ấy biết nói tiếng Trung.","Con người anh ta thật là tốt!","Ghen tị với bạn quá đi! Kỳ nghỉ hè năm nay tôi cũng sẽ đi du lịch Bắc Kinh.","9 giờ 30 sáng tôi có một tiết tiếng Hán, 11 giờ rưỡi đi nhà ăn."]'::jsonb, 0, 'Nội dung nghe được: “她会说汉语。” (Tā huì shuō Hànyǔ.) → Cô ấy biết nói tiếng Trung.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct20_2', 'lesson-20', NULL, 'comprehensive_test', 'listening', '我会打羽毛球。', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["老师您好！","是谁的生日礼物？","我会打羽毛球。","这件大衣的颜色我很喜欢"]'::jsonb, 2, 'Câu vừa đọc: “我会打羽毛球。” (Wǒ huì dǎ yǔmáoqiú.) → Tôi biết đánh cầu lông.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct20_3', 'lesson-20', NULL, 'comprehensive_test', 'listening', '你好认真啊！', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Bây giờ tôi phải vào lớp học rồi.","5 giờ rưỡi! Bạn muốn mượn sách à?","Cậu chăm chỉ thật đấy!","Một quả 7 tệ."]'::jsonb, 2, 'Nội dung nghe được: “你好认真啊！” (Nǐ hǎo rènzhēn a!) → Cậu chăm chỉ thật đấy!', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct20_4', 'lesson-20', NULL, 'comprehensive_test', 'listening', '每天早上跑步半个小时对身体有很多好处。', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["每天早上跑步半个小时对身体有很多好处。","我的头很疼，不能上课。","教室里有三个人。","如果你有困难，我就帮助你。"]'::jsonb, 0, 'Câu vừa đọc: “每天早上跑步半个小时对身体有很多好处。” → Sáng nào cũng chạy bộ nửa tiếng rất tốt cho sức khỏe.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct20_5', 'lesson-20', NULL, 'comprehensive_test', 'listening', '我喜欢一边喝水一边听音乐', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Người đó là thầy Vương.","Tôi thích vừa uống nước vừa nghe nhạc.","Bố tớ cũng rất thích đọc sách, lúc rảnh rỗi ông thường kể chuyện cho tớ và em trai nghe. Em trai cậu thích gì?","cây thước kẻ của anh ấy"]'::jsonb, 1, 'Nội dung nghe được: “我喜欢一边喝水一边听音乐” (Wǒ xǐhuan yìbiān hē shuǐ yìbiān tīng yīnyuè.) → Tôi thích vừa uống nước vừa nghe nhạc.', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct20_6', 'lesson-20', NULL, 'comprehensive_test', 'listening', '早点儿睡吧，明天还要早点儿起床呢！', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["他这个人真好！","明天我想去图书馆看书。","爸爸热情地接待了我的同学","早点儿睡吧，明天还要早点儿起床呢！"]'::jsonb, 3, 'Câu vừa đọc: “早点儿睡吧，明天还要早点儿起床呢！” (Zǎodiǎnr shuì ba, míngtiān hái yào zǎodiǎnr qǐchuáng ne!) → Ngủ sớm đi, ngày mai còn phải dậy sớm nữa.', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct20_7', 'lesson-20', NULL, 'comprehensive_test', 'listening', '好啊！', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Không phải bạn nói năm nay sẽ đi du lịch Nhật Bản sao?","Được chứ!","Đợi một chút.","Nếu chăm chỉ học hành thì bạn sẽ có thể thi đỗ đại học."]'::jsonb, 1, 'Nội dung nghe được: “好啊！” (Hǎo a!) → Được chứ!', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct20_8', 'lesson-20', NULL, 'comprehensive_test', 'listening', '谢谢你经常在学习上帮助我', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["我妹妹的。","谢谢你经常在学习上帮助我","然后呢？","打游戏、听音乐、聊天儿、喝 水、吃东西。到十点半我们才回宿舍。现在回想起来，昨天真快乐，真热闹。"]'::jsonb, 1, 'Câu vừa đọc: “谢谢你经常在学习上帮助我” (Xièxie nǐ jīngcháng zài xuéxí shàng bāngzhù wǒ.) → Cảm ơn bạn thường xuyên giúp đỡ tôi trong việc học.', 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
