INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v21_1', 'lesson-21', '医院', 'yīyuàn', 'y viện', 'bệnh viện', 'Danh từ', 'Bộ cấu tạo [医] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [医] + [院].', 'Kết hợp các thành tố [医] + [院] để tạo thành từ mang nghĩa ''bệnh viện''.', '马克，我下午想去医院检查身体， 你可以陪我去吗？', 'Mǎkè, wǒ xiàwǔ xiǎng qù yīyuàn jiǎnchá shēntǐ, nǐ kěyǐ péi wǒ qù ma?', 'Mark, chiều nay tôi muốn đi bệnh viện kiểm tra sức khỏe, bạn đi cùng tôi được không?', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v21_2', 'lesson-21', '医生', 'yīshēng', 'y sinh', 'bác sĩ', 'Danh từ', 'Bộ cấu tạo [医] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [医] + [生].', 'Kết hợp các thành tố [医] + [生] để tạo thành từ mang nghĩa ''bác sĩ''.', '那现在怎么治病呢, 医生？', 'Nà xiànzài zěnme zhì bìng ne, yīshēng?', 'Vậy bây giờ điều trị thế nào ạ, thưa bác sĩ?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v21_3', 'lesson-21', '护士', 'hùshi', 'từ Hán ngữ', 'y tá, hộ sĩ', 'Danh từ', 'Bộ cấu tạo [护] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [护] + [士].', 'Kết hợp các thành tố [护] + [士] để tạo thành từ mang nghĩa ''y tá, hộ sĩ''.', '其实没有什么要紧的。 我让护士给你打个针并开给你一个处方，你回家吃完饭再吃药和多喝水，过几天身体就恢复了。', 'Qíshí méiyǒu shénme yàojǐn de. Wǒ ràng hùshì gěi nǐ dǎ gè zhēn bìng kāi gěi nǐ yí gè chǔfāng, nǐ huí jiā chī wán fàn zài chī yào hé duō hē shuǐ, guò jǐ tiān shēntǐ jiù huīfù le.', 'Thực ra không có gì nghiêm trọng đâu. Tôi bảo y tá tiêm cho bạn một mũi và kê đơn thuốc, bạn về nhà ăn cơm xong uống thuốc và uống nhiều nước, vài ngày sau sức khỏe sẽ hồi phục thôi.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v21_4', 'lesson-21', '病人', 'bìngrén', 'bệnh nhân', 'bệnh nhân', 'Danh từ', '人 (Nhân) (Con người, nhân loại)', 'Ghép từ các chữ Hán: [病] + [人].', 'Kết hợp các thành tố [病] + [人] để tạo thành từ mang nghĩa ''bệnh nhân''.', '大多数病人都买医疗保险，它很重要，你应该买一个!', 'Dàduōshù bìngrén dōu mǎi yīliáo bǎoxiǎn, tā hěn zhòngyào, nǐ yīnggāi mǎi yígè!', 'Đa số bệnh nhân đều mua bảo hiểm y tế, nó rất quan trọng, bạn nên mua một cái nhé!', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v21_5', 'lesson-21', '医疗保险', 'yīliáo bǎoxiǎn', 'y', 'bảo hiểm y tế', 'Danh từ', 'Bộ cấu tạo [医] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [医] + [疗] + [保] + [险].', 'Kết hợp các thành tố [医] + [疗] + [保] + [险] để tạo thành từ mang nghĩa ''bảo hiểm y tế''.', '对了，你有没有医疗保险？如果有的话就可以减少检查费用。', 'Duì le, nǐ yǒu méiyǒu yīliáo bǎoxiǎn? Rúguǒ yǒu de huà jiù kěyǐ jiǎnshǎo jiǎnchá fèiyòng.', 'À đúng rồi, bạn có bảo hiểm y tế không? Nếu có thì có thể giảm bớt chi phí khám bệnh đấy.', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v21_6', 'lesson-21', '费用', 'fèiyòng', 'từ Hán ngữ', 'chi phí', 'Danh từ', 'Bộ cấu tạo [费] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [费] + [用].', 'Kết hợp các thành tố [费] + [用] để tạo thành từ mang nghĩa ''chi phí''.', '对了，你有没有医疗保险？如果有的话就可以减少检查费用。', 'Duì le, nǐ yǒu méiyǒu yīliáo bǎoxiǎn? Rúguǒ yǒu de huà jiù kěyǐ jiǎnshǎo jiǎnchá fèiyòng.', 'À đúng rồi, bạn có bảo hiểm y tế không? Nếu có thì có thể giảm bớt chi phí khám bệnh đấy.', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v21_7', 'lesson-21', '胃口', 'wèikǒu', 'khẩu', 'ăn uống, khẩu vị', 'Danh từ', '口 (Khẩu) (Miệng, ăn uống, lời nói, âm thanh phát ra)', 'Ghép từ các chữ Hán: [胃] + [口].', 'Kết hợp các thành tố [胃] + [口] để tạo thành từ mang nghĩa ''ăn uống, khẩu vị''.', '我经常觉得头晕，吃什么都过敏。 最近胃口和睡眠都不好。', 'Wǒ jīngcháng juéde tóuyūn, chī shénme dōu guòmǐn. Zuìjìn wèikǒu hé shuìmián dōu bù hǎo.', 'Tôi hay bị chóng mặt, ăn gì cũng bị dị ứng. Dạo này ăn uống và giấc ngủ đều kém.', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
