INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v21_9', 'lesson-21', '重病', 'zhòngbìng', 'bệnh', 'trọng bệnh, bệnh nặng', 'Danh từ', 'Bộ cấu tạo [重] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [重] + [病].', 'Kết hợp các thành tố [重] + [病] để tạo thành từ mang nghĩa ''trọng bệnh, bệnh nặng''.', '我是不是得了重病？', 'Wǒ shì bu shì dé le zhòngbìng?', 'Có phải tôi mắc bệnh nặng rồi không?', 9) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v21_10', 'lesson-21', '症状', 'zhèngzhuàng', 'từ Hán ngữ', 'triệu chứng', 'Danh từ', 'Bộ cấu tạo [症] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [症] + [状].', 'Kết hợp các thành tố [症] + [状] để tạo thành từ mang nghĩa ''triệu chứng''.', '你有什么症状？', 'Nǐ yǒu shénme zhèngzhuàng?', 'Bạn có triệu chứng gì?', 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v21_11', 'lesson-21', '头晕', 'tóuyūn', 'từ Hán ngữ', 'chóng mặt', 'Tính từ', 'Bộ cấu tạo [头] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [头] + [晕].', 'Kết hợp các thành tố [头] + [晕] để tạo thành từ mang nghĩa ''chóng mặt''.', '我经常觉得头晕，吃什么都过敏。 最近胃口和睡眠都不好。', 'Wǒ jīngcháng juéde tóuyūn, chī shénme dōu guòmǐn. Zuìjìn wèikǒu hé shuìmián dōu bù hǎo.', 'Tôi hay bị chóng mặt, ăn gì cũng bị dị ứng. Dạo này ăn uống và giấc ngủ đều kém.', 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v21_12', 'lesson-21', '过敏', 'guòmǐn', 'từ Hán ngữ', 'dị ứng', 'Động từ', 'Bộ cấu tạo [过] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [过] + [敏].', 'Kết hợp các thành tố [过] + [敏] để tạo thành từ mang nghĩa ''dị ứng''.', '我经常觉得头晕，吃什么都过敏。 最近胃口和睡眠都不好。', 'Wǒ jīngcháng juéde tóuyūn, chī shénme dōu guòmǐn. Zuìjìn wèikǒu hé shuìmián dōu bù hǎo.', 'Tôi hay bị chóng mặt, ăn gì cũng bị dị ứng. Dạo này ăn uống và giấc ngủ đều kém.', 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v21_13', 'lesson-21', '最近', 'zuìjìn', 'từ Hán ngữ', 'gần đây', 'Phó từ', 'Bộ cấu tạo [最] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [最] + [近].', 'Kết hợp các thành tố [最] + [近] để tạo thành từ mang nghĩa ''gần đây''.', '是的，最近觉得身体不太好，所以想去医院看看得了什么病。', 'Shì de, zuìjìn juéde shēntǐ bù tài hǎo, suǒyǐ xiǎng qù yīyuàn kànkan déle shénme bìng.', 'Đúng vậy, dạo này thấy người không khỏe lắm, nên muốn đi bệnh viện khám xem bị bệnh gì.', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v21_14', 'lesson-21', '看病', 'kànbìng', 'khán bệnh', 'khám bệnh', 'Động từ', 'Bộ cấu tạo [看] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [看] + [病].', 'Kết hợp các thành tố [看] + [病] để tạo thành từ mang nghĩa ''khám bệnh''.', '好的。 我陪你去看病。', 'Hǎo de. Wǒ péi nǐ qù kànbìng.', 'Được thôi. Tôi sẽ đi khám bệnh cùng bạn.', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v21_15', 'lesson-21', '检查', 'jiǎnchá', 'tra', 'kiểm tra', 'Động từ', 'Bộ cấu tạo [检] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [检] + [查].', 'Kết hợp các thành tố [检] + [查] để tạo thành từ mang nghĩa ''kiểm tra''.', '马克，我下午想去医院检查身体， 你可以陪我去吗？', 'Mǎkè, wǒ xiàwǔ xiǎng qù yīyuàn jiǎnchá shēntǐ, nǐ kěyǐ péi wǒ qù ma?', 'Mark, chiều nay tôi muốn đi bệnh viện kiểm tra sức khỏe, bạn đi cùng tôi được không?', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v21_16', 'lesson-21', '治病', 'zhìbìng', 'bệnh', 'trị bệnh', 'Động từ', 'Bộ cấu tạo [治] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [治] + [病].', 'Kết hợp các thành tố [治] + [病] để tạo thành từ mang nghĩa ''trị bệnh''.', '那现在怎么治病呢, 医生？', 'Nà xiànzài zěnme zhì bìng ne, yīshēng?', 'Vậy bây giờ điều trị thế nào ạ, thưa bác sĩ?', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v21_17', 'lesson-21', '打针', 'dǎzhēn', 'từ Hán ngữ', 'tiêm', 'Động từ', 'Bộ cấu tạo [打] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [打] + [针].', 'Kết hợp các thành tố [打] + [针] để tạo thành từ mang nghĩa ''tiêm''.', '这是关于“打针”的常用句子。', 'Zhè shì guānyú ''dǎzhēn'' de chángyòng jùzi.', 'Đây là câu ví dụ sử dụng từ ''打针'' (tiêm).', 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v21_18', 'lesson-21', '开处方', 'kāi chǔfāng', 'từ Hán ngữ', 'kê đơn thuốc', 'Động từ', '方 (Phương) (Vuông vức, phương hướng)', 'Ghép từ các chữ Hán: [开] + [处] + [方].', 'Kết hợp các thành tố [开] + [处] + [方] để tạo thành từ mang nghĩa ''kê đơn thuốc''.', '这是关于“开处方”的常用句子。', 'Zhè shì guānyú ''kāi chǔfāng'' de chángyòng jùzi.', 'Đây là câu ví dụ sử dụng từ ''开处方'' (kê đơn thuốc).', 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v21_19', 'lesson-21', '陪', 'péi', 'từ Hán ngữ', 'đi cùng', 'Động từ', 'Bộ cấu tạo [陪] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Chữ độc thể / hình thanh gồm Bộ cấu tạo [陪] và các nét bổ trợ.', 'Ghi nhớ chữ [陪] (đi cùng) qua hình tượng Thành phần biểu ý/biểu âm cơ bản trong chữ Hán.', '马克，我下午想去医院检查身体， 你可以陪我去吗？', 'Mǎkè, wǒ xiàwǔ xiǎng qù yīyuàn jiǎnchá shēntǐ, nǐ kěyǐ péi wǒ qù ma?', 'Mark, chiều nay tôi muốn đi bệnh viện kiểm tra sức khỏe, bạn đi cùng tôi được không?', 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v21_20', 'lesson-21', '减少', 'jiǎnshǎo', 'thiểu', 'giảm', 'Động từ', 'Bộ cấu tạo [减] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [减] + [少].', 'Kết hợp các thành tố [减] + [少] để tạo thành từ mang nghĩa ''giảm''.', '对了，你有没有医疗保险？如果有的话就可以减少检查费用。', 'Duì le, nǐ yǒu méiyǒu yīliáo bǎoxiǎn? Rúguǒ yǒu de huà jiù kěyǐ jiǎnshǎo jiǎnchá fèiyòng.', 'À đúng rồi, bạn có bảo hiểm y tế không? Nếu có thì có thể giảm bớt chi phí khám bệnh đấy.', 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v21_21', 'lesson-21', '明白', 'míngbai', 'minh bạch', 'hiểu', 'Động từ', '白 (Bạch) (Màu trắng, sáng tỏ)', 'Ghép từ các chữ Hán: [明] + [白].', 'Kết hợp các thành tố [明] + [白] để tạo thành từ mang nghĩa ''hiểu''.', '我明白了。 谢谢您！', 'Wǒ míngbai le. Xièxie nín!', 'Tôi hiểu rồi. Cảm ơn ông ạ!', 21) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v21_22', 'lesson-21', '其实', 'qíshí', 'từ Hán ngữ', 'thực ra', 'Phó từ', 'Bộ cấu tạo [其] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [其] + [实].', 'Kết hợp các thành tố [其] + [实] để tạo thành từ mang nghĩa ''thực ra''.', '其实没有什么要紧的。 我让护士给你打个针并开给你一个处方，你回家吃完饭再吃药和多喝水，过几天身体就恢复了。', 'Qíshí méiyǒu shénme yàojǐn de. Wǒ ràng hùshì gěi nǐ dǎ gè zhēn bìng kāi gěi nǐ yí gè chǔfāng, nǐ huí jiā chī wán fàn zài chī yào hé duō hē shuǐ, guò jǐ tiān shēntǐ jiù huīfù le.', 'Thực ra không có gì nghiêm trọng đâu. Tôi bảo y tá tiêm cho bạn một mũi và kê đơn thuốc, bạn về nhà ăn cơm xong uống thuốc và uống nhiều nước, vài ngày sau sức khỏe sẽ hồi phục thôi.', 22) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v21_23', 'lesson-21', '并', 'bìng', 'từ Hán ngữ', 'và', 'Liên từ', 'Bộ cấu tạo [并] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Chữ độc thể / hình thanh gồm Bộ cấu tạo [并] và các nét bổ trợ.', 'Ghi nhớ chữ [并] (và) qua hình tượng Thành phần biểu ý/biểu âm cơ bản trong chữ Hán.', '其实没有什么要紧的。 我让护士给你打个针并开给你一个处方，你回家吃完饭再吃药和多喝水，过几天身体就恢复了。', 'Qíshí méiyǒu shénme yàojǐn de. Wǒ ràng hùshì gěi nǐ dǎ gè zhēn bìng kāi gěi nǐ yí gè chǔfāng, nǐ huí jiā chī wán fàn zài chī yào hé duō hē shuǐ, guò jǐ tiān shēntǐ jiù huīfù le.', 'Thực ra không có gì nghiêm trọng đâu. Tôi bảo y tá tiêm cho bạn một mũi và kê đơn thuốc, bạn về nhà ăn cơm xong uống thuốc và uống nhiều nước, vài ngày sau sức khỏe sẽ hồi phục thôi.', 23) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g21_1', 'lesson-21', '1. 最好', 'Cấu trúc câu ngữ pháp trọng tâm', ' 你最好继续锻炼身体吧！ Nǐ zuì hǎo jìxù duànliàn shēntǐ ba! Tốt nhất bạn nên tiếp tục rèn luyện sức khỏe đi! 最好的办法是什么都不要说，保持安静！ Zuì hǎo de bànfǎ shì shénme dōu búyào shuō, bǎochí ānjìng! Cách tốt nhất đó chính là không nói gì cả và giữ im lặng!', NULL, '[{"hanzi":"你最好继续锻炼身体吧！","pinyin":"Nǐ zuì hǎo jìxù duànliàn shēntǐ ba!","meaning":"Tốt nhất bạn nên tiếp tục rèn luyện sức khỏe đi!"},{"hanzi":"最好的办法是什么都不要说，保持安静！","pinyin":"Zuì hǎo de bànfǎ shì shénme dōu búyào shuō, bǎochí ānjìng!","meaning":"Cách tốt nhất đó chính là không nói gì cả và giữ im lặng!"}]'::jsonb, 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g21_2', 'lesson-21', '2. 吧', 'Cấu trúc câu ngữ pháp trọng tâm', ' 你这么努力，肯定很累吧？ Nǐ zhème nǔlì, kěndìng hěn lèi ba? Bạn cố gắng như vậy, nhất định rất mệt nhỉ? 他可能同意了吧？ Tā kěnéng tóngyì le ba? Hẳn là anh ấy đồng ý rồi?', NULL, '[{"hanzi":"你这么努力，肯定很累吧？","pinyin":"Nǐ zhème nǔlì, kěndìng hěn lèi ba?","meaning":"Bạn cố gắng như vậy, nhất định rất mệt nhỉ?"},{"hanzi":"他可能同意了吧？","pinyin":"Tā kěnéng tóngyì le ba?","meaning":"Hẳn là anh ấy đồng ý rồi?"}]'::jsonb, 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g21_3', 'lesson-21', '3. 多 + Động  từ', 'Cấu trúc câu ngữ pháp trọng tâm', ' 你多吃点儿蔬菜吧，对身体有好处！ Nǐ duō chī diǎnr shūcài ba, duì shēntǐ yǒu hǎochù! Con ăn nhiều rau chút, có lợi cho sức khỏe! 你多运动运动吧！ Nǐ duō yùndòng yùndòng ba! Con vận động nhiều hơn đi!', NULL, '[{"hanzi":"你多吃点儿蔬菜吧，对身体有好处！","pinyin":"Nǐ duō chī diǎnr shūcài ba, duì shēntǐ yǒu hǎochù!","meaning":"Con ăn nhiều rau chút, có lợi cho sức khỏe!"},{"hanzi":"你多运动运动吧！","pinyin":"Nǐ duō yùndòng yùndòng ba!","meaning":"Con vận động nhiều hơn đi!"}]'::jsonb, 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g21_4', 'lesson-21', '4. Động từ năng nguyện', 'Cấu trúc câu ngữ pháp trọng tâm', ' 我会游泳，也会滑冰。 Wǒ huì yóuyǒng, yě huì huábīng. Tớ biết bơi, còn biết trượt băng. 你能给我倒杯水吗？ Nǐ néng gěi wǒ dào bēi shuǐ ma? Cậu có thể rót cho tớ cốc nước không? 可能快要下雪了！ Kěnéng kuàiyào xià xuě le! Có lẽ sắp có tuyết rơi rồi! 我想去公园跑步。 Wǒ xiǎng qù gōngyuá', NULL, '[{"hanzi":"我会游泳，也会滑冰。","pinyin":"Wǒ huì yóuyǒng, yě huì huábīng.","meaning":"Tớ biết bơi, còn biết trượt băng."},{"hanzi":"你能给我倒杯水吗？","pinyin":"Nǐ néng gěi wǒ dào bēi shuǐ ma?","meaning":"Cậu có thể rót cho tớ cốc nước không?"}]'::jsonb, 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_21_1', 'lesson-21', 'Bài khoá #1: Hội thoại giáo trình — Kiểm tra sức khoẻ', 'Hội thoại chuẩn giáo trình Bài 21. Từ vựng chưa học được chú thích phiên âm & nghĩa trong ngoặc.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_21_1_1', 'txt_21_1', '白茹雪', '马克，我下午想去医院检查身体， 你可以陪我去吗？', '马克，我下午想去医院检查身体， 你可以陪我去吗？', 'Mǎkè, wǒ xiàwǔ xiǎng qù yīyuàn jiǎnchá shēntǐ, nǐ kěyǐ péi wǒ qù ma?', 'Mark, chiều nay tôi muốn đi bệnh viện kiểm tra sức khỏe, bạn đi cùng tôi được không?', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_21_1_2', 'txt_21_1', '马克', '你怎么了? 身体不好吗？', '你怎么了? 身体不好吗？', 'Nǐ zěnme le? Shēntǐ bù hǎo ma?', 'Bạn làm sao thế? Trong người không khỏe à?', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_21_1_3', 'txt_21_1', '白茹雪', '是的，最近觉得身体不太好，所以想去医院看看得了什么病。', '是的，最近觉得身体不太好，所以 (suǒyǐ: cho nên)想去医院看看得了什么病 (bìng: bệnh)。', 'Shì de, zuìjìn juéde shēntǐ bù tài hǎo, suǒyǐ xiǎng qù yīyuàn kànkan déle shénme bìng.', 'Đúng vậy, dạo này thấy người không khỏe lắm, nên muốn đi bệnh viện khám xem bị bệnh gì.', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_21_1_4', 'txt_21_1', '马克', '好的。 我陪你去看病。', '好的。 我陪你去看病。', 'Hǎo de. Wǒ péi nǐ qù kànbìng.', 'Được thôi. Tôi sẽ đi khám bệnh cùng bạn.', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_21_1_5', 'txt_21_1', '医生', '你有什么症状？', '你有什么症状？', 'Nǐ yǒu shénme zhèngzhuàng?', 'Bạn có triệu chứng gì?', 5) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_21_1_6', 'txt_21_1', '白茹雪', '我经常觉得头晕，吃什么都过敏。 最近胃口和睡眠都不好。', '我经常觉得头晕，吃什么都过敏。 最近胃口和睡眠都不好。', 'Wǒ jīngcháng juéde tóuyūn, chī shénme dōu guòmǐn. Zuìjìn wèikǒu hé shuìmián dōu bù hǎo.', 'Tôi hay bị chóng mặt, ăn gì cũng bị dị ứng. Dạo này ăn uống và giấc ngủ đều kém.', 6) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_21_1_7', 'txt_21_1', '医生', '好的，我们现在给你检查检查。', '好的，我们现在给你检查检查。', 'Hǎo de，wǒmen xiànzài gěi nǐ jiǎnchá jiǎnchá.', 'Được rồi, bây giờ chúng tôi sẽ kiểm tra cho bạn.', 7) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_21_1_8', 'txt_21_1', '白茹雪', '我是不是得了重病？', '我是不是得了重病？', 'Wǒ shì bu shì dé le zhòngbìng?', 'Có phải tôi mắc bệnh nặng rồi không?', 8) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_21_1_9', 'txt_21_1', '医生', '你学习和工作太累了， 所以才有那样的症状。', '你学习 (xuéxí: học tập)和工作 (gōngzuò: nghề nghiệp, công việc)太累了， 所以 (suǒyǐ: cho nên)才 (cái: mới)有那样 (yàng: kiểu, dáng)的症状。', 'Nǐ xuéxí hé gōngzuò tài lèi le, suǒyǐ cái yǒu nàyàng de zhèngzhuàng.', 'Bạn học tập và làm việc quá mệt mỏi, nên mới xuất hiện những triệu chứng như vậy.', 9) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_21_1_10', 'txt_21_1', '白茹雪', '那现在怎么治病呢, 医生？', '那现在怎么治病呢, 医生？', 'Nà xiànzài zěnme zhì bìng ne, yīshēng?', 'Vậy bây giờ điều trị thế nào ạ, thưa bác sĩ?', 10) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_21_1_11', 'txt_21_1', '医生', '其实没有什么要紧的。 我让护士给你打个针并开给你一个处方，你回家吃完饭再吃药和多喝水，过几天身体就恢复了。', '其实没有 (méiyǒu: không có)什么要紧的。 我让 (ràng: bảo, khiến)护士给你打 (dǎ: đánh, gọi, chơi)个针 (zhēn: kim tiêm)并开 (kāi: mở, lái)给你一个处方 (chǔfāng: đơn thuốc)，你回家吃完 (wán: xong, hết)饭再吃药和多喝水，过 (guò: từng, qua)几天 (tiān: ngày, trời)身体就恢复了。', 'Qíshí méiyǒu shénme yàojǐn de. Wǒ ràng hùshì gěi nǐ dǎ gè zhēn bìng kāi gěi nǐ yí gè chǔfāng, nǐ huí jiā chī wán fàn zài chī yào hé duō hē shuǐ, guò jǐ tiān shēntǐ jiù huīfù le.', 'Thực ra không có gì nghiêm trọng đâu. Tôi bảo y tá tiêm cho bạn một mũi và kê đơn thuốc, bạn về nhà ăn cơm xong uống thuốc và uống nhiều nước, vài ngày sau sức khỏe sẽ hồi phục thôi.', 11) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_21_1_12', 'txt_21_1', '白茹雪', '谢谢医生！', '谢谢医生！', 'Xièxie yīshēng!', 'Cảm ơn bác sĩ ạ!', 12) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_21_1_13', 'txt_21_1', '医生', '对了，你有没有医疗保险？如果有的话就可以减少检查费用。', '对了，你有没有 (méiyǒu: không có)医疗保险？如果有的话 (huà: lời nói)就可以减少检查费用。', 'Duì le, nǐ yǒu méiyǒu yīliáo bǎoxiǎn? Rúguǒ yǒu de huà jiù kěyǐ jiǎnshǎo jiǎnchá fèiyòng.', 'À đúng rồi, bạn có bảo hiểm y tế không? Nếu có thì có thể giảm bớt chi phí khám bệnh đấy.', 13) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_21_1_14', 'txt_21_1', '白茹雪', '我没有医疗保险。', '我没有 (méiyǒu: không có)医疗保险。', 'Wǒ méiyǒu yīliáo bǎoxiǎn.', 'Tôi chưa có bảo hiểm y tế ạ.', 14) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_21_1_15', 'txt_21_1', '医生', '大多数病人都买医疗保险，它很重要，你应该买一个!', '大 (dà: to, lớn)多数病人都买医疗保险，它很重要，你应该买一个!', 'Dàduōshù bìngrén dōu mǎi yīliáo bǎoxiǎn, tā hěn zhòngyào, nǐ yīnggāi mǎi yígè!', 'Đa số bệnh nhân đều mua bảo hiểm y tế, nó rất quan trọng, bạn nên mua một cái nhé!', 15) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_21_1_16', 'txt_21_1', '白茹雪', '我明白了。 谢谢您！', '我明白了。 谢谢您！', 'Wǒ míngbai le. Xièxie nín!', 'Tôi hiểu rồi. Cảm ơn ông ạ!', 16) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_21_1_1', 'lesson-21', 'txt_21_1', 'listening', 'listening', '马克，我下午想去医院检查身体， 你可以陪我去吗？', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Anh ấy không phải giáo viên.","Mark, chiều nay tôi muốn đi bệnh viện kiểm tra sức khỏe, bạn đi cùng tôi được không?","Anh ta lại đến rồi!","Bạn đã làm xong bài tập hôm nay chưa?"]'::jsonb, 1, 'Nội dung nghe được: 马克，我下午想去医院检查身体， 你可以陪我去吗？ (Mǎkè, wǒ xiàwǔ xiǎng qù yīyuàn jiǎnchá shēntǐ, nǐ kěyǐ péi wǒ qù ma?) → Mark, chiều nay tôi muốn đi bệnh viện kiểm tra sức khỏe, bạn đi cùng tôi được không?', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_21_1_2', 'lesson-21', 'txt_21_1', 'listening', 'listening', '你怎么了? 身体不好吗？', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["你怎么了? 身体不好吗？","护士告诉我这只是小毛病 (bìng: bệnh)，不是重病。","你这么努力 (nǔlì: cố gắng, nỗ lực)，肯定 (kěndìng: khẳng định, chắc chắn)很累吧？","是的，最近觉得身体不太好，所以 (suǒyǐ: cho nên)想去医院看看得了什么病 (bìng: bệnh)。"]'::jsonb, 0, 'Câu vừa đọc: 你怎么了? 身体不好吗？ (Nǐ zěnme le? Shēntǐ bù hǎo ma?) → Bạn làm sao thế? Trong người không khỏe à?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_21_1_3', 'lesson-21', 'txt_21_1', 'listening', 'listening', '是的，最近觉得身体不太好，所以想去医院看看得了什么病。', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Tớ định đi xe buýt.","Đúng vậy, dạo này thấy người không khỏe lắm, nên muốn đi bệnh viện khám xem bị bệnh gì.","Bạn cứ đi thẳng, sau đó rẽ phải là sẽ nhìn thấy bệnh viện ở bên trái của","Bạn mệt à? Nghỉ ngơi thêm chút đi!"]'::jsonb, 1, 'Nội dung nghe được: 是的，最近觉得身体不太好，所以想去医院看看得了什么病。 (Shì de, zuìjìn juéde shēntǐ bù tài hǎo, suǒyǐ xiǎng qù yīyuàn kànkan déle shénme bìng.) → Đúng vậy, dạo này thấy người không khỏe lắm, nên muốn đi bệnh viện khám xem bị bệnh gì.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_21_1_4', 'lesson-21', 'txt_21_1', 'listening', 'listening', '好的。 我陪你去看病。', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["病人对这种水果有点儿过敏。","我下午陪奶奶去医院看病。","医生仔细检查了我的身体和症状。","好的。 我陪你去看病。"]'::jsonb, 3, 'Câu vừa đọc: 好的。 我陪你去看病。 (Hǎo de. Wǒ péi nǐ qù kànbìng.) → Được thôi. Tôi sẽ đi khám bệnh cùng bạn.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_21_2', 'lesson-21', 'Bài nghe tổng hợp: Ôn tập lũy tiến (Bài 1 – Bài 21)', 'Kết hợp từ vựng & mẫu câu đã học từ Bài 1 đến Bài 20 cùng trọng tâm Bài 21 để củng cố phản xạ nghe.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_21_2_1', 'txt_21_2', 'Ôn Bài 20', '明天我想去图书馆看书。', '明天我想去图书馆看书。', 'Míngtiān wǒ xiǎng qù túshū guǎn kànshū.', 'Ngày mai tôi muốn đi thư viện đọc sách.', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_21_2_2', 'txt_21_2', 'Bài 21', '你多运动运动吧！', '你多运动运动吧！', 'Nǐ duō yùndòng yùndòng ba!', 'Con vận động nhiều hơn đi!', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_21_2_3', 'txt_21_2', 'Ôn Bài 10', '这本书是我的。', '这本书是我的。', 'Zhè běn shū shì wǒ de.', 'Quyển sách này là sách của tôi.', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_21_2_4', 'txt_21_2', 'Bài 21', '我会游泳，也会滑冰。', '我会游泳，也会滑冰。', 'Wǒ huì yóuyǒng, yě huì huábīng.', 'Tớ biết bơi, còn biết trượt băng.', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_21_2_5', 'txt_21_2', 'Ôn Bài 1', '老师好', '老师好', 'Lǎoshī hǎo', 'Chào thầy/Chào cô', 5) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_21_2_6', 'txt_21_2', 'Bài 21', '可能快要下雪了！', '可能快要下雪了！', 'Kěnéng kuàiyào xià xuě le!', 'Có lẽ sắp có tuyết rơi rồi!', 6) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_21_2_7', 'txt_21_2', 'Ôn Bài 18', '你知道他在哪儿吗？', '你知道他在哪儿吗？', 'Nǐ zhīdào tā zài nǎr ma?', 'Bạn biết anh ấy ở đâu không?', 7) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_21_2_8', 'txt_21_2', 'Bài 21', '我想去公园跑步。', '我想去公园跑步。', 'Wǒ xiǎng qù gōngyuán pǎobù.', 'Tớ muốn đến công viên chạy bộ.', 8) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_21_2_1', 'lesson-21', 'txt_21_2', 'listening', 'listening', '明天我想去图书馆看书。', NULL, '[Ôn tập Bài 20] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Mẹ bảo tôi ăn cơm xong thì giúp mẹ quét dọn nhà cửa.","chi phí sinh hoạt","Tôi có thể làm tốt việc này","Ngày mai tôi muốn đi thư viện đọc sách."]'::jsonb, 3, 'Nội dung nghe được: 明天我想去图书馆看书。 (Míngtiān wǒ xiǎng qù túshū guǎn kànshū.) → Ngày mai tôi muốn đi thư viện đọc sách.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_21_2_2', 'lesson-21', 'txt_21_2', 'listening', 'listening', '你多运动运动吧！', NULL, '[Bài 21] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["你多运动运动吧！","如果有医疗保险，看病费用可以减少很多。","他可能同意 (tóngyì: đồng ý)了吧？","我想去公园跑步。"]'::jsonb, 0, 'Câu vừa đọc: 你多运动运动吧！ (Nǐ duō yùndòng yùndòng ba!) → Con vận động nhiều hơn đi!', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_21_2_3', 'lesson-21', 'txt_21_2', 'listening', 'listening', '这本书是我的。', NULL, '[Ôn tập Bài 10] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Tớ biết bơi, còn biết trượt băng.","Bộ quần áo này không to cũng không nhỏ.","Một bộ quần áo","Quyển sách này là sách của tôi."]'::jsonb, 3, 'Nội dung nghe được: 这本书是我的。 (Zhè běn shū shì wǒ de.) → Quyển sách này là sách của tôi.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_21_2_4', 'lesson-21', 'txt_21_2', 'listening', 'listening', '我会游泳，也会滑冰。', NULL, '[Bài 21] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["我下午陪奶奶去医院看病。","我经常觉得头晕，吃什么都过敏。 最近胃口和睡眠都不好。","如果有医疗保险，看病费用可以减少很多。","我会游泳，也会滑冰。"]'::jsonb, 3, 'Câu vừa đọc: 我会游泳，也会滑冰。 (Wǒ huì yóuyǒng, yě huì huábīng.) → Tớ biết bơi, còn biết trượt băng.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_21_2_5', 'lesson-21', 'txt_21_2', 'listening', 'listening', '老师好', NULL, '[Ôn tập Bài 1] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Em trai vui đến nổi nhảy cẫng lên.","Chào thầy/Chào cô","Lúc tôi gọi điện thoại cho bạn thì bố đang nhìn tôi.","Trời mưa rồi mà tôi không mang ô, chỉ đành đợi ở trường."]'::jsonb, 1, 'Nội dung nghe được: 老师好 (Lǎoshī hǎo) → Chào thầy/Chào cô', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_21_3', 'lesson-21', 'Bài khoá mở rộng: Đi khám kiểm tra sức khỏe (Mở rộng)', 'Hội thoại tình huống mới xây dựng dựa trên từ vựng và ngữ pháp Bài 21 (không trùng lặp nguyên văn giáo trình).', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_21_3_1', 'txt_21_3', 'Bác sĩ', '你最近有什么症状，哪里不舒服？', '你最近有什么症状，哪里不舒服？', 'Nǐ zuìjìn yǒu shénme zhèngzhuàng, nǎlǐ bù shūfu?', 'Dạo này bạn có triệu chứng gì, thấy khó chịu ở đâu?', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_21_3_2', 'txt_21_3', 'Bệnh nhân', '医生，我头晕、睡眠不好，对有些食物还会过敏。', '医生，我头晕、睡眠不好，对有些 (xiē: vài, một ít)食物还会过敏。', 'Yīshēng, wǒ tóuyūn, shuìmián bù hǎo, duì yǒuxiē shíwù hái huì guòmǐn.', 'Thưa bác sĩ, tôi bị chóng mặt, ngủ không ngon giấc, lại còn dị ứng với vài món ăn.', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_21_3_3', 'txt_21_3', 'Bác sĩ', '别担心，检查结果正常，没有重病，只是太累了。', '别 (bié: đừng)担心 (dānxīn: lo lắng)，检查结果正 (zhèng: đang)常，没有 (méiyǒu: không có)重病，只是太累了。', 'Bié dānxīn, jiǎnchá jiéguǒ zhèngcháng, méiyǒu zhòngbìng, zhǐshì tài lèi le.', 'Đừng lo, kết quả kiểm tra bình thường, không có bệnh nặng đâu, chỉ là làm việc quá mệt thôi.', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_21_3_4', 'txt_21_3', 'Bệnh nhân', '还好我有医疗保险，费用减轻了不少，谢谢医生和护士！', '还好我有医疗保险，费用减轻了不少 (shǎo: ít)，谢谢医生和护士！', 'Háihǎo wǒ yǒu yīliáo bǎoxiǎn, fèiyòng jiǎnqīng le bùshǎo, xièxie yīshēng hé hùshi!', 'May quá tôi có bảo hiểm y tế nên chi phí giảm đi nhiều, cảm ơn bác sĩ và y tá!', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_21_3_1', 'lesson-21', 'txt_21_3', 'listening', 'listening', '你最近有什么症状，哪里不舒服？ 医生，我头晕、睡眠不好，对有些食物还会过敏。 别担心，检查结果正常，没有重病，只是太累了。 还好我有医疗保险，费用减轻了不少，谢谢医生和护士！', NULL, '[Nghe hiểu tình huống mới] Bác sĩ kết luận tình trạng của bệnh nhân sau khi kiểm tra là gì?', '["Bị gãy chân khi chạy bộ","Cần đổi bảo hiểm y tế","Mắc bệnh nặng phải nhập viện ngay","Không mắc bệnh nặng, chỉ do làm việc quá mệt mỏi"]'::jsonb, 3, 'Bác sĩ trấn an: ''检查结果正常，没有重病，只是太累了''.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_21_3_2', 'lesson-21', 'txt_21_3', 'listening', 'listening', '你最近有什么症状，哪里不舒服？', NULL, '[Mở rộng] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Bọn họ chỉ quan tâm đến bản thân mình mà thôi.","Một câu chuyện","Anh ta không cho tôi đi.","Dạo này bạn có triệu chứng gì, thấy khó chịu ở đâu?"]'::jsonb, 3, 'Nội dung nghe được: 你最近有什么症状，哪里不舒服？ (Nǐ zuìjìn yǒu shénme zhèngzhuàng, nǎlǐ bù shūfu?) → Dạo này bạn có triệu chứng gì, thấy khó chịu ở đâu?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_21_3_3', 'lesson-21', 'txt_21_3', 'listening', 'listening', '医生，我头晕、睡眠不好，对有些食物还会过敏。', NULL, '[Mở rộng] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["如果八点我还没 (méi: chưa, không có)回来 (lái: đến)，你就不用 (yòng: dùng)等我了。","病人对这种水果有点儿过敏。","如果有医疗保险，看病费用可以减少很多。","医生，我头晕、睡眠不好，对有些 (xiē: vài, một ít)食物还会过敏。"]'::jsonb, 3, 'Câu vừa đọc: 医生，我头晕、睡眠不好，对有些食物还会过敏。 (Yīshēng, wǒ tóuyūn, shuìmián bù hǎo, duì yǒuxiē shíwù hái huì guòmǐn.) → Thưa bác sĩ, tôi bị chóng mặt, ngủ không ngon giấc, lại còn dị ứng với vài món ăn.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_21_3_4', 'lesson-21', 'txt_21_3', 'listening', 'listening', '别担心，检查结果正常，没有重病，只是太累了。', NULL, '[Mở rộng] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Cô ấy là học sinh trường nào?","một câu chuyện","Lúc tôi về nhà, bố đang xem ti vi.","Đừng lo, kết quả kiểm tra bình thường, không có bệnh nặng đâu, chỉ là làm việc quá mệt thôi."]'::jsonb, 3, 'Nội dung nghe được: 别担心，检查结果正常，没有重病，只是太累了。 (Bié dānxīn, jiǎnchá jiéguǒ zhèngcháng, méiyǒu zhòngbìng, zhǐshì tài lèi le.) → Đừng lo, kết quả kiểm tra bình thường, không có bệnh nặng đâu, chỉ là làm việc quá mệt thôi.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss21_1', 'lesson-21', '病人对这种水果有点儿过敏', '[Mở rộng] Bệnh nhân hơi bị dị ứng với loại trái cây này.', 'Bìngrén duì zhè zhǒng shuǐguǒ yǒudiǎnr guòmǐn.', '["病人","对这","种","水果","有点儿","过敏"]'::jsonb, NULL, 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss21_2', 'lesson-21', '我下午陪奶奶去医院看病', '[Mở rộng] Chiều nay tôi đưa bà nội đi bệnh viện khám bệnh.', 'Wǒ xiàwǔ péi nǎinai qù yīyuàn kànbìng.', '["我下午","陪","奶奶","去","医院","看病"]'::jsonb, NULL, 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss21_3', 'lesson-21', '你多运动运动吧', 'Con vận động nhiều hơn đi!', 'Nǐ duō yùndòng yùndòng ba!', '["你","多","运动","运动","吧"]'::jsonb, NULL, 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss21_4', 'lesson-21', '我会游泳也会滑冰', 'Tớ biết bơi, còn biết trượt băng.', 'Wǒ huì yóuyǒng, yě huì huábīng.', '["我","会","游泳","也","会","滑冰"]'::jsonb, NULL, 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss21_5', 'lesson-21', '请告诉我这副眼镜多少钱', '[Ôn tập Bài 10] Làm ơn cho tôi biết cặp kính mắt này bao nhiêu tiền.', 'Qǐng gàosu wǒ zhè fù yǎnjìng duōshao qián.', '["请告诉","我这","副","眼镜","多少","钱"]'::jsonb, NULL, 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss21_6', 'lesson-21', '马克明天早上见', '[Ôn tập Bài 2] Mark, sáng mai gặp lại nhé!', 'Mǎkè, míngtiān zǎoshang jiàn!', '["马克","明天","早上","见"]'::jsonb, NULL, 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr21_vi_1', 'lesson-21', 'vi_to_zh', '[Mở rộng] Dạo này tôi hay bị chóng mặt, ăn uống và giấc ngủ đều không tốt lắm.', NULL, NULL, '最近我常常头晕，胃口和睡眠都不太好。', NULL, 'zuìjìn wǒ chángcháng tóuyūn wèikǒu hé shuìmián dōu bú tài hǎo', '[]'::jsonb, 'Gợi ý Pinyin: Zuìjìn wǒ chángcháng tóuyūn, wèikǒu hé shuìmián dōu bú tài hǎo.', 'Dạo này tôi hay bị chóng mặt, ăn uống và giấc ngủ đều không tốt lắm. → 最近我常常头晕，胃口和睡眠都不太好。 (Zuìjìn wǒ chángcháng tóuyūn, wèikǒu hé shuìmián dōu bú tài hǎo.)', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr21_vi_2', 'lesson-21', 'vi_to_zh', '[Mở rộng] Nếu có bảo hiểm y tế, chi phí khám bệnh có thể giảm đi rất nhiều.', NULL, NULL, '如果有医疗保险，看病费用可以减少很多。', NULL, 'rúguǒ yǒu yīliáo bǎoxiǎn kànbìng fèiyòng kěyǐ jiǎnshǎo hěnduō', '[]'::jsonb, 'Gợi ý Pinyin: Rúguǒ yǒu yīliáo bǎoxiǎn, kànbìng fèiyòng kěyǐ jiǎnshǎo hěnduō.', 'Nếu có bảo hiểm y tế, chi phí khám bệnh có thể giảm đi rất nhiều. → 如果有医疗保险，看病费用可以减少很多。 (Rúguǒ yǒu yīliáo bǎoxiǎn, kànbìng fèiyòng kěyǐ jiǎnshǎo hěnduō.)', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr21_vi_3', 'lesson-21', 'vi_to_zh', 'Con vận động nhiều hơn đi!', NULL, NULL, '你多运动运动吧！', NULL, 'nǐ duō yùndòng yùndòng ba', '[]'::jsonb, 'Gợi ý Pinyin: Nǐ duō yùndòng yùndòng ba!', 'Con vận động nhiều hơn đi! → 你多运动运动吧！ (Nǐ duō yùndòng yùndòng ba!)', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr21_vi_4', 'lesson-21', 'vi_to_zh', 'Tớ biết bơi, còn biết trượt băng.', NULL, NULL, '我会游泳，也会滑冰。', NULL, 'wǒ huì yóuyǒng yě huì huábīng', '[]'::jsonb, 'Gợi ý Pinyin: Wǒ huì yóuyǒng, yě huì huábīng.', 'Tớ biết bơi, còn biết trượt băng. → 我会游泳，也会滑冰。 (Wǒ huì yóuyǒng, yě huì huábīng.)', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
