INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq21_13', 'lesson-21', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “医院” chứa bộ thủ nào sau đây?', '["Bộ cấu tạo [打] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [治] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","木 (Mộc) (Cây cối, gỗ)","Bộ cấu tạo [医] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)"]'::jsonb, 3, 'Chữ “医院” có Bộ cấu tạo [医] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán). Ghép từ các chữ Hán: [医] + [院].', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq21_14', 'lesson-21', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “医生” chứa bộ thủ nào sau đây?', '["Bộ cấu tạo [重] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [医] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [最] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [费] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)"]'::jsonb, 1, 'Chữ “医生” có Bộ cấu tạo [医] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán). Ghép từ các chữ Hán: [医] + [生].', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq21_15', 'lesson-21', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “护士” chứa bộ thủ nào sau đây?', '["Bộ cấu tạo [重] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [护] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","口 (Khẩu) (Miệng, ăn uống, lời nói)","白 (Bạch) (Màu trắng, sáng tỏ)"]'::jsonb, 1, 'Chữ “护士” có Bộ cấu tạo [护] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán). Ghép từ các chữ Hán: [护] + [士].', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq21_16', 'lesson-21', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “病人” chứa bộ thủ nào sau đây?', '["方 (Phương) (Vuông vức, phương hướng)","Bộ cấu tạo [过] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [头] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","人 (Nhân) (Con người, nhân loại)"]'::jsonb, 3, 'Chữ “病人” có 人 (Nhân) (Con người, nhân loại). Ghép từ các chữ Hán: [病] + [人].', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
