INSERT INTO lessons (id, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id) VALUES ('lesson-22', 'Bài 22: Thích nghi - Đơn nguyên 7: Du học Trung Quốc', 'Bài 22', 'Đơn nguyên 7: Du học Trung Quốc', 'Cuộc sống mới tại trường đại học Trung Quốc, giải tỏa áp lực, kết bạn và thích nghi văn hóa.', '2026-11-14'::date, 22, TRUE, NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, date_added = EXCLUDED.date_added, sort_order = EXCLUDED.sort_order, is_system = TRUE, updated_at = NOW();
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v22_1', 'lesson-22', '压力', 'yālì', 'lực', 'áp lực', 'Danh từ', '力 (Lực) (Sức mạnh, động lực)', 'Ghép từ các chữ Hán: [压] + [力].', 'Kết hợp các thành tố [压] + [力] để tạo thành từ mang nghĩa ''áp lực''.', '都是留学生经常遇到的困难，比如文化不同、生活环境不同等等。我们留学生的压力很大。', 'Dōu shì liúxuéshēng jīngcháng yùdào de kùnnan, bǐrú wénhuà bùtóng, shēnghuó huánjìng bùtóng děngděng. Wǒmen liúxuéshēng de yālì hěn dà.', 'Đều là những khó khăn mà du học sinh hay gặp phải thôi, như khác biệt văn hóa, môi trường sống khác nhau, v.v. Áp lực của du học sinh bọn tớ lớn lắm.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v22_2', 'lesson-22', '困难', 'kùnnan', 'từ Hán ngữ', 'khó khăn', 'Danh từ', 'Bộ cấu tạo [困] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [困] + [难].', 'Kết hợp các thành tố [困] + [难] để tạo thành từ mang nghĩa ''khó khăn''.', '怎么了？你还有什么困难，告诉我吧！我会帮你解决。', 'Zěnmele? Nǐ hái yǒu shén me kùnnan, gàosù wǒ ba! Wǒ huì bāng nǐ jiějué.', 'Sao vậy? Cậu còn gặp khó khăn gì cứ nói với tớ! Tớ sẽ giúp cậu giải quyết.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v22_3', 'lesson-22', '问题', 'wèntí', 'vấn', 'vấn đề, câu hỏi', 'Danh từ', 'Bộ cấu tạo [问] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [问] + [题].', 'Kết hợp các thành tố [问] + [题] để tạo thành từ mang nghĩa ''vấn đề, câu hỏi''.', '那些困难我都能自己适应，自己解决。最糟糕的要说到学习问题。刚来中国的时候，因为不习惯这里的学习方法，所以我做什么事都很难。虽然在国内已经学汉语了，但是到中国以后，有很多时候你们说的我听不懂。考试又有很多，要抓紧时间练习。我一点儿也不习惯，哭了很多次。', 'Nàxiē kùnnan wǒ dōu néng zìjǐ shìyìng, zìjǐ jiějué. Zuì zāogāo de yāo shuō dào xuéxí wèntí. Gāng lái Zhōngguó de shíhou, yīn wèi bù xíguàn zhèli de xuéxí fāngfǎ, suǒ yǐ wǒ zuò shénme shì dōu hěn nán. Suīrán zài guónèi yǐjīng xué Hànyǔ le, dànshì dào Zhōngguó yǐhòu, yǒu hěnduō shíhou nǐmen shuō de wǒ tīng bù dǒng. Kǎoshì yòu yǒu hěnduō, yào zhuā jǐn shíjiān liànxí. Wǒ yīdiǎnr yě bù xíguàn, kūle hěnduō cì.', 'Những khó khăn đó tớ đều có thể tự thích nghi và tự giải quyết. Tệ nhất phải nói đến chuyện học tập. Hồi mới sang Trung Quốc, vì chưa quen phương pháp học ở đây nên làm việc gì cũng thấy khó. Dù ở trong nước đã học tiếng Trung rồi, nhưng sang đây có nhiều lúc các bạn nói tớ nghe không hiểu. Thi cử lại nhiều, phải tranh thủ thời gian luyện tập. Tớ chẳng quen chút nào, đã khóc rất nhiều lần.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v22_4', 'lesson-22', '方法', 'fāngfǎ', 'Pháp', 'phương pháp, cách làm', 'Danh từ', '方 (Phương) (Vuông vức, phương hướng)', 'Ghép từ các chữ Hán: [方] + [法].', 'Kết hợp các thành tố [方] + [法] để tạo thành từ mang nghĩa ''phương pháp, cách làm''.', '那些困难我都能自己适应，自己解决。最糟糕的要说到学习问题。刚来中国的时候，因为不习惯这里的学习方法，所以我做什么事都很难。虽然在国内已经学汉语了，但是到中国以后，有很多时候你们说的我听不懂。考试又有很多，要抓紧时间练习。我一点儿也不习惯，哭了很多次。', 'Nàxiē kùnnan wǒ dōu néng zìjǐ shìyìng, zìjǐ jiějué. Zuì zāogāo de yāo shuō dào xuéxí wèntí. Gāng lái Zhōngguó de shíhou, yīn wèi bù xíguàn zhèli de xuéxí fāngfǎ, suǒ yǐ wǒ zuò shénme shì dōu hěn nán. Suīrán zài guónèi yǐjīng xué Hànyǔ le, dànshì dào Zhōngguó yǐhòu, yǒu hěnduō shíhou nǐmen shuō de wǒ tīng bù dǒng. Kǎoshì yòu yǒu hěnduō, yào zhuā jǐn shíjiān liànxí. Wǒ yīdiǎnr yě bù xíguàn, kūle hěnduō cì.', 'Những khó khăn đó tớ đều có thể tự thích nghi và tự giải quyết. Tệ nhất phải nói đến chuyện học tập. Hồi mới sang Trung Quốc, vì chưa quen phương pháp học ở đây nên làm việc gì cũng thấy khó. Dù ở trong nước đã học tiếng Trung rồi, nhưng sang đây có nhiều lúc các bạn nói tớ nghe không hiểu. Thi cử lại nhiều, phải tranh thủ thời gian luyện tập. Tớ chẳng quen chút nào, đã khóc rất nhiều lần.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v22_5', 'lesson-22', '气候', 'qìhòu', 'khí hậu', 'khí hậu', 'Danh từ', 'Bộ cấu tạo [气] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [气] + [候].', 'Kết hợp các thành tố [气] + [候] để tạo thành từ mang nghĩa ''khí hậu''.', '你还没习惯这里的气候吗？', 'Nǐ hái méi xíguàn zhèli de qìhòu ma?', 'Cậu vẫn chưa quen với khí hậu ở đây à?', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v22_6', 'lesson-22', '环境', 'huánjìng', 'từ Hán ngữ', 'môi trường, hoàn cảnh', 'Danh từ', 'Bộ cấu tạo [环] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [环] + [境].', 'Kết hợp các thành tố [环] + [境] để tạo thành từ mang nghĩa ''môi trường, hoàn cảnh''.', '都是留学生经常遇到的困难，比如文化不同、生活环境不同等等。我们留学生的压力很大。', 'Dōu shì liúxuéshēng jīngcháng yùdào de kùnnan, bǐrú wénhuà bùtóng, shēnghuó huánjìng bùtóng děngděng. Wǒmen liúxuéshēng de yālì hěn dà.', 'Đều là những khó khăn mà du học sinh hay gặp phải thôi, như khác biệt văn hóa, môi trường sống khác nhau, v.v. Áp lực của du học sinh bọn tớ lớn lắm.', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v22_7', 'lesson-22', '以前', 'yǐqián', 'tiền', 'trước, lúc trước', 'Danh từ', 'Bộ cấu tạo [以] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [以] + [前].', 'Kết hợp các thành tố [以] + [前] để tạo thành từ mang nghĩa ''trước, lúc trước''.', '其实这些事我出国以前我奶奶已经跟我说了。她年轻的时候也去国外留学，很有经验。', 'Qíshí zhèxiē shì wǒ chūguó yǐqián wǒ nǎinai yǐjīng gēn wǒ shuō le. Tā niánqīng de shíhou yě qù guówài liúxué, hěn yǒu jīngyàn.', 'Thực ra những chuyện này trước khi ra nước ngoài bà nội tớ đã dặn dò tớ hết rồi. Thời trẻ bà cũng từng đi du học nên rất có kinh nghiệm.', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v22_8', 'lesson-22', '以后', 'yǐhòu', 'hậu', 'sau, lúc sau', 'Danh từ', 'Bộ cấu tạo [以] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [以] + [后].', 'Kết hợp các thành tố [以] + [后] để tạo thành từ mang nghĩa ''sau, lúc sau''.', '那些困难我都能自己适应，自己解决。最糟糕的要说到学习问题。刚来中国的时候，因为不习惯这里的学习方法，所以我做什么事都很难。虽然在国内已经学汉语了，但是到中国以后，有很多时候你们说的我听不懂。考试又有很多，要抓紧时间练习。我一点儿也不习惯，哭了很多次。', 'Nàxiē kùnnan wǒ dōu néng zìjǐ shìyìng, zìjǐ jiějué. Zuì zāogāo de yāo shuō dào xuéxí wèntí. Gāng lái Zhōngguó de shíhou, yīn wèi bù xíguàn zhèli de xuéxí fāngfǎ, suǒ yǐ wǒ zuò shénme shì dōu hěn nán. Suīrán zài guónèi yǐjīng xué Hànyǔ le, dànshì dào Zhōngguó yǐhòu, yǒu hěnduō shíhou nǐmen shuō de wǒ tīng bù dǒng. Kǎoshì yòu yǒu hěnduō, yào zhuā jǐn shíjiān liànxí. Wǒ yīdiǎnr yě bù xíguàn, kūle hěnduō cì.', 'Những khó khăn đó tớ đều có thể tự thích nghi và tự giải quyết. Tệ nhất phải nói đến chuyện học tập. Hồi mới sang Trung Quốc, vì chưa quen phương pháp học ở đây nên làm việc gì cũng thấy khó. Dù ở trong nước đã học tiếng Trung rồi, nhưng sang đây có nhiều lúc các bạn nói tớ nghe không hiểu. Thi cử lại nhiều, phải tranh thủ thời gian luyện tập. Tớ chẳng quen chút nào, đã khóc rất nhiều lần.', 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v22_9', 'lesson-22', '家乡', 'jiāxiāng', 'gia', 'quê hương', 'Danh từ', 'Bộ cấu tạo [家] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [家] + [乡].', 'Kết hợp các thành tố [家] + [乡] để tạo thành từ mang nghĩa ''quê hương''.', '还没习惯，因为我家乡冬天不太冷，也不下雪。', 'Hái méi xíguàn, yīnwèi wǒ jiāxiāng dōngtiān bú tài lěng, yě bú xià xuě.', 'Vẫn chưa quen, vì mùa đông quê tớ không quá lạnh, cũng không có tuyết rơi.', 9) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v22_10', 'lesson-22', '年纪', 'niánjì', 'niên', 'tuổi, tuổi tác', 'Danh từ', 'Bộ cấu tạo [年] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [年] + [纪].', 'Kết hợp các thành tố [年] + [纪] để tạo thành từ mang nghĩa ''tuổi, tuổi tác''.', '您今年多大年纪？', 'Nín jīnnián duōdà niánjì?', 'Năm nay bác bao nhiêu tuổi rồi ạ?', 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v22_11', 'lesson-22', '出国', 'chūguó', 'quốc', 'ra nước ngoài', 'Động từ', 'Bộ cấu tạo [出] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [出] + [国].', 'Kết hợp các thành tố [出] + [国] để tạo thành từ mang nghĩa ''ra nước ngoài''.', '我也希望是这样。出国留学真是不容易啊！', 'Wǒ yě xīwàng shì zhèyàng. Chūguó liúxué zhēnshì bù róngyì a!', 'Tớ cũng hy vọng là thế. Đi du học nước ngoài thật sự không dễ dàng chút nào!', 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v22_12', 'lesson-22', '遇到', 'yù dào', 'đáo', 'gặp phải', 'Động từ', 'Bộ cấu tạo [遇] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [遇] + [到].', 'Kết hợp các thành tố [遇] + [到] để tạo thành từ mang nghĩa ''gặp phải''.', '都是留学生经常遇到的困难，比如文化不同、生活环境不同等等。我们留学生的压力很大。', 'Dōu shì liúxuéshēng jīngcháng yùdào de kùnnan, bǐrú wénhuà bùtóng, shēnghuó huánjìng bùtóng děngděng. Wǒmen liúxuéshēng de yālì hěn dà.', 'Đều là những khó khăn mà du học sinh hay gặp phải thôi, như khác biệt văn hóa, môi trường sống khác nhau, v.v. Áp lực của du học sinh bọn tớ lớn lắm.', 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v22_13', 'lesson-22', '适应', 'shìyìng', 'thích ứng', 'thích nghi, thích ứng', 'Động từ', 'Bộ cấu tạo [适] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [适] + [应].', 'Kết hợp các thành tố [适] + [应] để tạo thành từ mang nghĩa ''thích nghi, thích ứng''.', '那些困难我都能自己适应，自己解决。最糟糕的要说到学习问题。刚来中国的时候，因为不习惯这里的学习方法，所以我做什么事都很难。虽然在国内已经学汉语了，但是到中国以后，有很多时候你们说的我听不懂。考试又有很多，要抓紧时间练习。我一点儿也不习惯，哭了很多次。', 'Nàxiē kùnnan wǒ dōu néng zìjǐ shìyìng, zìjǐ jiějué. Zuì zāogāo de yāo shuō dào xuéxí wèntí. Gāng lái Zhōngguó de shíhou, yīn wèi bù xíguàn zhèli de xuéxí fāngfǎ, suǒ yǐ wǒ zuò shénme shì dōu hěn nán. Suīrán zài guónèi yǐjīng xué Hànyǔ le, dànshì dào Zhōngguó yǐhòu, yǒu hěnduō shíhou nǐmen shuō de wǒ tīng bù dǒng. Kǎoshì yòu yǒu hěnduō, yào zhuā jǐn shíjiān liànxí. Wǒ yīdiǎnr yě bù xíguàn, kūle hěnduō cì.', 'Những khó khăn đó tớ đều có thể tự thích nghi và tự giải quyết. Tệ nhất phải nói đến chuyện học tập. Hồi mới sang Trung Quốc, vì chưa quen phương pháp học ở đây nên làm việc gì cũng thấy khó. Dù ở trong nước đã học tiếng Trung rồi, nhưng sang đây có nhiều lúc các bạn nói tớ nghe không hiểu. Thi cử lại nhiều, phải tranh thủ thời gian luyện tập. Tớ chẳng quen chút nào, đã khóc rất nhiều lần.', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v22_14', 'lesson-22', '练习', 'liànxí', 'luyện tập', 'luyện tập', 'Động từ', 'Bộ cấu tạo [练] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [练] + [习].', 'Kết hợp các thành tố [练] + [习] để tạo thành từ mang nghĩa ''luyện tập''.', '那些困难我都能自己适应，自己解决。最糟糕的要说到学习问题。刚来中国的时候，因为不习惯这里的学习方法，所以我做什么事都很难。虽然在国内已经学汉语了，但是到中国以后，有很多时候你们说的我听不懂。考试又有很多，要抓紧时间练习。我一点儿也不习惯，哭了很多次。', 'Nàxiē kùnnan wǒ dōu néng zìjǐ shìyìng, zìjǐ jiějué. Zuì zāogāo de yāo shuō dào xuéxí wèntí. Gāng lái Zhōngguó de shíhou, yīn wèi bù xíguàn zhèli de xuéxí fāngfǎ, suǒ yǐ wǒ zuò shénme shì dōu hěn nán. Suīrán zài guónèi yǐjīng xué Hànyǔ le, dànshì dào Zhōngguó yǐhòu, yǒu hěnduō shíhou nǐmen shuō de wǒ tīng bù dǒng. Kǎoshì yòu yǒu hěnduō, yào zhuā jǐn shíjiān liànxí. Wǒ yīdiǎnr yě bù xíguàn, kūle hěnduō cì.', 'Những khó khăn đó tớ đều có thể tự thích nghi và tự giải quyết. Tệ nhất phải nói đến chuyện học tập. Hồi mới sang Trung Quốc, vì chưa quen phương pháp học ở đây nên làm việc gì cũng thấy khó. Dù ở trong nước đã học tiếng Trung rồi, nhưng sang đây có nhiều lúc các bạn nói tớ nghe không hiểu. Thi cử lại nhiều, phải tranh thủ thời gian luyện tập. Tớ chẳng quen chút nào, đã khóc rất nhiều lần.', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v22_15', 'lesson-22', '懂', 'dǒng', 'từ Hán ngữ', 'hiểu', 'Động từ', 'Bộ cấu tạo [懂] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Chữ độc thể / hình thanh gồm Bộ cấu tạo [懂] và các nét bổ trợ.', 'Ghi nhớ chữ [懂] (hiểu) qua hình tượng Thành phần biểu ý/biểu âm cơ bản trong chữ Hán.', '那些困难我都能自己适应，自己解决。最糟糕的要说到学习问题。刚来中国的时候，因为不习惯这里的学习方法，所以我做什么事都很难。虽然在国内已经学汉语了，但是到中国以后，有很多时候你们说的我听不懂。考试又有很多，要抓紧时间练习。我一点儿也不习惯，哭了很多次。', 'Nàxiē kùnnan wǒ dōu néng zìjǐ shìyìng, zìjǐ jiějué. Zuì zāogāo de yāo shuō dào xuéxí wèntí. Gāng lái Zhōngguó de shíhou, yīn wèi bù xíguàn zhèli de xuéxí fāngfǎ, suǒ yǐ wǒ zuò shénme shì dōu hěn nán. Suīrán zài guónèi yǐjīng xué Hànyǔ le, dànshì dào Zhōngguó yǐhòu, yǒu hěnduō shíhou nǐmen shuō de wǒ tīng bù dǒng. Kǎoshì yòu yǒu hěnduō, yào zhuā jǐn shíjiān liànxí. Wǒ yīdiǎnr yě bù xíguàn, kūle hěnduō cì.', 'Những khó khăn đó tớ đều có thể tự thích nghi và tự giải quyết. Tệ nhất phải nói đến chuyện học tập. Hồi mới sang Trung Quốc, vì chưa quen phương pháp học ở đây nên làm việc gì cũng thấy khó. Dù ở trong nước đã học tiếng Trung rồi, nhưng sang đây có nhiều lúc các bạn nói tớ nghe không hiểu. Thi cử lại nhiều, phải tranh thủ thời gian luyện tập. Tớ chẳng quen chút nào, đã khóc rất nhiều lần.', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v22_16', 'lesson-22', '哭', 'kū', 'từ Hán ngữ', 'khóc', 'Động từ', 'Bộ cấu tạo [哭] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Chữ độc thể / hình thanh gồm Bộ cấu tạo [哭] và các nét bổ trợ.', 'Ghi nhớ chữ [哭] (khóc) qua hình tượng Thành phần biểu ý/biểu âm cơ bản trong chữ Hán.', '那些困难我都能自己适应，自己解决。最糟糕的要说到学习问题。刚来中国的时候，因为不习惯这里的学习方法，所以我做什么事都很难。虽然在国内已经学汉语了，但是到中国以后，有很多时候你们说的我听不懂。考试又有很多，要抓紧时间练习。我一点儿也不习惯，哭了很多次。', 'Nàxiē kùnnan wǒ dōu néng zìjǐ shìyìng, zìjǐ jiějué. Zuì zāogāo de yāo shuō dào xuéxí wèntí. Gāng lái Zhōngguó de shíhou, yīn wèi bù xíguàn zhèli de xuéxí fāngfǎ, suǒ yǐ wǒ zuò shénme shì dōu hěn nán. Suīrán zài guónèi yǐjīng xué Hànyǔ le, dànshì dào Zhōngguó yǐhòu, yǒu hěnduō shíhou nǐmen shuō de wǒ tīng bù dǒng. Kǎoshì yòu yǒu hěnduō, yào zhuā jǐn shíjiān liànxí. Wǒ yīdiǎnr yě bù xíguàn, kūle hěnduō cì.', 'Những khó khăn đó tớ đều có thể tự thích nghi và tự giải quyết. Tệ nhất phải nói đến chuyện học tập. Hồi mới sang Trung Quốc, vì chưa quen phương pháp học ở đây nên làm việc gì cũng thấy khó. Dù ở trong nước đã học tiếng Trung rồi, nhưng sang đây có nhiều lúc các bạn nói tớ nghe không hiểu. Thi cử lại nhiều, phải tranh thủ thời gian luyện tập. Tớ chẳng quen chút nào, đã khóc rất nhiều lần.', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v22_17', 'lesson-22', '希望', 'xīwàng', 'hy vọng', 'hi vọng, mong, niềm hi vọng', 'Động từ / Danh từ', 'Bộ cấu tạo [希] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [希] + [望].', 'Kết hợp các thành tố [希] + [望] để tạo thành từ mang nghĩa ''hi vọng, mong, niềm hi vọng''.', '我也希望是这样。出国留学真是不容易啊！', 'Wǒ yě xīwàng shì zhèyàng. Chūguó liúxué zhēnshì bù róngyì a!', 'Tớ cũng hy vọng là thế. Đi du học nước ngoài thật sự không dễ dàng chút nào!', 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v22_18', 'lesson-22', '相信', 'xiāngxìn', 'từ Hán ngữ', 'tin, tin tưởng', 'Động từ', 'Bộ cấu tạo [相] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [相] + [信].', 'Kết hợp các thành tố [相] + [信] để tạo thành từ mang nghĩa ''tin, tin tưởng''.', '没关系！我只要继续努力，相信自己就好。再说，虽然我不说，但是你们也帮助我很多。能到中国，跟你们交朋友，我很幸福。', 'Méiguānxi! Wǒ zhǐyào jìxù nǔlì, xiāngxìn zìjǐ jiù hǎo. Zàishuō, suīrán wǒ bù shuō, dànshì nǐmen yě bāngzhù wǒ hěnduō. Néng dào Zhōngguó, gēn nǐmen jiāo péngyou, wǒ hěn xìngfú.', 'Không sao đâu! Chỉ cần tớ tiếp tục cố gắng, tin vào bản thân là được. Hơn nữa, dù tớ không nói ra nhưng các bạn cũng giúp đỡ tớ rất nhiều. Được đến Trung Quốc và kết bạn với các bạn, tớ thấy rất hạnh phúc.', 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v22_19', 'lesson-22', '习惯', 'xíguàn', 'tập quán', 'quen , thói quen', 'Động từ / Danh từ', 'Bộ cấu tạo [习] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [习] + [惯].', 'Kết hợp các thành tố [习] + [惯] để tạo thành từ mang nghĩa ''quen , thói quen''.', '你还没习惯这里的气候吗？', 'Nǐ hái méi xíguàn zhèli de qìhòu ma?', 'Cậu vẫn chưa quen với khí hậu ở đây à?', 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v22_20', 'lesson-22', '抓紧', 'zhuājǐn', 'từ Hán ngữ', 'nắm bắt, nắm chặt', 'Động từ', 'Bộ cấu tạo [抓] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [抓] + [紧].', 'Kết hợp các thành tố [抓] + [紧] để tạo thành từ mang nghĩa ''nắm bắt, nắm chặt''.', '那些困难我都能自己适应，自己解决。最糟糕的要说到学习问题。刚来中国的时候，因为不习惯这里的学习方法，所以我做什么事都很难。虽然在国内已经学汉语了，但是到中国以后，有很多时候你们说的我听不懂。考试又有很多，要抓紧时间练习。我一点儿也不习惯，哭了很多次。', 'Nàxiē kùnnan wǒ dōu néng zìjǐ shìyìng, zìjǐ jiějué. Zuì zāogāo de yāo shuō dào xuéxí wèntí. Gāng lái Zhōngguó de shíhou, yīn wèi bù xíguàn zhèli de xuéxí fāngfǎ, suǒ yǐ wǒ zuò shénme shì dōu hěn nán. Suīrán zài guónèi yǐjīng xué Hànyǔ le, dànshì dào Zhōngguó yǐhòu, yǒu hěnduō shíhou nǐmen shuō de wǒ tīng bù dǒng. Kǎoshì yòu yǒu hěnduō, yào zhuā jǐn shíjiān liànxí. Wǒ yīdiǎnr yě bù xíguàn, kūle hěnduō cì.', 'Những khó khăn đó tớ đều có thể tự thích nghi và tự giải quyết. Tệ nhất phải nói đến chuyện học tập. Hồi mới sang Trung Quốc, vì chưa quen phương pháp học ở đây nên làm việc gì cũng thấy khó. Dù ở trong nước đã học tiếng Trung rồi, nhưng sang đây có nhiều lúc các bạn nói tớ nghe không hiểu. Thi cử lại nhiều, phải tranh thủ thời gian luyện tập. Tớ chẳng quen chút nào, đã khóc rất nhiều lần.', 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v22_21', 'lesson-22', '继续', 'jìxù', 'từ Hán ngữ', 'tiếp tục', 'Động từ', 'Bộ cấu tạo [继] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [继] + [续].', 'Kết hợp các thành tố [继] + [续] để tạo thành từ mang nghĩa ''tiếp tục''.', '没关系！我只要继续努力，相信自己就好。再说，虽然我不说，但是你们也帮助我很多。能到中国，跟你们交朋友，我很幸福。', 'Méiguānxi! Wǒ zhǐyào jìxù nǔlì, xiāngxìn zìjǐ jiù hǎo. Zàishuō, suīrán wǒ bù shuō, dànshì nǐmen yě bāngzhù wǒ hěnduō. Néng dào Zhōngguó, gēn nǐmen jiāo péngyou, wǒ hěn xìngfú.', 'Không sao đâu! Chỉ cần tớ tiếp tục cố gắng, tin vào bản thân là được. Hơn nữa, dù tớ không nói ra nhưng các bạn cũng giúp đỡ tớ rất nhiều. Được đến Trung Quốc và kết bạn với các bạn, tớ thấy rất hạnh phúc.', 21) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v22_22', 'lesson-22', '解决', 'jiějué', 'từ Hán ngữ', 'giải quyết', 'Động từ', 'Bộ cấu tạo [解] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [解] + [决].', 'Kết hợp các thành tố [解] + [决] để tạo thành từ mang nghĩa ''giải quyết''.', '怎么了？你还有什么困难，告诉我吧！我会帮你解决。', 'Zěnmele? Nǐ hái yǒu shén me kùnnan, gàosù wǒ ba! Wǒ huì bāng nǐ jiějué.', 'Sao vậy? Cậu còn gặp khó khăn gì cứ nói với tớ! Tớ sẽ giúp cậu giải quyết.', 22) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v22_23', 'lesson-22', '努力', 'nǔlì', 'nỗ lực', 'cố gắng, nỗ lực', 'Động từ / Tính từ', '力 (Lực) (Sức mạnh, động lực)', 'Ghép từ các chữ Hán: [努] + [力].', 'Kết hợp các thành tố [努] + [力] để tạo thành từ mang nghĩa ''cố gắng, nỗ lực''.', '没关系！我只要继续努力，相信自己就好。再说，虽然我不说，但是你们也帮助我很多。能到中国，跟你们交朋友，我很幸福。', 'Méiguānxi! Wǒ zhǐyào jìxù nǔlì, xiāngxìn zìjǐ jiù hǎo. Zàishuō, suīrán wǒ bù shuō, dànshì nǐmen yě bāngzhù wǒ hěnduō. Néng dào Zhōngguó, gēn nǐmen jiāo péngyou, wǒ hěn xìngfú.', 'Không sao đâu! Chỉ cần tớ tiếp tục cố gắng, tin vào bản thân là được. Hơn nữa, dù tớ không nói ra nhưng các bạn cũng giúp đỡ tớ rất nhiều. Được đến Trung Quốc và kết bạn với các bạn, tớ thấy rất hạnh phúc.', 23) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v22_24', 'lesson-22', '难过', 'nánguò', 'từ Hán ngữ', 'buồn', 'Tính từ', 'Bộ cấu tạo [难] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [难] + [过].', 'Kết hợp các thành tố [难] + [过] để tạo thành từ mang nghĩa ''buồn''.', '你怎么不跟我们说啊？那时候你一定很难过。', 'Nǐ zěnme bù gēn wǒmen shuō a? Nà shíhou nǐ yídìng hěn nánguò.', 'Sao cậu không kể với bọn tớ? Lúc đó chắc cậu buồn lắm.', 24) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v22_25', 'lesson-22', '幸福', 'xìngfú', 'từ Hán ngữ', 'hạnh phúc', 'Tính từ / Danh từ', 'Bộ cấu tạo [幸] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [幸] + [福].', 'Kết hợp các thành tố [幸] + [福] để tạo thành từ mang nghĩa ''hạnh phúc''.', '没关系！我只要继续努力，相信自己就好。再说，虽然我不说，但是你们也帮助我很多。能到中国，跟你们交朋友，我很幸福。', 'Méiguānxi! Wǒ zhǐyào jìxù nǔlì, xiāngxìn zìjǐ jiù hǎo. Zàishuō, suīrán wǒ bù shuō, dànshì nǐmen yě bāngzhù wǒ hěnduō. Néng dào Zhōngguó, gēn nǐmen jiāo péngyou, wǒ hěn xìngfú.', 'Không sao đâu! Chỉ cần tớ tiếp tục cố gắng, tin vào bản thân là được. Hơn nữa, dù tớ không nói ra nhưng các bạn cũng giúp đỡ tớ rất nhiều. Được đến Trung Quốc và kết bạn với các bạn, tớ thấy rất hạnh phúc.', 25) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v22_26', 'lesson-22', '糟糕', 'zāogāo', 'cao', 'tồi tệ, gay go', 'Tính từ', 'Bộ cấu tạo [糟] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [糟] + [糕].', 'Kết hợp các thành tố [糟] + [糕] để tạo thành từ mang nghĩa ''tồi tệ, gay go''.', '那些困难我都能自己适应，自己解决。最糟糕的要说到学习问题。刚来中国的时候，因为不习惯这里的学习方法，所以我做什么事都很难。虽然在国内已经学汉语了，但是到中国以后，有很多时候你们说的我听不懂。考试又有很多，要抓紧时间练习。我一点儿也不习惯，哭了很多次。', 'Nàxiē kùnnan wǒ dōu néng zìjǐ shìyìng, zìjǐ jiějué. Zuì zāogāo de yāo shuō dào xuéxí wèntí. Gāng lái Zhōngguó de shíhou, yīn wèi bù xíguàn zhèli de xuéxí fāngfǎ, suǒ yǐ wǒ zuò shénme shì dōu hěn nán. Suīrán zài guónèi yǐjīng xué Hànyǔ le, dànshì dào Zhōngguó yǐhòu, yǒu hěnduō shíhou nǐmen shuō de wǒ tīng bù dǒng. Kǎoshì yòu yǒu hěnduō, yào zhuā jǐn shíjiān liànxí. Wǒ yīdiǎnr yě bù xíguàn, kūle hěnduō cì.', 'Những khó khăn đó tớ đều có thể tự thích nghi và tự giải quyết. Tệ nhất phải nói đến chuyện học tập. Hồi mới sang Trung Quốc, vì chưa quen phương pháp học ở đây nên làm việc gì cũng thấy khó. Dù ở trong nước đã học tiếng Trung rồi, nhưng sang đây có nhiều lúc các bạn nói tớ nghe không hiểu. Thi cử lại nhiều, phải tranh thủ thời gian luyện tập. Tớ chẳng quen chút nào, đã khóc rất nhiều lần.', 26) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v22_27', 'lesson-22', '不同', 'bùtóng', 'đồng', 'khác biệt, bất đồng, không giống nhau', 'Tính từ', 'Bộ cấu tạo [不] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [不] + [同].', 'Kết hợp các thành tố [不] + [同] để tạo thành từ mang nghĩa ''khác biệt, bất đồng, không giống nhau''.', '都是留学生经常遇到的困难，比如文化不同、生活环境不同等等。我们留学生的压力很大。', 'Dōu shì liúxuéshēng jīngcháng yùdào de kùnnan, bǐrú wénhuà bùtóng, shēnghuó huánjìng bùtóng děngděng. Wǒmen liúxuéshēng de yālì hěn dà.', 'Đều là những khó khăn mà du học sinh hay gặp phải thôi, như khác biệt văn hóa, môi trường sống khác nhau, v.v. Áp lực của du học sinh bọn tớ lớn lắm.', 27) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v22_28', 'lesson-22', '难', 'nán', 'từ Hán ngữ', 'khó', 'Tính từ', 'Bộ cấu tạo [难] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Chữ độc thể / hình thanh gồm Bộ cấu tạo [难] và các nét bổ trợ.', 'Ghi nhớ chữ [难] (khó) qua hình tượng Thành phần biểu ý/biểu âm cơ bản trong chữ Hán.', '怎么了？你还有什么困难，告诉我吧！我会帮你解决。', 'Zěnmele? Nǐ hái yǒu shén me kùnnan, gàosù wǒ ba! Wǒ huì bāng nǐ jiějué.', 'Sao vậy? Cậu còn gặp khó khăn gì cứ nói với tớ! Tớ sẽ giúp cậu giải quyết.', 28) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v22_29', 'lesson-22', '有经验', 'yǒu jīngyàn', 'hữu', 'có kinh nghiệm', 'Cụm từ / Tên riêng', 'Bộ cấu tạo [有] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [有] + [经] + [验].', 'Kết hợp các thành tố [有] + [经] + [验] để tạo thành từ mang nghĩa ''có kinh nghiệm''.', '其实这些事我出国以前我奶奶已经跟我说了。她年轻的时候也去国外留学，很有经验。', 'Qíshí zhèxiē shì wǒ chūguó yǐqián wǒ nǎinai yǐjīng gēn wǒ shuō le. Tā niánqīng de shíhou yě qù guówài liúxué, hěn yǒu jīngyàn.', 'Thực ra những chuyện này trước khi ra nước ngoài bà nội tớ đã dặn dò tớ hết rồi. Thời trẻ bà cũng từng đi du học nên rất có kinh nghiệm.', 29) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v22_30', 'lesson-22', '已经', 'yǐjīng', 'từ Hán ngữ', 'đã', 'Phó từ', 'Bộ cấu tạo [已] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [已] + [经].', 'Kết hợp các thành tố [已] + [经] để tạo thành từ mang nghĩa ''đã''.', '那些困难我都能自己适应，自己解决。最糟糕的要说到学习问题。刚来中国的时候，因为不习惯这里的学习方法，所以我做什么事都很难。虽然在国内已经学汉语了，但是到中国以后，有很多时候你们说的我听不懂。考试又有很多，要抓紧时间练习。我一点儿也不习惯，哭了很多次。', 'Nàxiē kùnnan wǒ dōu néng zìjǐ shìyìng, zìjǐ jiějué. Zuì zāogāo de yāo shuō dào xuéxí wèntí. Gāng lái Zhōngguó de shíhou, yīn wèi bù xíguàn zhèli de xuéxí fāngfǎ, suǒ yǐ wǒ zuò shénme shì dōu hěn nán. Suīrán zài guónèi yǐjīng xué Hànyǔ le, dànshì dào Zhōngguó yǐhòu, yǒu hěnduō shíhou nǐmen shuō de wǒ tīng bù dǒng. Kǎoshì yòu yǒu hěnduō, yào zhuā jǐn shíjiān liànxí. Wǒ yīdiǎnr yě bù xíguàn, kūle hěnduō cì.', 'Những khó khăn đó tớ đều có thể tự thích nghi và tự giải quyết. Tệ nhất phải nói đến chuyện học tập. Hồi mới sang Trung Quốc, vì chưa quen phương pháp học ở đây nên làm việc gì cũng thấy khó. Dù ở trong nước đã học tiếng Trung rồi, nhưng sang đây có nhiều lúc các bạn nói tớ nghe không hiểu. Thi cử lại nhiều, phải tranh thủ thời gian luyện tập. Tớ chẳng quen chút nào, đã khóc rất nhiều lần.', 30) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v22_31', 'lesson-22', '慢慢', 'mànmàn', 'mạn mạn', 'từ từ, dần dần', 'Phó từ', 'Bộ cấu tạo [慢] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [慢] + [慢].', 'Kết hợp các thành tố [慢] + [慢] để tạo thành từ mang nghĩa ''từ từ, dần dần''.', '慢慢就会习惯了。', 'Mànmàn jiù huì xíguàn le.', 'Dần dần rồi sẽ quen thôi.', 31) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v22_32', 'lesson-22', '再说', 'zàishuō', 'thuyết', 'ngoài ra, hơn nữa', 'Liên từ', 'Bộ cấu tạo [再] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [再] + [说].', 'Kết hợp các thành tố [再] + [说] để tạo thành từ mang nghĩa ''ngoài ra, hơn nữa''.', '好了，我同意，你别再说了！', 'Hǎole, wǒ tóngyì, nǐ bié zài shuōle!', 'Được rồi, tôi đồng ý, cậu đừng nói lại nữa!', 32) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v22_33', 'lesson-22', '虽然...... 但是......', 'suīrán...dànshì...', 'thị', 'mặc dù... nhưng...', 'Cụm từ / Tên riêng', 'Bộ cấu tạo [虽] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [虽] + [然] + [但] + [是].', 'Kết hợp các thành tố [虽] + [然] + [但] + [是] để tạo thành từ mang nghĩa ''mặc dù... nhưng...''.', '这是关于“虽然...... 但是......”的常用句子。', 'Zhè shì guānyú ''suīrán...dànshì...'' de chángyòng jùzi.', 'Đây là câu ví dụ sử dụng từ ''虽然...... 但是......'' (mặc dù... nhưng...).', 33) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v22_34', 'lesson-22', '没关系', 'méiguānxi', 'một', 'không sao', 'Cụm từ / Tên riêng', 'Bộ cấu tạo [没] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [没] + [关] + [系].', 'Kết hợp các thành tố [没] + [关] + [系] để tạo thành từ mang nghĩa ''không sao''.', '没关系！我只要继续努力，相信自己就好。再说，虽然我不说，但是你们也帮助我很多。能到中国，跟你们交朋友，我很幸福。', 'Méiguānxi! Wǒ zhǐyào jìxù nǔlì, xiāngxìn zìjǐ jiù hǎo. Zàishuō, suīrán wǒ bù shuō, dànshì nǐmen yě bāngzhù wǒ hěnduō. Néng dào Zhōngguó, gēn nǐmen jiāo péngyou, wǒ hěn xìngfú.', 'Không sao đâu! Chỉ cần tớ tiếp tục cố gắng, tin vào bản thân là được. Hơn nữa, dù tớ không nói ra nhưng các bạn cũng giúp đỡ tớ rất nhiều. Được đến Trung Quốc và kết bạn với các bạn, tớ thấy rất hạnh phúc.', 34) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g22_1', 'lesson-22', '1. Trợ từ ngữ khí 了', 'Chủ ngữ + Động từ + (Tân ngữ) + 了', ' Trợ từ ngữ khí 了 dùng ở cuối câu để biểu thị ngữ khí khẳng định, có sự thay đổi hoặc biểu thị ý khuyên ngăn, than thở. - Hình thức khẳng định: 我吃饭了。 Wǒ chīfàn le. Tôi ăn cơm rồi. 我的病好了。 Wǒ de bìng hǎo le. Tớ khỏi bệnh rồi. 好了，我同意，你别再说了！ Hǎole, wǒ tó', NULL, '[{"hanzi":"我吃饭了。","pinyin":"Wǒ chīfàn le.","meaning":"Tôi ăn cơm rồi."},{"hanzi":"好了，我同意，你别再说了！","pinyin":"Hǎole, wǒ tóngyì, nǐ bié zài shuōle!","meaning":"Được rồi, tôi đồng ý, cậu đừng nói lại nữa!"}]'::jsonb, 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g22_2', 'lesson-22', '2. 年龄的表达 - Cách biểu đạt tuổi tác', 'Chủ ngữ + （今年）几岁（了）？', ' - Có ba cách để hỏi về tuổi tác như sau: * Cách 1: Dùng cho trường hợp trẻ em dưới 10 tuổi. 你今年几岁了？ Nǐ jīnnián jǐ suì le? Năm nay cháu mấy tuổi rồi? * Cách 2: Thường dùng để hỏi tuổi của người lớn tuổi. Chủ ngữ （今年）多大年纪（了）？ 您今年多大年纪？ Nín jīnnián duōd', NULL, '[{"hanzi":"我没吃饭。","pinyin":"Wǒ méi chīfàn.","meaning":"Tôi chưa ăn cơm."},{"hanzi":"我的病还没好。","pinyin":"Wǒ de bìng hái méi hǎo.","meaning":"Bệnh của tôi vẫn chưa khỏi."}]'::jsonb, 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_22_1', 'lesson-22', 'Bài khoá #1: Hội thoại giáo trình — Thích nghi', 'Hội thoại chuẩn giáo trình Bài 22. Từ vựng chưa học được chú thích phiên âm & nghĩa trong ngoặc.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_22_1_1', 'txt_22_1', '白茹雪', '玉兰，你怎么了？生病了吗？', '玉兰，你怎么了？生病了吗？', 'Yùlán, nǐ zěnmele? Shēngbìngle ma?', 'Ngọc Lan, cậu sao thế? Bị ốm à?', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_22_1_2', 'txt_22_1', '范玉兰', '昨天下雪了，天挺冷的，所以我好像感冒了。', '昨天下雪了，天 (tiān: ngày, trời)挺冷的，所以 (suǒyǐ: cho nên)我好像感冒了。', 'Zuótiān xià xuěle, tiān tǐng lěng de, suǒyǐ wǒ hǎoxiàng gǎnmào le.', 'Hôm qua trời có tuyết rơi, lạnh lắm, nên hình như tớ bị cảm rồi.', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_22_1_3', 'txt_22_1', '白茹雪', '你还没习惯这里的气候吗？', '你还没 (méi: chưa, không có)习惯这里 (lǐ: trong)的气候吗？', 'Nǐ hái méi xíguàn zhèli de qìhòu ma?', 'Cậu vẫn chưa quen với khí hậu ở đây à?', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_22_1_4', 'txt_22_1', '范玉兰', '还没习惯，因为我家乡冬天不太冷，也不下雪。', '还没 (méi: chưa, không có)习惯，因为我家乡冬天不太冷，也不下雪。', 'Hái méi xíguàn, yīnwèi wǒ jiāxiāng dōngtiān bú tài lěng, yě bú xià xuě.', 'Vẫn chưa quen, vì mùa đông quê tớ không quá lạnh, cũng không có tuyết rơi.', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_22_1_5', 'txt_22_1', '白茹雪', '慢慢就会习惯了。', '慢慢就会习惯了。', 'Mànmàn jiù huì xíguàn le.', 'Dần dần rồi sẽ quen thôi.', 5) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_22_1_6', 'txt_22_1', '范玉兰', '我也希望是这样。出国留学真是不容易啊！', '我也希望是这样。出国留学 (liúxué: du học)真是不容易啊！', 'Wǒ yě xīwàng shì zhèyàng. Chūguó liúxué zhēnshì bù róngyì a!', 'Tớ cũng hy vọng là thế. Đi du học nước ngoài thật sự không dễ dàng chút nào!', 6) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_22_1_7', 'txt_22_1', '白茹雪', '怎么了？你还有什么困难，告诉我吧！我会帮你解决。', '怎么了？你还有什么困难，告诉我吧！我会帮 (bāng: giúp đỡ)你解决。', 'Zěnmele? Nǐ hái yǒu shén me kùnnan, gàosù wǒ ba! Wǒ huì bāng nǐ jiějué.', 'Sao vậy? Cậu còn gặp khó khăn gì cứ nói với tớ! Tớ sẽ giúp cậu giải quyết.', 7) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_22_1_8', 'txt_22_1', '范玉兰', '都是留学生经常遇到的困难，比如文化不同、生活环境不同等等。我们留学生的压力很大。', '都是留学生经常遇到的困难，比如文化不同、生活环境不同等等。我们留学生的压力很大 (dà: to, lớn)。', 'Dōu shì liúxuéshēng jīngcháng yùdào de kùnnan, bǐrú wénhuà bùtóng, shēnghuó huánjìng bùtóng děngděng. Wǒmen liúxuéshēng de yālì hěn dà.', 'Đều là những khó khăn mà du học sinh hay gặp phải thôi, như khác biệt văn hóa, môi trường sống khác nhau, v.v. Áp lực của du học sinh bọn tớ lớn lắm.', 8) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_22_1_9', 'txt_22_1', '白茹雪', '我现在才知道。你们辛苦了。', '我现在才 (cái: mới)知道。你们辛苦了。', 'Wǒ xiànzài cái zhīdao. Nǐmen xīnkǔle.', 'Bây giờ tớ mới biết đấy. Các cậu vất vả quá.', 9) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_22_1_10', 'txt_22_1', '范玉兰', '那些困难我都能自己适应，自己解决。最糟糕的要说到学习问题。刚来中国的时候，因为不习惯这里的学习方法，所以我做什么事都很难。虽然在国内已经学汉语了，但是到中国以后，有很多时候你们说的我听不懂。考试又有很多，要抓紧时间练习。我一点儿也不习惯，哭了很多次。', '那些 (xiē: vài, một ít)困难我都能自己适应，自己解决。最糟糕的要说到学习 (xuéxí: học tập)问题。刚 (gāng: vừa mới)来 (lái: đến)中国的时候，因为不习惯这里 (lǐ: trong)的学习方法，所以 (suǒyǐ: cho nên)我做 (zuò: làm)什么事都很难。虽然在国内 (guónèi: trong nước)已经学 (xué: học)汉语了，但是到中国以后，有很多时候你们说的我听 (tīng: nghe)不懂。考试又有很多，要抓紧时间练习。我一点儿 (ér: con, (âm uốn lưỡi))也不习惯，哭了很多次 (cì: lần)。', 'Nàxiē kùnnan wǒ dōu néng zìjǐ shìyìng, zìjǐ jiějué. Zuì zāogāo de yāo shuō dào xuéxí wèntí. Gāng lái Zhōngguó de shíhou, yīn wèi bù xíguàn zhèli de xuéxí fāngfǎ, suǒ yǐ wǒ zuò shénme shì dōu hěn nán. Suīrán zài guónèi yǐjīng xué Hànyǔ le, dànshì dào Zhōngguó yǐhòu, yǒu hěnduō shíhou nǐmen shuō de wǒ tīng bù dǒng. Kǎoshì yòu yǒu hěnduō, yào zhuā jǐn shíjiān liànxí. Wǒ yīdiǎnr yě bù xíguàn, kūle hěnduō cì.', 'Những khó khăn đó tớ đều có thể tự thích nghi và tự giải quyết. Tệ nhất phải nói đến chuyện học tập. Hồi mới sang Trung Quốc, vì chưa quen phương pháp học ở đây nên làm việc gì cũng thấy khó. Dù ở trong nước đã học tiếng Trung rồi, nhưng sang đây có nhiều lúc các bạn nói tớ nghe không hiểu. Thi cử lại nhiều, phải tranh thủ thời gian luyện tập. Tớ chẳng quen chút nào, đã khóc rất nhiều lần.', 10) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_22_1_11', 'txt_22_1', '白茹雪', '你怎么不跟我们说啊？那时候你一定很难过。', '你怎么不跟 (gēn: cùng, với)我们说啊？那时候你一定 (yīdìng: nhất định)很难过。', 'Nǐ zěnme bù gēn wǒmen shuō a? Nà shíhou nǐ yídìng hěn nánguò.', 'Sao cậu không kể với bọn tớ? Lúc đó chắc cậu buồn lắm.', 11) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_22_1_12', 'txt_22_1', '范玉兰', '没关系！我只要继续努力，相信自己就好。再说，虽然我不说，但是你们也帮助我很多。能到中国，跟你们交朋友，我很幸福。', '没关系！我只要继续努力，相信自己就好。再说，虽然我不说，但是你们也帮助我很多。能到中国，跟 (gēn: cùng, với)你们交 (jiāo: nộp, kết bạn)朋友，我很幸福。', 'Méiguānxi! Wǒ zhǐyào jìxù nǔlì, xiāngxìn zìjǐ jiù hǎo. Zàishuō, suīrán wǒ bù shuō, dànshì nǐmen yě bāngzhù wǒ hěnduō. Néng dào Zhōngguó, gēn nǐmen jiāo péngyou, wǒ hěn xìngfú.', 'Không sao đâu! Chỉ cần tớ tiếp tục cố gắng, tin vào bản thân là được. Hơn nữa, dù tớ không nói ra nhưng các bạn cũng giúp đỡ tớ rất nhiều. Được đến Trung Quốc và kết bạn với các bạn, tớ thấy rất hạnh phúc.', 12) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_22_1_13', 'txt_22_1', '白茹雪', '哪有啊！都是你自己解决，我们没有做什么。', '哪有啊！都是你自己解决，我们没有 (méiyǒu: không có)做 (zuò: làm)什么。', 'Nǎ yǒu a! Dōu shì nǐ zìjǐ jiějué, wǒmen méiyǒu zuò shénme.', 'Đâu có đâu! Đều do cậu tự vượt qua cả, bọn tớ có làm gì đâu.', 13) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_22_1_14', 'txt_22_1', '范玉兰', '其实这些事我出国以前我奶奶已经跟我说了。她年轻的时候也去国外留学，很有经验。', '其实这些 (xiē: vài, một ít)事我出国以前我奶奶已经跟 (gēn: cùng, với)我说了。她年轻的时候也去国外 (guówài: nước ngoài)留学 (liúxué: du học)，很有经验。', 'Qíshí zhèxiē shì wǒ chūguó yǐqián wǒ nǎinai yǐjīng gēn wǒ shuō le. Tā niánqīng de shíhou yě qù guówài liúxué, hěn yǒu jīngyàn.', 'Thực ra những chuyện này trước khi ra nước ngoài bà nội tớ đã dặn dò tớ hết rồi. Thời trẻ bà cũng từng đi du học nên rất có kinh nghiệm.', 14) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_22_1_15', 'txt_22_1', '白茹雪', '到中国留学的时候你多大？', '到中国留学 (liúxué: du học)的时候你多大？', 'Dào Zhōngguó liúxué de shíhou nǐ duōdà?', 'Lúc sang Trung Quốc du học cậu bao nhiêu tuổi?', 15) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_22_1_16', 'txt_22_1', '范玉兰', '十八岁。', '十八岁。', 'Shíbā suì.', 'Mười tám tuổi.', 16) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_22_1_17', 'txt_22_1', '白茹雪', '你奶奶呢？', '你奶奶呢？', 'Nǐ nǎinai ne?', 'Còn bà nội cậu thì sao?', 17) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_22_1_18', 'txt_22_1', '范玉兰', '那时候她才十六岁。', '那时候她才 (cái: mới)十六岁。', 'Nà shíhou tā cái shíliù suì.', 'Lúc đó bà mới mười sáu tuổi thôi.', 18) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_22_1_19', 'txt_22_1', '白茹雪', '这么年轻！你奶奶真棒！你也真棒！对了，你奶奶今年多大年纪了？', '这么年轻！你奶奶真棒！你也真棒！对了，你奶奶今 (jīn: hôm nay, nay)年多大年纪了？', 'Zhème niánqīng! Nǐ nǎinai zhēn bàng! Nǐ yě zhēn bàng! Duìle, nǐ nǎinai jīnnián duōdà niánjì le?', 'Trẻ thế cơ à! Bà nội cậu giỏi thật! Cậu cũng rất giỏi! À, năm nay bà nội cậu bao nhiêu tuổi rồi?', 19) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_22_1_20', 'txt_22_1', '范玉兰', '她今年七十三岁。', '她今 (jīn: hôm nay, nay)年七十三岁。', 'Tā jīnnián qīshísān suì.', 'Năm nay bà 73 tuổi rồi.', 20) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_22_1_21', 'txt_22_1', '白茹雪', '奶奶身体好吗？', '奶奶身体好吗？', 'Nǎinai shēntǐ hǎo ma?', 'Sức khỏe của bà có tốt không?', 21) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_22_1_22', 'txt_22_1', '范玉兰', '她的身体很好。', '她的身体很好。', 'Tā de shēntǐ hěn hǎo.', 'Sức khỏe của bà rất tốt.', 22) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_22_1_1', 'lesson-22', 'txt_22_1', 'listening', 'listening', '玉兰，你怎么了？生病了吗？', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["học sinh tốt, học sinh giỏi","Ngoài trời mưa đã tạnh chưa? Tớ không mang theo ô.","Ngọc Lan, cậu sao thế? Bị ốm à?","con đường này"]'::jsonb, 2, 'Nội dung nghe được: 玉兰，你怎么了？生病了吗？ (Yùlán, nǐ zěnmele? Shēngbìngle ma?) → Ngọc Lan, cậu sao thế? Bị ốm à?', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_22_1_2', 'lesson-22', 'txt_22_1', 'listening', 'listening', '昨天下雪了，天挺冷的，所以我好像感冒了。', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["我二十三岁。","还没 (méi: chưa, không có)习惯，因为我家乡冬天不太冷，也不下雪。","昨天下雪了，天 (tiān: ngày, trời)挺冷的，所以 (suǒyǐ: cho nên)我好像感冒了。","我今 (jīn: hôm nay, nay)年六岁。"]'::jsonb, 2, 'Câu vừa đọc: 昨天下雪了，天挺冷的，所以我好像感冒了。 (Zuótiān xià xuěle, tiān tǐng lěng de, suǒyǐ wǒ hǎoxiàng gǎnmào le.) → Hôm qua trời có tuyết rơi, lạnh lắm, nên hình như tớ bị cảm rồi.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_22_1_3', 'lesson-22', 'txt_22_1', 'listening', 'listening', '你还没习惯这里的气候吗？', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Lúc sang Trung Quốc du học cậu bao nhiêu tuổi?","Cậu vẫn chưa quen với khí hậu ở đây à?","Năm nay bác bao nhiêu tuổi rồi ạ?","Cậu có thể rót cho tớ cốc nước không?"]'::jsonb, 1, 'Nội dung nghe được: 你还没习惯这里的气候吗？ (Nǐ hái méi xíguàn zhèli de qìhòu ma?) → Cậu vẫn chưa quen với khí hậu ở đây à?', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_22_1_4', 'lesson-22', 'txt_22_1', 'listening', 'listening', '还没习惯，因为我家乡冬天不太冷，也不下雪。', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["只要多练习听 (tīng: nghe)力，以后就会听懂的。","你还没 (méi: chưa, không có)习惯这里 (lǐ: trong)的气候吗？","我今 (jīn: hôm nay, nay)年六岁。","还没 (méi: chưa, không có)习惯，因为我家乡冬天不太冷，也不下雪。"]'::jsonb, 3, 'Câu vừa đọc: 还没习惯，因为我家乡冬天不太冷，也不下雪。 (Hái méi xíguàn, yīnwèi wǒ jiāxiāng dōngtiān bú tài lěng, yě bú xià xuě.) → Vẫn chưa quen, vì mùa đông quê tớ không quá lạnh, cũng không có tuyết rơi.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_22_2', 'lesson-22', 'Bài nghe tổng hợp: Ôn tập lũy tiến (Bài 1 – Bài 22)', 'Kết hợp từ vựng & mẫu câu đã học từ Bài 1 đến Bài 21 cùng trọng tâm Bài 22 để củng cố phản xạ nghe.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_22_2_1', 'txt_22_2', 'Ôn Bài 21', '你多运动运动吧！', '你多运动运动吧！', 'Nǐ duō yùndòng yùndòng ba!', 'Con vận động nhiều hơn đi!', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_22_2_2', 'txt_22_2', 'Bài 22', '我吃饭了。', '我吃饭了。', 'Wǒ chīfàn le.', 'Tôi ăn cơm rồi.', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_22_2_3', 'txt_22_2', 'Ôn Bài 11', '他真的这么说。', '他真的这么说。', 'Tā zhēn de zhème shuō.', 'Anh ta thật sự nói như thế.', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_22_2_4', 'txt_22_2', 'Bài 22', '我二十三岁。', '我二十三岁。', 'Wǒ èrshísān suì.', 'Tôi 23 tuổi.', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_22_2_5', 'txt_22_2', 'Ôn Bài 1', '她不是学生吗？', '她不是学生吗？', 'Tā bú shì xuésheng ma?', 'Cô ấy không phải là học sinh à?', 5) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_22_2_6', 'txt_22_2', 'Bài 22', '玉兰，你怎么了？生病了吗？', '玉兰，你怎么了？生病了吗？', 'Yùlán, nǐ zěnmele? Shēngbìngle ma?', 'Ngọc Lan, cậu sao thế? Bị ốm à?', 6) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_22_2_7', 'txt_22_2', 'Ôn Bài 8', '二十五个', '二十五个', 'èrshíwǔ gè', 'Hai mươi lăm cái', 7) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_22_2_8', 'txt_22_2', 'Bài 22', '慢慢就会习惯了。', '慢慢就会习惯了。', 'Mànmàn jiù huì xíguàn le.', 'Dần dần rồi sẽ quen thôi.', 8) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_22_2_1', 'lesson-22', 'txt_22_2', 'listening', 'listening', '你多运动运动吧！', NULL, '[Ôn tập Bài 21] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Chào buổi trưa!","Hai người họ dường như là bạn bè thân thiết đã nhiều năm rồi.","Con vận động nhiều hơn đi!","Hẹn gặp lại vào ngày mai! (Hoặc “Mai gặp nhé!”)"]'::jsonb, 2, 'Nội dung nghe được: 你多运动运动吧！ (Nǐ duō yùndòng yùndòng ba!) → Con vận động nhiều hơn đi!', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_22_2_2', 'lesson-22', 'txt_22_2', 'listening', 'listening', '我吃饭了。', NULL, '[Bài 22] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["玉兰，你怎么了？生病了吗？","我也希望是这样。出国留学 (liúxué: du học)真是不容易啊！","我今 (jīn: hôm nay, nay)年六十岁了。","我吃饭了。"]'::jsonb, 3, 'Câu vừa đọc: 我吃饭了。 (Wǒ chīfàn le.) → Tôi ăn cơm rồi.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_22_2_3', 'lesson-22', 'txt_22_2', 'listening', 'listening', '他真的这么说。', NULL, '[Ôn tập Bài 11] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Cậu là Nhật Minh phải không?","Bệnh viện ở bên phải trường học của chúng ta.","Nếu ngày mai mưa thì chúng tôi sẽ không đi chơi nữa.","Anh ta thật sự nói như thế."]'::jsonb, 3, 'Nội dung nghe được: 他真的这么说。 (Tā zhēn de zhème shuō.) → Anh ta thật sự nói như thế.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_22_2_4', 'lesson-22', 'txt_22_2', 'listening', 'listening', '我二十三岁。', NULL, '[Bài 22] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["我二十三岁。","老师教 (jiāo: Dạy)给了我一个很有效的学习 (xuéxí: học tập)方法。","他昨天没 (méi: chưa, không có)来 (lái: đến)。","你今 (jīn: hôm nay, nay)年多大？"]'::jsonb, 0, 'Câu vừa đọc: 我二十三岁。 (Wǒ èrshísān suì.) → Tôi 23 tuổi.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_22_2_5', 'lesson-22', 'txt_22_2', 'listening', 'listening', '她不是学生吗？', NULL, '[Ôn tập Bài 1] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Hội nghị này, cậu đi hay Minh đi?","Sáng nay cậu gặp anh ấy chưa?","Lúc sang Trung Quốc du học cậu bao nhiêu tuổi?","Cô ấy không phải là học sinh à?"]'::jsonb, 3, 'Nội dung nghe được: 她不是学生吗？ (Tā bú shì xuésheng ma?) → Cô ấy không phải là học sinh à?', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_22_3', 'lesson-22', 'Bài khoá mở rộng: Vượt qua khó khăn khi mới du học (Mở rộng)', 'Hội thoại tình huống mới xây dựng dựa trên từ vựng và ngữ pháp Bài 22 (không trùng lặp nguyên văn giáo trình).', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_22_3_1', 'txt_22_3', 'Lan', '刚来中国的时候，我对这里的气候和学习方法都不太适应。', '刚 (gāng: vừa mới)来 (lái: đến)中国的时候，我对这里 (lǐ: trong)的气候和学习 (xuéxí: học tập)方法都不太适应。', 'Gāng lái Zhōngguó de shíhou, wǒ duì zhèlǐ de qìhòu hé xuéxí fāngfǎ dōu bú tài shìyìng.', 'Hồi mới sang Trung Quốc, tôi đều chưa quen lắm với khí hậu và phương pháp học ở đây.', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_22_3_2', 'txt_22_3', 'Minh', '遇到那些困难的时候，你的压力很大吧？', '遇到那些 (xiē: vài, một ít)困难的时候，你的压力很大 (dà: to, lớn)吧？', 'Yùdào nàxiē kùnnan de shíhou, nǐ de yālì hěn dà ba?', 'Khi gặp những khó khăn đó, chắc áp lực của cậu lớn lắm nhỉ?', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_22_3_3', 'txt_22_3', 'Lan', '是的，不过有朋友鼓励，我也每天努力练习，现在都能听懂了。', '是的，不过 (búguò: nhưng, tuy nhiên)有朋友鼓励，我也每天 (tiān: ngày, trời)努力练习，现在都能听 (tīng: nghe)懂了。', 'Shì de, búguò yǒu péngyou gǔlì, wǒ yě měitiān nǔlì liànxí, xiànzài dōu néng tīng dǒng le.', 'Đúng vậy, nhưng nhờ bạn bè động viên và ngày nào tôi cũng chăm chỉ luyện tập, giờ đã nghe hiểu hết rồi.', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_22_3_4', 'txt_22_3', 'Minh', '太棒了！以后我们还会更加习惯这里的生活。', '太棒了！以后我们还会更 (gèng: càng)加习惯这里 (lǐ: trong)的生活。', 'Tài bàng le! Yǐhòu wǒmen hái huì gèngjiā xíguàn zhèlǐ de shēnghuó.', 'Tuyệt vời! Sau này chúng ta sẽ còn quen với cuộc sống ở đây hơn nữa.', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_22_3_1', 'lesson-22', 'txt_22_3', 'listening', 'listening', '刚来中国的时候，我对这里的气候和学习方法都不太适应。 遇到那些困难的时候，你的压力很大吧？ 是的，不过有朋友鼓励，我也每天努力练习，现在都能听懂了。 太棒了！以后我们还会更加习惯这里的生活。', NULL, '[Nghe hiểu tình huống mới] Nhờ đâu Ngọc Lan đã vượt qua khó khăn nghe giảng không hiểu lúc mới du học?', '["Nhờ bạn bè động viên và chăm chỉ luyện tập mỗi ngày","Vì bỏ hết các tiết học trên lớp","Vì chuyển về quê nhà học","Vì khí hậu bỗng nhiên thay đổi"]'::jsonb, 0, 'Lan chia sẻ: ''有朋友鼓励，我也每天努力练习，现在都能听懂了''.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_22_3_2', 'lesson-22', 'txt_22_3', 'listening', 'listening', '刚来中国的时候，我对这里的气候和学习方法都不太适应。', NULL, '[Mở rộng] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["người Trung Quốc","ba cây bút chì","Hồi mới sang Trung Quốc, tôi đều chưa quen lắm với khí hậu và phương pháp học ở đây.","Ai đấy?"]'::jsonb, 2, 'Nội dung nghe được: 刚来中国的时候，我对这里的气候和学习方法都不太适应。 (Gāng lái Zhōngguó de shíhou, wǒ duì zhèlǐ de qìhòu hé xuéxí fāngfǎ dōu bú tài shìyìng.) → Hồi mới sang Trung Quốc, tôi đều chưa quen lắm với khí hậu và phương pháp học ở đây.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_22_3_3', 'lesson-22', 'txt_22_3', 'listening', 'listening', '遇到那些困难的时候，你的压力很大吧？', NULL, '[Mở rộng] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["你姥姥 (lǎolao: bà ngoại)今 (jīn: hôm nay, nay)年多大年纪？","遇到那些 (xiē: vài, một ít)困难的时候，你的压力很大 (dà: to, lớn)吧？","好了，我同意 (tóngyì: đồng ý)，你别 (bié: đừng)再说了！","我吃饭了。"]'::jsonb, 1, 'Câu vừa đọc: 遇到那些困难的时候，你的压力很大吧？ (Yùdào nàxiē kùnnan de shíhou, nǐ de yālì hěn dà ba?) → Khi gặp những khó khăn đó, chắc áp lực của cậu lớn lắm nhỉ?', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_22_3_4', 'lesson-22', 'txt_22_3', 'listening', 'listening', '是的，不过有朋友鼓励，我也每天努力练习，现在都能听懂了。', NULL, '[Mở rộng] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["cuộc sống hạnh phúc","Bên trái tôi không phải là tòa giảng đường.","Hội nghị này, cậu đi hay Minh đi?","Đúng vậy, nhưng nhờ bạn bè động viên và ngày nào tôi cũng chăm chỉ luyện tập, giờ đã nghe hiểu hết rồi."]'::jsonb, 3, 'Nội dung nghe được: 是的，不过有朋友鼓励，我也每天努力练习，现在都能听懂了。 (Shì de, búguò yǒu péngyou gǔlì, wǒ yě měitiān nǔlì liànxí, xiànzài dōu néng tīng dǒng le.) → Đúng vậy, nhưng nhờ bạn bè động viên và ngày nào tôi cũng chăm chỉ luyện tập, giờ đã nghe hiểu hết rồi.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss22_1', 'lesson-22', '只要多练习听力以后就会听懂的', '[Mở rộng] Chỉ cần luyện nghe nhiều thì sau này sẽ nghe hiểu thôi.', 'Zhǐyào duō liànxí tīnglì, yǐhòu jiù huì tīng dǒng de.', '["只要多","练习","听力","以后","就会听","懂的"]'::jsonb, 'Từ chưa học: 听 (tīng: nghe)', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
