INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq22_13', 'lesson-22', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “压力” chứa bộ thủ nào sau đây?', '["Bộ cấu tạo [气] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","木 (Mộc) (Cây cối, gỗ)","口 (Khẩu) (Miệng, ăn uống, lời nói)","力 (Lực) (Sức mạnh, động lực)"]'::jsonb, 3, 'Chữ “压力” có 力 (Lực) (Sức mạnh, động lực). Ghép từ các chữ Hán: [压] + [力].', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq22_14', 'lesson-22', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “困难” chứa bộ thủ nào sau đây?', '["Bộ cấu tạo [相] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [再] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [困] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [没] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)"]'::jsonb, 2, 'Chữ “困难” có Bộ cấu tạo [困] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán). Ghép từ các chữ Hán: [困] + [难].', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq22_15', 'lesson-22', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “问题” chứa bộ thủ nào sau đây?', '["Bộ cấu tạo [问] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","口 (Khẩu) (Miệng, ăn uống, lời nói)","Bộ cấu tạo [困] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [家] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)"]'::jsonb, 0, 'Chữ “问题” có Bộ cấu tạo [问] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán). Ghép từ các chữ Hán: [问] + [题].', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq22_16', 'lesson-22', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “方法” chứa bộ thủ nào sau đây?', '["Bộ cấu tạo [不] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [虽] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","方 (Phương) (Vuông vức, phương hướng)","Bộ cấu tạo [解] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)"]'::jsonb, 2, 'Chữ “方法” có 方 (Phương) (Vuông vức, phương hướng). Ghép từ các chữ Hán: [方] + [法].', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq22_17', 'lesson-22', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 16] Từ đã học “休息” (xiūxi) có nghĩa là gì?', '["bữa cơm tất niên","nhiều","màu vàng","nghỉ ngơi"]'::jsonb, 3, 'Ôn tập Bài 16: “休息” (xiūxi) nghĩa là: nghỉ ngơi.', 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq22_18', 'lesson-22', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 16] Từ đã học “逛街” (guàngjiē) có nghĩa là gì?', '["sủi cảo","chúc mừng năm mới","ngoài ra, hơn nữa","dạo phố"]'::jsonb, 3, 'Ôn tập Bài 16: “逛街” (guàngjiē) nghĩa là: dạo phố.', 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq22_19', 'lesson-22', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 10] Từ đã học “等等” (děng děng) có nghĩa là gì?', '["ồn ào, náo nhiệt","cây","lân cận, gần đây","vân vân"]'::jsonb, 3, 'Ôn tập Bài 10: “等等” (děng děng) nghĩa là: vân vân.', 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq22_20', 'lesson-22', NULL, 'expanded_quiz', 'reading', NULL, NULL, '[Mở rộng] Câu “慢慢适应新环境以后，我的压力小多了。” có nghĩa tiếng Việt là gì?', '["Quyển sách đó ở ngay trên bàn.","Hình như tớ quen người này.","Sau khi dần thích nghi với môi trường mới, áp lực của tôi giảm đi nhiều rồi.","Tôi vẫn chưa chuẩn bị xong bài khóa ngày mai."]'::jsonb, 2, '慢慢适应新环境以后，我的压力小多了。 (Mànmàn shìyìng xīn huánjìng yǐhòu, wǒ de yālì xiǎo duō le.) → Sau khi dần thích nghi với môi trường mới, áp lực của tôi giảm đi nhiều rồi.', 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq22_21', 'lesson-22', NULL, 'expanded_quiz', 'reading', NULL, NULL, '[Đọc hiểu mở rộng] Đọc đoạn hội thoại:
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq22_22', 'lesson-22', NULL, 'expanded_quiz', 'reading', NULL, NULL, 'Câu “我吃饭了。” có nghĩa tiếng Việt là gì?', '["Tôi 23 tuổi.","Tôi ăn cơm rồi.","Anh ấy hát không hay lắm.","Năm nay tôi 60 rồi."]'::jsonb, 1, '我吃饭了。 (Wǒ chīfàn le.) → Tôi ăn cơm rồi.', 22) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct22_1', 'lesson-22', NULL, 'comprehensive_test', 'listening', '刚来中国的时候，我对这里的气候和学习方法都不太适应。', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Hồi mới sang Trung Quốc, tôi đều chưa quen lắm với khí hậu và phương pháp học ở đây.","Chờ tôi một lát, đây là ảnh gia đình tôi, cho bạn xem này.","Sức khỏe của bà có tốt không?","Cơ thể con sao rồi?"]'::jsonb, 0, 'Nội dung nghe được: “刚来中国的时候，我对这里的气候和学习方法都不太适应。” (Gāng lái Zhōngguó de shíhou, wǒ duì zhèlǐ de qìhòu hé xuéxí fāngfǎ dōu bú tài shìyìng.) → Hồi mới sang Trung Quốc, tôi đều chưa quen lắm với khí hậu và phương pháp học ở đây.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct22_2', 'lesson-22', NULL, 'comprehensive_test', 'listening', '慢慢就会习惯了。', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["慢慢就会习惯了。","你今年去留学还是明年去？","你看这个蓝色的书包，好看吗？","你放心吧！"]'::jsonb, 0, 'Câu vừa đọc: “慢慢就会习惯了。” (Mànmàn jiù huì xíguàn le.) → Dần dần rồi sẽ quen thôi.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct22_3', 'lesson-22', NULL, 'comprehensive_test', 'listening', '怎么了？你还有什么困难，告诉我吧！我会帮你解决。', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["3 giờ 15 phút. Khi nào bạn đi?","Trương Phong, bạn có biết hiệu sách ở đâu không?","Bạn cố gắng như vậy, nhất định rất mệt nhỉ?","Sao vậy? Cậu còn gặp khó khăn gì cứ nói với tớ! Tớ sẽ giúp cậu giải quyết."]'::jsonb, 3, 'Nội dung nghe được: “怎么了？你还有什么困难，告诉我吧！我会帮你解决。” (Zěnmele? Nǐ hái yǒu shén me kùnnan, gàosù wǒ ba! Wǒ huì bāng nǐ jiějué.) → Sao vậy? Cậu còn gặp khó khăn gì cứ nói với tớ! Tớ sẽ giúp cậu giải quyết.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct22_4', 'lesson-22', NULL, 'comprehensive_test', 'listening', '玉兰，你怎么了？生病了吗？', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["我昨天睡得挺晚的，所以今天有点儿困！","玉兰，你怎么了？生病了吗？","好。总共 53 块。","你得多锻炼了。"]'::jsonb, 1, 'Câu vừa đọc: “玉兰，你怎么了？生病了吗？” (Yùlán, nǐ zěnmele? Shēngbìngle ma?) → Ngọc Lan, cậu sao thế? Bị ốm à?', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct22_5', 'lesson-22', NULL, 'comprehensive_test', 'listening', '还没习惯，因为我家乡冬天不太冷，也不下雪。', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Rất nhiệt tình và hiếu khách, tôi còn kết quen được một người bạn rất tốt.","Đến ngã tư phía trước kia thì rẽ phải.","Giá trên mạng có rẻ không? Chất lượng có tốt không?","Vẫn chưa quen, vì mùa đông quê tớ không quá lạnh, cũng không có tuyết rơi."]'::jsonb, 3, 'Nội dung nghe được: “还没习惯，因为我家乡冬天不太冷，也不下雪。” (Hái méi xíguàn, yīnwèi wǒ jiāxiāng dōngtiān bú tài lěng, yě bú xià xuě.) → Vẫn chưa quen, vì mùa đông quê tớ không quá lạnh, cũng không có tuyết rơi.', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct22_6', 'lesson-22', NULL, 'comprehensive_test', 'listening', '用手机上网购物非常方便', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["用手机上网购物非常方便","三个朋友","我喜欢一边喝水一边听音乐","你的前面是城市图书馆。"]'::jsonb, 0, 'Câu vừa đọc: “用手机上网购物非常方便” (Yòng shǒujī shàngwǎng gòuwù fēicháng fāngbiàn.) → Dùng điện thoại lên mạng mua sắm vô cùng tiện lợi.', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct22_7', 'lesson-22', NULL, 'comprehensive_test', 'listening', '只要多练习听力以后就会听懂的', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Con cố gắng học hành đi!","Chỉ cần luyện nghe nhiều thì sau này sẽ nghe hiểu thôi.","Anh ta mời tôi ngày mai tới nhà dùng cơm.","Ghen tị với bạn quá đi! Kỳ nghỉ hè năm nay tôi cũng sẽ đi du lịch Bắc Kinh."]'::jsonb, 1, 'Nội dung nghe được: “只要多练习听力以后就会听懂的” (Zhǐyào duō liànxí tīnglì, yǐhòu jiù huì tīng dǒng de.) → Chỉ cần luyện nghe nhiều thì sau này sẽ nghe hiểu thôi.', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct22_8', 'lesson-22', NULL, 'comprehensive_test', 'listening', '我的病还没好。', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["秋天呢？","这是 60 块，找你 7 块。谢谢！","我的病还没好。","下星期六是我妹妹的生日"]'::jsonb, 2, 'Câu vừa đọc: “我的病还没好。” (Wǒ de bìng hái méi hǎo.) → Bệnh của tôi vẫn chưa khỏi.', 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
