INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v23_1', 'lesson-23', '饮食', 'yǐnshí', 'thực', 'đồ ăn thức uống', 'Danh từ / Động từ', '食 (Thực) (Đồ ăn, ẩm thực)', 'Ghép từ các chữ Hán: [饮] + [食].', 'Kết hợp các thành tố [饮] + [食] để tạo thành từ mang nghĩa ''đồ ăn thức uống''.', '这是关于“饮食”的常用句子。', 'Zhè shì guānyú ''yǐnshí'' de chángyòng jùzi.', 'Đây là câu ví dụ sử dụng từ ''饮食'' (đồ ăn thức uống).', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v23_2', 'lesson-23', '饮料', 'yǐnliào', 'từ Hán ngữ', 'đồ uống, thức uống', 'Danh từ', 'Bộ cấu tạo [饮] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [饮] + [料].', 'Kết hợp các thành tố [饮] + [料] để tạo thành từ mang nghĩa ''đồ uống, thức uống''.', '中国的饮料呢？', 'Zhōngguó de yǐnliào ne?', 'Còn đồ uống ở Trung Quốc thì sao?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v23_3', 'lesson-23', '主食', 'zhǔshí', 'thực', 'món chính, thức ăn chính', 'Danh từ', '食 (Thực) (Đồ ăn, ẩm thực)', 'Ghép từ các chữ Hán: [主] + [食].', 'Kết hợp các thành tố [主] + [食] để tạo thành từ mang nghĩa ''món chính, thức ăn chính''.', '是吗？下次我会尝一尝。那中国人的主食是什么？', 'Shì ma? Xià cì wǒ huì cháng yi cháng. Nà Zhōngguó rén de zhǔshí shì shénme?', 'Thật sao? Lần sau tớ sẽ nếm thử xem. Vậy lương thực chính của người Trung Quốc là gì?', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v23_4', 'lesson-23', '味道', 'wèidào/wèidao', 'vị đạo', 'vị, mùi vị, mùi', 'Danh từ', 'Bộ cấu tạo [味] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [味] + [道].', 'Kết hợp các thành tố [味] + [道] để tạo thành từ mang nghĩa ''vị, mùi vị, mùi''.', '小雪，中国人常吃什么味道的菜？', 'Xiǎoxuě, Zhōngguó rén cháng chī shénme wèidao de cài?', 'Tiểu Tuyết, người Trung Quốc thường ăn các món có hương vị như thế nào?', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v23_5', 'lesson-23', '面包', 'miànbāo', 'bao', 'bánh mì', 'Danh từ', 'Bộ cấu tạo [面] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [面] + [包].', 'Kết hợp các thành tố [面] + [包] để tạo thành từ mang nghĩa ''bánh mì''.', '中国人常说：“南米北面”，意思是北方人的主食是馒头、面包和小麦，南方人的主食是米饭。', 'Zhōngguó rén cháng shuō: “Nán mǐ Běi miàn”, yìsi shì Běifāng rén de zhǔshí shì mántou, miànbāo hé xiǎomài, Nánfāng rén de zhǔshí shì mǐfàn.', 'Người Trung Quốc hay nói ''Nam cơm Bắc mì'', nghĩa là món chính của người miền Bắc là màn thầu, bánh mì và lúa mì, còn người miền Nam là cơm.', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v23_6', 'lesson-23', '馒头', 'mántou', 'từ Hán ngữ', 'bánh màn thầu', 'Danh từ', 'Bộ cấu tạo [馒] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [馒] + [头].', 'Kết hợp các thành tố [馒] + [头] để tạo thành từ mang nghĩa ''bánh màn thầu''.', '中国人常说：“南米北面”，意思是北方人的主食是馒头、面包和小麦，南方人的主食是米饭。', 'Zhōngguó rén cháng shuō: “Nán mǐ Běi miàn”, yìsi shì Běifāng rén de zhǔshí shì mántou, miànbāo hé xiǎomài, Nánfāng rén de zhǔshí shì mǐfàn.', 'Người Trung Quốc hay nói ''Nam cơm Bắc mì'', nghĩa là món chính của người miền Bắc là màn thầu, bánh mì và lúa mì, còn người miền Nam là cơm.', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v23_7', 'lesson-23', '小麦', 'xiǎomài', 'tiểu', 'tiểu mạch, lúa mì', 'Danh từ', '小 (Tiểu) (Nhỏ bé, ít ỏi)', 'Ghép từ các chữ Hán: [小] + [麦].', 'Kết hợp các thành tố [小] + [麦] để tạo thành từ mang nghĩa ''tiểu mạch, lúa mì''.', '中国人常说：“南米北面”，意思是北方人的主食是馒头、面包和小麦，南方人的主食是米饭。', 'Zhōngguó rén cháng shuō: “Nán mǐ Běi miàn”, yìsi shì Běifāng rén de zhǔshí shì mántou, miànbāo hé xiǎomài, Nánfāng rén de zhǔshí shì mǐfàn.', 'Người Trung Quốc hay nói ''Nam cơm Bắc mì'', nghĩa là món chính của người miền Bắc là màn thầu, bánh mì và lúa mì, còn người miền Nam là cơm.', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v23_8', 'lesson-23', '臭豆腐', 'chòudòufu', 'từ Hán ngữ', 'đậu phụ thối', 'Danh từ', 'Bộ cấu tạo [臭] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [臭] + [豆] + [腐].', 'Kết hợp các thành tố [臭] + [豆] + [腐] để tạo thành từ mang nghĩa ''đậu phụ thối''.', '有，中国的臭豆腐。真的太难吃了。我来中国快要三个月了，可是到现在还不能吃，闻也不行。', 'Yǒu, Zhōngguó de Chòudòufu. Zhēn de tài nán chī le. Wǒ lái Zhōngguó kuàiyào sān gè yuè le, kěshì dào xiànzài hái bùnéng chī, wén yě bùxíng.', 'Có chứ, đậu phụ thối của Trung Quốc. Thật sự khó ăn quá. Tớ sang Trung Quốc gần ba tháng rồi mà đến giờ vẫn không ăn nổi, ngửi cũng không chịu được.', 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v23_9', 'lesson-23', '年糕', 'niángāo', 'niên cao', 'Bánh Tổ (món đặc trưng vào dịp tết ở các tỉnh miền Nam Trung Quốc)', 'Danh từ', 'Bộ cấu tạo [年] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [年] + [糕].', 'Kết hợp các thành tố [年] + [糕] để tạo thành từ mang nghĩa ''Bánh Tổ (món đặc trưng vào dịp tết ở các tỉnh miền Nam Trung Quốc)''.', '中国北方人习惯吃饺子，南方人喜欢吃年糕。春节是一年最快乐的时候。家人开开心心地坐在一起，一起包饺子，煮饺子。', 'Zhōngguó běifāng rén xíguàn chī jiǎozi, nánfāng rén xǐhuan chī niángāo. Chūnjié shì yī nián zuì kuàilè de shíhou. Jiārén kāi kāi xīn xīn de zuò zài yīqǐ, yīqǐ bāo jiǎozi, zhǔ jiǎozi.', 'Người miền Bắc Trung Quốc quen ăn sủi cảo, người miền Nam thích ăn bánh tổ. Tết là dịp vui nhất trong năm. Cả nhà quây quần vui vẻ bên nhau, cùng gói và luộc sủi cảo.', 9) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v23_10', 'lesson-23', '碗', 'wǎn', 'từ Hán ngữ', 'cái bát', 'Danh từ', 'Bộ cấu tạo [碗] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Chữ độc thể / hình thanh gồm Bộ cấu tạo [碗] và các nét bổ trợ.', 'Ghi nhớ chữ [碗] (cái bát) qua hình tượng Thành phần biểu ý/biểu âm cơ bản trong chữ Hán.', '这是关于“碗”的常用句子。', 'Zhè shì guānyú ''wǎn'' de chángyòng jùzi.', 'Đây là câu ví dụ sử dụng từ ''碗'' (cái bát).', 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v23_11', 'lesson-23', '红酒', 'hóngjiǔ', 'hồng', 'rượu vang', 'Danh từ', 'Bộ cấu tạo [红] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [红] + [酒].', 'Kết hợp các thành tố [红] + [酒] để tạo thành từ mang nghĩa ''rượu vang''.', '中国人常喝啤酒、白酒、红酒还有茶。如果你到中国人家里去做客，他们就会请你喝酒。', 'Zhōngguó rén cháng hē píjiǔ, báijiǔ, hóngjiǔ hái yǒu chá. Rúguǒ nǐ dào Zhōngguó rén jiāli qù zuòkè, tāmen jiù huì qǐng nǐ hē jiǔ.', 'Người Trung Quốc hay uống bia, rượu trắng, rượu vang đỏ và trà. Nếu cậu đến nhà người Trung Quốc làm khách, họ sẽ mời cậu uống rượu.', 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v23_12', 'lesson-23', '啤酒', 'píjiǔ', 'từ Hán ngữ', 'bia', 'Danh từ', 'Bộ cấu tạo [啤] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [啤] + [酒].', 'Kết hợp các thành tố [啤] + [酒] để tạo thành từ mang nghĩa ''bia''.', '中国人常喝啤酒、白酒、红酒还有茶。如果你到中国人家里去做客，他们就会请你喝酒。', 'Zhōngguó rén cháng hē píjiǔ, báijiǔ, hóngjiǔ hái yǒu chá. Rúguǒ nǐ dào Zhōngguó rén jiāli qù zuòkè, tāmen jiù huì qǐng nǐ hē jiǔ.', 'Người Trung Quốc hay uống bia, rượu trắng, rượu vang đỏ và trà. Nếu cậu đến nhà người Trung Quốc làm khách, họ sẽ mời cậu uống rượu.', 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v23_13', 'lesson-23', '白酒', 'báijiǔ', 'bạch', 'rượu trắng', 'Danh từ', '白 (Bạch) (Màu trắng, sáng tỏ)', 'Ghép từ các chữ Hán: [白] + [酒].', 'Kết hợp các thành tố [白] + [酒] để tạo thành từ mang nghĩa ''rượu trắng''.', '中国人常喝啤酒、白酒、红酒还有茶。如果你到中国人家里去做客，他们就会请你喝酒。', 'Zhōngguó rén cháng hē píjiǔ, báijiǔ, hóngjiǔ hái yǒu chá. Rúguǒ nǐ dào Zhōngguó rén jiāli qù zuòkè, tāmen jiù huì qǐng nǐ hē jiǔ.', 'Người Trung Quốc hay uống bia, rượu trắng, rượu vang đỏ và trà. Nếu cậu đến nhà người Trung Quốc làm khách, họ sẽ mời cậu uống rượu.', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v23_14', 'lesson-23', '北方', 'běifāng', 'từ Hán ngữ', 'phương Bắc, miền Bắc', 'Danh từ', '方 (Phương) (Vuông vức, phương hướng)', 'Ghép từ các chữ Hán: [北] + [方].', 'Kết hợp các thành tố [北] + [方] để tạo thành từ mang nghĩa ''phương Bắc, miền Bắc''.', '在中国，不同地方菜的味道不同，比如：南方人常吃甜的、北方人吃咸的、东部的人吃酸的、西部人吃辣的。', 'Zài Zhōngguó, bùtóng dìfang cài de wèidao bùtóng, bǐrú: Nánfāng rén cháng chī tián de, Běifāng rén chī xián de, Dōngbù de rén chī suān de, Xībù rén chī là de.', 'Ở Trung Quốc, hương vị món ăn từng vùng khác nhau, ví dụ: người miền Nam hay ăn ngọt, miền Bắc ăn mặn, miền Đông ăn chua, còn miền Tây ăn cay.', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v23_15', 'lesson-23', '南方', 'nánfāng', 'Nam', 'phương Nam, miền Nam', 'Danh từ', '方 (Phương) (Vuông vức, phương hướng)', 'Ghép từ các chữ Hán: [南] + [方].', 'Kết hợp các thành tố [南] + [方] để tạo thành từ mang nghĩa ''phương Nam, miền Nam''.', '在中国，不同地方菜的味道不同，比如：南方人常吃甜的、北方人吃咸的、东部的人吃酸的、西部人吃辣的。', 'Zài Zhōngguó, bùtóng dìfang cài de wèidao bùtóng, bǐrú: Nánfāng rén cháng chī tián de, Běifāng rén chī xián de, Dōngbù de rén chī suān de, Xībù rén chī là de.', 'Ở Trung Quốc, hương vị món ăn từng vùng khác nhau, ví dụ: người miền Nam hay ăn ngọt, miền Bắc ăn mặn, miền Đông ăn chua, còn miền Tây ăn cay.', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v23_16', 'lesson-23', '东部', 'dōngbù', 'từ Hán ngữ', 'miền Đông, vùng phía Đông', 'Danh từ', 'Bộ cấu tạo [东] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [东] + [部].', 'Kết hợp các thành tố [东] + [部] để tạo thành từ mang nghĩa ''miền Đông, vùng phía Đông''.', '在中国，不同地方菜的味道不同，比如：南方人常吃甜的、北方人吃咸的、东部的人吃酸的、西部人吃辣的。', 'Zài Zhōngguó, bùtóng dìfang cài de wèidao bùtóng, bǐrú: Nánfāng rén cháng chī tián de, Běifāng rén chī xián de, Dōngbù de rén chī suān de, Xībù rén chī là de.', 'Ở Trung Quốc, hương vị món ăn từng vùng khác nhau, ví dụ: người miền Nam hay ăn ngọt, miền Bắc ăn mặn, miền Đông ăn chua, còn miền Tây ăn cay.', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v23_17', 'lesson-23', '西部', 'xībù', 'tây', 'miền Tây, vùng phía Tây', 'Danh từ', 'Bộ cấu tạo [西] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [西] + [部].', 'Kết hợp các thành tố [西] + [部] để tạo thành từ mang nghĩa ''miền Tây, vùng phía Tây''.', '在中国，不同地方菜的味道不同，比如：南方人常吃甜的、北方人吃咸的、东部的人吃酸的、西部人吃辣的。', 'Zài Zhōngguó, bùtóng dìfang cài de wèidao bùtóng, bǐrú: Nánfāng rén cháng chī tián de, Běifāng rén chī xián de, Dōngbù de rén chī suān de, Xībù rén chī là de.', 'Ở Trung Quốc, hương vị món ăn từng vùng khác nhau, ví dụ: người miền Nam hay ăn ngọt, miền Bắc ăn mặn, miền Đông ăn chua, còn miền Tây ăn cay.', 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v23_18', 'lesson-23', '外国', 'wàiguó', 'quốc', 'nước ngoài', 'Danh từ', 'Bộ cấu tạo [外] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [外] + [国].', 'Kết hợp các thành tố [外] + [国] để tạo thành từ mang nghĩa ''nước ngoài''.', '好像大多数外国人都跟你一样，都不喜欢它的味道，但是如果你吃了一两次，你会觉得它很好吃！', 'Hǎoxiàng dàduōshù wàiguó rén dōu gēn nǐ yíyàng, dōu bù xǐhuan tā de wèidào, dànshì rúguǒ nǐ chīle yī liǎng cì, nǐ huì juéde tā hěn hǎo chī!', 'Hình như đa số người nước ngoài đều giống cậu, không thích mùi vị của nó, nhưng nếu ăn thử một hai lần cậu sẽ thấy nó rất ngon đấy!', 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v23_19', 'lesson-23', '煮', 'zhǔ', 'từ Hán ngữ', 'nấu, đun, luộc', 'Động từ', 'Bộ cấu tạo [煮] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Chữ độc thể / hình thanh gồm Bộ cấu tạo [煮] và các nét bổ trợ.', 'Ghi nhớ chữ [煮] (nấu, đun, luộc) qua hình tượng Thành phần biểu ý/biểu âm cơ bản trong chữ Hán.', '中国北方人习惯吃饺子，南方人喜欢吃年糕。春节是一年最快乐的时候。家人开开心心地坐在一起，一起包饺子，煮饺子。', 'Zhōngguó běifāng rén xíguàn chī jiǎozi, nánfāng rén xǐhuan chī niángāo. Chūnjié shì yī nián zuì kuàilè de shíhou. Jiārén kāi kāi xīn xīn de zuò zài yīqǐ, yīqǐ bāo jiǎozi, zhǔ jiǎozi.', 'Người miền Bắc Trung Quốc quen ăn sủi cảo, người miền Nam thích ăn bánh tổ. Tết là dịp vui nhất trong năm. Cả nhà quây quần vui vẻ bên nhau, cùng gói và luộc sủi cảo.', 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v23_20', 'lesson-23', '闻', 'wén', 'từ Hán ngữ', 'ngửi, nghe', 'Động từ', 'Bộ cấu tạo [闻] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Chữ độc thể / hình thanh gồm Bộ cấu tạo [闻] và các nét bổ trợ.', 'Ghi nhớ chữ [闻] (ngửi, nghe) qua hình tượng Thành phần biểu ý/biểu âm cơ bản trong chữ Hán.', '有，中国的臭豆腐。真的太难吃了。我来中国快要三个月了，可是到现在还不能吃，闻也不行。', 'Yǒu, Zhōngguó de Chòudòufu. Zhēn de tài nán chī le. Wǒ lái Zhōngguó kuàiyào sān gè yuè le, kěshì dào xiànzài hái bùnéng chī, wén yě bùxíng.', 'Có chứ, đậu phụ thối của Trung Quốc. Thật sự khó ăn quá. Tớ sang Trung Quốc gần ba tháng rồi mà đến giờ vẫn không ăn nổi, ngửi cũng không chịu được.', 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v23_21', 'lesson-23', '用', 'yòng', 'từ Hán ngữ', 'dùng', 'Động từ', 'Bộ cấu tạo [用] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Chữ độc thể / hình thanh gồm Bộ cấu tạo [用] và các nét bổ trợ.', 'Ghi nhớ chữ [用] (dùng) qua hình tượng Thành phần biểu ý/biểu âm cơ bản trong chữ Hán.', '那也没关系。你可以用茶来代替也行。', 'Nà yě méiguānxi. Nǐ kěyǐ yòng chá lái dàitì yě xíng.', 'Cũng không sao cả. Cậu có thể dùng trà thay thế cũng được.', 21) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v23_22', 'lesson-23', '代替', 'dàitì', 'từ Hán ngữ', 'thay,  thế', 'Động từ', 'Bộ cấu tạo [代] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [代] + [替].', 'Kết hợp các thành tố [代] + [替] để tạo thành từ mang nghĩa ''thay,  thế''.', '那也没关系。你可以用茶来代替也行。', 'Nà yě méiguānxi. Nǐ kěyǐ yòng chá lái dàitì yě xíng.', 'Cũng không sao cả. Cậu có thể dùng trà thay thế cũng được.', 22) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v23_23', 'lesson-23', '教', 'jiāo/jiào', 'giáo', 'Dạy (Khi 教 đứng 1 mình thì thanh điệu của nó là thanh 1)', 'Động từ', 'Bộ cấu tạo [教] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Chữ độc thể / hình thanh gồm Bộ cấu tạo [教] và các nét bổ trợ.', 'Ghi nhớ chữ [教] (Dạy (Khi 教 đứng 1 mình thì thanh điệu của nó là thanh 1)) qua hình tượng Thành phần biểu ý/biểu âm cơ bản trong chữ Hán.', '哇，你会包饺子吗？我特别喜欢吃饺子，但是不会包饺子。你可以教我吗？', 'Wa, nǐ huì bāo jiǎozi ma? Wǒ tèbié xǐhuan chī jiǎozi, dànshì bú huì bāo jiǎozi. Nǐ kěyǐ jiào wǒ ma?', 'Chà, cậu biết gói sủi cảo không? Tớ đặc biệt thích ăn sủi cảo nhưng lại không biết gói. Cậu dạy tớ được không?', 23) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v23_24', 'lesson-23', '臭', 'chòu', 'từ Hán ngữ', 'hôi, thối, ôi (mùi)', 'Tính từ', 'Bộ cấu tạo [臭] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Chữ độc thể / hình thanh gồm Bộ cấu tạo [臭] và các nét bổ trợ.', 'Ghi nhớ chữ [臭] (hôi, thối, ôi (mùi)) qua hình tượng Thành phần biểu ý/biểu âm cơ bản trong chữ Hán.', '有，中国的臭豆腐。真的太难吃了。我来中国快要三个月了，可是到现在还不能吃，闻也不行。', 'Yǒu, Zhōngguó de Chòudòufu. Zhēn de tài nán chī le. Wǒ lái Zhōngguó kuàiyào sān gè yuè le, kěshì dào xiànzài hái bùnéng chī, wén yě bùxíng.', 'Có chứ, đậu phụ thối của Trung Quốc. Thật sự khó ăn quá. Tớ sang Trung Quốc gần ba tháng rồi mà đến giờ vẫn không ăn nổi, ngửi cũng không chịu được.', 24) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v23_25', 'lesson-23', '辣', 'là', 'từ Hán ngữ', 'cay', 'Tính từ', 'Bộ cấu tạo [辣] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Chữ độc thể / hình thanh gồm Bộ cấu tạo [辣] và các nét bổ trợ.', 'Ghi nhớ chữ [辣] (cay) qua hình tượng Thành phần biểu ý/biểu âm cơ bản trong chữ Hán.', '你好像不太喜欢吃辣的。', 'Nǐ hǎoxiàng bú tài xǐhuan chī là de.', 'Hình như cậu không thích ăn cay.', 25) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v23_26', 'lesson-23', '咸', 'xián', 'từ Hán ngữ', 'mặn', 'Tính từ', 'Bộ cấu tạo [咸] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Chữ độc thể / hình thanh gồm Bộ cấu tạo [咸] và các nét bổ trợ.', 'Ghi nhớ chữ [咸] (mặn) qua hình tượng Thành phần biểu ý/biểu âm cơ bản trong chữ Hán.', '在中国，不同地方菜的味道不同，比如：南方人常吃甜的、北方人吃咸的、东部的人吃酸的、西部人吃辣的。', 'Zài Zhōngguó, bùtóng dìfang cài de wèidao bùtóng, bǐrú: Nánfāng rén cháng chī tián de, Běifāng rén chī xián de, Dōngbù de rén chī suān de, Xībù rén chī là de.', 'Ở Trung Quốc, hương vị món ăn từng vùng khác nhau, ví dụ: người miền Nam hay ăn ngọt, miền Bắc ăn mặn, miền Đông ăn chua, còn miền Tây ăn cay.', 26) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v23_27', 'lesson-23', '行', 'xíng', 'hành', 'được ( mức độ có thể chấp nhận được)', 'Động từ', 'Bộ cấu tạo [行] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Chữ độc thể / hình thanh gồm Bộ cấu tạo [行] và các nét bổ trợ.', 'Ghi nhớ chữ [行] (được ( mức độ có thể chấp nhận được)) qua hình tượng Thành phần biểu ý/biểu âm cơ bản trong chữ Hán.', '有，中国的臭豆腐。真的太难吃了。我来中国快要三个月了，可是到现在还不能吃，闻也不行。', 'Yǒu, Zhōngguó de Chòudòufu. Zhēn de tài nán chī le. Wǒ lái Zhōngguó kuàiyào sān gè yuè le, kěshì dào xiànzài hái bùnéng chī, wén yě bùxíng.', 'Có chứ, đậu phụ thối của Trung Quốc. Thật sự khó ăn quá. Tớ sang Trung Quốc gần ba tháng rồi mà đến giờ vẫn không ăn nổi, ngửi cũng không chịu được.', 27) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v23_28', 'lesson-23', '地', 'de', 'địa', 'liên kết trạng từ và trung tâm ngữ (không có nghĩa)', 'Trợ từ', 'Bộ cấu tạo [地] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Chữ độc thể / hình thanh gồm Bộ cấu tạo [地] và các nét bổ trợ.', 'Ghi nhớ chữ [地] (liên kết trạng từ và trung tâm ngữ (không có nghĩa)) qua hình tượng Thành phần biểu ý/biểu âm cơ bản trong chữ Hán.', '他高高兴兴地对我讲故事。', 'Tā gāogāoxìngxìng de duì wǒ jiǎng gùshì.', 'Anh ấy kể chuyện cho tôi nghe một cách hạnh phúc.', 28) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v23_29', 'lesson-23', '可是', 'kěshì', 'thị', 'nhưng', 'Liên từ', 'Bộ cấu tạo [可] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [可] + [是].', 'Kết hợp các thành tố [可] + [是] để tạo thành từ mang nghĩa ''nhưng''.', '有，中国的臭豆腐。真的太难吃了。我来中国快要三个月了，可是到现在还不能吃，闻也不行。', 'Yǒu, Zhōngguó de Chòudòufu. Zhēn de tài nán chī le. Wǒ lái Zhōngguó kuàiyào sān gè yuè le, kěshì dào xiànzài hái bùnéng chī, wén yě bùxíng.', 'Có chứ, đậu phụ thối của Trung Quốc. Thật sự khó ăn quá. Tớ sang Trung Quốc gần ba tháng rồi mà đến giờ vẫn không ăn nổi, ngửi cũng không chịu được.', 29) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g23_1', 'lesson-23', '1. Trợ từ động thái 了', 'Động từ + 了+ số lượng từ + O', ' Trợ từ động thái 了 gắn liền với nhiều vấn đề ngữ pháp phức tạp nhưng trong giới hạn giáo trình này chúng tôi xin phép trình bày hai công thức phổ biểu với mục đích biểu thị động tác đã hoàn thành và đã thực hiện: Cấu trúc 1: 她吃了三个饺子。 Tā chīle sān gè', NULL, '[{"hanzi":"她吃了三个饺子。","pinyin":"Tā chīle sān gè jiǎozi.","meaning":"Cô ấy đã ăn 3 cái sủi cảo."},{"hanzi":"昨天我们一起去书店，他买了一本词典。","pinyin":"Zuótiān wǒmen yīqǐ qù shūdiàn, tā mǎile yī běn cídiǎn.","meaning":"Hôm qua chúng tôi đi hiệu sách, anh ấy đã mua một cuốn từ điển."}]'::jsonb, 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g23_2', 'lesson-23', '2. 好像: Hình như, dường như', 'Cấu trúc câu ngữ pháp trọng tâm', ' Dùng trong những phán đoán không chắc chắn. 这个人我好像认识 。 Zhège rén wǒ hǎoxiàng rènshi. Hình như tớ quen người này. 你好像不太喜欢吃辣的。 Nǐ hǎoxiàng bú tài xǐhuan chī là de. Hình như cậu không thích ăn cay. 他好像不太喜欢我。 Tā hǎoxiàng bú tài xǐhuan wǒ. Hình như anh ấ', NULL, '[{"hanzi":"昨天我去了超市和书店。 （你去哪儿了？）","pinyin":"Zuótiān wǒ qù le chāoshì hé shūdiàn. (Nǐ qù nǎr le?)","meaning":"Hôm qua tôi đã đi đến siêu thị và hiệu sách. (Bạn đã đi đâu thế?)"},{"hanzi":"这个人我好像认识 。","pinyin":"Zhège rén wǒ hǎoxiàng rènshi.","meaning":"Hình như tớ quen người này."}]'::jsonb, 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g23_3', 'lesson-23', '3. 地', 'S + Tính từ/cụm từ/động từ/từ tượng thanh... + 地+ động từ', ' Là trợ từ kết cấu trong cụm trạng ngữ, hay còn gọi là kết cấu trạng trung. Thường dùng theo cấu trúc： Trong cấu trúc trên thành phần phía trước 地 dùng để miêu tả động tác ở phía sau 地 được thực hiện như thế nào hoặc miêu tả người thực hiện động tác ', NULL, '[{"hanzi":"你好像不太喜欢吃辣的。","pinyin":"Nǐ hǎoxiàng bú tài xǐhuan chī là de.","meaning":"Hình như cậu không thích ăn cay."},{"hanzi":"他们俩好像是多年的好朋友了。","pinyin":"Tāmen liǎ hǎoxiàng shì duōnián de hǎo péngyou le.","meaning":"Hai người họ dường như là bạn bè thân thiết đã nhiều năm rồi."}]'::jsonb, 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g23_4', 'lesson-23', '1.    Tính từ đơn âm tiết làm trạng ngữ, thường không dùng 地', 'Cấu trúc câu ngữ pháp trọng tâm', ' 快走、快吃、慢走、快说、快跑、大哭、大喊、傻笑……', NULL, '[{"hanzi":"他高高兴兴地对我讲故事。","pinyin":"Tā gāogāoxìngxìng de duì wǒ jiǎng gùshì.","meaning":"Anh ấy kể chuyện cho tôi nghe một cách hạnh phúc."},{"hanzi":"她自信地参加比赛。","pinyin":"Tā zìxìn de cānjiā bǐsài.","meaning":"Cô ấy tự tin tham gia cuộc thi."}]'::jsonb, 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_23_1', 'lesson-23', 'Bài khoá #1: Hội thoại giáo trình — Ăn uống', 'Hội thoại chuẩn giáo trình Bài 23. Từ vựng chưa học được chú thích phiên âm & nghĩa trong ngoặc.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_23_1_1', 'txt_23_1', '范玉兰', '小雪，中国人常吃什么味道的菜？', '小雪 (Xiǎoxuě: Tiểu Tuyết)，中国人常吃什么味道的菜？', 'Xiǎoxuě, Zhōngguó rén cháng chī shénme wèidao de cài?', 'Tiểu Tuyết, người Trung Quốc thường ăn các món có hương vị như thế nào?', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_23_1_2', 'txt_23_1', '白茹雪', '在中国，不同地方菜的味道不同，比如：南方人常吃甜的、北方人吃咸的、东部的人吃酸的、西部人吃辣的。', '在中国，不同地方菜的味道不同，比如：南方人常吃甜的、北方人吃咸的、东部的人吃酸的、西部人吃辣的。', 'Zài Zhōngguó, bùtóng dìfang cài de wèidao bùtóng, bǐrú: Nánfāng rén cháng chī tián de, Běifāng rén chī xián de, Dōngbù de rén chī suān de, Xībù rén chī là de.', 'Ở Trung Quốc, hương vị món ăn từng vùng khác nhau, ví dụ: người miền Nam hay ăn ngọt, miền Bắc ăn mặn, miền Đông ăn chua, còn miền Tây ăn cay.', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_23_1_3', 'txt_23_1', '范玉兰', '那你喜欢吃什么味道？', '那你喜欢吃什么味道？', 'Nà nǐ xǐhuan chī shénme wèidao?', 'Vậy cậu thích ăn vị gì?', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_23_1_4', 'txt_23_1', '白茹雪', '我喜欢吃辣的，你呢？', '我喜欢吃辣的，你呢？', 'Wǒ xǐhuan chī là de, nǐ ne?', 'Tớ thích ăn cay, còn cậu?', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_23_1_5', 'txt_23_1', '范玉兰', '我不能吃辣的，我每次吃辣都会过敏。', '我不能吃辣的，我每次 (cì: lần)吃辣都会过敏。', 'Wǒ bùnéng chī là de, wǒ měi cì chī là dōu huì guòmǐn.', 'Tớ không ăn được cay, hễ ăn cay là tớ lại bị dị ứng.', 5) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_23_1_6', 'txt_23_1', '白茹雪', '你还有什么菜不能吃的吗？', '你还有什么菜不能吃的吗？', 'Nǐ hái yǒu shén me cài bùnéng chī de ma?', 'Cậu còn món nào không ăn được nữa không?', 6) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_23_1_7', 'txt_23_1', '范玉兰', '有，中国的臭豆腐。真的太难吃了。我来中国快要三个月了，可是到现在还不能吃，闻也不行。', '有，中国的臭豆腐。真的太难吃了。我来 (lái: đến)中国快要三个月了，可是到现在还不能吃，闻也不行。', 'Yǒu, Zhōngguó de Chòudòufu. Zhēn de tài nán chī le. Wǒ lái Zhōngguó kuàiyào sān gè yuè le, kěshì dào xiànzài hái bùnéng chī, wén yě bùxíng.', 'Có chứ, đậu phụ thối của Trung Quốc. Thật sự khó ăn quá. Tớ sang Trung Quốc gần ba tháng rồi mà đến giờ vẫn không ăn nổi, ngửi cũng không chịu được.', 7) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_23_1_8', 'txt_23_1', '白茹雪', '好像大多数外国人都跟你一样，都不喜欢它的味道，但是如果你吃了一两次，你会觉得它很好吃！', '好像大 (dà: to, lớn)多数外国人都跟 (gēn: cùng, với)你一样，都不喜欢它的味道，但是如果你吃了一两 (liǎng: hai (số lượng))次 (cì: lần)，你会觉得它很好吃！', 'Hǎoxiàng dàduōshù wàiguó rén dōu gēn nǐ yíyàng, dōu bù xǐhuan tā de wèidào, dànshì rúguǒ nǐ chīle yī liǎng cì, nǐ huì juéde tā hěn hǎo chī!', 'Hình như đa số người nước ngoài đều giống cậu, không thích mùi vị của nó, nhưng nếu ăn thử một hai lần cậu sẽ thấy nó rất ngon đấy!', 8) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_23_1_9', 'txt_23_1', '范玉兰', '是吗？下次我会尝一尝。那中国人的主食是什么？', '是吗？下次我会尝 (cháng: nếm thử)一尝。那中国人的主食是什么？', 'Shì ma? Xià cì wǒ huì cháng yi cháng. Nà Zhōngguó rén de zhǔshí shì shénme?', 'Thật sao? Lần sau tớ sẽ nếm thử xem. Vậy lương thực chính của người Trung Quốc là gì?', 9) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_23_1_10', 'txt_23_1', '白茹雪', '中国人常说：“南米北面”，意思是北方人的主食是馒头、面包和小麦，南方人的主食是米饭。', '中国人常说：“南 (nán: phía Nam)米北面 (běimian: phía Bắc)”，意思 (yìsi: ý nghĩa)是北方人的主食是馒头、面包和小麦，南方人的主食是米饭。', 'Zhōngguó rén cháng shuō: “Nán mǐ Běi miàn”, yìsi shì Běifāng rén de zhǔshí shì mántou, miànbāo hé xiǎomài, Nánfāng rén de zhǔshí shì mǐfàn.', 'Người Trung Quốc hay nói ''Nam cơm Bắc mì'', nghĩa là món chính của người miền Bắc là màn thầu, bánh mì và lúa mì, còn người miền Nam là cơm.', 10) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_23_1_11', 'txt_23_1', '范玉兰', '中国的饮料呢？', '中国的饮料呢？', 'Zhōngguó de yǐnliào ne?', 'Còn đồ uống ở Trung Quốc thì sao?', 11) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_23_1_12', 'txt_23_1', '白茹雪', '中国人常喝啤酒、白酒、红酒还有茶。如果你到中国人家里去做客，他们就会请你喝酒。', '中国人常喝啤酒、白酒、红酒还有茶。如果你到中国人家里 (lǐ: trong)去做客，他们就会请你喝酒 (jiǔ: rượu)。', 'Zhōngguó rén cháng hē píjiǔ, báijiǔ, hóngjiǔ hái yǒu chá. Rúguǒ nǐ dào Zhōngguó rén jiāli qù zuòkè, tāmen jiù huì qǐng nǐ hē jiǔ.', 'Người Trung Quốc hay uống bia, rượu trắng, rượu vang đỏ và trà. Nếu cậu đến nhà người Trung Quốc làm khách, họ sẽ mời cậu uống rượu.', 12) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_23_1_13', 'txt_23_1', '范玉兰', '如果不会喝酒呢？', '如果不会喝酒 (jiǔ: rượu)呢？', 'Rúguǒ bú huì hējiǔ ne?', 'Nếu không biết uống rượu thì sao?', 13) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_23_1_14', 'txt_23_1', '白茹雪', '那也没关系。你可以用茶来代替也行。', '那也没关系。你可以用茶来 (lái: đến)代替也行。', 'Nà yě méiguānxi. Nǐ kěyǐ yòng chá lái dàitì yě xíng.', 'Cũng không sao cả. Cậu có thể dùng trà thay thế cũng được.', 14) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_23_1_15', 'txt_23_1', '范玉兰', '春节快到了，春节的时候中国人常吃什么？', '春节快到了，春节的时候中国人常吃什么？', 'Chūnjié kuài dào le, Chūnjié de shíhou Zhōngguó rén cháng chī shénme?', 'Sắp đến Tết rồi, dịp Tết người Trung Quốc thường ăn món gì?', 15) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_23_1_16', 'txt_23_1', '白茹雪', '中国北方人习惯吃饺子，南方人喜欢吃年糕。春节是一年最快乐的时候。家人开开心心地坐在一起，一起包饺子，煮饺子。', '中国北方人习惯吃饺子，南方人喜欢吃年糕。春节是一年最快乐的时候。家人开 (kāi: mở, lái)开心心 (xīn: tim, lòng)地坐 (zuò: ngồi)在一起，一起包饺子，煮饺子。', 'Zhōngguó běifāng rén xíguàn chī jiǎozi, nánfāng rén xǐhuan chī niángāo. Chūnjié shì yī nián zuì kuàilè de shíhou. Jiārén kāi kāi xīn xīn de zuò zài yīqǐ, yīqǐ bāo jiǎozi, zhǔ jiǎozi.', 'Người miền Bắc Trung Quốc quen ăn sủi cảo, người miền Nam thích ăn bánh tổ. Tết là dịp vui nhất trong năm. Cả nhà quây quần vui vẻ bên nhau, cùng gói và luộc sủi cảo.', 16) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_23_1_17', 'txt_23_1', '范玉兰', '哇，你会包饺子吗？我特别喜欢吃饺子，但是不会包饺子。你可以教我吗？', '哇 (wa: oa, chà (cảm thán))，你会包饺子吗？我特别喜欢吃饺子，但是不会包饺子。你可以教我吗？', 'Wa, nǐ huì bāo jiǎozi ma? Wǒ tèbié xǐhuan chī jiǎozi, dànshì bú huì bāo jiǎozi. Nǐ kěyǐ jiào wǒ ma?', 'Chà, cậu biết gói sủi cảo không? Tớ đặc biệt thích ăn sủi cảo nhưng lại không biết gói. Cậu dạy tớ được không?', 17) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_23_1_18', 'txt_23_1', '白茹雪', '当然可以啊！', '当然可以啊！', 'Dāngrán kěyǐ a!', 'Tất nhiên là được rồi!', 18) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_23_1_1', 'lesson-23', 'txt_23_1', 'listening', 'listening', '小雪，中国人常吃什么味道的菜？', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Một chiếc khăn","Tôi muốn đi siêu thị mua một chút đồ.","Người đó là thầy Vương.","Tiểu Tuyết, người Trung Quốc thường ăn các món có hương vị như thế nào?"]'::jsonb, 3, 'Nội dung nghe được: 小雪，中国人常吃什么味道的菜？ (Xiǎoxuě, Zhōngguó rén cháng chī shénme wèidao de cài?) → Tiểu Tuyết, người Trung Quốc thường ăn các món có hương vị như thế nào?', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_23_1_2', 'lesson-23', 'txt_23_1', 'listening', 'listening', '在中国，不同地方菜的味道不同，比如：南方人常吃甜的、北方人吃咸的、东部的人吃酸的、西部人吃辣的。', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["那你喜欢吃什么味道？","在中国，不同地方菜的味道不同，比如：南方人常吃甜的、北方人吃咸的、东部的人吃酸的、西部人吃辣的。","他们俩好像是多年的好朋友了。","昨天我去了超市和书店。 （你去哪儿了？）"]'::jsonb, 1, 'Câu vừa đọc: 在中国，不同地方菜的味道不同，比如：南方人常吃甜的、北方人吃咸的、东部的人吃酸的、西部人吃辣的。 (Zài Zhōngguó, bùtóng dìfang cài de wèidao bùtóng, bǐrú: Nánfāng rén cháng chī tián de, Běifāng rén chī xián de, Dōngbù de rén chī suān de, Xībù rén chī là de.) → Ở Trung Quốc, hương vị món ăn từng vùng khác nhau, ví dụ: người miền Nam hay ăn ngọt, miền Bắc ăn mặn, miền Đông ăn chua, còn miền Tây ăn cay.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_23_1_3', 'lesson-23', 'txt_23_1', 'listening', 'listening', '那你喜欢吃什么味道？', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Tôi mệt đến mức chẳng muốn động đậy gì nữa.","Chốc nữa cậu ấy sẽ đến.","Nửa kg (1 cân) táo bao nhiêu tiền?","Vậy cậu thích ăn vị gì?"]'::jsonb, 3, 'Nội dung nghe được: 那你喜欢吃什么味道？ (Nà nǐ xǐhuan chī shénme wèidao?) → Vậy cậu thích ăn vị gì?', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_23_1_4', 'lesson-23', 'txt_23_1', 'listening', 'listening', '我喜欢吃辣的，你呢？', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["南方人的主食一般是米饭，北方人常吃馒头。","我喜欢吃辣的，你呢？","他高高兴兴地对我讲故事。","小雪 (Xiǎoxuě: Tiểu Tuyết)，中国人常吃什么味道的菜？"]'::jsonb, 1, 'Câu vừa đọc: 我喜欢吃辣的，你呢？ (Wǒ xǐhuan chī là de, nǐ ne?) → Tớ thích ăn cay, còn cậu?', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_23_2', 'lesson-23', 'Bài nghe tổng hợp: Ôn tập lũy tiến (Bài 1 – Bài 23)', 'Kết hợp từ vựng & mẫu câu đã học từ Bài 1 đến Bài 22 cùng trọng tâm Bài 23 để củng cố phản xạ nghe.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_23_2_1', 'txt_23_2', 'Ôn Bài 22', '我二十三岁。', '我二十三岁。', 'Wǒ èrshísān suì.', 'Tôi 23 tuổi.', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_23_2_2', 'txt_23_2', 'Bài 23', '她吃了三个饺子。', '她吃了三个饺子。', 'Tā chīle sān gè jiǎozi.', 'Cô ấy đã ăn 3 cái sủi cảo.', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_23_2_3', 'txt_23_2', 'Ôn Bài 11', '他在吃饭呢。', '他在吃饭呢。', 'Tā zài chīfàn ne.', 'Anh ấy đang ăn cơm kìa.', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_23_2_4', 'txt_23_2', 'Bài 23', '昨天我们一起去书店，他买了一本词典。', '昨天我们一起去书店，他买了一本词典。', 'Zuótiān wǒmen yīqǐ qù shūdiàn, tā mǎile yī běn cídiǎn.', 'Hôm qua chúng tôi đi hiệu sách, anh ấy đã mua một cuốn từ điển.', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_23_2_5', 'txt_23_2', 'Ôn Bài 1', '老师好', '老师好', 'Lǎoshī hǎo', 'Chào thầy/Chào cô', 5) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_23_2_6', 'txt_23_2', 'Bài 23', '昨天我去了超市和书店。 （你去哪儿了？）', '昨天我去了超市和书店。 （你去哪儿了？）', 'Zuótiān wǒ qù le chāoshì hé shūdiàn. (Nǐ qù nǎr le?)', 'Hôm qua tôi đã đi đến siêu thị và hiệu sách. (Bạn đã đi đâu thế?)', 6) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_23_2_7', 'txt_23_2', 'Ôn Bài 14', '你喜欢春天还是夏天？', '你喜欢春天还是夏天？', 'Nǐ xǐhuan chūntiān háishi xiàtiān?', 'Cậu thích mùa xuân hay mùa hè?', 7) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_23_2_8', 'txt_23_2', 'Bài 23', '这个人我好像认识 。', '这个人我好像认识 。', 'Zhège rén wǒ hǎoxiàng rènshi.', 'Hình như tớ quen người này.', 8) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_23_2_1', 'lesson-23', 'txt_23_2', 'listening', 'listening', '我二十三岁。', NULL, '[Ôn tập Bài 22] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Tôi 23 tuổi.","Năm nay cháu 6 tuổi ạ.","Thầy giáo đang đợi bạn ở bên ngoài.","cuộc sống hạnh phúc"]'::jsonb, 0, 'Nội dung nghe được: 我二十三岁。 (Wǒ èrshísān suì.) → Tôi 23 tuổi.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_23_2_2', 'lesson-23', 'txt_23_2', 'listening', 'listening', '她吃了三个饺子。', NULL, '[Bài 23] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["中国的饮料呢？","昨天我们一起去书店，他买了一本词典。","她吃了三个饺子。","早餐 (zǎocān: bữa sáng)我通常吃一碗面 (miàn: mặt, phía)条或者几块面包。"]'::jsonb, 2, 'Câu vừa đọc: 她吃了三个饺子。 (Tā chīle sān gè jiǎozi.) → Cô ấy đã ăn 3 cái sủi cảo.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_23_2_3', 'lesson-23', 'txt_23_2', 'listening', 'listening', '他在吃饭呢。', NULL, '[Ôn tập Bài 11] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Anh ấy đang ăn cơm kìa.","Tôi đứng ở giữa Lâm và Phương.","Mark, cậu lại đang làm gì nữa vậy?","Tôi đang tắm."]'::jsonb, 0, 'Nội dung nghe được: 他在吃饭呢。 (Tā zài chīfàn ne.) → Anh ấy đang ăn cơm kìa.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_23_2_4', 'lesson-23', 'txt_23_2', 'listening', 'listening', '昨天我们一起去书店，他买了一本词典。', NULL, '[Bài 23] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["我不能吃辣的，我每次 (cì: lần)吃辣都会过敏。","有，中国的臭豆腐。真的太难吃了。我来 (lái: đến)中国快要三个月了，可是到现在还不能吃，闻也不行。","中国的饮料呢？","昨天我们一起去书店，他买了一本词典。"]'::jsonb, 3, 'Câu vừa đọc: 昨天我们一起去书店，他买了一本词典。 (Zuótiān wǒmen yīqǐ qù shūdiàn, tā mǎile yī běn cídiǎn.) → Hôm qua chúng tôi đi hiệu sách, anh ấy đã mua một cuốn từ điển.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_23_2_5', 'lesson-23', 'txt_23_2', 'listening', 'listening', '老师好', NULL, '[Ôn tập Bài 1] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Bố rất ít đưa tôi đi du lịch.","Chào thầy/Chào cô","Không phải hôm qua chúng ta đã gặp nhau rồi sao? (Khẳng định hôm","Một con gà"]'::jsonb, 1, 'Nội dung nghe được: 老师好 (Lǎoshī hǎo) → Chào thầy/Chào cô', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_23_3', 'lesson-23', 'Bài khoá mở rộng: Khám phá ẩm thực vùng miền Trung Quốc (Mở rộng)', 'Hội thoại tình huống mới xây dựng dựa trên từ vựng và ngữ pháp Bài 23 (không trùng lặp nguyên văn giáo trình).', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_23_3_1', 'txt_23_3', 'Mark', '听说中国南方和北方的饮食习惯不太一样，是真的吗？', '听说中国南方和北方的饮食习惯不太一样，是真的吗？', 'Tīngshuō Zhōngguó nánfāng hé běifāng de yǐnshí xíguàn bú tài yíyàng, shì zhēn de ma?', 'Nghe nói thói quen ăn uống của miền Nam và miền Bắc Trung Quốc khá khác nhau, có thật không?', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_23_3_2', 'txt_23_3', 'Phong', '真的！南方主食多是米饭和年糕，北方人爱吃馒头和面条。', '真的！南方主食多是米饭和年糕，北方人爱吃馒头和面 (miàn: mặt, phía)条。', 'Zhēn de! Nánfāng zhǔshí duō shì mǐfàn hé niángāo, běifāng rén ài chī mántou hé miàntiáo.', 'Thật đấy! Món chính miền Nam phần nhiều là cơm và bánh tổ, người miền Bắc thích ăn màn thầu và mì sợi.', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_23_3_3', 'txt_23_3', 'Mark', '那你敢吃臭豆腐或者特别辣的菜吗？', '那你敢吃臭豆腐或者特别辣的菜吗？', 'Nà nǐ gǎn chī chòudòufu huòzhě tèbié là de cài ma?', 'Vậy cậu có dám ăn đậu phụ thối hay các món thật cay không?', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_23_3_4', 'txt_23_3', 'Phong', '臭豆腐我还没试过，但是辣菜配冰饮料可香了！', '臭豆腐我还没 (méi: chưa, không có)试过 (guò: từng, qua)，但是辣菜配冰饮料可香 (xiāng: thơm)了！', 'Chòudòufu wǒ hái méi shì guo, dànshì là cài pèi bīng yǐnliào kě xiāng le!', 'Đậu phụ thối mình chưa thử bao giờ, nhưng món cay ăn kèm đồ uống lạnh thì ngon tuyệt!', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_23_3_1', 'lesson-23', 'txt_23_3', 'listening', 'listening', '听说中国南方和北方的饮食习惯不太一样，是真的吗？ 真的！南方主食多是米饭和年糕，北方人爱吃馒头和面条。 那你敢吃臭豆腐或者特别辣的菜吗？ 臭豆腐我还没试过，但是辣菜配冰饮料可香了！', NULL, '[Nghe hiểu tình huống mới] Theo Trương Phong, lương thực chính quen thuộc của người miền Bắc Trung Quốc là gì?', '["Chỉ uống rượu vang đỏ","Màn thầu và mì sợi (馒头和面条)","Cơm trắng và bánh chưng","Chỉ ăn đậu phụ thối"]'::jsonb, 1, 'Phong nói ''北方人爱吃馒头和面条''.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_23_3_2', 'lesson-23', 'txt_23_3', 'listening', 'listening', '听说中国南方和北方的饮食习惯不太一样，是真的吗？', NULL, '[Mở rộng] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Người (mà) đi hiệu sách mua sách rất nhiều.","Mẹ ơi, sau khi làm xong bài tập về nhà con có thể xem phim không ạ?","Bố nhẹ nhàng vỗ vai tôi, lẳng lặng an ủi tôi.","Nghe nói thói quen ăn uống của miền Nam và miền Bắc Trung Quốc khá khác nhau, có thật không?"]'::jsonb, 3, 'Nội dung nghe được: 听说中国南方和北方的饮食习惯不太一样，是真的吗？ (Tīngshuō Zhōngguó nánfāng hé běifāng de yǐnshí xíguàn bú tài yíyàng, shì zhēn de ma?) → Nghe nói thói quen ăn uống của miền Nam và miền Bắc Trung Quốc khá khác nhau, có thật không?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_23_3_3', 'lesson-23', 'txt_23_3', 'listening', 'listening', '真的！南方主食多是米饭和年糕，北方人爱吃馒头和面条。', NULL, '[Mở rộng] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["你更 (gèng: càng)喜欢喝什么饮料：茶还是果汁？","这个人我好像认识 。","他高高兴兴地对我讲故事。","真的！南方主食多是米饭和年糕，北方人爱吃馒头和面 (miàn: mặt, phía)条。"]'::jsonb, 3, 'Câu vừa đọc: 真的！南方主食多是米饭和年糕，北方人爱吃馒头和面条。 (Zhēn de! Nánfāng zhǔshí duō shì mǐfàn hé niángāo, běifāng rén ài chī mántou hé miàntiáo.) → Thật đấy! Món chính miền Nam phần nhiều là cơm và bánh tổ, người miền Bắc thích ăn màn thầu và mì sợi.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_23_3_4', 'lesson-23', 'txt_23_3', 'listening', 'listening', '那你敢吃臭豆腐或者特别辣的菜吗？', NULL, '[Mở rộng] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Bạn đã chuẩn bị đầy đủ đồ đạc để đi du lịch chưa?","Quyển sách này là sách của tớ.","Vậy cậu có dám ăn đậu phụ thối hay các món thật cay không?","mắt to to (mang sự dễ thương)"]'::jsonb, 2, 'Nội dung nghe được: 那你敢吃臭豆腐或者特别辣的菜吗？ (Nà nǐ gǎn chī chòudòufu huòzhě tèbié là de cài ma?) → Vậy cậu có dám ăn đậu phụ thối hay các món thật cay không?', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss23_1', 'lesson-23', '这道菜的味道太辣了我吃不习惯', '[Mở rộng] Món ăn này cay quá, tôi ăn không quen.', 'Zhè dào cài de wèidao tài là le, wǒ chī bu xíguàn.', '["这道","菜的","味道太","辣了","我吃不","习惯"]'::jsonb, NULL, 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss23_2', 'lesson-23', '爸爸喜欢喝一点儿啤酒或者红酒', '[Mở rộng] Bố thích uống một chút bia hoặc rượu vang đỏ.', 'Bàba xǐhuan hē yìdiǎnr píjiǔ huòzhě hóngjiǔ.', '["爸爸喜欢","喝一","点儿","啤酒","或者","红酒"]'::jsonb, 'Từ chưa học: 儿 (ér: con, (âm uốn lưỡi))', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss23_3', 'lesson-23', '她吃了三个饺子', 'Cô ấy đã ăn 3 cái sủi cảo.', 'Tā chīle sān gè jiǎozi.', '["她","吃","了","三","个","饺子"]'::jsonb, NULL, 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
