INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss23_5', 'lesson-23', '他来自哪个国家', '[Ôn tập Bài 3] Anh ấy đến từ đất nước nào?', 'Tā láizì nǎ gè guójiā?', '["他","来自","哪","个","国家"]'::jsonb, NULL, 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss23_6', 'lesson-23', '我要一个西瓜一共多少钱', '[Ôn tập Bài 8] Cháu lấy một quả dưa hấu, tổng cộng bao nhiêu tiền ạ?', 'Wǒ yào yígè xīguā, yígòng duōshao qián?', '["我要","一个","西瓜","一共","多少","钱"]'::jsonb, NULL, 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr23_vi_1', 'lesson-23', 'vi_to_zh', '[Mở rộng] Lương thực chính của người miền Nam thường là cơm, còn người miền Bắc hay ăn màn thầu.', NULL, NULL, '南方人的主食一般是米饭，北方人常吃馒头。', NULL, 'nánfāng rén de zhǔshí yìbān shì mǐfàn běifāng rén cháng chī mántou', '[]'::jsonb, 'Gợi ý Pinyin: Nánfāng rén de zhǔshí yìbān shì mǐfàn, běifāng rén cháng chī mántou.', 'Lương thực chính của người miền Nam thường là cơm, còn người miền Bắc hay ăn màn thầu. → 南方人的主食一般是米饭，北方人常吃馒头。 (Nánfāng rén de zhǔshí yìbān shì mǐfàn, běifāng rén cháng chī mántou.)', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
