INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr23_vi_4', 'lesson-23', 'vi_to_zh', 'Hôm qua chúng tôi đi hiệu sách, anh ấy đã mua một cuốn từ điển.', NULL, NULL, '昨天我们一起去书店，他买了一本词典。', NULL, 'zuótiān wǒmen yīqǐ qù shūdiàn tā mǎile yī běn cídiǎn', '[]'::jsonb, 'Gợi ý Pinyin: Zuótiān wǒmen yīqǐ qù shūdiàn, tā mǎile yī běn cídiǎn.', 'Hôm qua chúng tôi đi hiệu sách, anh ấy đã mua một cuốn từ điển. → 昨天我们一起去书店，他买了一本词典。 (Zuótiān wǒmen yīqǐ qù shūdiàn, tā mǎile yī běn cídiǎn.)', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr23_zh_1', 'lesson-23', 'zh_to_vi', '[Mở rộng] 爸爸喜欢喝一点儿 (ér: con, (âm uốn lưỡi))啤酒或者红酒。', '爸爸喜欢喝一点儿啤酒或者红酒。', 'Bàba xǐhuan hē yìdiǎnr píjiǔ huòzhě hóngjiǔ.', NULL, 'Bố thích uống một chút bia hoặc rượu vang đỏ.', NULL, '["Bố","thích","uống"]'::jsonb, 'Pinyin: Bàba xǐhuan hē yìdiǎnr píjiǔ huòzhě hóngjiǔ.', '爸爸喜欢喝一点儿啤酒或者红酒。 (Bàba xǐhuan hē yìdiǎnr píjiǔ huòzhě hóngjiǔ.) nghĩa là: Bố thích uống một chút bia hoặc rượu vang đỏ.', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr23_zh_2', 'lesson-23', 'zh_to_vi', '[Mở rộng] 你更 (gèng: càng)喜欢喝什么饮料：茶还是果汁？', '你更喜欢喝什么饮料：茶还是果汁？', 'Nǐ gèng xǐhuan hē shénme yǐnliào: chá háishi guǒzhī?', NULL, 'Bạn thích uống loại đồ uống nào hơn: trà hay nước ép trái cây?', NULL, '["Bạn","thích","uống"]'::jsonb, 'Pinyin: Nǐ gèng xǐhuan hē shénme yǐnliào: chá háishi guǒzhī?', '你更喜欢喝什么饮料：茶还是果汁？ (Nǐ gèng xǐhuan hē shénme yǐnliào: chá háishi guǒzhī?) nghĩa là: Bạn thích uống loại đồ uống nào hơn: trà hay nước ép trái cây?', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr23_zh_3', 'lesson-23', 'zh_to_vi', '昨天我去了超市和书店。 （你去哪儿了？）', '昨天我去了超市和书店。 （你去哪儿了？）', 'Zuótiān wǒ qù le chāoshì hé shūdiàn. (Nǐ qù nǎr le?)', NULL, 'Hôm qua tôi đã đi đến siêu thị và hiệu sách. (Bạn đã đi đâu thế?)', NULL, '["Hôm","qua","tôi"]'::jsonb, 'Pinyin: Zuótiān wǒ qù le chāoshì hé shūdiàn. (Nǐ qù nǎr le?)', '昨天我去了超市和书店。 （你去哪儿了？） (Zuótiān wǒ qù le chāoshì hé shūdiàn. (Nǐ qù nǎr le?)) nghĩa là: Hôm qua tôi đã đi đến siêu thị và hiệu sách. (Bạn đã đi đâu thế?)', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
