INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq23_6', 'lesson-23', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Từ Hán tự “馒头” có nghĩa tiếng Việt là gì?', '["rượu trắng","dùng","bánh màn thầu","nhưng"]'::jsonb, 2, '“馒头” (mántou) là Danh từ, nghĩa là: bánh màn thầu.', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
