INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq23_11', 'lesson-23', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Phiên âm Pinyin chính xác của “咸” là gì?', '["xián","yǐnshí","nánfāng","báijiǔ"]'::jsonb, 0, '“咸” đọc là: xián (mặn).', 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq23_12', 'lesson-23', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Phiên âm Pinyin chính xác của “辣” là gì?', '["yǐnshí","xībù","de","là"]'::jsonb, 3, '“辣” đọc là: là (cay).', 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq23_13', 'lesson-23', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “饮食” chứa bộ thủ nào sau đây?', '["Bộ cấu tạo [碗] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","木 (Mộc) (Cây cối, gỗ)","食 (Thực) (Đồ ăn, ẩm thực)","Bộ cấu tạo [东] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)"]'::jsonb, 2, 'Chữ “饮食” có 食 (Thực) (Đồ ăn, ẩm thực). Ghép từ các chữ Hán: [饮] + [食].', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq23_14', 'lesson-23', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “饮料” chứa bộ thủ nào sau đây?', '["Bộ cấu tạo [饮] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [可] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [行] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [地] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)"]'::jsonb, 0, 'Chữ “饮料” có Bộ cấu tạo [饮] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán). Ghép từ các chữ Hán: [饮] + [料].', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq23_15', 'lesson-23', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “主食” chứa bộ thủ nào sau đây?', '["Bộ cấu tạo [馒] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","食 (Thực) (Đồ ăn, ẩm thực)","Bộ cấu tạo [用] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [面] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)"]'::jsonb, 1, 'Chữ “主食” có 食 (Thực) (Đồ ăn, ẩm thực). Ghép từ các chữ Hán: [主] + [食].', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq23_16', 'lesson-23', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “味道” chứa bộ thủ nào sau đây?', '["Bộ cấu tạo [红] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [煮] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [味] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","食 (Thực) (Đồ ăn, ẩm thực)"]'::jsonb, 2, 'Chữ “味道” có Bộ cấu tạo [味] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán). Ghép từ các chữ Hán: [味] + [道].', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq23_17', 'lesson-23', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 20] Từ đã học “新鲜” (xīnxiān) có nghĩa là gì?', '["tươi, trong lành, mới mẻ","cả nhà","năm sau","bị ốm, bị bệnh, ốm"]'::jsonb, 0, 'Ôn tập Bài 20: “新鲜” (xīnxiān) nghĩa là: tươi, trong lành, mới mẻ.', 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq23_18', 'lesson-23', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 20] Từ đã học “得” (děi) có nghĩa là gì?', '["áp lực","bảo hiểm y tế","phải","lần sau"]'::jsonb, 2, 'Ôn tập Bài 20: “得” (děi) nghĩa là: phải.', 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq23_19', 'lesson-23', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 20] Từ đã học “可能” (kěnéng) có nghĩa là gì?', '["khả năng, có thể","yếu, yếu sức","không sao","mẹ"]'::jsonb, 0, 'Ôn tập Bài 20: “可能” (kěnéng) nghĩa là: khả năng, có thể.', 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq23_20', 'lesson-23', NULL, 'expanded_quiz', 'reading', NULL, NULL, '[Mở rộng] Câu “南方人的主食一般是米饭，北方人常吃馒头。” có nghĩa tiếng Việt là gì?', '["Tôi đã đọc sách hết một buổi sáng.","Anh ấy hát không hay lắm.","Lương thực chính của người miền Nam thường là cơm, còn người miền Bắc hay ăn màn thầu.","Anh ấy kể chuyện cho tôi nghe một cách hạnh phúc."]'::jsonb, 2, '南方人的主食一般是米饭，北方人常吃馒头。 (Nánfāng rén de zhǔshí yìbān shì mǐfàn, běifāng rén cháng chī mántou.) → Lương thực chính của người miền Nam thường là cơm, còn người miền Bắc hay ăn màn thầu.', 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq23_21', 'lesson-23', NULL, 'expanded_quiz', 'reading', NULL, NULL, '[Đọc hiểu mở rộng] Đọc đoạn hội thoại:
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq23_22', 'lesson-23', NULL, 'expanded_quiz', 'reading', NULL, NULL, 'Câu “她吃了三个饺子。” có nghĩa tiếng Việt là gì?', '["Hình như ban nãy tôi mới trông thấy cô ấy.","Cô ấy đã ăn 3 cái sủi cảo.","Lương thực chính của người miền Nam thường là cơm, còn người miền Bắc hay ăn màn thầu.","Năm nay bác bao nhiêu tuổi rồi ạ? (Hỏi người lớn tuổi)"]'::jsonb, 1, '她吃了三个饺子。 (Tā chīle sān gè jiǎozi.) → Cô ấy đã ăn 3 cái sủi cảo.', 22) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct23_1', 'lesson-23', NULL, 'comprehensive_test', 'listening', '当然可以啊！', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Đẹp quá! Vậy ông nội cậu thích gì?","Trương Phong, bây giờ mấy giờ rồi?","Tất nhiên là được rồi!","Sau khi làm xong bài tập tôi muốn đi xem phim."]'::jsonb, 2, 'Nội dung nghe được: “当然可以啊！” (Dāngrán kěyǐ a!) → Tất nhiên là được rồi!', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct23_2', 'lesson-23', NULL, 'comprehensive_test', 'listening', '他在吃饭呢。', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["晚上好！","他在吃饭呢。","真的吗？","同学们"]'::jsonb, 1, 'Câu vừa đọc: “他在吃饭呢。” (Tā zài chīfàn ne.) → Anh ấy đang ăn cơm kìa.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct23_3', 'lesson-23', NULL, 'comprehensive_test', 'listening', '你还有什么菜不能吃的吗？', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["giáo viên tiếng Trung","Cậu còn món nào không ăn được nữa không?","Được rồi! Giờ tớ đang rảnh, còn giúp được gì cho cậu nữa không?","Vậy cậu có dám ăn đậu phụ thối hay các món thật cay không?"]'::jsonb, 1, 'Nội dung nghe được: “你还有什么菜不能吃的吗？” (Nǐ hái yǒu shén me cài bùnéng chī de ma?) → Cậu còn món nào không ăn được nữa không?', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct23_4', 'lesson-23', NULL, 'comprehensive_test', 'listening', '好像大多数外国人都跟你一样，都不喜欢它的味道，但是如果你吃了一两次，你会觉得它很好吃！', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["= 明天天气好的话，我们就去爬山。","马克，我下午想去医院检查身体， 你可以陪我去吗？","好像大多数外国人都跟你一样，都不喜欢它的味道，但是如果你吃了一两次，你会觉得它很好吃！","她叫什么名字"]'::jsonb, 2, 'Câu vừa đọc: “好像大多数外国人都跟你一样，都不喜欢它的味道，但是如果你吃了一两次，你会觉得它很好吃！” (Hǎoxiàng dàduōshù wàiguó rén dōu gēn nǐ yíyàng, dōu bù xǐhuan tā de wèidào, dànshì rúguǒ nǐ chīle yī liǎng cì, nǐ huì juéde tā hěn hǎo chī!) → Hình như đa số người nước ngoài đều giống cậu, không thích mùi vị của nó, nhưng nếu ăn thử một hai lần cậu sẽ thấy nó rất ngon đấy!', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct23_5', 'lesson-23', NULL, 'comprehensive_test', 'listening', '你喜欢春天还是夏天？', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Một cốc 6 tệ.","A Minh, mỗi ngày mấy giờ cậu thức dậy rèn luyện sức khỏe?","Cậu thích mùa xuân hay mùa hè?","Tôi là Trần Anh."]'::jsonb, 2, 'Nội dung nghe được: “你喜欢春天还是夏天？” (Nǐ xǐhuan chūntiān háishi xiàtiān?) → Cậu thích mùa xuân hay mùa hè?', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct23_6', 'lesson-23', NULL, 'comprehensive_test', 'listening', '她自信地参加比赛。', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["她自信地参加比赛。","这个会议，你去还是小明去？","他最喜欢画画儿，我才是家里的足球迷。","中国的饮料呢？"]'::jsonb, 0, 'Câu vừa đọc: “她自信地参加比赛。” (Tā zìxìn de cānjiā bǐsài.) → Cô ấy tự tin tham gia cuộc thi.', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct23_7', 'lesson-23', NULL, 'comprehensive_test', 'listening', '臭豆腐我还没试过，但是辣菜配冰饮料可香了！', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Đậu phụ thối mình chưa thử bao giờ, nhưng món cay ăn kèm đồ uống lạnh thì ngon tuyệt!","Được, ngày mai gặp lại nhé!","Tiểu Lan, sắc mặt cậu không tốt lắm, có phải bị ốm rồi không?","4 giờ 20 phút rồi! Có chuyện gì thế?"]'::jsonb, 0, 'Nội dung nghe được: “臭豆腐我还没试过，但是辣菜配冰饮料可香了！” (Chòudòufu wǒ hái méi shì guo, dànshì là cài pèi bīng yǐnliào kě xiāng le!) → Đậu phụ thối mình chưa thử bao giờ, nhưng món cay ăn kèm đồ uống lạnh thì ngon tuyệt!', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct23_8', 'lesson-23', NULL, 'comprehensive_test', 'listening', '春节快到了，春节的时候中国人常吃什么？', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["大衣很合适，颜色也不错，但是裤子有点儿大。","给我一个西瓜和两斤火龙果，还要两杯草莓果汁。","这里有果汁吗？","春节快到了，春节的时候中国人常吃什么？"]'::jsonb, 3, 'Câu vừa đọc: “春节快到了，春节的时候中国人常吃什么？” (Chūnjié kuài dào le, Chūnjié de shíhou Zhōngguó rén cháng chī shénme?) → Sắp đến Tết rồi, dịp Tết người Trung Quốc thường ăn món gì?', 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
