INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr24_zh_1', 'lesson-24', 'zh_to_vi', '[Mở rộng] 大家 (dàjiā: mọi người)都要遵守交通规则，注意 (zhùyì: chú ý)红绿灯标志。', '大家都要遵守交通规则，注意红绿灯标志。', 'Dàjiā dōu yào zūnshǒu jiāotōng guīzé, zhùyì hónglǜdēng biāozhì.', NULL, 'Mọi người đều phải tuân thủ luật giao thông và chú ý biển báo đèn giao thông.', NULL, '["Mọi","người","đều"]'::jsonb, 'Pinyin: Dàjiā dōu yào zūnshǒu jiāotōng guīzé, zhùyì hónglǜdēng biāozhì.', '大家都要遵守交通规则，注意红绿灯标志。 (Dàjiā dōu yào zūnshǒu jiāotōng guīzé, zhùyì hónglǜdēng biāozhì.) nghĩa là: Mọi người đều phải tuân thủ luật giao thông và chú ý biển báo đèn giao thông.', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
