INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq24_13', 'lesson-24', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “交通” chứa bộ thủ nào sau đây?', '["Bộ cấu tạo [停] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [遵] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [乘] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [交] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)"]'::jsonb, 3, 'Chữ “交通” có Bộ cấu tạo [交] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán). Ghép từ các chữ Hán: [交] + [通].', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq24_14', 'lesson-24', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “自行车” chứa bộ thủ nào sau đây?', '["Bộ cấu tạo [拥] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [高] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [停] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","车 (Xa) (Xe cộ, phương tiện giao thông)"]'::jsonb, 3, 'Chữ “自行车” có 车 (Xa) (Xe cộ, phương tiện giao thông). Ghép từ các chữ Hán: [自] + [行] + [车].', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq24_15', 'lesson-24', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “摩托车” chứa bộ thủ nào sau đây?', '["Bộ cấu tạo [交] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [慢] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","车 (Xa) (Xe cộ, phương tiện giao thông)","Bộ cấu tạo [辆] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)"]'::jsonb, 2, 'Chữ “摩托车” có 车 (Xa) (Xe cộ, phương tiện giao thông). Ghép từ các chữ Hán: [摩] + [托] + [车].', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq24_16', 'lesson-24', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “汽车” chứa bộ thủ nào sau đây?', '["Bộ cấu tạo [警] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","车 (Xa) (Xe cộ, phương tiện giao thông)","Bộ cấu tạo [标] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [地] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)"]'::jsonb, 1, 'Chữ “汽车” có 车 (Xa) (Xe cộ, phương tiện giao thông). Ghép từ các chữ Hán: [汽] + [车].', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq24_17', 'lesson-24', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 6] Từ đã học “都” (dōu) có nghĩa là gì?', '["bệnh viện","đi, nhé,…","du ngoạn; du lịch","đều"]'::jsonb, 3, 'Ôn tập Bài 6: “都” (dōu) nghĩa là: đều.', 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq24_18', 'lesson-24', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 1] Từ đã học “您” (nín) có nghĩa là gì?', '["thứ bảy","ngài, ông, bà... (cách gọi tôn trọng và lịch sự dành cho những người có địa vị cao...)","hoặc, hoặc là","trượt tuyết"]'::jsonb, 1, 'Ôn tập Bài 1: “您” (nín) nghĩa là: ngài, ông, bà... (cách gọi tôn trọng và lịch sự dành cho những người có địa vị cao...).', 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq24_19', 'lesson-24', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 11] Từ đã học “矮” (ǎi) có nghĩa là gì?', '["mùa xuân","quê hương","cái gì, gì","thấp"]'::jsonb, 3, 'Ôn tập Bài 11: “矮” (ǎi) nghĩa là: thấp.', 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq24_20', 'lesson-24', NULL, 'expanded_quiz', 'reading', NULL, NULL, '[Mở rộng] Câu “高峰时间公共汽车上 (shàng: trên / lên)的乘客非常多。” có nghĩa tiếng Việt là gì?', '["Vào giờ cao điểm, hành khách trên xe buýt rất đông.","Năm nay cháu mấy tuổi rồi (Hỏi trẻ em dưới mười tuổi)","Tôi sắp thi đại học rồi, vậy nên cảm thấy rất căng thẳng.","Nếu có gì không biết thì cậu cứ hỏi tớ."]'::jsonb, 0, '高峰时间公共汽车上的乘客非常多。 (Gāofēng shíjiān gōnggòng qìchē shàng de chéngkè fēicháng duō.) → Vào giờ cao điểm, hành khách trên xe buýt rất đông.', 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq24_21', 'lesson-24', NULL, 'expanded_quiz', 'reading', NULL, NULL, '[Đọc hiểu mở rộng] Đọc đoạn hội thoại:
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq24_22', 'lesson-24', NULL, 'expanded_quiz', 'reading', NULL, NULL, 'Câu “我看了一个上午的书了。” có nghĩa tiếng Việt là gì?', '["Hôm qua anh ấy không đến.","Quyển sách đó ở ngay trên bàn.","Tôi đã đọc sách hết một buổi sáng.","Anh ấy ăn không no lắm."]'::jsonb, 2, '我看了一个上午的书了。 (Wǒ kànle yígè shàngwǔ de shū le.) → Tôi đã đọc sách hết một buổi sáng.', 22) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct24_1', 'lesson-24', NULL, 'comprehensive_test', 'listening', '你会骑什么车？', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Bây giờ cậu cảm thấy thế nào?","Cậu biết đi xe gì?","Hôm nay là thứ mấy?","Vậy làm sao để mua được đồ tốt?"]'::jsonb, 1, 'Nội dung nghe được: “你会骑什么车？” (Nǐ huì qí shénme chē?) → Cậu biết đi xe gì?', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct24_2', 'lesson-24', NULL, 'comprehensive_test', 'listening', '是啊! 大部分中国人都遵守交通规则。', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["我觉得春天的天气最暖和最舒服","是啊! 大部分中国人都遵守交通规则。","很好，那你周末常常做什么？","他正在听音乐呢。"]'::jsonb, 1, 'Câu vừa đọc: “是啊! 大部分中国人都遵守交通规则。” (Shì a! Dàbùfen Zhōngguó rén dōu zūnshǒu jiāotōng guīzé.) → Đúng vậy! Phần lớn người Trung Quốc đều tuân thủ luật giao thông.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct24_3', 'lesson-24', NULL, 'comprehensive_test', 'listening', '昨天我去了超市和书店。 （你去哪儿了？）', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Cảm ơn hai bạn!","Trời có thể sắp mưa.","Buổi chiều chúng ta đi nhé!","Hôm qua tôi đã đi đến siêu thị và hiệu sách. (Bạn đã đi đâu thế?)"]'::jsonb, 3, 'Nội dung nghe được: “昨天我去了超市和书店。 （你去哪儿了？）” (Zuótiān wǒ qù le chāoshì hé shūdiàn. (Nǐ qù nǎr le?)) → Hôm qua tôi đã đi đến siêu thị và hiệu sách. (Bạn đã đi đâu thế?)', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct24_4', 'lesson-24', NULL, 'comprehensive_test', 'listening', '我学会了太极拳了。', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["他一直在等你。","是啊。在网上你可以买到很多东西，比如衣服、手表、眼镜、书本等等。","我学会了太极拳了。","当然了。北京特别美，有很多有名的景点，比如：万里长城、颐和园、故宫和天安门。"]'::jsonb, 2, 'Câu vừa đọc: “我学会了太极拳了。” (Wǒ xuéhuìle tàijí quánle.) → Tớ học được môn Thái cực quyền rồi.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct24_5', 'lesson-24', NULL, 'comprehensive_test', 'listening', '这是我的书。', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Từ ký túc xá đến nhà ăn đi như thế nào?","Người Bắc Kinh thì sao?","Đây là sách của tôi.","Mười tám tuổi."]'::jsonb, 2, 'Nội dung nghe được: “这是我的书。” (Zhè shì wǒ de shū.) → Đây là sách của tôi.', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct24_6', 'lesson-24', NULL, 'comprehensive_test', 'listening', '如果要去比较近的地方，你可以走路或者骑自行车。较远的地方可以坐火车、出租车或者公共汽车， 但公共汽车上的乘客比较多。', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["如果要去比较近的地方，你可以走路或者骑自行车。较远的地方可以坐火车、出租车或者公共汽车， 但公共汽车上的乘客比较多。","等我一下儿，这是我家的照片，给你看。","爷爷的爱好是早上看报纸喝茶","好的，一共 150 块。"]'::jsonb, 0, 'Câu vừa đọc: “如果要去比较近的地方，你可以走路或者骑自行车。较远的地方可以坐火车、出租车或者公共汽车， 但公共汽车上的乘客比较多。” (Rúguǒ yào qù bǐjiào jìn de dìfang, nǐ kěyǐ zǒulù huòzhě qí zìxíngchē. Jiào yuǎn de dìfang kěyǐ zuò huǒchē, chūzūchē huòzhě gōnggòng qìchē, dàn gōnggòng qìchē shàng de chéngkè bǐjiào duō.) → Nếu đi chỗ gần, cậu có thể đi bộ hoặc đạp xe. Chỗ xa hơn có thể đi tàu hỏa, taxi hoặc xe buýt, nhưng hành khách trên xe buýt khá đông.', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct24_7', 'lesson-24', NULL, 'comprehensive_test', 'listening', '从学校去火车站坐公共汽车还是坐出租车方便？', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Từ trường ra ga tàu hỏa thì đi xe buýt hay taxi tiện hơn?","Mình thấy thể lực của cậu tốt thật đấy. Chắc cậu rất thích thể dục thể thao nhỉ?","Mark, kỳ nghỉ hè năm ngoái bạn đi du lịch ở đâu?","Vậy Tết năm nay mời các bạn đến nhà chúng tôi chơi, chúng ta cùng nhau đón Tết thật vui vẻ, chắc chắn sẽ rất hạnh phúc."]'::jsonb, 0, 'Nội dung nghe được: “从学校去火车站坐公共汽车还是坐出租车方便？” (Cóng xuéxiào qù huǒchēzhàn zuò gōnggòng qìchē háishi zuò chūzūchē fāngbiàn?) → Từ trường ra ga tàu hỏa thì đi xe buýt hay taxi tiện hơn?', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct24_8', 'lesson-24', NULL, 'comprehensive_test', 'listening', '如果担心迷路，你可以先看看手机地图。', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["如果担心迷路，你可以先看看手机地图。","明天上午你几点去教室？","离这儿远吗？","拜拜！"]'::jsonb, 0, 'Câu vừa đọc: “如果担心迷路，你可以先看看手机地图。” → Nếu lo bị lạc đường, bạn có thể xem trước bản đồ trên điện thoại.', 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
