INSERT INTO lessons (id, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id) VALUES ('lesson-26', 'Bài 26: Sau khi tốt nghiệp - Đơn nguyên 7: Du học Trung Quốc', 'Bài 26', 'Đơn nguyên 7: Du học Trung Quốc', 'Định hướng tương lai: học lên thạc sĩ, đi làm phiên dịch, giảng dạy, tuyển dụng và tổng kết khóa học.', '2026-11-14'::date, 26, TRUE, NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, date_added = EXCLUDED.date_added, sort_order = EXCLUDED.sort_order, is_system = TRUE, updated_at = NOW();
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v26_1', 'lesson-26', '专业', 'zhuānyè', 'nghiệp', 'chuyên ngành, chuyên nghiệp', 'Danh từ / Tính từ', 'Bộ cấu tạo [专] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [专] + [业].', 'Kết hợp các thành tố [专] + [业] để tạo thành từ mang nghĩa ''chuyên ngành, chuyên nghiệp''.', '因为我的专业是汉语教育，所以回国后我想当一位老师。我想帮助越南学生学习汉语，让他们更了解中国文化，更喜欢中国。那你呢？你有什么打算？', 'Yīnwèi wǒ de zhuānyè shì Hànyǔ jiàoyù, suǒyǐ huíguó hòu wǒ xiǎng dāng yí wèi lǎoshī. Wǒ xiǎng bāngzhù Yuènán xuésheng xuéxí Hànyǔ, ràng tāmen gèng liǎojiě Zhōngguó wénhuà, gèng xǐhuan Zhōngguó. Nà nǐ ne? Nǐ yǒu shén me dǎsuan?', 'Vì chuyên ngành của tôi là Giáo dục Hán ngữ, nên sau khi về nước tôi muốn làm giáo viên. Tôi muốn giúp học sinh Việt Nam học tiếng Hán, giúp các em hiểu hơn về văn hóa Trung Quốc và yêu thích Trung Quốc hơn. Còn cậu thì sao? Cậu có dự định gì?', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v26_2', 'lesson-26', '硕士', 'shuòshì', 'từ Hán ngữ', 'thạc sĩ', 'Danh từ', 'Bộ cấu tạo [硕] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [硕] + [士].', 'Kết hợp các thành tố [硕] + [士] để tạo thành từ mang nghĩa ''thạc sĩ''.', '你想学硕士吗？', 'Nǐ xiǎng xué shuòshì ma?', 'Cậu muốn học thạc sĩ à?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v26_3', 'lesson-26', '理想', 'lǐxiǎng', 'tưởng', 'lý tưởng', 'Danh từ', 'Bộ cấu tạo [理] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [理] + [想].', 'Kết hợp các thành tố [理] + [想] để tạo thành từ mang nghĩa ''lý tưởng''.', '你的理想工作是什么？', 'Nǐ de lǐxiǎng gōngzuò shì shénme?', 'Công việc lý tưởng của cậu là gì?', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v26_4', 'lesson-26', '梦想', 'mèngxiǎng', 'tưởng', 'khát vọng, ước mơ', 'Danh từ', 'Bộ cấu tạo [梦] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [梦] + [想].', 'Kết hợp các thành tố [梦] + [想] để tạo thành từ mang nghĩa ''khát vọng, ước mơ''.', '翻译。这是我从小的梦想。现在我正在一家企业实习。虽然工作有点儿累，但是在这里我学会了很多技能和经验。', 'Fānyì. Zhè shì wǒ cóngxiǎo de mèngxiǎng. Xiànzài wǒ zhèng zài yījiā qǐyè shíxí. Suīrán gōngzuò yǒudiǎnr lèi dànshì zài zhèlǐ wǒ xué huì le hěn duō jìnéng hé jīngyàn.', 'Phiên dịch viên. Đây là ước mơ từ nhỏ của tôi. Hiện tôi đang thực tập tại một doanh nghiệp. Tuy công việc hơi vất vả nhưng ở đây tôi học được rất nhiều kỹ năng và kinh nghiệm.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v26_5', 'lesson-26', '工作', 'gōngzuò', 'công tác', 'nghề nghiệp, công việc', 'Danh từ / Động từ', 'Bộ cấu tạo [工] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [工] + [作].', 'Kết hợp các thành tố [工] + [作] để tạo thành từ mang nghĩa ''nghề nghiệp, công việc''.', '学两年。然后我会回国找工作。', 'Xué liǎng nián. Ránhòu wǒ huì huíguó zhǎo gōngzuò.', 'Học hai năm. Sau đó tôi sẽ về nước tìm việc.', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v26_6', 'lesson-26', '翻译', 'fānyì', 'từ Hán ngữ', 'dịch, phiên dịch', 'Danh từ / Động từ', 'Bộ cấu tạo [翻] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [翻] + [译].', 'Kết hợp các thành tố [翻] + [译] để tạo thành từ mang nghĩa ''dịch, phiên dịch''.', '翻译。这是我从小的梦想。现在我正在一家企业实习。虽然工作有点儿累，但是在这里我学会了很多技能和经验。', 'Fānyì. Zhè shì wǒ cóngxiǎo de mèngxiǎng. Xiànzài wǒ zhèng zài yījiā qǐyè shíxí. Suīrán gōngzuò yǒudiǎnr lèi dànshì zài zhèlǐ wǒ xué huì le hěn duō jìnéng hé jīngyàn.', 'Phiên dịch viên. Đây là ước mơ từ nhỏ của tôi. Hiện tôi đang thực tập tại một doanh nghiệp. Tuy công việc hơi vất vả nhưng ở đây tôi học được rất nhiều kỹ năng và kinh nghiệm.', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v26_7', 'lesson-26', '教育', 'jiàoyù', 'giáo', 'giáo dục, đào tạo', 'Danh từ / Động từ', 'Bộ cấu tạo [教] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [教] + [育].', 'Kết hợp các thành tố [教] + [育] để tạo thành từ mang nghĩa ''giáo dục, đào tạo''.', '因为我的专业是汉语教育，所以回国后我想当一位老师。我想帮助越南学生学习汉语，让他们更了解中国文化，更喜欢中国。那你呢？你有什么打算？', 'Yīnwèi wǒ de zhuānyè shì Hànyǔ jiàoyù, suǒyǐ huíguó hòu wǒ xiǎng dāng yí wèi lǎoshī. Wǒ xiǎng bāngzhù Yuènán xuésheng xuéxí Hànyǔ, ràng tāmen gèng liǎojiě Zhōngguó wénhuà, gèng xǐhuan Zhōngguó. Nà nǐ ne? Nǐ yǒu shén me dǎsuan?', 'Vì chuyên ngành của tôi là Giáo dục Hán ngữ, nên sau khi về nước tôi muốn làm giáo viên. Tôi muốn giúp học sinh Việt Nam học tiếng Hán, giúp các em hiểu hơn về văn hóa Trung Quốc và yêu thích Trung Quốc hơn. Còn cậu thì sao? Cậu có dự định gì?', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v26_8', 'lesson-26', '技能', 'jìnéng', 'từ Hán ngữ', 'kỹ năng, năng lực (chuyên môn)', 'Danh từ', 'Bộ cấu tạo [技] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [技] + [能].', 'Kết hợp các thành tố [技] + [能] để tạo thành từ mang nghĩa ''kỹ năng, năng lực (chuyên môn)''.', '翻译。这是我从小的梦想。现在我正在一家企业实习。虽然工作有点儿累，但是在这里我学会了很多技能和经验。', 'Fānyì. Zhè shì wǒ cóngxiǎo de mèngxiǎng. Xiànzài wǒ zhèng zài yījiā qǐyè shíxí. Suīrán gōngzuò yǒudiǎnr lèi dànshì zài zhèlǐ wǒ xué huì le hěn duō jìnéng hé jīngyàn.', 'Phiên dịch viên. Đây là ước mơ từ nhỏ của tôi. Hiện tôi đang thực tập tại một doanh nghiệp. Tuy công việc hơi vất vả nhưng ở đây tôi học được rất nhiều kỹ năng và kinh nghiệm.', 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
