INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v26_11', 'lesson-26', '毕业', 'bìyè', 'tất nghiệp', 'tốt nghiệp', 'Động từ', 'Bộ cấu tạo [毕] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [毕] + [业].', 'Kết hợp các thành tố [毕] + [业] để tạo thành từ mang nghĩa ''tốt nghiệp''.', '日明，快要毕业了，你有什么打算了吗？', 'Rìmíng, kuàiyào bìyè le, nǐ yǒu shénme dǎsuan le ma?', 'Nhật Minh, sắp tốt nghiệp rồi, cậu đã có dự định gì chưa?', 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v26_12', 'lesson-26', '回国', 'huíguó', 'quốc', 'về nước', 'Động từ', 'Bộ cấu tạo [回] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [回] + [国].', 'Kết hợp các thành tố [回] + [国] để tạo thành từ mang nghĩa ''về nước''.', '学两年。然后我会回国找工作。', 'Xué liǎng nián. Ránhòu wǒ huì huíguó zhǎo gōngzuò.', 'Học hai năm. Sau đó tôi sẽ về nước tìm việc.', 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v26_13', 'lesson-26', '当', 'dāng', 'từ Hán ngữ', 'đảm nhiệm, làm', 'Động từ', 'Bộ cấu tạo [当] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Chữ độc thể / hình thanh gồm Bộ cấu tạo [当] và các nét bổ trợ.', 'Ghi nhớ chữ [当] (đảm nhiệm, làm) qua hình tượng Thành phần biểu ý/biểu âm cơ bản trong chữ Hán.', '因为我的专业是汉语教育，所以回国后我想当一位老师。我想帮助越南学生学习汉语，让他们更了解中国文化，更喜欢中国。那你呢？你有什么打算？', 'Yīnwèi wǒ de zhuānyè shì Hànyǔ jiàoyù, suǒyǐ huíguó hòu wǒ xiǎng dāng yí wèi lǎoshī. Wǒ xiǎng bāngzhù Yuènán xuésheng xuéxí Hànyǔ, ràng tāmen gèng liǎojiě Zhōngguó wénhuà, gèng xǐhuan Zhōngguó. Nà nǐ ne? Nǐ yǒu shén me dǎsuan?', 'Vì chuyên ngành của tôi là Giáo dục Hán ngữ, nên sau khi về nước tôi muốn làm giáo viên. Tôi muốn giúp học sinh Việt Nam học tiếng Hán, giúp các em hiểu hơn về văn hóa Trung Quốc và yêu thích Trung Quốc hơn. Còn cậu thì sao? Cậu có dự định gì?', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v26_14', 'lesson-26', '实习', 'shíxí', 'tập', 'thực tập', 'Động từ', 'Bộ cấu tạo [实] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [实] + [习].', 'Kết hợp các thành tố [实] + [习] để tạo thành từ mang nghĩa ''thực tập''.', '翻译。这是我从小的梦想。现在我正在一家企业实习。虽然工作有点儿累，但是在这里我学会了很多技能和经验。', 'Fānyì. Zhè shì wǒ cóngxiǎo de mèngxiǎng. Xiànzài wǒ zhèng zài yījiā qǐyè shíxí. Suīrán gōngzuò yǒudiǎnr lèi dànshì zài zhèlǐ wǒ xué huì le hěn duō jìnéng hé jīngyàn.', 'Phiên dịch viên. Đây là ước mơ từ nhỏ của tôi. Hiện tôi đang thực tập tại một doanh nghiệp. Tuy công việc hơi vất vả nhưng ở đây tôi học được rất nhiều kỹ năng và kinh nghiệm.', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v26_15', 'lesson-26', '了解', 'liǎojiě', 'từ Hán ngữ', 'hiểu rõ, biết rõ', 'Động từ', 'Bộ cấu tạo [了] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [了] + [解].', 'Kết hợp các thành tố [了] + [解] để tạo thành từ mang nghĩa ''hiểu rõ, biết rõ''.', '因为我的专业是汉语教育，所以回国后我想当一位老师。我想帮助越南学生学习汉语，让他们更了解中国文化，更喜欢中国。那你呢？你有什么打算？', 'Yīnwèi wǒ de zhuānyè shì Hànyǔ jiàoyù, suǒyǐ huíguó hòu wǒ xiǎng dāng yí wèi lǎoshī. Wǒ xiǎng bāngzhù Yuènán xuésheng xuéxí Hànyǔ, ràng tāmen gèng liǎojiě Zhōngguó wénhuà, gèng xǐhuan Zhōngguó. Nà nǐ ne? Nǐ yǒu shén me dǎsuan?', 'Vì chuyên ngành của tôi là Giáo dục Hán ngữ, nên sau khi về nước tôi muốn làm giáo viên. Tôi muốn giúp học sinh Việt Nam học tiếng Hán, giúp các em hiểu hơn về văn hóa Trung Quốc và yêu thích Trung Quốc hơn. Còn cậu thì sao? Cậu có dự định gì?', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v26_16', 'lesson-26', '实现', 'shíxiàn', 'hiện', 'thực hiện', 'Động từ', 'Bộ cấu tạo [实] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [实] + [现].', 'Kết hợp các thành tố [实] + [现] để tạo thành từ mang nghĩa ''thực hiện''.', '我觉得当翻译也很好，很多人都想做这个工作。希望你能实现你的梦想！', 'Wǒ juéde dāng fānyì yě hěn hǎo, hěnduō rén dōu xiǎng zuò zhège gōngzuò. Xīwàng nǐ néng shíxiàn nǐ de mèngxiǎng!', 'Tôi thấy làm phiên dịch viên cũng rất hay, rất nhiều người muốn làm công việc này. Chúc cậu thực hiện được ước mơ của mình!', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v26_17', 'lesson-26', '合适', 'héshì', 'hợp thích', 'hợp, thích hợp, vừa vặn', 'Tính từ', 'Bộ cấu tạo [合] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [合] + [适].', 'Kết hợp các thành tố [合] + [适] để tạo thành từ mang nghĩa ''hợp, thích hợp, vừa vặn''.', '我想找一份好工作。不过对我们留学生来说，在中国找工作确实很难，所以我只好回国，希望找到一份合适的工作。', 'Wǒ xiǎng zhǎo yí fèn hǎo gōngzuò. Búguò duì wǒmen liúxuéshēng lái shuō, zài Zhōngguó zhǎo gōngzuò quèshí hěn nán, suǒyǐ wǒ zhǐhǎo huíguó, xīwàng zhǎodào yí fèn héshì de gōngzuò.', 'Tôi muốn tìm một công việc tốt. Nhưng với du học sinh chúng mình, tìm việc ở Trung Quốc thực sự rất khó, nên tôi đành về nước, hy vọng tìm được một công việc phù hợp.', 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v26_18', 'lesson-26', '然后', 'ránhòu', 'hậu', 'sau đó, tiếp đó', 'Liên từ', 'Bộ cấu tạo [然] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [然] + [后].', 'Kết hợp các thành tố [然] + [后] để tạo thành từ mang nghĩa ''sau đó, tiếp đó''.', '学两年。然后我会回国找工作。', 'Xué liǎng nián. Ránhòu wǒ huì huíguó zhǎo gōngzuò.', 'Học hai năm. Sau đó tôi sẽ về nước tìm việc.', 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v26_19', 'lesson-26', '不过', 'búguò', 'từ Hán ngữ', 'nhưng, tuy nhiên', 'Liên từ', 'Bộ cấu tạo [不] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [不] + [过].', 'Kết hợp các thành tố [不] + [过] để tạo thành từ mang nghĩa ''nhưng, tuy nhiên''.', '我想找一份好工作。不过对我们留学生来说，在中国找工作确实很难，所以我只好回国，希望找到一份合适的工作。', 'Wǒ xiǎng zhǎo yí fèn hǎo gōngzuò. Búguò duì wǒmen liúxuéshēng lái shuō, zài Zhōngguó zhǎo gōngzuò quèshí hěn nán, suǒyǐ wǒ zhǐhǎo huíguó, xīwàng zhǎodào yí fèn héshì de gōngzuò.', 'Tôi muốn tìm một công việc tốt. Nhưng với du học sinh chúng mình, tìm việc ở Trung Quốc thực sự rất khó, nên tôi đành về nước, hy vọng tìm được một công việc phù hợp.', 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v26_20', 'lesson-26', '份', 'fèn', 'từ Hán ngữ', 'phần (lượng từ của công việc)', 'Lượng từ', 'Bộ cấu tạo [份] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Chữ độc thể / hình thanh gồm Bộ cấu tạo [份] và các nét bổ trợ.', 'Ghi nhớ chữ [份] (phần (lượng từ của công việc)) qua hình tượng Thành phần biểu ý/biểu âm cơ bản trong chữ Hán.', '我想找一份好工作。不过对我们留学生来说，在中国找工作确实很难，所以我只好回国，希望找到一份合适的工作。', 'Wǒ xiǎng zhǎo yí fèn hǎo gōngzuò. Búguò duì wǒmen liúxuéshēng lái shuō, zài Zhōngguó zhǎo gōngzuò quèshí hěn nán, suǒyǐ wǒ zhǐhǎo huíguó, xīwàng zhǎodào yí fèn héshì de gōngzuò.', 'Tôi muốn tìm một công việc tốt. Nhưng với du học sinh chúng mình, tìm việc ở Trung Quốc thực sự rất khó, nên tôi đành về nước, hy vọng tìm được một công việc phù hợp.', 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v26_21', 'lesson-26', '位', 'wèi', 'từ Hán ngữ', 'vị (lượng từ chỉ người, thể hiện sự tôn trọng)', 'Lượng từ', 'Bộ cấu tạo [位] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Chữ độc thể / hình thanh gồm Bộ cấu tạo [位] và các nét bổ trợ.', 'Ghi nhớ chữ [位] (vị (lượng từ chỉ người, thể hiện sự tôn trọng)) qua hình tượng Thành phần biểu ý/biểu âm cơ bản trong chữ Hán.', '因为我的专业是汉语教育，所以回国后我想当一位老师。我想帮助越南学生学习汉语，让他们更了解中国文化，更喜欢中国。那你呢？你有什么打算？', 'Yīnwèi wǒ de zhuānyè shì Hànyǔ jiàoyù, suǒyǐ huíguó hòu wǒ xiǎng dāng yí wèi lǎoshī. Wǒ xiǎng bāngzhù Yuènán xuésheng xuéxí Hànyǔ, ràng tāmen gèng liǎojiě Zhōngguó wénhuà, gèng xǐhuan Zhōngguó. Nà nǐ ne? Nǐ yǒu shén me dǎsuan?', 'Vì chuyên ngành của tôi là Giáo dục Hán ngữ, nên sau khi về nước tôi muốn làm giáo viên. Tôi muốn giúp học sinh Việt Nam học tiếng Hán, giúp các em hiểu hơn về văn hóa Trung Quốc và yêu thích Trung Quốc hơn. Còn cậu thì sao? Cậu có dự định gì?', 21) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v26_22', 'lesson-26', '确实', 'quèshí', 'từ Hán ngữ', 'thực sự, khẳng định', 'Phó từ', 'Bộ cấu tạo [确] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)', 'Ghép từ các chữ Hán: [确] + [实].', 'Kết hợp các thành tố [确] + [实] để tạo thành từ mang nghĩa ''thực sự, khẳng định''.', '我想找一份好工作。不过对我们留学生来说，在中国找工作确实很难，所以我只好回国，希望找到一份合适的工作。', 'Wǒ xiǎng zhǎo yí fèn hǎo gōngzuò. Búguò duì wǒmen liúxuéshēng lái shuō, zài Zhōngguó zhǎo gōngzuò quèshí hěn nán, suǒyǐ wǒ zhǐhǎo huíguó, xīwàng zhǎodào yí fèn héshì de gōngzuò.', 'Tôi muốn tìm một công việc tốt. Nhưng với du học sinh chúng mình, tìm việc ở Trung Quốc thực sự rất khó, nên tôi đành về nước, hy vọng tìm được một công việc phù hợp.', 22) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g26_1', 'lesson-26', '1. Cách biểu đạt tuổi tác', 'Cấu trúc câu ngữ pháp trọng tâm', ' 你今年多大了？ Nǐ jīnnián duōdà le? Năm nay cậu bao nhiêu tuổi? (Hỏi chung chung) 你今年几岁了？ Nǐ jīnnián jǐ suì le? Năm nay cháu mấy tuổi rồi (Hỏi trẻ em dưới mười tuổi) 你今年多大年纪了？ Nǐ jīnnián duōdà niánjì le? Năm nay bác bao nhiêu tuổi rồi ạ? (Hỏi người lớn tuổ', NULL, '[{"hanzi":"你今年多大了？","pinyin":"Nǐ jīnnián duōdà le?","meaning":"Năm nay cậu bao nhiêu tuổi? (Hỏi chung chung)"},{"hanzi":"你今年几岁了？","pinyin":"Nǐ jīnnián jǐ suì le?","meaning":"Năm nay cháu mấy tuổi rồi (Hỏi trẻ em dưới mười tuổi)"}]'::jsonb, 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g26_2', 'lesson-26', '2. Cách sử dụng của 了', 'Cấu trúc câu ngữ pháp trọng tâm', ' 他睡觉了。 Tā shuìjiào le. Thằng bé ngủ rồi. 我去了几家商店才买到她喜欢的玩具。 Wǒ qù le jǐ jiā shāngdiàn cái mǎi dào tā xǐhuan de wánjù. Tôi đi khắp mấy cửa hàng mới mua được món đồ chơi mà con bé thích. 他画了一个上午才画完这幅画儿。 Tā huà le yígè shàngwǔ cái huà wán zhè fú huàr. Cậ', NULL, '[{"hanzi":"你今年多大年纪了？","pinyin":"Nǐ jīnnián duōdà niánjì le?","meaning":"Năm nay bác bao nhiêu tuổi rồi ạ? (Hỏi người lớn tuổi)"},{"hanzi":"我去了几家商店才买到她喜欢的玩具。","pinyin":"Wǒ qù le jǐ jiā shāngdiàn cái mǎi dào tā xǐhuan de wánjù.","meaning":"Tôi đi khắp mấy cửa hàng mới mua được món đồ chơi mà con bé thích."}]'::jsonb, 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g26_3', 'lesson-26', '3. 好像', 'Cấu trúc câu ngữ pháp trọng tâm', ' 刚才我好像看见了她。 Gāngcái wǒ hǎoxiàng kànjiàn le tā. Hình như ban nãy tôi mới trông thấy cô ấy. 他好像又长高了。 Tā hǎoxiàng yòu zhǎng gāo le. Hình như cậu ấy lại cao hơn rồi.', NULL, '[{"hanzi":"他画了一个上午才画完这幅画儿。","pinyin":"Tā huà le yígè shàngwǔ cái huà wán zhè fú huàr.","meaning":"Cậu ấy vẽ hết một buổi sáng mới vẽ xong bức tranh này."},{"hanzi":"小阳回了家就去做饭。","pinyin":"Xiǎoyáng huí le jiā jiù qù zuò fàn.","meaning":"Dương vừa về nhà là đi nấu cơm."}]'::jsonb, 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g26_4', 'lesson-26', '4. Trợ từ kết cấu 地', 'Cấu trúc câu ngữ pháp trọng tâm', ' 爸爸轻轻地拍我的肩膀，无声地安慰我。 Bàba qīngqīng de pāi wǒ de jiānbǎng, wúshēng de ānwèi wǒ. Bố nhẹ nhàng vỗ vai tôi, lẳng lặng an ủi tôi. 他连忙地向我挥手。 Tā liánmáng de xiàng wǒ huīshǒu. Cậu ấy vội vàng vẫy tay với tôi.', NULL, '[{"hanzi":"刚才我好像看见了她。","pinyin":"Gāngcái wǒ hǎoxiàng kànjiàn le tā.","meaning":"Hình như ban nãy tôi mới trông thấy cô ấy."},{"hanzi":"爸爸轻轻地拍我的肩膀，无声地安慰我。","pinyin":"Bàba qīngqīng de pāi wǒ de jiānbǎng, wúshēng de ānwèi wǒ.","meaning":"Bố nhẹ nhàng vỗ vai tôi, lẳng lặng an ủi tôi."}]'::jsonb, 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_26_1', 'lesson-26', 'Bài khoá #1: Hội thoại giáo trình — Sau khi tốt nghiệp', 'Hội thoại chuẩn giáo trình Bài 26. Từ vựng chưa học được chú thích phiên âm & nghĩa trong ngoặc.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_26_1_1', 'txt_26_1', '马克', '日明，快要毕业了，你有什么打算了吗？', '日明，快要毕业了，你有什么打算了吗？', 'Rìmíng, kuàiyào bìyè le, nǐ yǒu shénme dǎsuan le ma?', 'Nhật Minh, sắp tốt nghiệp rồi, cậu đã có dự định gì chưa?', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_26_1_2', 'txt_26_1', '阮日明', '我打算继续在这儿学习。', '我打算继续在这儿学习 (xuéxí: học tập)。', 'Wǒ dǎsuan jìxù zài zhèr xuéxí.', 'Tôi dự định tiếp tục học ở đây.', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_26_1_3', 'txt_26_1', '马克', '你想学硕士吗？', '你想学 (xué: học)硕士吗？', 'Nǐ xiǎng xué shuòshì ma?', 'Cậu muốn học thạc sĩ à?', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_26_1_4', 'txt_26_1', '阮日明', '对。', '对。', 'Duì.', 'Đúng vậy.', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_26_1_5', 'txt_26_1', '马克', '学几年？', '学 (xué: học)几年？', 'Xué jǐ nián?', 'Học mấy năm?', 5) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_26_1_6', 'txt_26_1', '阮日明', '学两年。然后我会回国找工作。', '学 (xué: học)两 (liǎng: hai (số lượng))年。然后我会回国找工作。', 'Xué liǎng nián. Ránhòu wǒ huì huíguó zhǎo gōngzuò.', 'Học hai năm. Sau đó tôi sẽ về nước tìm việc.', 6) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_26_1_7', 'txt_26_1', '马克', '你想做什么工作？', '你想做 (zuò: làm)什么工作？', 'Nǐ xiǎng zuò shénme gōngzuò?', 'Cậu muốn làm công việc gì?', 7) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_26_1_8', 'txt_26_1', '阮日明', '因为我的专业是汉语教育，所以回国后我想当一位老师。我想帮助越南学生学习汉语，让他们更了解中国文化，更喜欢中国。那你呢？你有什么打算？', '因为我的专业是汉语教育，所以 (suǒyǐ: cho nên)回国后 (hòu: sau)我想当一位老师。我想帮助越南学生学习 (xuéxí: học tập)汉语，让他们更了解中国文化，更喜欢中国。那你呢？你有什么打算？', 'Yīnwèi wǒ de zhuānyè shì Hànyǔ jiàoyù, suǒyǐ huíguó hòu wǒ xiǎng dāng yí wèi lǎoshī. Wǒ xiǎng bāngzhù Yuènán xuésheng xuéxí Hànyǔ, ràng tāmen gèng liǎojiě Zhōngguó wénhuà, gèng xǐhuan Zhōngguó. Nà nǐ ne? Nǐ yǒu shén me dǎsuan?', 'Vì chuyên ngành của tôi là Giáo dục Hán ngữ, nên sau khi về nước tôi muốn làm giáo viên. Tôi muốn giúp học sinh Việt Nam học tiếng Hán, giúp các em hiểu hơn về văn hóa Trung Quốc và yêu thích Trung Quốc hơn. Còn cậu thì sao? Cậu có dự định gì?', 8) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_26_1_9', 'txt_26_1', '马克', '我想找一份好工作。不过对我们留学生来说，在中国找工作确实很难，所以我只好回国，希望找到一份合适的工作。', '我想找一份好工作。不过对我们留学生来 (lái: đến)说，在中国找工作确实很难，所以 (suǒyǐ: cho nên)我只好回国，希望找到一份合适的工作。', 'Wǒ xiǎng zhǎo yí fèn hǎo gōngzuò. Búguò duì wǒmen liúxuéshēng lái shuō, zài Zhōngguó zhǎo gōngzuò quèshí hěn nán, suǒyǐ wǒ zhǐhǎo huíguó, xīwàng zhǎodào yí fèn héshì de gōngzuò.', 'Tôi muốn tìm một công việc tốt. Nhưng với du học sinh chúng mình, tìm việc ở Trung Quốc thực sự rất khó, nên tôi đành về nước, hy vọng tìm được một công việc phù hợp.', 9) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_26_1_10', 'txt_26_1', '阮日明', '你的理想工作是什么？', '你的理想工作是什么？', 'Nǐ de lǐxiǎng gōngzuò shì shénme?', 'Công việc lý tưởng của cậu là gì?', 10) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_26_1_11', 'txt_26_1', '马克', '翻译。这是我从小的梦想。现在我正在一家企业实习。虽然工作有点儿累，但是在这里我学会了很多技能和经验。', '翻译。这是我从小的梦想。现在我正在一家企业实习。虽然工作有点儿累，但是在这里 (lǐ: trong)我学 (xué: học)会了很多技能和经验。', 'Fānyì. Zhè shì wǒ cóngxiǎo de mèngxiǎng. Xiànzài wǒ zhèng zài yījiā qǐyè shíxí. Suīrán gōngzuò yǒudiǎnr lèi dànshì zài zhèlǐ wǒ xué huì le hěn duō jìnéng hé jīngyàn.', 'Phiên dịch viên. Đây là ước mơ từ nhỏ của tôi. Hiện tôi đang thực tập tại một doanh nghiệp. Tuy công việc hơi vất vả nhưng ở đây tôi học được rất nhiều kỹ năng và kinh nghiệm.', 11) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_26_1_12', 'txt_26_1', '阮日明', '我觉得当翻译也很好，很多人都想做这个工作。希望你能实现你的梦想！', '我觉得当翻译也很好，很多人都想做 (zuò: làm)这个工作。希望你能实现你的梦想！', 'Wǒ juéde dāng fānyì yě hěn hǎo, hěnduō rén dōu xiǎng zuò zhège gōngzuò. Xīwàng nǐ néng shíxiàn nǐ de mèngxiǎng!', 'Tôi thấy làm phiên dịch viên cũng rất hay, rất nhiều người muốn làm công việc này. Chúc cậu thực hiện được ước mơ của mình!', 12) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_26_1_13', 'txt_26_1', '马克', '谢谢！希望你也是！', '谢谢！希望你也是！', 'Xièxie! Xīwàng nǐ yěshì!', 'Cảm ơn cậu! Chúc cậu cũng vậy nhé!', 13) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_26_1_1', 'lesson-26', 'txt_26_1', 'listening', 'listening', '日明，快要毕业了，你有什么打算了吗？', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Nhật Minh, sắp tốt nghiệp rồi, cậu đã có dự định gì chưa?","Thời tiết dễ chịu quá!","Tôi không hay (không thường) liên lạc với Lý Quân.","Anh ta mời tôi ngày mai tới nhà dùng cơm."]'::jsonb, 0, 'Nội dung nghe được: 日明，快要毕业了，你有什么打算了吗？ (Rìmíng, kuàiyào bìyè le, nǐ yǒu shénme dǎsuan le ma?) → Nhật Minh, sắp tốt nghiệp rồi, cậu đã có dự định gì chưa?', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_26_1_2', 'lesson-26', 'txt_26_1', 'listening', 'listening', '我打算继续在这儿学习。', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["刚才 (gāngcái: vừa nãy)我好像看见了她。","我打算继续在这儿学习 (xuéxí: học tập)。","爸爸轻轻 (qīngqīng: nhẹ nhàng)地拍 (pāi: chụp, vỗ)我的肩膀 (jiānbǎng: bờ vai)，无声 (wúshēng: không tiếng động)地安慰 (ānwèi: an ủi)我。","我的理想是当一名 (míng: người (lượng từ))优秀的汉语翻译。"]'::jsonb, 1, 'Câu vừa đọc: 我打算继续在这儿学习。 (Wǒ dǎsuan jìxù zài zhèr xuéxí.) → Tôi dự định tiếp tục học ở đây.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_26_1_3', 'lesson-26', 'txt_26_1', 'listening', 'listening', '你想学硕士吗？', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Cậu muốn học thạc sĩ à?","Ngày mai chúng tôi sẽ đi leo núi.","Cô ấy tự tin tham gia cuộc thi.","Anh ta không thích tôi, tôi còn đi làm gì? (Tôi không đi)"]'::jsonb, 0, 'Nội dung nghe được: 你想学硕士吗？ (Nǐ xiǎng xué shuòshì ma?) → Cậu muốn học thạc sĩ à?', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_26_1_4', 'lesson-26', 'txt_26_1', 'listening', 'listening', '学几年？', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["回国以后，我想帮助学生更了解中国文化。","他笑得留下 (liúxià: để lại)了眼泪 (yǎnlèi: nước mắt)。","学 (xué: học)几年？","我朋友就要去重庆 (Chóngqìng: Trùng Khánh)留学 (liúxué: du học)了。"]'::jsonb, 2, 'Câu vừa đọc: 学几年？ (Xué jǐ nián?) → Học mấy năm?', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_26_2', 'lesson-26', 'Bài nghe tổng hợp: Ôn tập lũy tiến (Bài 1 – Bài 26)', 'Kết hợp từ vựng & mẫu câu đã học từ Bài 1 đến Bài 25 cùng trọng tâm Bài 26 để củng cố phản xạ nghe.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_26_2_1', 'txt_26_2', 'Ôn Bài 25', '他说汉语说得很好。', '他说汉语说得很好。', 'Tā shuō Hànyǔ shuō de hěn hǎo.', 'Anh ấy nói tiếng Trung rất tốt.', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_26_2_2', 'txt_26_2', 'Bài 26', '日明，快要毕业了，你有什么打算了吗？', '日明，快要毕业了，你有什么打算了吗？', 'Rìmíng, kuàiyào bìyè le, nǐ yǒu shénme dǎsuan le ma?', 'Nhật Minh, sắp tốt nghiệp rồi, cậu đã có dự định gì chưa?', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_26_2_3', 'txt_26_2', 'Ôn Bài 13', 'A: 今天星期几啊？', 'A: 今天星期几啊？', 'Jīntiān xīngqī jǐ a?', 'Hôm nay là thứ mấy thế?', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_26_2_4', 'txt_26_2', 'Bài 26', '对。', '对。', 'Duì.', 'Đúng vậy.', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_26_2_5', 'txt_26_2', 'Ôn Bài 1', '她是老师。', '她是老师。', 'Tā shì lǎoshī.', 'Cô ấy là giáo viên.', 5) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_26_2_6', 'txt_26_2', 'Bài 26', '你的理想工作是什么？', '你的理想工作是什么？', 'Nǐ de lǐxiǎng gōngzuò shì shénme?', 'Công việc lý tưởng của cậu là gì?', 6) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_26_2_7', 'txt_26_2', 'Ôn Bài 11', '他正在听音乐呢。', '他正在听音乐呢。', 'Tā zhèngzài tīng yīnyuè ne.', 'Anh ấy đang nghe nhạc.', 7) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_26_2_8', 'txt_26_2', 'Bài 26', '谢谢！希望你也是！', '谢谢！希望你也是！', 'Xièxie! Xīwàng nǐ yěshì!', 'Cảm ơn cậu! Chúc cậu cũng vậy nhé!', 8) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_26_2_1', 'lesson-26', 'txt_26_2', 'listening', 'listening', '他说汉语说得很好。', NULL, '[Ôn tập Bài 25] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Anh ấy nói tiếng Trung rất tốt.","Mẹ bảo tôi ăn cơm xong thì giúp mẹ quét dọn nhà cửa.","thời gian bắt đầu cuộc họp","Tớ định đi xe buýt."]'::jsonb, 0, 'Nội dung nghe được: 他说汉语说得很好。 (Tā shuō Hànyǔ shuō de hěn hǎo.) → Anh ấy nói tiếng Trung rất tốt.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_26_2_2', 'lesson-26', 'txt_26_2', 'listening', 'listening', '日明，快要毕业了，你有什么打算了吗？', NULL, '[Bài 26] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["日明，快要毕业了，你有什么打算了吗？","你今 (jīn: hôm nay, nay)年多大年纪了？","大学 (dàxué: đại học)毕业以后，我想继续读 (dú: đọc)汉语教育硕士。","他连忙 (liánmáng: vội vàng)地向 (xiàng: hướng về)我挥手 (huīshǒu: vẫy tay)。"]'::jsonb, 0, 'Câu vừa đọc: 日明，快要毕业了，你有什么打算了吗？ (Rìmíng, kuàiyào bìyè le, nǐ yǒu shénme dǎsuan le ma?) → Nhật Minh, sắp tốt nghiệp rồi, cậu đã có dự định gì chưa?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_26_2_3', 'lesson-26', 'txt_26_2', 'listening', 'listening', 'A: 今天星期几啊？', NULL, '[Ôn tập Bài 13] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Mẹ gõ nhẹ vào đầu tôi.","Năm nay hay năm sau cậu đi du học?","Buổi chiều chúng ta đi nhé!","Hôm nay là thứ mấy thế?"]'::jsonb, 3, 'Nội dung nghe được: A: 今天星期几啊？ (Jīntiān xīngqī jǐ a?) → Hôm nay là thứ mấy thế?', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_26_2_4', 'lesson-26', 'txt_26_2', 'listening', 'listening', '她是老师。', NULL, '[Ôn tập Bài 1] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["这次 (cì: lần)比赛如果他参加我就参加。","希望你早 (zǎo: sớm)日 (rì: ngày)找到一份理想的工作，实现梦想！","回国以后，我想帮助学生更了解中国文化。","她是老师。"]'::jsonb, 3, 'Câu vừa đọc: 她是老师。 (Tā shì lǎoshī.) → Cô ấy là giáo viên.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_26_2_5', 'lesson-26', 'txt_26_2', 'listening', 'listening', '你的理想工作是什么？', NULL, '[Bài 26] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["zǒu jiù dào.","Công việc lý tưởng của cậu là gì?","Cái váy này là của em à?","đứa bé hiểu chuyện"]'::jsonb, 1, 'Nội dung nghe được: 你的理想工作是什么？ (Nǐ de lǐxiǎng gōngzuò shì shénme?) → Công việc lý tưởng của cậu là gì?', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_26_3', 'lesson-26', 'Bài khoá mở rộng: Định hướng sau lễ tốt nghiệp (Mở rộng)', 'Hội thoại tình huống mới xây dựng dựa trên từ vựng và ngữ pháp Bài 26 (không trùng lặp nguyên văn giáo trình).', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_26_3_1', 'txt_26_3', 'Minh', '下个月就要毕业了，你的梦想是什么工作？', '下 (xià: dưới / xuống)个月就要毕业了，你的梦想是什么工作？', 'Xià gè yuè jiù yào bìyè le, nǐ de mèngxiǎng shì shénme gōngzuò?', 'Tháng sau là tốt nghiệp rồi, công việc mơ ước của cậu là gì?', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_26_3_2', 'txt_26_3', 'Lan', '我的专业是汉语教育，想先读两年硕士，以后当一位老师。', '我的专业是汉语教育，想先读 (dú: đọc)两 (liǎng: hai (số lượng))年硕士，以后当一位老师。', 'Wǒ de zhuānyè shì Hànyǔ jiàoyù, xiǎng xiān dú liǎng nián shuòshì, yǐhòu dāng yí wèi lǎoshī.', 'Chuyên ngành của mình là Giáo dục Hán ngữ, mình muốn học thạc sĩ hai năm trước rồi sau này làm giáo viên.', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_26_3_3', 'txt_26_3', 'Minh', '真好！我现在在一家企业实习做翻译，积累了很多技能和经验。', '真好！我现在在一家企业实习做 (zuò: làm)翻译，积累了很多技能和经验。', 'Zhēn hǎo! Wǒ xiànzài zài yì jiā qǐyè shíxí zuò fānyì, jīlěi le hěnduō jìnéng hé jīngyàn.', 'Hay quá! Mình thì đang thực tập biên phiên dịch tại một doanh nghiệp, tích lũy được nhiều kỹ năng và kinh nghiệm.', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_26_3_4', 'txt_26_3', 'Lan', '祝我们都能找到理想的工作，继续了解并热爱中国文化！', '祝我们都能找到理想的工作，继续了解并热爱中国文化！', 'Zhù wǒmen dōu néng zhǎodào lǐxiǎng de gōngzuò, jìxù liǎojiě bìng rè''ài Zhōngguó wénhuà!', 'Chúc hai đứa mình đều tìm được công việc lý tưởng và tiếp tục hiểu biết, yêu mến văn hóa Trung Quốc!', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_26_3_1', 'lesson-26', 'txt_26_3', 'listening', 'listening', '下个月就要毕业了，你的梦想是什么工作？ 我的专业是汉语教育，想先读两年硕士，以后当一位老师。 真好！我现在在一家企业实习做翻译，积累了很多技能和经验。 祝我们都能找到理想的工作，继续了解并热爱中国文化！', NULL, '[Nghe hiểu tình huống mới] Nhật Minh hiện đang tích lũy kinh nghiệm làm công việc gì trước khi tốt nghiệp?', '["Mở nhà hàng ở Bắc Kinh","Học thạc sĩ y khoa","Làm tài xế taxi","Thực tập làm biên phiên dịch tại một doanh nghiệp"]'::jsonb, 3, 'Minh nói rõ ''现在在一家企业实习做翻译，积累了很多技能和经验''.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_26_3_2', 'lesson-26', 'txt_26_3', 'listening', 'listening', '下个月就要毕业了，你的梦想是什么工作？', NULL, '[Mở rộng] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Tháng sau là tốt nghiệp rồi, công việc mơ ước của cậu là gì?","thành tích kiểm tra","Tôi đang vẽ tranh.","Tàu hỏa sắp chạy ngay bây giờ."]'::jsonb, 0, 'Nội dung nghe được: 下个月就要毕业了，你的梦想是什么工作？ (Xià gè yuè jiù yào bìyè le, nǐ de mèngxiǎng shì shénme gōngzuò?) → Tháng sau là tốt nghiệp rồi, công việc mơ ước của cậu là gì?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_26_3_3', 'lesson-26', 'txt_26_3', 'listening', 'listening', '我的专业是汉语教育，想先读两年硕士，以后当一位老师。', NULL, '[Mở rộng] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["希望你早 (zǎo: sớm)日 (rì: ngày)找到一份理想的工作，实现梦想！","我的专业是汉语教育，想先读 (dú: đọc)两 (liǎng: hai (số lượng))年硕士，以后当一位老师。","我的理想是当一名 (míng: người (lượng từ))优秀的汉语翻译。","我朋友就要去重庆 (Chóngqìng: Trùng Khánh)留学 (liúxué: du học)了。"]'::jsonb, 1, 'Câu vừa đọc: 我的专业是汉语教育，想先读两年硕士，以后当一位老师。 (Wǒ de zhuānyè shì Hànyǔ jiàoyù, xiǎng xiān dú liǎng nián shuòshì, yǐhòu dāng yí wèi lǎoshī.) → Chuyên ngành của mình là Giáo dục Hán ngữ, mình muốn học thạc sĩ hai năm trước rồi sau này làm giáo viên.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_26_3_4', 'lesson-26', 'txt_26_3', 'listening', 'listening', '真好！我现在在一家企业实习做翻译，积累了很多技能和经验。', NULL, '[Mở rộng] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Hay quá! Mình thì đang thực tập biên phiên dịch tại một doanh nghiệp, tích lũy được nhiều kỹ năng và kinh nghiệm.","Cậu thích mùa xuân hay mùa hè?","Không sớm cũng không muộn, rất đúng giờ!","Cảm ơn cậu! Chúc cậu cũng vậy nhé!"]'::jsonb, 0, 'Nội dung nghe được: 真好！我现在在一家企业实习做翻译，积累了很多技能和经验。 (Zhēn hǎo! Wǒ xiànzài zài yì jiā qǐyè shíxí zuò fānyì, jīlěi le hěnduō jìnéng hé jīngyàn.) → Hay quá! Mình thì đang thực tập biên phiên dịch tại một doanh nghiệp, tích lũy được nhiều kỹ năng và kinh nghiệm.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
