INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss26_2', 'lesson-26', '你今年多大了', 'Năm nay cậu bao nhiêu tuổi? (Hỏi chung chung)', 'Nǐ jīnnián duōdà le?', '["你","今","年","多大","了"]'::jsonb, 'Từ chưa học: 今 (jīn: hôm nay, nay)', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss26_3', 'lesson-26', '你今年几岁了', 'Năm nay cháu mấy tuổi rồi (Hỏi trẻ em dưới mười tuổi)', 'Nǐ jīnnián jǐ suì le?', '["你","今","年","几","岁","了"]'::jsonb, 'Từ chưa học: 今 (jīn: hôm nay, nay)', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss26_4', 'lesson-26', '你今年多大年纪了', 'Năm nay bác bao nhiêu tuổi rồi ạ? (Hỏi người lớn tuổi)', 'Nǐ jīnnián duōdà niánjì le?', '["你","今","年","多大","年纪","了"]'::jsonb, 'Từ chưa học: 今 (jīn: hôm nay, nay)', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss26_5', 'lesson-26', '北京的秋天比夏天凉快得多', '[Ôn tập Bài 15] Mùa thu ở Bắc Kinh mát mẻ hơn mùa hè nhiều.', 'Běijīng de qiūtiān bǐ xiàtiān liángkuai de duō.', '["北京的","秋天","比","夏天","凉快","得多"]'::jsonb, NULL, 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss26_6', 'lesson-26', '他汉语说得很好', '[Ôn tập Bài 25] Anh ấy nói tiếng Trung rất tốt.', 'Tā Hànyǔ shuō de hěn hǎo.', '["他","汉语","说","得","很","好"]'::jsonb, NULL, 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr26_vi_1', 'lesson-26', 'vi_to_zh', '[Mở rộng] Sau khi về nước, tôi muốn giúp học sinh hiểu thêm về văn hóa Trung Quốc.', NULL, NULL, '回国以后，我想帮助学生更了解中国文化。', NULL, 'huíguó yǐhòu wǒ xiǎng bāngzhù xuésheng gèng liǎojiě zhōngguó wénhuà', '[]'::jsonb, 'Gợi ý Pinyin: Huíguó yǐhòu, wǒ xiǎng bāngzhù xuésheng gèng liǎojiě Zhōngguó wénhuà.', 'Sau khi về nước, tôi muốn giúp học sinh hiểu thêm về văn hóa Trung Quốc. → 回国以后，我想帮助学生更了解中国文化。 (Huíguó yǐhòu, wǒ xiǎng bāngzhù xuésheng gèng liǎojiě Zhōngguó wénhuà.)', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr26_vi_2', 'lesson-26', 'vi_to_zh', '[Mở rộng] Thực tập tại doanh nghiệp giúp tôi học được rất nhiều kỹ năng và kinh nghiệm làm việc.', NULL, NULL, '在企业实习让我学到了很多工作技能和经验。', NULL, 'zài qǐyè shíxí ràng wǒ xuédào le hěnduō gōngzuò jìnéng hé jīngyàn', '[]'::jsonb, 'Gợi ý Pinyin: Zài qǐyè shíxí ràng wǒ xuédào le hěnduō gōngzuò jìnéng hé jīngyàn. | Từ chưa học: 学 (xué: học)', 'Thực tập tại doanh nghiệp giúp tôi học được rất nhiều kỹ năng và kinh nghiệm làm việc. → 在企业实习让我学到了很多工作技能和经验。 (Zài qǐyè shíxí ràng wǒ xuédào le hěnduō gōngzuò jìnéng hé jīngyàn.)', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr26_vi_3', 'lesson-26', 'vi_to_zh', 'Năm nay cậu bao nhiêu tuổi? (Hỏi chung chung)', NULL, NULL, '你今年多大了？', NULL, 'nǐ jīnnián duōdà le', '[]'::jsonb, 'Gợi ý Pinyin: Nǐ jīnnián duōdà le? | Từ chưa học: 今 (jīn: hôm nay, nay)', 'Năm nay cậu bao nhiêu tuổi? (Hỏi chung chung) → 你今年多大了？ (Nǐ jīnnián duōdà le?)', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
