INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr26_zh_1', 'lesson-26', 'zh_to_vi', '[Mở rộng] 大学 (dàxué: đại học)毕业以后，我想继续读 (dú: đọc)汉语教育硕士。', '大学毕业以后，我想继续读汉语教育硕士。', 'Dàxué bìyè yǐhòu, wǒ xiǎng jìxù dú Hànyǔ jiàoyù shuòshì.', NULL, 'Sau khi tốt nghiệp đại học, tôi muốn học tiếp thạc sĩ Giáo dục Hán ngữ.', NULL, '["Sau","khi","tốt"]'::jsonb, 'Pinyin: Dàxué bìyè yǐhòu, wǒ xiǎng jìxù dú Hànyǔ jiàoyù shuòshì.', '大学毕业以后，我想继续读汉语教育硕士。 (Dàxué bìyè yǐhòu, wǒ xiǎng jìxù dú Hànyǔ jiàoyù shuòshì.) nghĩa là: Sau khi tốt nghiệp đại học, tôi muốn học tiếp thạc sĩ Giáo dục Hán ngữ.', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr26_zh_2', 'lesson-26', 'zh_to_vi', '[Mở rộng] 希望你早 (zǎo: sớm)日 (rì: ngày)找到一份理想的工作，实现梦想！', '希望你早日找到一份理想的工作，实现梦想！', 'Xīwàng nǐ zǎorì zhǎodào yí fèn lǐxiǎng de gōngzuò, shíxiàn mèngxiǎng!', NULL, 'Hy vọng bạn sớm tìm được một công việc lý tưởng và thực hiện được ước mơ!', NULL, '["Hy","vọng","bạn"]'::jsonb, 'Pinyin: Xīwàng nǐ zǎorì zhǎodào yí fèn lǐxiǎng de gōngzuò, shíxiàn mèngxiǎng!', '希望你早日找到一份理想的工作，实现梦想！ (Xīwàng nǐ zǎorì zhǎodào yí fèn lǐxiǎng de gōngzuò, shíxiàn mèngxiǎng!) nghĩa là: Hy vọng bạn sớm tìm được một công việc lý tưởng và thực hiện được ước mơ!', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
