INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq26_13', 'lesson-26', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “专业” chứa bộ thủ nào sau đây?', '["Bộ cấu tạo [理] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [位] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [企] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)","Bộ cấu tạo [专] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán)"]'::jsonb, 3, 'Chữ “专业” có Bộ cấu tạo [专] (Thành phần biểu ý/biểu âm cơ bản trong chữ Hán). Ghép từ các chữ Hán: [专] + [业].', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
