INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct26_22', 'lesson-26', NULL, 'comprehensive_test', 'listening', '下个月就要毕业了，你的梦想是什么工作？ 我的专业是汉语教育，想先读两年硕士，以后当一位老师。 真好！我现在在一家企业实习做翻译，积累了很多技能和经验。 祝我们都能找到理想的工作，继续了解并热爱中国文化！', NULL, 'Nhật Minh hiện đang tích lũy kinh nghiệm làm công việc gì trước khi tốt nghiệp?', '["Mở nhà hàng ở Bắc Kinh","Học thạc sĩ y khoa","Làm tài xế taxi","Thực tập làm biên phiên dịch tại một doanh nghiệp"]'::jsonb, 3, 'Minh nói rõ ''现在在一家企业实习做翻译，积累了很多技能和经验''.', 22) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
